SEUIL_EN_LIGNE_MINUTES = 2

def est_en_ligne(user):
    if not user or not user.last_seen:
        return False
    return (datetime.utcnow() - user.last_seen) < timedelta(minutes=SEUIL_EN_LIGNE_MINUTES)

def formater_derniere_connexion(last_seen):
    if not last_seen:
        return "Hors ligne"
    delta = datetime.utcnow() - last_seen
    secondes = delta.total_seconds()
    if secondes < 60:
        return "À l'instant"
    minutes = int(secondes // 60)
    if minutes < 60:
        return f"Actif il y a {minutes} minute{'s' if minutes > 1 else ''}"
    heures = int(secondes // 3600)
    if heures < 24:
        return f"Actif il y a {heures} heure{'s' if heures > 1 else ''}"
    jours = int(secondes // 86400)
    if jours < 7:
        return f"Actif il y a {jours} jour{'s' if jours > 1 else ''}"
    return f"Actif le {last_seen.strftime('%d/%m/%Y')}"

def formater_etait_en_ligne(last_seen):
    """Texte de présence du profil : « Était en ligne il y a 5 minutes / 2 heures / un jour /
    une semaine / un mois / un an… ». (Fonction additive : formater_derniere_connexion reste inchangée.)"""
    if not last_seen:
        return "Hors ligne"
    secondes = max(0, int((datetime.utcnow() - last_seen).total_seconds()))
    minutes = secondes // 60
    if minutes < 60:
        n = max(minutes, 1)
        return f"Était en ligne il y a {n} minute{'s' if n > 1 else ''}"
    heures = secondes // 3600
    if heures < 24:
        return f"Était en ligne il y a {heures} heure{'s' if heures > 1 else ''}"
    jours = secondes // 86400
    if jours < 7:
        return "Était en ligne il y a un jour" if jours == 1 else f"Était en ligne il y a {jours} jours"
    if jours < 30:
        semaines = jours // 7
        return "Était en ligne il y a une semaine" if semaines == 1 else f"Était en ligne il y a {semaines} semaines"
    if jours < 365:
        mois = min(jours // 30, 11)
        return "Était en ligne il y a un mois" if mois == 1 else f"Était en ligne il y a {mois} mois"
    ans = jours // 365
    return "Était en ligne il y a un an" if ans == 1 else f"Était en ligne il y a {ans} ans"

def badge_presence_court(last_seen):
    """Pastille courte des listes d'amis : '5 min' / '3 h' si actif depuis moins de 24 h, sinon ''."""
    if not last_seen:
        return ''
    secondes = max(0, int((datetime.utcnow() - last_seen).total_seconds()))
    minutes = secondes // 60
    if minutes < 60:
        return f"{max(minutes, 1)} min"
    heures = secondes // 3600
    return f"{heures} h" if heures < 24 else ''

def attacher_statut_presence(user):
    if user is None:
        return user
    user.est_en_ligne_calc = est_en_ligne(user)
    user.derniere_connexion_texte = "En ligne" if user.est_en_ligne_calc else formater_derniere_connexion(user.last_seen)
    user.derniere_connexion_iso = (user.last_seen.isoformat() + "Z") if user.last_seen else ""
    return user

DUREE_STORY_HEURES = 24
EXTENSIONS_VIDEO_STORY = {'.mp4', '.webm', '.mov', '.avi', '.mkv', '.m4v'}

def story_media_est_video(story):
    if not story or not story.image:
        return False
    return os.path.splitext(story.image)[1].lower() in EXTENSIONS_VIDEO_STORY

def formater_age_story(date_creation):
    if not date_creation:
        return ""
    secondes = (datetime.utcnow() - date_creation).total_seconds()
    if secondes < 0:
        secondes = 0
    if secondes < 60:
        return "à l'instant"
    minutes = int(secondes // 60)
    if minutes < 60:
        return f"il y a {minutes} minute{'s' if minutes > 1 else ''}"
    heures = int(secondes // 3600)
    if heures < 24:
        return f"il y a {heures} heure{'s' if heures > 1 else ''}"
    jours = max(1, int(secondes // 86400))
    return f"il y a {jours} jour{'s' if jours > 1 else ''}"

def attacher_stories_calc(user, viewer_id):
    if user is None:
        return user
    limite = datetime.utcnow() - timedelta(hours=DUREE_STORY_HEURES)
    user.stories_actives_calc = sorted(
        [s for s in user.stories if s.date_creation >= limite and not s.est_brouillon],
        key=lambda s: s.date_creation
    )
    if user.stories_actives_calc:
        ids_stories = [s.id for s in user.stories_actives_calc]
        ids_deja_vues = {
            v.story_id for v in StoryView.query.filter(
                StoryView.viewer_id == viewer_id,
                StoryView.story_id.in_(ids_stories)
            ).all()
        }
        user.story_non_vue_calc = any(sid not in ids_deja_vues for sid in ids_stories)
    else:
        user.story_non_vue_calc = False
    return user

def formater_temps_ecoule(date_creation):
    if not date_creation:
        return "à l'instant"
    secondes = (datetime.utcnow() - date_creation).total_seconds()
    if secondes < 0:
        secondes = 0
    if secondes < 60:
        return "à l'instant"
    minutes = int(secondes // 60)
    if minutes < 60:
        return f"il y a {minutes} min"
    heures = int(secondes // 3600)
    if heures < 24:
        return f"il y a {heures} h"
    jours = int(secondes // 86400)
    if jours < 7:
        return f"il y a {jours} j"
    semaines = int(jours // 7)
    if semaines < 4:
        return f"il y a {semaines} sem."
    mois = int(jours // 30)
    if mois < 12:
        return f"il y a {mois} mois"
    annees = int(jours // 365)
    if annees < 100:
        return f"il y a {annees} an{'s' if annees > 1 else ''}"
    siecles = int(jours // 36500)
    return f"il y a {siecles} siècle{'s' if siecles > 1 else ''}"

