@main_bp.route('/api/publications/<int:pub_id>/traduction', methods=['GET'])
def api_publication_traduction(pub_id):
    """Traduction d'une seule publication (bouton « Voir la traduction » / « Voir l'original »)."""
    uid = session.get('user_id')
    if not uid:
        return jsonify({'success': False, 'error': 'Connexion requise.'}), 401
    pub = db.session.get(Publication, pub_id)
    if pub is None or getattr(pub, 'is_removed', False) or not _peut_voir_publication(pub, uid):
        return jsonify({'success': False, 'error': 'Publication introuvable.'}), 404
    cible = _tr_base(request.args.get('vers') or '')
    if not _langue_valide(cible):
        cible = _tr_cible(uid)
    original = pub.contenu or ''
    rep = {'success': True, 'traduit': False, 'original': original, 'texte': original, 'source': None, 'cible': cible}
    if not _tr_assurer_tables() or not _tr_texte_traduisible(original):
        return jsonify(rep)
    emp = _tr_empreinte(original)
    try:
        c = PublicationTraduction.query.filter_by(publication_id=pub.id, cible=cible).first()
        info = (c.source, c.texte) if (c and c.empreinte == emp) else None
    except Exception:
        try: db.session.rollback()
        except Exception: pass
        info = None
    if info is None:
        res = _tr_appeler_llm([(pub.id, original)], cible)
        if res and pub.id in res:
            info = res[pub.id]
            _tr_stocker(res, cible, {pub.id: emp})
    if info:
        rep['source'] = info[0]
        if info[1]:
            rep['traduit'], rep['texte'] = True, info[1]
    return jsonify(rep)

