_sj_table_ok = False

def _sj_assurer_table():
    """Crée la table serie_jours si elle n'existe pas encore (une fois par processus)."""
    global _sj_table_ok
    if _sj_table_ok:
        return True
    try:
        SerieJours.__table__.create(db.engine, checkfirst=True)
        _sj_table_ok = True
    except Exception as e:
        print(f"[serie-jours] table indisponible : {e}")
    return _sj_table_ok

@main_bp.route('/api/serie-jours/ping', methods=['POST'])
def api_serie_jours_ping():
    """Compte l'ouverture du jour (une seule fois par jour) et renvoie la série en cours."""
    uid = session.get('user_id')
    if not uid:
        return jsonify({'success': False, 'error': 'Connexion requise.'}), 401
    if not _sj_assurer_table():
        return jsonify({'success': False})
    aujourdhui = datetime.utcnow().date()
    try:
        s = db.session.get(SerieJours, uid)
        nouveau_jour = False
        if s is None:
            s = SerieJours(user_id=uid, derniere_date=aujourdhui, serie=1, meilleure=1)
            db.session.add(s)
            nouveau_jour = True
        elif s.derniere_date != aujourdhui:
            hier = aujourdhui - timedelta(days=1)
            s.serie = (s.serie or 0) + 1 if s.derniere_date == hier else 1
            s.meilleure = max(s.meilleure or 1, s.serie)
            s.derniere_date = aujourdhui
            nouveau_jour = True
        db.session.commit()
        return jsonify({'success': True, 'serie': s.serie, 'meilleure': s.meilleure, 'nouveau_jour': nouveau_jour})
    except Exception as e:
        try: db.session.rollback()
        except Exception: pass
        print(f"[serie-jours] erreur : {e}")
        return jsonify({'success': False})


