def formater_compteur(n):
    """AJOUT : abrège un compteur → 999 ; 1 000 = 1K ; 1 500 = 1,5K ; 10 000 = 10K ; 1 000 000 = 1M ; 1 000 000 000 = 1Md."""
    try:
        n = int(n or 0)
    except (TypeError, ValueError):
        n = 0
    if n < 0:
        n = 0
    for seuil, suffixe in ((10 ** 9, 'Md'), (10 ** 6, 'M'), (10 ** 3, 'K')):
        if n >= seuil:
            dixiemes = n * 10 // seuil
            entier, dec = divmod(dixiemes, 10)
            return f"{entier}{(',' + str(dec)) if dec else ''}{suffixe}"
    return str(n)

