def extraire_prompt_image(message):
    mots = ['génère', 'genere', 'crée', 'cree', 'dessine', 'illustre', 'fais moi', 'une image de', 'une photo de', 'image', 'photo']
    texte = message
    for mot in mots:
        texte = re.sub(re.escape(mot), '', texte, flags=re.IGNORECASE)
    return ' '.join(texte.split()).strip()

