def _masquer_nom(nom):
    nom = (nom or '').strip()
    return ' '.join((p[0] + '*' * (len(p) - 1)) if len(p) > 1 else p for p in nom.split())

def _masquer_contact(valeur):
    valeur = (valeur or '').strip()
    if '@' in valeur:
        local, domaine = valeur.split('@', 1)
        return local[:2] + '*' * max(len(local) - 2, 1) + '@' + domaine
    if len(valeur) > 5:
        return valeur[:3] + '*' * (len(valeur) - 5) + valeur[-2:]
    return '*' * len(valeur)

