def generer_reponse_ollama(instructions, historique, contenu):
    """
    Solution de secours locale via Ollama (llama3.2).
    Utilisée si Gemini ET Groq échouent.
    """
    try:
        messages = [{"role": "system", "content": instructions}]
        for h in historique:
            role = "assistant" if h.get("role") == "model" else "user"
            texte = h.get("parts", [{}])[0].get("text", "")
            if texte:
                messages.append({"role": role, "content": texte})
        messages.append({"role": "user", "content": contenu})

        reponse = ollama.chat(model="llama3.2", messages=messages)
        return reponse["message"]["content"]
    except Exception as e:
        print(f"DEBUG: Ollama indisponible ({e})")
        return None

def _nettoyer_texte_pour_voix(texte):
    """Retire le markdown, les blocs de code, les liens et les emojis pour que la voix lise proprement."""
    t = str(texte or "")
    t = re.sub(r"```[\s\S]*?```", " ", t)
    t = re.sub(r"`([^`]*)`", r"\1", t)
    t = re.sub(r"!?\[([^\]]*)\]\([^)]*\)", r"\1", t)
    t = re.sub(r"https?://\S+", " ", t)
    t = re.sub(r"[*_#>~|]+", " ", t)
    t = re.sub(r"[\U0001F000-\U0001FAFF\u2600-\u27BF\uFE0F]", "", t)
    t = re.sub(r"\s+", " ", t).strip()
    return t[:1500]

def _purger_vieux_audios(dossier, jours=3):
    try:
        import time as _time
        limite = _time.time() - jours * 86400
        for nom in os.listdir(dossier):
            if nom.startswith("reponse_") and nom.endswith(".mp3"):
                chemin = os.path.join(dossier, nom)
                if os.path.getmtime(chemin) < limite:
                    os.remove(chemin)
    except Exception as e:
        print(f"DEBUG: Purge audios ignorée : {e}")

def generer_audio_elevenlabs(texte, chemin_sortie):
    """Génère la voix ElevenLabs. Retourne le chemin du fichier, ou None en cas d'échec."""
    try:
        texte_voix = _nettoyer_texte_pour_voix(texte)
        if not texte_voix:
            return None
        try:
            # SDK ElevenLabs récent (v1+/v2+)
            audio = client_eleven.text_to_speech.convert(
                voice_id="21m00Tcm4TlvDq8ikWAM",  # Rachel
                text=texte_voix,
                model_id="eleven_multilingual_v2",
                output_format="mp3_44100_128",
            )
        except AttributeError:
            # Ancien SDK
            audio = client_eleven.generate(text=texte_voix, voice="Rachel", model="eleven_multilingual_v2")
        with open(chemin_sortie, "wb") as f:
            if isinstance(audio, (bytes, bytearray)):
                f.write(audio)
            else:
                for chunk in audio:
                    if chunk:
                        f.write(chunk)
        if os.path.getsize(chemin_sortie) == 0:
            os.remove(chemin_sortie)
            return None
        return chemin_sortie
    except Exception as e:
        print(f"DEBUG: Erreur lors de la génération ElevenLabs : {e}")
        return None

_MOTIFS_NOUVELLE_DISCUSSION = [
    r"commen[çc]ons une nouvelle discussion", r"nouvelle discussion",
    r"recommen[çc]ons(\s+la\s+discussion)?",
    r"oublie (tout|notre discussion|ce qu'on (a|s'est) dit)",
    r"repartons? (de|à) z[ée]ro",
]
