def _get_historique_ia(user_id, limite=10):
    requete = Message.query.filter_by(expediteur_id=user_id, destinataire_id=0)
    marqueur = session.get(_cle_session_reset(user_id))
    if marqueur:
        requete = requete.filter(Message.id > marqueur)
    messages = requete.order_by(Message.id.desc()).limit(limite).all()
    messages.reverse()
    contents = []
    for m in messages:
        if m.contenu_utilisateur:
            contents.append({"role": "user", "parts": [{"text": m.contenu_utilisateur}]})
        if m.reponse_ia:
            contents.append({"role": "model", "parts": [{"text": m.reponse_ia}]})
        elif m.contenu_utilisateur:
            # AJOUT : réponse interrompue par l'utilisateur (bouton « Arrêter ») — on garde l'alternance des tours
            contents.append({"role": "model", "parts": [{"text": "(Ma réponse a été interrompue par l'utilisateur avant d'être terminée.)"}]})
    return contents

def _retirer_markdown(texte):
    """Supprime les asterisques et le markdown (gras, italique, puces, titres) hors blocs de code."""
    t = str(texte or "")
    morceaux = re.split(r"(```[\s\S]*?```)", t)
    sortie = []
    for m in morceaux:
        if m.startswith("```"):
            sortie.append(m)
            continue
        m = re.sub(r"(?m)^[ \t]*[\*\u2022][ \t]+", "- ", m)
        m = re.sub(r"\*{1,3}([^*\n]+?)\*{1,3}", r"\1", m)
        m = m.replace("*", "")
        m = re.sub(r"(?m)^[ \t]{0,3}#{1,6}[ \t]*", "", m)
        sortie.append(m)
    return "".join(sortie).strip()

import threading as _threading
_VERROU_MEMOIRE_IA = _threading.Lock()
_MOTIFS_OUBLI_MEMOIRE = [
    r"(oublie|efface|supprime|vide|reinitialise|r\u00e9initialise).{0,30}(ta m[e\u00e9]moire|ma m[e\u00e9]moire|ce que tu sais sur moi|ce que tu retiens|tout ce que je t'ai dit|tout ce que tu sais)",
]

def _chemin_memoire_ia(user_id):
    dossier = os.path.join(current_app.instance_path, "ia_memoire")
    os.makedirs(dossier, exist_ok=True)
    return os.path.join(dossier, f"user_{int(user_id)}.json")

def _charger_memoire_ia(chemin):
    """Retourne la liste des souvenirs durables de l'utilisateur (liste de phrases)."""
    try:
        with open(chemin, "r", encoding="utf-8") as f:
            data = json.load(f)
        return [str(x).strip() for x in data if str(x).strip()][:80]
    except Exception:
        return []

def _effacer_memoire_ia(chemin):
    try:
        with _VERROU_MEMOIRE_IA:
            if os.path.exists(chemin):
                os.remove(chemin)
        return True
    except Exception as e:
        print(f"DEBUG: Erreur effacement memoire : {e}")
        return False

def _mettre_a_jour_memoire_ia(chemin, souvenirs_actuels, message, reponse):
    """Tourne en arriere-plan : extrait les faits durables de l'echange et les ajoute a la memoire."""
    try:
        if len(message.strip()) < 8:
            return
        consigne = (
            "Tu geres la memoire a long terme d'un assistant IA. "
            "Voici les souvenirs deja connus sur l'utilisateur :\n"
            + json.dumps(souvenirs_actuels, ensure_ascii=False)
            + "\n\nNouvel echange :\nUtilisateur : " + message[:1500]
            + "\nAssistant : " + str(reponse)[:1500]
            + "\n\nMets a jour la liste des souvenirs durables et utiles sur l'utilisateur : prenom, nom, "
              "ville, pays, metier, etudes, famille, projets, gouts, preferences, objectifs, problemes en cours, "
              "et tout ce qu'il demande explicitement de retenir. Une phrase courte par souvenir. "
              "Si une information en corrige une ancienne, remplace l'ancienne. "
              "N'ajoute ni suppositions, ni faits generaux, ni contenu de la reponse de l'assistant. "
              "Garde au maximum 60 souvenirs. "
              "Reponds UNIQUEMENT par un tableau JSON de chaines, sans texte autour."
        )
        rep = client.models.generate_content(
            model='gemini-3.5-flash-lite', contents=consigne,
            config=types.GenerateContentConfig(temperature=0, max_output_tokens=2048))
        brut = (rep.text or "").strip()
        brut = re.sub(r"^```(?:json)?|```$", "", brut, flags=re.MULTILINE).strip()
        nouveaux = json.loads(brut)
        if not isinstance(nouveaux, list):
            return
        propres, vus = [], set()
        for x in nouveaux:
            x = str(x).strip()
            if x and x.lower() not in vus:
                vus.add(x.lower())
                propres.append(x)
        if not propres and souvenirs_actuels:
            return
        with _VERROU_MEMOIRE_IA:
            with open(chemin, "w", encoding="utf-8") as f:
                json.dump(propres[:60], f, ensure_ascii=False, indent=1)
    except Exception as e:
        print(f"DEBUG: Mise a jour memoire IA ignoree ({e})")

