# ══════════════════════════════════════════════════════════════════
#  AJOUT ADDITIF : clic sur une notification -> page concernée (jamais de 404)
#  La destination est calculée AU MOMENT DU CLIC à partir de ce qui existe
#  vraiment en base (publication, message, story, profil...). Si la cible a
#  été supprimée ou n'est plus accessible, on retombe sur une page sûre.
# ══════════════════════════════════════════════════════════════════
def _lien_interne_valide(lien):
    """True si `lien` est un chemin interne qui correspond à une route réellement enregistrée."""
    try:
        if not lien or not isinstance(lien, str):
            return False
        lien = lien.strip()
        if not lien.startswith('/') or lien.startswith('//'):
            return False
        chemin = lien.split('?')[0].split('#')[0]
        from werkzeug.exceptions import NotFound, MethodNotAllowed, RequestRedirect
        adaptateur = current_app.url_map.bind('localhost')
        try:
            adaptateur.match(chemin, method='GET')
            return True
        except RequestRedirect:
            return True
        except (NotFound, MethodNotAllowed):
            return False
    except Exception:
        return False


def _url_commentaire(pub_id, comm_id, viewer):
    """AJOUT : lien vers la page des commentaires, ancré sur le commentaire exact (#comment-<id>)."""
    try:
        comm_id = int(comm_id) if comm_id else None
        pub_id = int(pub_id) if pub_id else None
        c = db.session.get(Commentaire, comm_id) if comm_id else None
        if c is not None and not pub_id:
            pub_id = c.publication_id
        if not pub_id:
            return None
        pub = db.session.get(Publication, pub_id)
        if pub is None or not _peut_voir_publication(pub, viewer.id):
            return None
        lien = url_for('main.commentaires', pub_id=pub.id)
        if c is not None and c.publication_id == pub.id:
            lien += f'#comment-{c.id}'      # commentaire supprimé -> on arrive simplement en haut de la page
        return lien
    except Exception:
        return None


def _resoudre_lien_notification(notif, viewer):
    """Retourne l'URL où mener l'utilisateur quand il clique sur `notif`. Ne lève jamais d'erreur."""
    extra = notif.extra_data if isinstance(notif.extra_data, dict) else {}
    genre = ((getattr(notif, 'type', None) or getattr(notif, 'verb', None) or '')).strip().lower()
    verbe = (getattr(notif, 'verb', None) or '').strip().lower()
    cible_type = (getattr(notif, 'target_type', None) or '').strip().lower()
    cible_id = getattr(notif, 'target_id', None) or 0
    page_notifs = url_for('main.notifications')

    def url_profil(user_id):
        try:
            if not user_id:
                return None
            u = db.session.get(User, int(user_id))
            # Lien par identifiant : fonctionne même si le nom d'utilisateur contient un espace, un accent, un « / »…
            return url_for('main.profil_par_id', user_id=u.id) if u else None
        except Exception:
            return None

    def int_ou_none(v):
        try:
            return int(v) if v not in (None, '', 0, '0') else None
        except (TypeError, ValueError):
            return None

    def url_publication(pub_id):
        try:
            pub_id = int_ou_none(pub_id)
            if not pub_id:
                return None
            pub = db.session.get(Publication, pub_id)
            if pub is None or not _peut_voir_publication(pub, viewer.id):
                return None
            return url_for('main.feed') + f'#publication-{pub.id}'
        except Exception:
            return None

    def pub_id_depuis_commentaire(comm_id):
        try:
            comm_id = int_ou_none(comm_id)
            c = db.session.get(Commentaire, comm_id) if comm_id else None
            return c.publication_id if c else None
        except Exception:
            return None

    try:
        tous = {genre, verbe}

        # ── 0) Notifications du système / support / paiements / sécurité (testées en premier :
        #       leur target_type vaut « user » par défaut et ne doit pas les envoyer sur un profil) ──
        if genre == 'reverif_refusee':           # AJOUT : refus de revérification -> réessayer (et non les forfaits)
            return url_for('main.reverif_choix')
        if genre == 'reverif_approuvee':         # AJOUT : revérification approuvée -> son profil
            return url_profil(viewer.id) or url_for('main.feed')
        if genre in ('blue_badge_sub', 'blue_badge_active', 'verification_badge'):
            return url_for('main.avantages_badge')
        if genre == 'blue_badge_rejete':
            return url_for('main.verification_etape_forfait')
        if genre == 'securite_mot_de_passe':
            return url_for('main.securite_mot_de_passe')
        if genre in ('signalement_recu', 'signalement_traite', 'contenu_signale', 'contenu_supprime',
                     'profil_probleme', 'avertissement'):
            return url_for('main.statut_profil')
        if genre in ('paiement_confirme', 'paiement_echoue'):
            return url_for('main.forfait')
        if genre in ('support', 'welcome', 'bienvenue'):
            return url_for('main.feed')
        if genre in ('family_invite', 'family_accept'):          # AJOUT : Cercle familial
            return url_for('main.famille_page')

        # ── 0 bis) Types qui n'avaient pas de page dédiée ──
        if genre == 'securite_connexion':
            return url_for('main.securite_mot_de_passe')
        if genre in ('blue_badge_expire_bientot', 'blue_badge_expire'):
            return url_for('main.forfait')

        # ── 0 ter) Commentaire / réponse / mention : page des commentaires, ancre sur le commentaire exact ──
        if (tous & {'comment', 'commentaire', 'reply', 'mention'}
                or cible_type in ('comment', 'commentaire')):
            comm_id = int_ou_none(extra.get('comment_id') or extra.get('commentaire_id'))
            if not comm_id and cible_type in ('comment', 'commentaire'):
                comm_id = int_ou_none(cible_id)      # anciennes notifications de réponse
            pub_cible = (extra.get('pub_id') or extra.get('publication_id')
                         or (cible_id if cible_type in ('post', 'publication') else None))
            lien = _url_commentaire(pub_cible, comm_id, viewer)
            if lien:
                return lien
            return url_profil(notif.actor_id) or page_notifs

        # ── 1) Publications : like, réaction, commentaire, réponse, partage, mention ──
        genres_pub = {'like', 'reaction', 'comment', 'commentaire', 'reply', 'mention', 'share', 'partage', 'boost', 'repost'}
        if (tous & genres_pub
                or any(g.startswith(('like', 'reaction', 'comment', 'mention', 'reply', 'share', 'partage', 'boost', 'repost')) for g in tous)
                or cible_type in ('post', 'publication', 'comment', 'commentaire')):
            candidats = [extra.get('pub_id'), extra.get('publication_id'), extra.get('post_id')]
            if cible_type in ('post', 'publication'):
                candidats.append(cible_id)
            if cible_type in ('comment', 'commentaire'):
                candidats.append(pub_id_depuis_commentaire(cible_id))
            candidats.append(pub_id_depuis_commentaire(extra.get('comment_id') or extra.get('commentaire_id')))
            for pid in candidats:
                lien = url_publication(pid)
                if lien:
                    return lien
            # publication supprimée / privée : on mène vers la personne qui a agi
            return url_profil(notif.actor_id) or page_notifs

        # ── 2) Messages : ouvre la discussion avec l'expéditeur ──
        if 'message' in tous or cible_type == 'message':
            expediteur = None
            if cible_type == 'message' and cible_id:
                m = db.session.get(Message, int(cible_id))
                if m and m.destinataire_id == viewer.id:
                    expediteur = m.expediteur_id
            expediteur = expediteur or int_ou_none(extra.get('expediteur_id')) or int_ou_none(notif.actor_id)
            if expediteur and db.session.get(User, expediteur):
                return url_for('main.messagerie', destinataire_id=expediteur)
            return url_for('main.messagerie')

        # ── 3) Demandes d'amis, acceptations, abonnés : profil de la personne ──
        _msg = (getattr(notif, 'message', None) or '').lower()   # anciennes notifications sans type reconnu
        if (tous & {'friend_request', 'invitation', 'friend_accept', 'follow', 'ami', 'amitie'}
                or cible_type in ('user', 'friend_request')
                or 'accepté votre invitation' in _msg or 'accepte votre invitation' in _msg
                or 'accepté votre demande' in _msg):
            return url_profil(notif.actor_id) or (url_for('main.afficher_suggesstions') if tous & {'friend_request', 'invitation'} else page_notifs)

        # ── 4) Stories ──
        if any(g.startswith('story') for g in tous) or cible_type == 'story':
            sid = int_ou_none(extra.get('story_id')) or (int_ou_none(cible_id) if cible_type == 'story' else None)
            s = db.session.get(Story, sid) if sid else None
            if s is not None and not getattr(s, 'est_brouillon', False):
                limite = datetime.utcnow() - timedelta(hours=DUREE_STORY_HEURES)
                visible = s.date_creation and s.date_creation >= limite
                if visible and s.user_id != viewer.id:
                    masquee = StoryHiddenUser.query.filter_by(owner_id=s.user_id, hidden_user_id=viewer.id).first()
                    visible = (not masquee) and (s.user_id in _amis_ids(viewer.id))
                if visible:
                    return url_for('main.voir_story', story_id=s.id)
            return url_profil(notif.actor_id) or url_for('main.feed')

        # ── 5) Type inconnu : on accepte l'ancien lien enregistré seulement s'il correspond à une vraie route ──
        ancien = extra.get('lien')
        if _lien_interne_valide(ancien):
            return ancien.strip()
        return url_profil(notif.actor_id) or page_notifs
    except Exception as e:
        print(f"DEBUG résolution lien notification : {e}")
        return page_notifs


@main_bp.route('/notifications/ouvrir/<int:notif_id>')
def ouvrir_notification(notif_id):
    if 'user_id' not in session:
        return redirect(url_for('main.login'))
    try:
        viewer = db.session.get(User, session['user_id'])
        notif = db.session.get(Notification, notif_id)
        # Notification introuvable ou appartenant à quelqu'un d'autre : retour à la liste, jamais de 404
        if viewer is None or notif is None or notif.recipient_id != viewer.id:
            return redirect(url_for('main.notifications'))
        destination = _resoudre_lien_notification(notif, viewer)
        try:
            if not notif.is_read:
                notif.is_read = True
                notif.read_at = datetime.utcnow()
                db.session.commit()
        except Exception as e:
            db.session.rollback()
            print(f"DEBUG marquage notification lue : {e}")
        return redirect(destination or url_for('main.notifications'))
    except Exception as e:
        print(f"DEBUG ouverture notification : {e}")
        return redirect(url_for('main.notifications'))

# ══════════════════════════════════════════════════════════════════
# AIGUILLAGE DES PAIEMENTS DES FORFAITS
#   • Carte bancaire                      → NotchPay
#   • Mobile money hors Cameroun          → NotchPay
#   • Mobile money Cameroun (Orange/MTN)  → Fapshi (flux d'origine)
# ══════════════════════════════════════════════════════════════════
_NOTCHPAY_FORFAITS = {"4500": "standard", "12000": "premium",
                      "78000": "max", "100000": "max_plus"}
_NOTCHPAY_INDICATIFS = {"CM": "237", "GA": "241", "CG": "242", "CI": "225",
                        "SN": "221", "BJ": "229", "TG": "228", "BF": "226", "ML": "223"}

def _payer_avec_notchpay(amount, nom_f, method, phone_country):
    try:
        email = current_user.email or f"user{current_user.id}@facenet.cm"
        forfait_key = _NOTCHPAY_FORFAITS.get(amount)
        channel, phone = "card", ""
        currency = str(request.form.get('currency') or 'XAF').strip().upper()
        if currency not in ("XAF", "XOF"):
            currency = "XAF"

        if method == "momo":
            channel = str(request.form.get('network') or '').strip().lower()
            chiffres = re.sub(r'\D', '', str(request.form.get('phone') or ''))
            indicatif = _NOTCHPAY_INDICATIFS.get(phone_country)
            if not re.match(r'^[a-z]{2}\.[a-z0-9]+$', channel) or not chiffres or not indicatif:
                flash("Choisissez votre opérateur et saisissez votre numéro de téléphone.", "danger")
                return redirect(url_for('main.forfait'))
            phone = "+" + indicatif + chiffres

        resultat = notchpay.initier_paiement_notchpay(
            email, forfait_key, channel, phone,
            callback=url_for('main.verification_paiements_valide', _external=True),
            currency=currency,
        )
        if not resultat.get('success') or not resultat.get('payment_url'):
            print(f"❌ Erreur NotchPay initialisation : {resultat}")
            flash("Le service de paiement est momentanément indisponible.", "danger")
            return redirect(url_for('main.forfait'))

        # une seule transaction en cours à la fois
        session.pop('fapshi_trans_id', None)
        session.pop('fapshi_forfait', None)
        session['notchpay_reference'] = resultat['reference']
        session['notchpay_forfait'] = nom_f
        session['notchpay_montant'] = int(amount)
        _verification_enregistrer_ref('notchpay:' + str(resultat['reference']), nom_f, amount)  # AJOUT
        return redirect(resultat['payment_url'])
    except Exception as e:
        import traceback
        print(f"❌ Erreur NotchPay (exception) : {e}")
        traceback.print_exc()
        flash("Le service de paiement est momentanément indisponible.", "danger")
        return redirect(url_for('main.forfait'))

@main_bp.route('/process_payment', methods=['GET', 'POST'])
def process_payment():
    if request.method != 'POST':
        return redirect(url_for('main.forfait'))
    if 'user_id' not in session:
        return redirect(url_for('main.login'))
    
    # AJOUT : jamais deux fois le même paiement (déjà payé, ou paiement lancé pas encore confirmé)
    _garde = _verification_garde_double_paiement()
    if _garde is not None:
        return _garde

    # Nettoyage automatique des espaces accidentels dans le formulaire
    amount = str(request.form.get('amount') or '').strip()
    method = str(request.form.get('method') or '').strip()
    
    noms_forfaits = {"4500": "Standard", "12000": "Premium",
                     "78000": "Max", "100000": "Max Plus (Membre Ultra)"}
    nom_f = noms_forfaits.get(amount, "Spécial")
    
    if method not in ("momo", "card", "paypal") or amount not in noms_forfaits:
        flash("Forfait ou méthode de paiement invalide.", "danger")
        return redirect(url_for('main.forfait'))

    # ── Aiguillage du fournisseur selon le mode choisi ──
    if method == "paypal":
        flash("PayPal n'est pas encore disponible. Choisissez Mobile Money ou Carte bancaire.", "warning")
        return redirect(url_for('main.forfait'))

    phone_country = str(request.form.get('phone_country') or 'CM').strip().upper()
    if method == "card" or (method == "momo" and phone_country != "CM"):
        return _payer_avec_notchpay(amount, nom_f, method, phone_country)

    # ── Mobile money Cameroun (Orange / MTN) : Fapshi, comme avant ──
    try:
        email = current_user.email or f"user{current_user.id}@facenet.cm"
        
        # Identifiant Fapshi sécurisé (sans espaces ni parenthèses)
        external_id_clean = f"forfait_{amount}_{current_user.id}"
        
        response = fapshi.initiate_pay({
            "amount": int(amount), 
            "email": email, 
            "userId": str(current_user.id),
            "externalId": external_id_clean,
            "redirectUrl": url_for('main.verification_paiements_valide', _external=True),
            "message": f"Forfait Tsapi Verified {nom_f}"
        })
        
        if response.get('statusCode') != 200:
            print(f"❌ Erreur Fapshi initiate_pay (statusCode={response.get('statusCode')}) : réponse complète = {response}")
            flash("Le service de paiement est momentanément indisponible.", "danger")
            return redirect(url_for('main.forfait'))
            
        session.pop('notchpay_reference', None)
        session.pop('notchpay_forfait', None)
        session.pop('notchpay_montant', None)
        session['fapshi_trans_id'] = response['transId']
        session['fapshi_forfait'] = nom_f
        _verification_enregistrer_ref('fapshi:' + str(response['transId']), nom_f, amount)  # AJOUT
        return redirect(response['link'])
        
    except Exception as e:
        import traceback
        print(f"❌ Erreur Fapshi initiate_pay (exception) : {e}")
        traceback.print_exc()
        flash("Le service de paiement est momentanément indisponible.", "danger")
        return redirect(url_for('main.forfait'))

