@main_bp.route('/verification/piece-identite', methods=['POST'])
def enregistrer_piece_identite():
    if 'user_id' not in session:
        return jsonify(success=False, error="Vous devez être connecté."), 401
    # Le paiement doit etre confirme (ou la demande precedente rejetee : l'utilisateur a deja paye)
    if not (session.get('verification_paiement_valide') or current_user.piece_identite_type == 'rejete'):
        return jsonify(success=False, error="Veuillez d'abord choisir un forfait et confirmer votre paiement."), 403
    type_piece = request.form.get('type_piece', '').strip()
    fichier = request.files.get('document')
    if not type_piece or not fichier or fichier.filename == '':
        return jsonify(success=False, error="Merci de choisir un type de pièce et d'envoyer un document."), 400
    _ext_piece = fichier.filename.rsplit('.', 1)[-1].lower() if '.' in fichier.filename else ''
    if _ext_piece not in ('jpg', 'jpeg', 'png', 'webp', 'pdf'):
        return jsonify(success=False, error="Format non accepté. Envoyez une photo (JPG, PNG) ou un PDF."), 400
    try:
        nom_fichier = f"{uuid.uuid4().hex}_{secure_filename(fichier.filename)}"
        fichier.save(os.path.join(UPLOAD_ID_FOLDER, nom_fichier))
        current_user.piece_identite_type = type_piece
        current_user.piece_identite_fichier = 'pieces_identite/' + nom_fichier
        current_user.piece_identite_date = datetime.utcnow()
        db.session.commit()
        return jsonify(success=True)
    except Exception as e:
        db.session.rollback()
        return jsonify(success=False, error=str(e)), 500

# ── Règles par type de pièce acceptée (recto seul / recto + verso) ───────────
_PIECES_ALIAS_ANALYSE = {'permis': 'driver_license', 'sejour': 'residence_permit',
                         'carte_identite': 'cni', 'national_id': 'cni', 'passeport': 'passport'}
_PIECES_FACES = {'cni': 2, 'passport': 1, 'driver_license': 2, 'residence_permit': 2}

@main_bp.route('/verification/analyser-piece', methods=['POST'])
@login_required
def verification_analyser_piece():
    """Contrôle d'une photo de pièce (OpenCV) : netteté, reflets, forme rectangulaire.
    Ne bloque jamais le flux si OpenCV est absent ou en cas d'erreur inattendue."""
    try:
        import cv2
        import numpy as np
    except ImportError:
        return jsonify(ok=True)
    try:
        type_piece = (request.form.get('type_piece') or 'cni').strip().lower()
        type_piece = _PIECES_ALIAS_ANALYSE.get(type_piece, type_piece)
        faces = _PIECES_FACES.get(type_piece, 2)
        f = request.files.get('image')
        if not f:
            return jsonify(ok=False, raison="Image manquante.", faces=faces)
        data = f.read(15 * 1024 * 1024 + 1)
        if len(data) > 15 * 1024 * 1024:
            return jsonify(ok=False, raison="Image trop volumineuse.", faces=faces)
        img = cv2.imdecode(np.frombuffer(data, np.uint8), cv2.IMREAD_COLOR)
        if img is None:
            return jsonify(ok=False, raison="Image illisible.", faces=faces)

        h, w = img.shape[:2]
        s = 800.0 / max(h, w)
        img = cv2.resize(img, (max(1, int(w * s)), max(1, int(h * s))))
        gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)

        if cv2.Laplacian(gray, cv2.CV_64F).var() < 60:
            return jsonify(ok=False, raison="Image floue. Stabilisez l'appareil.", faces=faces)
        if (gray > 250).mean() > 0.10:
            return jsonify(ok=False, raison="Reflet trop fort. Inclinez légèrement la pièce.", faces=faces)

        edges = cv2.Canny(cv2.GaussianBlur(gray, (5, 5), 0), 50, 150)
        edges = cv2.dilate(edges, np.ones((3, 3), np.uint8), iterations=2)
        contours, _ = cv2.findContours(edges, cv2.RETR_LIST, cv2.CHAIN_APPROX_SIMPLE)
        aire_img = img.shape[0] * img.shape[1]
        best = None
        for c in sorted(contours, key=cv2.contourArea, reverse=True)[:5]:
            approx = cv2.approxPolyDP(c, 0.02 * cv2.arcLength(c, True), True)
            if len(approx) == 4 and cv2.contourArea(approx) > 0.20 * aire_img:
                best = approx
                break
        if best is None:
            return jsonify(ok=False, raison="Pièce non détectée. Posez-la à plat dans le cadre.", faces=faces)

        (_, _), (rw, rh), _ = cv2.minAreaRect(best)
        ratio = max(rw, rh) / max(1.0, min(rw, rh))
        if not (1.2 <= ratio <= 1.95):
            return jsonify(ok=False, raison="Format non reconnu. Présentez la pièce entière.", faces=faces)
        return jsonify(ok=True, faces=faces)
    except Exception as e:
        print(f"DEBUG: analyse de pièce impossible : {e}")
        return jsonify(ok=True)

@main_bp.route('/verification/check-vpn')
def verification_check_vpn():
    if 'user_id' not in session:
        return jsonify(success=False, error="Non connecté."), 401
    ip = request.headers.get('X-Forwarded-For', request.remote_addr)
    if ip and ',' in ip:
        ip = ip.split(',')[0].strip()
    try:
        resp = requests.get(f'http://ip-api.com/json/{ip}',
                           params={'fields': 'status,message,proxy,hosting,query'}, timeout=5)
        data = resp.json()
        if data.get('status') != 'success':
            return jsonify(success=True, is_vpn=False, verifie=False)
        est_vpn = bool(data.get('proxy')) or bool(data.get('hosting'))
        return jsonify(success=True, is_vpn=est_vpn, verifie=True)
    except requests.RequestException:
        return jsonify(success=True, is_vpn=False, verifie=False)

@main_bp.route('/api/detecter-pays')
def detecter_pays():
    ip = request.headers.get('X-Forwarded-For', request.remote_addr)
    if ip and ',' in ip:
        ip = ip.split(',')[0].strip()
    try:
        resp = requests.get(f'http://ip-api.com/json/{ip}',
                           params={'fields': 'status,countryCode'}, timeout=5)
        data = resp.json()
        if data.get('status') == 'success' and data.get('countryCode'):
            return jsonify(success=True, country=data['countryCode'].lower())
    except requests.RequestException:
        pass
    return jsonify(success=False, country=None)

