@main_bp.route('/messagerie')
@main_bp.route('/messagerie/<int:destinataire_id>')
def messagerie(destinataire_id=None):
    if 'user_id' not in session:
        return redirect(url_for('main.login'))
    user_actif = db.session.get(User, session['user_id'])
    ids_bloques_par_moi = {b.blocked_id for b in BlockedUser.query.filter_by(owner_id=user_actif.id).all()}
    ids_qui_mont_bloque = {b.owner_id for b in BlockedUser.query.filter_by(blocked_id=user_actif.id).all()}
    ids_exclus = ids_bloques_par_moi | ids_qui_mont_bloque
    query_users = User.query.filter(User.id != user_actif.id)
    if ids_exclus:
        query_users = query_users.filter(~User.id.in_(ids_exclus))
    tous_les_utilisateurs = query_users.all()
    # AJOUT ADDITIF : le vrai compte « Tsapi AI » (base de données) est présenté par la ligne IA de la messagerie.
    # On le retire de la liste normale pour qu'il n'apparaisse plus en double, et on le transmet au template.
    tsapi_user = None
    try:
        tsapi_user = User.query.filter(db.func.lower(User.username).in_(('tsapi ai', 'tsapi_ai'))).first()
        if tsapi_user:
            tous_les_utilisateurs = [u for u in tous_les_utilisateurs if u.id != tsapi_user.id]
    except Exception as _e_tsapi:
        db.session.rollback()
        tsapi_user = None
        print(f"DEBUG: compte Tsapi AI dans la messagerie : {_e_tsapi}")
    for u in tous_les_utilisateurs:
        attacher_statut_presence(u)
        attacher_stories_calc(u, user_actif.id)
    messages = []
    destinataire_actif = None
    if destinataire_id:
        destinataire_actif = db.session.get(User, destinataire_id)
        if destinataire_actif:
            attacher_statut_presence(destinataire_actif)
            messages = Message.query.filter(
                ((Message.expediteur_id == user_actif.id) & (Message.destinataire_id == destinataire_id)) |
                ((Message.expediteur_id == destinataire_id) & (Message.destinataire_id == user_actif.id))
            ).order_by(Message.date_envoi.asc()).all()
    try:
        attacher_stories_calc(user_actif, user_actif.id)   # AJOUT : mes propres stories actives (barre de la messagerie)
    except Exception as _e_ms:
        print(f"DEBUG stories perso messagerie : {_e_ms}")
    return render_template('messagerie.html', conversations=tous_les_utilisateurs,
                           messages=messages, destinataire_actif=destinataire_actif,
                           tsapi_user=tsapi_user)

@main_bp.route('/envoyer_message/<int:destinataire_id>', methods=['POST'])
def envoyer_message(destinataire_id):
    is_ajax = request.headers.get('X-Requested-With') == 'XMLHttpRequest'
    if 'user_id' not in session:
        if is_ajax: return jsonify({'success': False, 'error': 'Non autorisé'}), 401
        return "Non autorisé", 401
    est_bloque = BlockedUser.query.filter(or_(
        (BlockedUser.owner_id == session['user_id']) & (BlockedUser.blocked_id == destinataire_id),
        (BlockedUser.owner_id == destinataire_id) & (BlockedUser.blocked_id == session['user_id']))).first()
    if est_bloque:
        if is_ajax: return jsonify({'success': False, 'error': 'Ce compte est bloqué ou vous a bloqué.'}), 403
        flash("Impossible d'envoyer ce message : compte bloqué.", "error")
        return redirect(url_for('main.messagerie'))
    destinataire_user = db.session.get(User, destinataire_id)
    if _est_compte_support(destinataire_user):
        if is_ajax: return jsonify({'success': False, 'error': "Ce compte ne reçoit pas de messages : vous pouvez le suivre."}), 403
        flash("Ce compte ne reçoit pas de messages.", "error")
        return redirect(url_for('main.messagerie'))
    if destinataire_user and destinataire_user.message_permission == 'amis':
        est_ami = DemandeAmitie.query.filter(DemandeAmitie.statut == 'acceptee', or_(
            (DemandeAmitie.emetteur_id == session['user_id']) & (DemandeAmitie.recepteur_id == destinataire_id),
            (DemandeAmitie.emetteur_id == destinataire_id) & (DemandeAmitie.recepteur_id == session['user_id']))).first()
        if not est_ami:
            if is_ajax: return jsonify({'success': False, 'error': "Ce compte n'accepte les messages que de ses amis."}), 403
            flash("Ce compte n'accepte les messages que de ses amis.", "error")
            return redirect(url_for('main.messagerie'))
    contenu = request.form.get('contenu', '').strip()
    nouveau_msg = None
    if contenu:
        nouveau_msg = Message(expediteur_id=session['user_id'], destinataire_id=destinataire_id, contenu=contenu)
        db.session.add(nouveau_msg)
        db.session.commit()
        try:
            notifier(destinataire_id, 'message', db.session.get(User, session['user_id']), cible=('message', nouveau_msg.id))
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            print(f"DEBUG notification message : {e}")
    if is_ajax:
        return jsonify({'success': True, 'message': {'id': nouveau_msg.id if nouveau_msg else None,
            'contenu': contenu,
            'date': nouveau_msg.date_envoi.strftime('%H:%M') if nouveau_msg and nouveau_msg.date_envoi else ''}})
    return redirect(url_for('main.messagerie', destinataire_id=destinataire_id))

UPLOAD_MESSAGE_FOLDER = os.path.join('static', 'uploads', 'messages')
os.makedirs(UPLOAD_MESSAGE_FOLDER, exist_ok=True)
ALLOWED_IMAGE_EXT = {'png', 'jpg', 'jpeg', 'gif', 'webp'}
ALLOWED_AUDIO_EXT = {'webm', 'mp3', 'ogg', 'wav', 'm4a'}
EXTENSIONS_INTERDITES_DOCUMENT = {'exe', 'bat', 'cmd', 'sh', 'msi', 'php', 'js', 'jar', 'com', 'scr', 'py'}

def _extension_fichier(filename):
    return filename.rsplit('.', 1)[1].lower() if '.' in filename else ''

@main_bp.route('/envoyer_media', methods=['POST'])
def envoyer_media():
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Non autorisé'}), 401
    destinataire_id = request.form.get('recipient_id', type=int)
    fichier = request.files.get('file')
    if not destinataire_id or not fichier or fichier.filename == '':
        return jsonify({'success': False, 'error': 'Fichier ou destinataire manquant.'}), 400
    est_bloque = BlockedUser.query.filter(or_(
        (BlockedUser.owner_id == session['user_id']) & (BlockedUser.blocked_id == destinataire_id),
        (BlockedUser.owner_id == destinataire_id) & (BlockedUser.blocked_id == session['user_id']))).first()
    if est_bloque:
        return jsonify({'success': False, 'error': 'Ce compte est bloqué ou vous a bloqué.'}), 403
    destinataire_user = db.session.get(User, destinataire_id)
    if _est_compte_support(destinataire_user):
        return jsonify({'success': False, 'error': "Ce compte ne reçoit pas de messages : vous pouvez le suivre."}), 403
    if destinataire_user and destinataire_user.message_permission == 'amis':
        est_ami = DemandeAmitie.query.filter(DemandeAmitie.statut == 'acceptee', or_(
            (DemandeAmitie.emetteur_id == session['user_id']) & (DemandeAmitie.recepteur_id == destinataire_id),
            (DemandeAmitie.emetteur_id == destinataire_id) & (DemandeAmitie.recepteur_id == session['user_id']))).first()
        if not est_ami:
            return jsonify({'success': False, 'error': "Ce compte n'accepte les messages que de ses amis."}), 403
    ext = _extension_fichier(fichier.filename)
    if ext in ALLOWED_VIDEO_EXT: media_type = 'video'
    elif ext in ALLOWED_IMAGE_EXT: media_type = 'image'
    elif ext in ALLOWED_AUDIO_EXT: media_type = 'audio'
    else:
        media_type = 'document'
        if ext in EXTENSIONS_INTERDITES_DOCUMENT:
            return jsonify({'success': False, 'error': 'Type de fichier non autorisé.'}), 400
    nom_original = secure_filename(fichier.filename) or f"fichier.{ext}"
    nom_stocke = f"{uuid.uuid4().hex}_{nom_original}"
    fichier.save(os.path.join(UPLOAD_MESSAGE_FOLDER, nom_stocke))
    nouveau_msg = Message(expediteur_id=session['user_id'], destinataire_id=destinataire_id,
                          contenu=None, media_url=nom_stocke, media_type=media_type, media_filename=nom_original)
    db.session.add(nouveau_msg)
    db.session.commit()
    try:
        notifier(destinataire_id, 'message', db.session.get(User, session['user_id']), cible=('message', nouveau_msg.id))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG notification message média : {e}")
    return jsonify({'success': True, 'message': {'id': nouveau_msg.id,
        'media_url': url_for('static', filename='uploads/messages/' + nom_stocke),
        'media_type': media_type, 'media_filename': nom_original,
        'date': nouveau_msg.date_envoi.strftime('%H:%M')}})

@main_bp.route('/get_messages/<int:user_id>')
def get_messages(user_id):
    if 'user_id' not in session:
        return jsonify({'messages': []}), 401
    current_id = session['user_id']
    moi = db.session.get(User, current_id)
    autre = db.session.get(User, user_id)
    conversation = Message.query.filter(
        ((Message.expediteur_id == current_id) & (Message.destinataire_id == user_id)) |
        ((Message.expediteur_id == user_id) & (Message.destinataire_id == current_id))
    ).order_by(Message.date_envoi.asc()).all()
    ids_caches = _ids_messages_caches_pour(current_id)
    if ids_caches:
        conversation = [m for m in conversation if m.id not in ids_caches]
    # AJOUT ADDITIF : « Supprimer la discussion » (de mon côté) → seuls les messages postérieurs restent visibles
    try:
        _limite_efface = _conv_effacee_limite(current_id, user_id)
        if _limite_efface:
            conversation = [m for m in conversation if not (m.date_envoi and m.date_envoi <= _limite_efface)]
    except Exception as _e_ef:
        db.session.rollback()
        print(f"DEBUG: discussion supprimée (get_messages) : {_e_ef}")
    a_modifie = False
    for m in conversation:
        if m.destinataire_id == current_id and not m.lu:
            m.lu = True; m.date_lu = datetime.utcnow(); a_modifie = True
    if a_modifie: db.session.commit()
    confirmations_visibles = bool(moi and autre and moi.confirmations_lecture_actif and autre.confirmations_lecture_actif)
    return jsonify({'messages': [{'id': m.id, 'contenu': m.contenu,
        'media_url': url_for('static', filename='uploads/messages/' + m.media_url) if m.media_url else None,
        'media_type': m.media_type, 'media_filename': m.media_filename,
        'sent_by_me': m.expediteur_id == current_id,
        'date': m.date_envoi.strftime('%H:%M') if m.date_envoi else '',
        'timestamp': (m.date_envoi.isoformat() + "Z") if m.date_envoi else '',
        'lu': bool(m.lu) if confirmations_visibles else False}
        for m in conversation if m.contenu or m.media_url],
        'confirmations_lecture_actives': confirmations_visibles})

