@main_bp.route('/profile/<username>/photos/<type_photo>')
def api_photos_historique(username, type_photo):
    if type_photo not in ('avatar', 'couverture'):
        return jsonify(success=False, error="Type invalide."), 400
    user_cible = User.query.filter_by(username=username).first_or_404()
    # AJOUT ADDITIF : rattrapage de l'historique. Les anciennes photos publiées automatiquement dans le fil
    # (« a changé sa photo de profil / couverture ») avant la création de la table d'historique, ou dont
    # l'entrée n'est pas reliée à sa publication, sont rajoutées / reliées ici (opération sans doublon).
    try:
        type_pub_h = 'photo_profil' if type_photo == 'avatar' else 'photo_couverture'
        existantes = PhotoHistorique.query.filter_by(user_id=user_cible.id, type_photo=type_photo).all()
        urls_connues = {e.url for e in existantes}
        pubs_photo = [p for p in Publication.query.filter_by(user_id=user_cible.id, type_publication=type_pub_h).all()
                      if p.media_url and not getattr(p, 'is_removed', False)]
        modifie = False
        par_url = {}
        for p in pubs_photo:
            par_url.setdefault(p.media_url, p)
        for e in existantes:
            if not e.publication_id and e.url in par_url:
                e.publication_id = par_url[e.url].id
                modifie = True
        for url_p, p in par_url.items():
            if url_p not in urls_connues:
                db.session.add(PhotoHistorique(user_id=user_cible.id, type_photo=type_photo, url=url_p,
                                               publication_id=p.id, date_creation=p.date_creation or datetime.utcnow()))
                modifie = True
        if modifie:
            db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG rattrapage historique photos : {e}")
    entries = (PhotoHistorique.query
               .filter_by(user_id=user_cible.id, type_photo=type_photo)
               .order_by(PhotoHistorique.date_creation.desc()).all())
    # État réel de chaque photo (J'aime de l'utilisateur connecté, compteurs) pour que
    # le visualiseur n'affiche jamais « pas aimé » à tort en naviguant dans l'historique.
    ids = [e.publication_id for e in entries if e.publication_id]
    pubs = {p.id: p for p in Publication.query.filter(Publication.id.in_(ids)).all()} if ids else {}
    uid = session.get('user_id')
    liked_ids = set()
    if uid and ids:
        liked_ids = {l.publication_id for l in Like.query.filter(
            Like.user_id == uid, Like.publication_id.in_(ids)).all()}
    def _etat(e):
        p = pubs.get(e.publication_id)
        if p is not None and not _peut_voir_publication(p, uid):
            p = None  # publication non accessible à ce visiteur : pas de boutons J'aime/commentaire
        return {'id': e.id,
                'pub_id': e.publication_id if p else None,
                'liked': bool(p) and e.publication_id in liked_ids,
                'likes': len(p.likes) if p else 0,
                'comments': len(p.commentaires) if p else 0,
                'vues': (p.vues or 0) if p else 0,
                'shares': (p.share_count or 0) if p else 0}
    return jsonify(success=True, photos=[dict({
        'url': url_for('static', filename='uploads/' + e.url),
        'pub_id': e.publication_id,
        'date': e.date_creation.strftime('%d/%m/%Y') if e.date_creation else ''
    }, **_etat(e)) for e in entries])

@main_bp.route('/api/photo/<type_photo>/publication', methods=['POST'])
@login_required
def api_photo_publication(type_photo):
    """Garantit qu'une photo de profil/couverture du PROPRIÉTAIRE possède une publication,
    afin que J'aime / commentaires / partages fonctionnent vraiment dessus.
    Si la photo n'était pas publiée (option « publier mes changements de photo » désactivée
    ou photo antérieure à l'historique), la publication est créée visible par les AMIS uniquement
    (jamais publique) : eux seuls peuvent aimer, commenter et recevoir un partage."""
    if type_photo not in ('avatar', 'couverture'):
        return jsonify(success=False, error="Type invalide."), 400
    data = request.get_json(silent=True) or {}
    type_pub = 'photo_profil' if type_photo == 'avatar' else 'photo_couverture'
    contenu = "a changé sa photo de profil" if type_photo == 'avatar' else "a changé sa photo de couverture"
    entry = None
    hid = data.get('historique_id')
    if hid:
        entry = PhotoHistorique.query.filter_by(id=hid, user_id=current_user.id, type_photo=type_photo).first()
        if not entry:
            return jsonify(success=False, error="Photo introuvable."), 404
        filename = entry.url
    else:
        filename = current_user.avatar if type_photo == 'avatar' else current_user.couverture
        if not filename or filename in ('default.png', 'default_cover.png'):
            return jsonify(success=False, error="Aucune photo personnalisée."), 400
        entry = (PhotoHistorique.query.filter_by(user_id=current_user.id, type_photo=type_photo, url=filename)
                 .order_by(PhotoHistorique.date_creation.desc()).first())
    pub = db.session.get(Publication, entry.publication_id) if (entry and entry.publication_id) else None
    if not pub:
        pub = Publication.query.filter_by(user_id=current_user.id, type_publication=type_pub, media_url=filename).first()
    if not pub:
        pub = Publication(contenu=contenu, media_url=filename, user_id=current_user.id,
                          type_publication=type_pub, confidentialite='amis')
        db.session.add(pub)
        db.session.flush()
    # Publications auto-créées auparavant en « privé » : on les ouvre aux amis pour que le partage fonctionne
    if pub.confidentialite == 'prive' and pub.contenu == contenu:
        pub.confidentialite = 'amis'
    if not entry:
        entry = PhotoHistorique(user_id=current_user.id, type_photo=type_photo, url=filename, publication_id=pub.id)
        db.session.add(entry)
    elif entry.publication_id != pub.id:
        entry.publication_id = pub.id
    db.session.commit()
    liked = Like.query.filter_by(user_id=current_user.id, publication_id=pub.id).first() is not None
    return jsonify(success=True, pub_id=pub.id, id=entry.id,
                   url=url_for('static', filename='uploads/' + filename),
                   liked=liked, likes=len(pub.likes), comments=len(pub.commentaires),
                   vues=pub.vues or 0, shares=pub.share_count or 0)

@main_bp.route('/api/profil/<username>/photo/<type_photo>/publication', methods=['POST'])
@login_required
def api_photo_publication_visiteur(username, type_photo):
    """AJOUT ADDITIF : même rôle que api_photo_publication, mais pour la photo de profil/couverture
    d'un AUTRE utilisateur. Sans cela, un visiteur ne pouvait ni aimer, ni commenter, ni partager une
    photo qui n'avait pas encore de publication (le fil et le profil partagent ensuite la même publication,
    donc les mêmes J'aime / commentaires / partages). La publication créée garde la date de la photo
    pour ne pas remonter en haut du fil."""
    if type_photo not in ('avatar', 'couverture'):
        return jsonify(success=False, error="Type invalide."), 400
    cible = User.query.filter_by(username=username).first()
    if not cible:
        return jsonify(success=False, error="Utilisateur introuvable."), 404
    data = request.get_json(silent=True) or {}
    type_pub = 'photo_profil' if type_photo == 'avatar' else 'photo_couverture'
    contenu = "a changé sa photo de profil" if type_photo == 'avatar' else "a changé sa photo de couverture"
    entry = None
    hid = data.get('historique_id')
    if hid:
        entry = PhotoHistorique.query.filter_by(id=hid, user_id=cible.id, type_photo=type_photo).first()
        if not entry:
            return jsonify(success=False, error="Photo introuvable."), 404
        filename = entry.url
    else:
        filename = cible.avatar if type_photo == 'avatar' else cible.couverture
        if not filename or filename in ('default.png', 'default_avatar.png', 'default_cover.png'):
            return jsonify(success=False, error="Aucune photo personnalisée."), 400
        entry = (PhotoHistorique.query.filter_by(user_id=cible.id, type_photo=type_photo, url=filename)
                 .order_by(PhotoHistorique.date_creation.desc()).first())
    try:
        pub = db.session.get(Publication, entry.publication_id) if (entry and entry.publication_id) else None
        if not pub:
            pub = Publication.query.filter_by(user_id=cible.id, type_publication=type_pub, media_url=filename).first()
        if not pub:
            pub = Publication(contenu=contenu, media_url=filename, user_id=cible.id,
                              type_publication=type_pub, confidentialite='public',
                              date_creation=(entry.date_creation if (entry and entry.date_creation) else datetime.utcnow()))
            db.session.add(pub)
            db.session.flush()
        if not _peut_voir_publication(pub, current_user.id):
            db.session.rollback()
            return jsonify(success=False, error="Cette photo n'est visible que par ses amis."), 403
        if entry and entry.publication_id != pub.id:
            entry.publication_id = pub.id
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG api_photo_publication_visiteur : {e}")
        return jsonify(success=False, error="Impossible de préparer cette photo pour le moment."), 500
    liked = Like.query.filter_by(user_id=current_user.id, publication_id=pub.id).first() is not None
    return jsonify(success=True, pub_id=pub.id, id=(entry.id if entry else None),
                   url=url_for('static', filename='uploads/' + filename),
                   liked=liked, likes=len(pub.likes), comments=len(pub.commentaires),
                   vues=pub.vues or 0, shares=pub.share_count or 0)

