@main_bp.route('/parametres/verifier-cles/<int:user_id>')
def verifier_cles_discussion(user_id):
    if 'user_id' not in session:
        return jsonify(success=False, error="Non connecté."), 401
    import hashlib
    paire = '-'.join(sorted([str(session['user_id']), str(user_id)]))
    empreinte = hashlib.sha256(paire.encode()).hexdigest().upper()
    code_affiche = ' '.join([empreinte[i:i+5] for i in range(0, 60, 5)])
    return jsonify(success=True, code_securite=code_affiche)

# ── AJOUT ADDITIF : « Publications » et « Pages » des personnes trouvées par la recherche (Explorer) ──
_EXT_IMAGES = ('.jpg', '.jpeg', '.png', '.gif', '.webp', '.bmp', '.avif')
_EXT_VIDEOS = ('.mp4', '.webm', '.mov')

def _explore_contenus_recherche(utilisateurs, requete, viewer_id):
    """(publications, pages) liés aux personnes trouvées. Respecte la confidentialité des publications.
    Ne lève jamais d'exception : en cas de problème, la page Explorer s'affiche quand même."""
    pubs, pages = [], []
    par_id = {u.id: u for u in (utilisateurs or [])[:8]}
    ids = list(par_id.keys())

    # ── Publications visibles par le visiteur ──
    try:
        if ids:
            candidates = (Publication.query.filter(Publication.user_id.in_(ids))
                          .order_by(Publication.id.desc()).limit(150).all())
            exclues = set()
            try:
                _assurer_tables_menu()
                for rg in PubReglage.query.filter(PubReglage.publication_id.in_([p.id for p in candidates])).all():
                    if rg.archive or rg.corbeille_le:
                        exclues.add(rg.publication_id)
            except Exception:
                db.session.rollback()
            visibles = []
            for p in candidates:
                if p.id in exclues or getattr(p, 'is_removed', False):
                    continue
                if getattr(p, 'type_publication', None) == 'media_enfant':
                    continue
                if not _peut_voir_publication(p, viewer_id):
                    continue
                visibles.append(p)
                if len(visibles) >= 30:
                    break
            pids = [p.id for p in visibles]
            likes, coms = {}, {}
            if pids:
                try:
                    likes = dict(db.session.query(Like.publication_id, func.count(Like.id))
                                 .filter(Like.publication_id.in_(pids)).group_by(Like.publication_id).all())
                    coms = dict(db.session.query(Commentaire.publication_id, func.count(Commentaire.id))
                                .filter(Commentaire.publication_id.in_(pids)).group_by(Commentaire.publication_id).all())
                except Exception as e:
                    db.session.rollback()
                    print(f"DEBUG explore : compteurs des publications indisponibles : {e}")
            for p in visibles:
                u = par_id.get(p.user_id)
                if u is None:
                    continue
                media = (p.media_url or '')
                bas = media.lower()
                est_video = bas.endswith(_EXT_VIDEOS)
                if not (est_video or bas.endswith(_EXT_IMAGES)):
                    media = ''          # document / audio : pas d'aperçu visuel
                avatar = ''
                if getattr(u, 'profile_pic', None):
                    avatar = url_for('static', filename='uploads/profiles/' + u.profile_pic)
                pubs.append({
                    'id': p.id, 'auteur_id': u.id,
                    'auteur': (u.nom_complet or u.username or 'Utilisateur'),
                    'username': u.username, 'avatar': avatar,
                    'verifie': bool(getattr(u, 'badge_expire', None)),
                    'contenu': (p.contenu or '').strip(),
                    'media': url_for('static', filename='uploads/' + media) if media else '',
                    'est_video': bool(media and est_video),
                    'date': _il_y_a(getattr(p, 'date_creation', None)),
                    'likes': int(likes.get(p.id, 0) or 0),
                    'commentaires': int(coms.get(p.id, 0) or 0),
                    'url_profil': url_for('main.profile', username=u.username),
                    'url_commentaires': url_for('main.commentaires', pub_id=p.id),
                })
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG explore : publications de la recherche ignorées : {e}")
        pubs = []

    # ── Pages dont le nom correspond OU créées par une personne trouvée ──
    conn = None
    try:
        cible = _fn_page_endpoint()
        filtres, params = ["nom_page LIKE ?"], [f"%{requete}%"]
        if ids:
            filtres.append("createur_id IN (%s)" % ','.join('?' * len(ids)))
            params += ids
        conn = sqlite3.connect('database.db')
        conn.row_factory = sqlite3.Row
        lignes = conn.execute("SELECT rowid AS _rid, * FROM pages WHERE " + " OR ".join(filtres) +
                              " ORDER BY rowid DESC LIMIT 30", params).fetchall()
        for l in lignes:
            d = dict(l)
            pid = d.get('id') or d.get('_rid')
            lien = ''
            if cible:
                try:
                    lien = url_for(cible[0], **{cible[1]: pid})
                except Exception:
                    lien = ''
            proprio = par_id.get(d.get('createur_id'))
            logo = d.get('photo_profil') or 'default_page.png'
            pages.append({'id': pid, 'nom': d.get('nom_page') or 'Page', 'categorie': d.get('categorie') or '',
                          'url': lien, 'photo': url_for('static', filename='uploads/pages/' + logo),
                          'proprietaire': ((proprio.nom_complet or proprio.username) if proprio else '')})
    except Exception as e:
        print(f"DEBUG explore : pages de la recherche ignorées : {e}")
        pages = []
    finally:
        try:
            if conn: conn.close()
        except Exception:
            pass
    return pubs, pages

@main_bp.route('/explore')
def explore():
    search_query = request.args.get('search_query', '').strip()
    active_tab = request.args.get('tab', 'tout')
    est_suggestion = bool(request.args.get('suggest'))   # appel « suggestions en tapant » : on reste léger
    utilisateurs_trouves = []
    if search_query:
        # Recherche par nom d'utilisateur OU par nom complet (insensible à la casse)
        utilisateurs_trouves = User.query.filter(or_(
            User.username.ilike(f'%{search_query}%'),
            User.nom_complet.ilike(f'%{search_query}%'))).limit(50).all()
        utilisateurs_trouves = [u for u in utilisateurs_trouves if not _compte_masque(u.id)]   # AJOUT : comptes masqués
    # AJOUT : les tendances respectent la confidentialité (Amis / Famille / Moi uniquement)
    _viewer_tendances = current_user.id if current_user.is_authenticated else None
    publications_tendances = [p for p in Publication.query.order_by(Publication.id.desc()).limit(60).all()
                              if getattr(p, 'type_publication', None) != 'media_enfant' and _peut_voir_publication(p, _viewer_tendances)][:5]
    # Identifiants des amis de l'utilisateur connecté : permet d'afficher « Ami » au lieu de « Ajouter »
    amis_ids = _amis_ids(current_user.id) if current_user.is_authenticated else set()

    # AJOUT ADDITIF (interface de recherche façon Facebook) : toutes ces données sont facultatives,
    # le gabarit fonctionne même si l'une d'elles est vide. Aucune erreur ici ne doit casser la page.
    recentes, suggestions_amis, pour_vous = [], [], []
    try:
        if current_user.is_authenticated:
            _enrichir_utilisateurs(utilisateurs_trouves, current_user.id, amis_ids)
            if search_query and not est_suggestion:
                _enregistrer_recherche(current_user.id, search_query)
            if not search_query:
                recentes = _recentes_pour(current_user.id)
                suggestions_amis = _suggestions_amis_pour_feed(current_user.id, amis_ids, nb=20)
                _enrichir_utilisateurs(suggestions_amis, current_user.id, amis_ids)
                pour_vous = _pour_vous_pour(current_user.id)
                _enrichir_utilisateurs(pour_vous, current_user.id, amis_ids)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG explore enrichissement ignoré : {e}")

    # AJOUT ADDITIF : publications et pages des personnes trouvées (onglets Tout / Publications / Pages)
    pubs_recherche, pages_recherche = [], []
    if search_query and not est_suggestion:
        pubs_recherche, pages_recherche = _explore_contenus_recherche(utilisateurs_trouves, search_query, _viewer_tendances)

    suivre_url_modele = msg_url_modele = None
    try:
        suivre_url_modele = url_for('main.api_suivre', user_id=987654321).replace('987654321', '__ID__')
        msg_url_modele = url_for('main.messagerie', destinataire_id=987654321).replace('987654321', '__ID__')
    except Exception:
        pass
    return render_template('explore.html', utilisateurs_trouves=utilisateurs_trouves,
        publications=publications_tendances, publications_tendances=publications_tendances,
        search_query=search_query, active_tab=active_tab, amis_ids=amis_ids,
        recentes=recentes, suggestions_amis=suggestions_amis, pour_vous=pour_vous,
        suivre_url_modele=suivre_url_modele, messagerie_url_modele=msg_url_modele,
        reels=[], photos=[], groupes=[], mentions=[], pages=pages_recherche, annonces=[],
        pubs_recherche=pubs_recherche, pages_recherche=pages_recherche)

@main_bp.route('/send-sms', methods=['POST'])
def send_sms():
    data = request.get_json()
    numero = data.get('phone')

    if not numero:
        return jsonify({'success': False, 'message': 'Numéro de téléphone manquant'}), 400

    code_secret = str(random.randint(100000, 999999))

    # CORRECTION : stockage en mémoire serveur (résistant au blocage de cookie)
    _dernier_otp["code"] = code_secret
    _dernier_otp["expire"] = datetime.utcnow() + timedelta(minutes=_otp_duree_minutes)
    _dernier_otp["contact"] = numero

    # On garde aussi la session en secours (au cas où le cookie passe)
    session['otp_code'] = code_secret

    print("\n" + "="*40)
    print(f" 📱 SMS ENVOYÉ AU NUMÉRO : {numero}")
    print(f" 🔑 CODE DE VALIDATION FACENET : {code_secret}")
    print("="*40 + "\n")

    return jsonify({'success': True, 'message': 'Code généré avec succès !'})

@main_bp.route('/send-email', methods=['POST'])
def send_email():
    data = request.get_json()
    email = data.get('email')
    if not email:
        return jsonify({'success': False, 'message': 'Adresse e-mail manquante'}), 400
    code_secret = str(random.randint(100000, 999999))
    session['otp_code'] = code_secret
    _dernier_otp["code"] = code_secret
    _dernier_otp["expire"] = datetime.utcnow() + timedelta(minutes=_otp_duree_minutes)
    _dernier_otp["contact"] = email
    print("\n" + "="*40)
    print(f" 📧 EMAIL ENVOYÉ À L'ADRESSE : {email}")
    print(f" 🔑 CODE DE VALIDATION FACENET : {code_secret}")
    print("="*40 + "\n")
    # AJOUT : en plus du code affiché ci-dessus dans le terminal, envoi par e-mail
    # SI les identifiants mail sont configurés (.env). Sinon : comportement d'origine.
    session.pop('otp_contact', None)
    try:
        from email_otp import envoyer_code_email, mail_est_configure
        if mail_est_configure():
            if envoyer_code_email(email, code_secret,
                                  "Votre code de vérification FaceNet",
                                  "Bienvenue sur FaceNet ! Voici votre code pour créer votre compte."):
                session['otp_contact'] = email  # le code est lié à l'adresse réellement contactée
            elif current_app.debug:
                # Mode local : l'inscription n'est jamais bloquée, le code est dans le terminal
                print(" ⚠️  E-mail non envoyé (mode local) -> utilise le code affiché ci-dessus.")
            else:
                return jsonify({'success': False, 'message': "L'e-mail n'a pas pu être envoyé. Réessayez dans un instant."}), 500
    except ImportError:
        pass  # Flask-Mail absent : comportement d'origine (code affiché dans le terminal)
    return jsonify({'success': True, 'message': 'Code généré avec succès !'})

