@main_bp.route('/api/facenet-create-page', methods=['POST'])
def facenet_create_page():
    user_id = session.get('user_id')
    nom_page = request.form.get('nom_page')
    categorie = request.form.get('categorie')
    site_web = request.form.get('site_web', '')
    photo_profil_filename = 'default_page.png'
    photo_couv_filename = 'default_cover.png'
    if 'photo_profil' in request.files:
        file = request.files['photo_profil']
        if file.filename != '':
            photo_profil_filename = 'avatar_' + secure_filename(file.filename)
            file.save(os.path.join(UPLOAD_PAGE_FOLDER, photo_profil_filename))
    if 'photo_couverture' in request.files:
        file = request.files['photo_couverture']
        if file.filename != '':
            photo_couv_filename = 'cover_' + secure_filename(file.filename)
            file.save(os.path.join(UPLOAD_PAGE_FOLDER, photo_couv_filename))
    if not nom_page or not categorie:
        return jsonify({'error': 'Le nom et la thématique sont obligatoires.'}), 400
    try:
        conn = sqlite3.connect('database.db')
        cursor = conn.cursor()
        cursor.execute("""INSERT INTO pages (nom_page, categorie, site_web, photo_profil, photo_couverture, createur_id)
                          VALUES (?, ?, ?, ?, ?, ?)""",
                       (nom_page, categorie, site_web, photo_profil_filename, photo_couv_filename, user_id))
        conn.commit()
        conn.close()
        return jsonify({'success': 'Votre Espace FaceNet a bien été créé avec succès !'})
    except sqlite3.Error as e:
        if 'conn' in locals(): conn.close()
        return jsonify({'error': f"Erreur de base de données : {str(e)}"}), 500

@main_bp.route('/like/<int:pub_id>', methods=['POST'])
def like_post(pub_id):
    like = Like.query.filter_by(user_id=session['user_id'], pub_id=pub_id).first()
    if like:
        db.session.delete(like); db.session.commit(); action = 'removed'
    else:
        new_like = Like(user_id=session['user_id'], pub_id=pub_id)
        db.session.add(new_like); db.session.commit(); action = 'added'
    count = Like.query.filter_by(pub_id=pub_id).count()
    return jsonify({'likes': count, 'action': action})

