# AJOUT ADDITIF : bouton d'action du profil (table `bouton_action`)
# ══════════════════════════════════════════════════════════════════════
from models import BoutonAction, ACTION_BUTTON_CATALOG, ACTION_BUTTON_GROUPS
from models import normaliser_bouton_action, donnees_bouton_action

_table_bouton_action_ok = False
def _assurer_table_bouton_action():
    global _table_bouton_action_ok
    if _table_bouton_action_ok:
        return
    try:
        BoutonAction.__table__.create(bind=db.engine, checkfirst=True)
        _table_bouton_action_ok = True
    except Exception as e:
        print(f"DEBUG: création table bouton_action impossible : {e}")

@main_bp.route('/api/bouton-action', methods=['POST'])
@login_required
def api_bouton_action():
    """Enregistre (ou supprime) le bouton d'action du profil de l'utilisateur connecté."""
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        data = request.form
    type_ = (data.get('type') or '').strip()
    valeur = data.get('valeur')
    _assurer_table_bouton_action()
    try:
        if not type_:
            BoutonAction.query.filter_by(user_id=current_user.id).delete()
            db.session.commit()
            return jsonify(success=True, supprime=True)
        valeur_norm, erreur = normaliser_bouton_action(type_, valeur if isinstance(valeur, str) else '')
        if erreur:
            return jsonify(success=False, error=erreur), 400
        ba = db.session.get(BoutonAction, current_user.id)
        if ba is None:
            ba = BoutonAction(user_id=current_user.id)
            db.session.add(ba)
        ba.type = type_
        ba.valeur = valeur_norm
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: enregistrement bouton d'action impossible : {e}")
        return jsonify(success=False, error="Enregistrement impossible, veuillez réessayer."), 500
    return jsonify(success=True, bouton=donnees_bouton_action(current_user.id))

