# AJOUT ADDITIF : partenaire identifié dans « Situation amoureuse »
# (ami réel vérifié côté serveur, ou nom saisi à la main APRÈS confirmation explicite)
# ══════════════════════════════════════════════════════════════════════
from models import ProfilPartenaire

STATUTS_AVEC_PARTENAIRE = ('En couple', 'En concubinage', 'Fiancé(e)', 'Marié(e)', "C'est compliqué")

_table_profil_partenaire_ok = False
def _assurer_table_profil_partenaire():
    global _table_profil_partenaire_ok
    if _table_profil_partenaire_ok:
        return
    try:
        ProfilPartenaire.__table__.create(bind=db.engine, checkfirst=True)
        _table_profil_partenaire_ok = True
    except Exception as e:
        print(f"DEBUG: création table profil_partenaire impossible : {e}")

def _partenaire_profil(user):
    """Partenaire à afficher : {'id','nom','username','avatar','manuel'} ou None.
    Un ami est relu dans la table user (son nom/avatar restent à jour) ; sans compte, on garde le nom enregistré."""
    try:
        _assurer_table_profil_partenaire()
        row = db.session.get(ProfilPartenaire, user.id)
    except Exception as e:
        print(f"DEBUG: lecture profil_partenaire impossible : {e}")
        db.session.rollback()
        return None
    if not row or (user.situation_amoureuse or '') not in STATUTS_AVEC_PARTENAIRE:
        return None
    if row.partenaire_id:
        ami = db.session.get(User, row.partenaire_id)
        if ami:
            return {'id': ami.id, 'nom': ami.nom_complet or ami.username, 'username': ami.username,
                    'avatar': ami.avatar or 'default_avatar.png', 'manuel': False}
    nom = (row.partenaire_nom or '').strip()
    if not nom:
        return None
    return {'id': None, 'nom': nom, 'username': None, 'avatar': None, 'manuel': bool(row.manuel)}

def _enregistrer_partenaire(user, form):
    """Enregistre / retire le partenaire envoyé par le formulaire (champ marqueur 'partenaire_present').
    - ami : doit réellement figurer dans la liste d'amis de l'utilisateur (vérifié ici, pas seulement dans le navigateur) ;
    - hors amis : nom libre accepté seulement avec la confirmation explicite 'partenaire_confirme' ;
    - statut sans partenaire (célibataire, divorcé…) : le partenaire est retiré."""
    if form.get('partenaire_present') != '1':
        return
    situation = (form.get('situation_amoureuse') or user.situation_amoureuse or '').strip()
    _assurer_table_profil_partenaire()
    row = db.session.get(ProfilPartenaire, user.id)
    if situation not in STATUTS_AVEC_PARTENAIRE:
        if row:
            db.session.delete(row)
        return
    pid_brut = (form.get('partenaire_id') or '').strip()
    nom_brut = ' '.join((form.get('partenaire_nom') or '').split())
    if pid_brut:
        if not pid_brut.isdigit() or int(pid_brut) not in _amis_ids(user.id):
            flash("La personne identifiée doit faire partie de vos amis : votre partenaire n'a pas été enregistré(e).")
            return
        ami = db.session.get(User, int(pid_brut))
        if not ami:
            flash("Cette personne est introuvable : votre partenaire n'a pas été enregistré(e).")
            return
        p_id, p_nom, p_manuel = ami.id, (ami.nom_complet or ami.username or '')[:80], False
    elif nom_brut:
        deja_enregistre = bool(row and not row.partenaire_id and (row.partenaire_nom or '') == nom_brut)
        if not deja_enregistre:
            if form.get('partenaire_confirme') != '1':
                flash("Pour identifier une personne qui n'est pas dans vos amis, vous devez confirmer que c'est bien elle : rien n'a été enregistré.")
                return
            if not (2 <= len(nom_brut) <= 80) or '<' in nom_brut or '>' in nom_brut:
                flash("Le nom du partenaire doit contenir entre 2 et 80 caractères (sans < ni >).")
                return
            if nom_brut.casefold() == (user.nom_complet or '').strip().casefold():
                flash("Le partenaire ne peut pas être vous-même.")
                return
        p_id, p_nom, p_manuel = None, nom_brut, True
    else:
        if row:
            db.session.delete(row)
        return
    if row is None:
        row = ProfilPartenaire(user_id=user.id)
        db.session.add(row)
    row.partenaire_id, row.partenaire_nom, row.manuel = p_id, p_nom, p_manuel
    row.date_maj = datetime.utcnow()

def _visibilite_profil(extra):
    """{champ: bool}. Sans choix enregistré, tout reste visible (comportement d'avant)."""
    vis = {c: True for c in CHAMPS_PROFIL_MASQUABLES}
    try:
        brut = json.loads(extra.visibilite) if (extra and extra.visibilite) else {}
    except (TypeError, ValueError):
        brut = {}
    if isinstance(brut, dict):
        for c in CHAMPS_PROFIL_MASQUABLES:
            if c in brut:
                vis[c] = bool(brut[c])
    return vis

def _donnees_edition_profil(user):
    """(visibilite, parcours) pour préremplir les formulaires de modification."""
    try:
        extra = _profil_extra(user.id)
    except Exception as e:
        print(f"DEBUG: lecture profil_extra impossible : {e}")
        db.session.rollback()
        extra = None
    parcours = {c: (getattr(extra, c, None) or '') for c in CHAMPS_PARCOURS}
    return _visibilite_profil(extra), parcours

def _infos_profil_publiques_base(user):
    """Informations réellement affichables sur le profil (choix de l'utilisateur appliqués)."""
    try:
        extra = _profil_extra(user.id)
    except Exception as e:
        print(f"DEBUG: lecture profil_extra impossible : {e}")
        db.session.rollback()
        extra = None
    vis = _visibilite_profil(extra)

    def v(champ, valeur):
        if isinstance(valeur, str):
            valeur = valeur.strip()
        return valeur if (vis.get(champ, True) and valeur) else None

    def periode(prefixe):
        if not vis.get(prefixe, True) or not getattr(user, prefixe, None):
            return None
        return _periode_fr(getattr(extra, prefixe + '_debut', None), getattr(extra, prefixe + '_fin', None))

    try:
        reseaux = json.loads(user.reseaux_sociaux) if user.reseaux_sociaux else {}
        if not isinstance(reseaux, dict):
            reseaux = {}
    except (TypeError, ValueError):
        reseaux = {}

    return {
        'nom': v('nom', user.nom),
        'prenom': v('prenom', user.prenom),
        'birth_date': _date_complete_fr(user.birth_date) if (vis['birth_date'] and user.birth_date) else None,
        'sexe': v('sexe', user.sexe),
        'situation_amoureuse': v('situation_amoureuse', user.situation_amoureuse),
        'partenaire': (_partenaire_profil(user) if (vis.get('situation_amoureuse', True) and user.situation_amoureuse) else None),
        'langues': v('langues', user.langues),
        'email': v('email', user.email),
        'phone': v('phone', user.phone),
        'site_web': v('site_web', user.site_web),
        'social_links': reseaux if vis['reseaux_sociaux'] else {},
        'ville': v('ville', user.ville),
        'localisation': v('localisation', user.localisation),
        'emploi_actuel': v('emploi_actuel', user.emploi_actuel),
        'entreprise': v('entreprise', user.entreprise),
        'entreprise_periode': periode('entreprise'),
        'ecole': v('ecole', user.ecole),
        'ecole_periode': periode('ecole'),
        'universite': v('universite', user.universite),
        'universite_periode': periode('universite'),
        'groupes_musicaux_preferes': v('groupes_musicaux_preferes', user.groupes_musicaux_preferes),
        'films_preferes': v('films_preferes', user.films_preferes),
        'jeux_video_preferes': v('jeux_video_preferes', user.jeux_video_preferes),
        'emissions_tv_preferees': v('emissions_tv_preferees', user.emissions_tv_preferees),
    }

def _enregistrer_profil_extra(user, form):
    """Enregistre les dates de parcours et les choix afficher/masquer envoyés par le formulaire.
    Seuls les champs listés dans 'vis_champs' sont modifiés (un formulaire qui ne propose
    pas un champ ne peut donc jamais changer sa visibilité par erreur)."""
    extra = _profil_extra(user.id, creer=True)
    champs_envoyes = [c.strip() for c in (form.get('vis_champs') or '').split(',') if c.strip()]
    if champs_envoyes:
        vis = _visibilite_profil(extra)
        for c in champs_envoyes:
            if c in CHAMPS_PROFIL_MASQUABLES:
                vis[c] = ('vis_' + c) in form
        extra.visibilite = json.dumps(vis)
    for prefixe in ('ecole', 'universite', 'entreprise'):
        cle_d, cle_f = prefixe + '_debut', prefixe + '_fin'
        if cle_d in form:
            setattr(extra, cle_d, _normaliser_mois(form.get(cle_d)))
        if cle_f in form:
            setattr(extra, cle_f, _normaliser_mois(form.get(cle_f)))
        d, f = getattr(extra, cle_d), getattr(extra, cle_f)
        if d and f and f < d:
            setattr(extra, cle_f, None)
            flash("La date de fin ne peut pas précéder la date de début : elle n'a pas été enregistrée.")

