@main_bp.route('/profil-id/<int:user_id>')
def profil_par_id(user_id):
    cible = db.session.get(User, user_id)
    if cible is None:
        abort(404)
    nom = cible.username or str(cible.id)
    if re.fullmatch(r'[A-Za-z0-9_.\-]+', nom or '') and cible.username:
        # Nom simple : on redirige vers l'adresse habituelle /profile/<username>
        return redirect(url_for('main.profile', username=cible.username))
    # Nom avec caractères spéciaux : on affiche le profil directement,
    # avec la valeur exacte de la base (aucun encodage d'adresse en jeu).
    return profile(nom)

# ──────────────────────────────────────────────────────────────
#  AJOUT ADDITIF : statistiques des publications du propriétaire
#  (menu « Paramètres du profil »). Lecture seule, aucune table modifiée.
#  Répond toujours en JSON : available=False => « Statistiques indisponibles ».
# ──────────────────────────────────────────────────────────────
@main_bp.route('/api/profil/statistiques')
@login_required
def api_profil_statistiques():
    try:
        # is_removed peut valoir NULL sur les anciennes lignes : on filtre côté Python
        # (un filtre SQL « is_removed = False » excluait ces publications).
        pubs = [p for p in (Publication.query
                .filter_by(user_id=current_user.id)
                .order_by(Publication.id.desc()).all())
                if not getattr(p, 'is_removed', False) and getattr(p, 'type_publication', None) != 'media_enfant']
        reglages = {}
        try:
            _assurer_tables_menu()
            ids_all = [p.id for p in pubs]
            if ids_all:
                reglages = {rg.publication_id: rg for rg in
                            PubReglage.query.filter(PubReglage.publication_id.in_(ids_all)).all()}
        except Exception:
            db.session.rollback()
            reglages = {}
        pubs = [p for p in pubs if not (reglages.get(p.id) and reglages[p.id].corbeille_le)]
        if not pubs:
            return jsonify(success=True, available=False, reason='no_posts')

        ids = [p.id for p in pubs]
        likes = dict(db.session.query(Like.publication_id, func.count(Like.id))
                     .filter(Like.publication_id.in_(ids)).group_by(Like.publication_id).all())
        coms = dict(db.session.query(Commentaire.publication_id, func.count(Commentaire.id))
                    .filter(Commentaire.publication_id.in_(ids)).group_by(Commentaire.publication_id).all())
        vues = {}
        try:
            from models import PublicationVideoView
            vues = dict(db.session.query(PublicationVideoView.publication_id, func.count(PublicationVideoView.id))
                        .filter(PublicationVideoView.publication_id.in_(ids))
                        .group_by(PublicationVideoView.publication_id).all())
        except Exception:
            db.session.rollback()
            vues = {}

        def extrait(p):
            t = (p.contenu or '').strip()
            if t:
                return (t[:70] + '…') if len(t) > 70 else t
            return 'Reel' if getattr(p, 'est_reel', False) else ('Photo / vidéo' if p.media_url else 'Publication')

        items = []
        for p in pubs:
            rg = reglages.get(p.id)
            items.append({
                'id': p.id,
                'extrait': extrait(p),
                'date': p.date_creation.strftime('%d/%m/%Y') if p.date_creation else '',
                'likes': int(likes.get(p.id, 0)),
                'commentaires': int(coms.get(p.id, 0)),
                'partages': int(p.share_count or 0),
                'vues': int(vues.get(p.id, 0)),
                'epingle': bool(rg and rg.epingle),
                'archive': bool(rg and rg.archive),
            })
        visibles = [i for i in items if not i['archive']]
        totaux = {
            'publications': len(visibles),
            'likes': sum(i['likes'] for i in items),
            'commentaires': sum(i['commentaires'] for i in items),
            'partages': sum(i['partages'] for i in items),
            'vues': sum(i['vues'] for i in items),
        }
        return jsonify(success=True, available=True, totaux=totaux, publications=visibles[:50])
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: statistiques du profil indisponibles : {e}")
        return jsonify(success=True, available=False, reason='error')

# ══════════════════════════════════════════════════════════════
#  AJOUT ADDITIF : LIVE STREAMING (hôte + spectateurs, chat, likes, stats réelles)
#  Tables créées automatiquement au premier appel (checkfirst). Rien d'existant modifié.
#  Vidéo : WebRTC pair-à-pair, signalisation via la base (voir /api/stream/signal).
# ══════════════════════════════════════════════════════════════
class LiveStream(db.Model):
    __tablename__ = 'live_stream'
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, nullable=False, index=True)
    titre = db.Column(db.String(150), nullable=True)
    statut = db.Column(db.String(10), default='live', nullable=False)   # live | ended
    started_at = db.Column(db.DateTime, default=datetime.utcnow)
    ended_at = db.Column(db.DateTime, nullable=True)
    last_seen = db.Column(db.DateTime, default=datetime.utcnow)
    like_count = db.Column(db.Integer, default=0, nullable=False)
    peak_viewers = db.Column(db.Integer, default=0, nullable=False)
    total_views = db.Column(db.Integer, default=0, nullable=False)
    last_fps = db.Column(db.Integer, nullable=True)
    last_bitrate = db.Column(db.Integer, nullable=True)

class LiveMessage(db.Model):
    __tablename__ = 'live_message'
    id = db.Column(db.Integer, primary_key=True)
    stream_id = db.Column(db.Integer, nullable=False, index=True)
    user_id = db.Column(db.Integer, nullable=False)
    message = db.Column(db.String(500), nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

class LiveViewer(db.Model):
    __tablename__ = 'live_viewer'
    __table_args__ = (db.UniqueConstraint('stream_id', 'viewer_key', name='uq_live_viewer'),)
    id = db.Column(db.Integer, primary_key=True)
    stream_id = db.Column(db.Integer, nullable=False, index=True)
    viewer_key = db.Column(db.String(40), nullable=False)
    user_id = db.Column(db.Integer, nullable=True)
    last_seen = db.Column(db.DateTime, default=datetime.utcnow)

class LiveSignal(db.Model):
    __tablename__ = 'live_signal'
    id = db.Column(db.Integer, primary_key=True)
    stream_id = db.Column(db.Integer, nullable=False, index=True)
    to_key = db.Column(db.String(40), nullable=False, index=True)    # 'host' ou clé spectateur
    from_key = db.Column(db.String(40), nullable=False)
    kind = db.Column(db.String(12), nullable=False)                  # offer | answer | ice
    payload = db.Column(db.Text, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

_tables_live_ok = False
_LIVE_TIMEOUT_S = 45      # hôte sans signe de vie => live terminé automatiquement
_LIVE_VIEWER_TTL_S = 20   # spectateur sans heartbeat => parti
_LIVE_MAX_PEERS = 8       # pair-à-pair : limite de spectateurs vidéo simultanés

def _assurer_tables_live():
    global _tables_live_ok
    if _tables_live_ok:
        return
    try:
        for t in (LiveStream.__table__, LiveMessage.__table__, LiveViewer.__table__, LiveSignal.__table__):
            t.create(bind=db.engine, checkfirst=True)
        _tables_live_ok = True
    except Exception as e:
        print(f"DEBUG: création tables live impossible : {e}")

def _live_iso(dt):
    return (dt.isoformat() + 'Z') if dt else None

def _live_nettoyer(stream):
    """Termine automatiquement un live dont l'hôte ne donne plus signe de vie."""
    if stream and stream.statut == 'live' and stream.last_seen and \
       (datetime.utcnow() - stream.last_seen).total_seconds() > _LIVE_TIMEOUT_S:
        stream.statut = 'ended'
        stream.ended_at = stream.last_seen
        db.session.commit()
    return stream

def _live_actif_de(user_id):
    _assurer_tables_live()
    s = (LiveStream.query.filter_by(user_id=user_id, statut='live')
         .order_by(LiveStream.id.desc()).first())
    return _live_nettoyer(s) if s and _live_nettoyer(s).statut == 'live' else None

def _live_spectateurs(stream_id):
    limite = datetime.utcnow() - timedelta(seconds=_LIVE_VIEWER_TTL_S)
    return LiveViewer.query.filter(LiveViewer.stream_id == stream_id, LiveViewer.last_seen >= limite).count()

def _live_cle(raw):
    cle = re.sub(r'[^A-Za-z0-9_-]', '', str(raw or ''))[:40]
    return cle

def _live_json(stream):
    return {'id': stream.id, 'titre': stream.titre or '', 'statut': stream.statut,
            'started_at': _live_iso(stream.started_at), 'like_count': stream.like_count,
            'viewer_count': _live_spectateurs(stream.id) if stream.statut == 'live' else 0,
            'peak_viewers': stream.peak_viewers, 'total_views': stream.total_views}

def _live_stream_hote(stream_id):
    """Retourne le live si l'utilisateur courant en est l'hôte, sinon None."""
    s = db.session.get(LiveStream, stream_id) if stream_id else None
    return s if s and s.user_id == current_user.id else None

@main_bp.route('/api/stream/start', methods=['POST'])
@login_required
def api_stream_start():
    try:
        _assurer_tables_live()
        data = request.get_json(silent=True) or {}
        # un seul live actif par utilisateur : on clôture les précédents
        for old in LiveStream.query.filter_by(user_id=current_user.id, statut='live').all():
            old.statut = 'ended'; old.ended_at = datetime.utcnow()
        s = LiveStream(user_id=current_user.id, titre=(data.get('titre') or '').strip()[:150])
        db.session.add(s); db.session.commit()
        return jsonify(success=True, stream=_live_json(s))
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: api_stream_start : {e}")
        return jsonify(success=False, error="Impossible de démarrer le live."), 500

@main_bp.route('/api/stream/stop', methods=['POST'])
@login_required
def api_stream_stop():
    try:
        _assurer_tables_live()
        data = request.get_json(silent=True) or {}
        s = _live_stream_hote(data.get('stream_id'))
        if not s:
            return jsonify(success=False, error="Live introuvable."), 404
        if s.statut == 'live':
            s.statut = 'ended'; s.ended_at = datetime.utcnow()
            db.session.commit()
        return jsonify(success=True, stream=_live_json(s))
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: api_stream_stop : {e}")
        return jsonify(success=False, error="Impossible d'arrêter le live."), 500

@main_bp.route('/api/stream/stats', methods=['POST'])
@login_required
def api_stream_stats():
    try:
        _assurer_tables_live()
        data = request.get_json(silent=True) or {}
        s = _live_stream_hote(data.get('stream_id'))
        if not s or s.statut != 'live':
            return jsonify(success=False, error="Live terminé ou introuvable."), 404
        def _int(v):
            try: return max(0, min(int(v), 10**7))
            except (TypeError, ValueError): return None
        s.last_fps = _int(data.get('fps')); s.last_bitrate = _int(data.get('bitrate'))
        s.last_seen = datetime.utcnow()
        nb = _live_spectateurs(s.id)
        s.peak_viewers = max(s.peak_viewers or 0, nb)
        db.session.commit()
        return jsonify(success=True, viewer_count=nb, total_views=s.total_views,
                       peak_viewers=s.peak_viewers, like_count=s.like_count)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: api_stream_stats : {e}")
        return jsonify(success=False, error="Statistiques indisponibles."), 500

def _live_msg_json(m, stream, users):
    u = users.get(m.user_id)
    avatar = None
    if u is not None and getattr(u, 'avatar', None):
        avatar = url_for('static', filename='uploads/' + u.avatar)
    return {'id': m.id, 'message': m.message,
            'auteur': (u.nom_complet or u.username) if u else 'Utilisateur',
            'avatar': avatar, 'user_role': 'host' if m.user_id == stream.user_id else None}

@main_bp.route('/api/stream/chat/send', methods=['POST'])
@login_required
def api_stream_chat_send():
    try:
        _assurer_tables_live()
        data = request.get_json(silent=True) or {}
        s = db.session.get(LiveStream, data.get('stream_id') or 0)
        if not s or _live_nettoyer(s).statut != 'live':
            return jsonify(success=False, error="Ce live est terminé."), 404
        txt = (data.get('message') or '').strip()[:500]
        if not txt:
            return jsonify(success=False, error="Message vide."), 400
        m = LiveMessage(stream_id=s.id, user_id=current_user.id, message=txt)
        db.session.add(m); db.session.commit()
        return jsonify(success=True, message=_live_msg_json(m, s, {current_user.id: current_user}))
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: api_stream_chat_send : {e}")
        return jsonify(success=False, error="Message non envoyé."), 500

@main_bp.route('/api/stream/chat/messages')
@login_required
def api_stream_chat_messages():
    try:
        _assurer_tables_live()
        sid = request.args.get('stream_id', type=int)
        after = request.args.get('after_id', 0, type=int)
        s = db.session.get(LiveStream, sid) if sid else None
        if not s:
            return jsonify(success=False, error="Live introuvable."), 404
        msgs = (LiveMessage.query.filter(LiveMessage.stream_id == s.id, LiveMessage.id > after)
                .order_by(LiveMessage.id.asc()).limit(100).all())
        ids = {m.user_id for m in msgs}
        users = {u.id: u for u in User.query.filter(User.id.in_(ids)).all()} if ids else {}
        return jsonify(success=True, messages=[_live_msg_json(m, s, users) for m in msgs],
                       statut=_live_nettoyer(s).statut)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: api_stream_chat_messages : {e}")
        return jsonify(success=False, error="Chat indisponible."), 500

@main_bp.route('/api/stream/like', methods=['POST'])
@login_required
def api_stream_like():
    try:
        _assurer_tables_live()
        data = request.get_json(silent=True) or {}
        s = db.session.get(LiveStream, data.get('stream_id') or 0)
        if not s or _live_nettoyer(s).statut != 'live':
            return jsonify(success=False, error="Ce live est terminé."), 404
        s.like_count = (s.like_count or 0) + 1
        db.session.commit()
        return jsonify(success=True, like_count=s.like_count)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: api_stream_like : {e}")
