@main_bp.route('/api/stream/join', methods=['POST'])
@login_required
def api_stream_join():
    """Heartbeat d'un spectateur (à appeler toutes les ~8 s)."""
    try:
        _assurer_tables_live()
        data = request.get_json(silent=True) or {}
        s = db.session.get(LiveStream, data.get('stream_id') or 0)
        cle = _live_cle(data.get('viewer_key'))
        if not s or not cle or _live_nettoyer(s).statut != 'live':
            return jsonify(success=False, error="Ce live est terminé."), 404
        v = LiveViewer.query.filter_by(stream_id=s.id, viewer_key=cle).first()
        if v is None:
            db.session.add(LiveViewer(stream_id=s.id, viewer_key=cle, user_id=current_user.id))
            s.total_views = (s.total_views or 0) + 1
        else:
            v.last_seen = datetime.utcnow()
        db.session.flush()
        s.peak_viewers = max(s.peak_viewers or 0, _live_spectateurs(s.id))
        db.session.commit()
        return jsonify(success=True, stream=_live_json(s), places_video=_LIVE_MAX_PEERS)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: api_stream_join : {e}")
        return jsonify(success=False, error="Connexion au live impossible."), 500

@main_bp.route('/api/stream/signal', methods=['POST'])
@login_required
def api_stream_signal():
    """Signalisation WebRTC : offer/answer/ice entre hôte et spectateurs."""
    try:
        _assurer_tables_live()
        data = request.get_json(silent=True) or {}
        s = db.session.get(LiveStream, data.get('stream_id') or 0)
        kind = data.get('kind')
        payload = data.get('payload')
        if not s or s.statut != 'live' or kind not in ('offer', 'answer', 'ice') or payload is None:
            return jsonify(success=False, error="Signal invalide."), 400
        est_hote = (s.user_id == current_user.id)
        de = 'host' if est_hote else _live_cle(data.get('from_key'))
        vers = _live_cle(data.get('to_key')) if est_hote else 'host'
        if not de or not vers:
            return jsonify(success=False, error="Clé manquante."), 400
        texte = json.dumps(payload)
        if len(texte) > 20000:
            return jsonify(success=False, error="Signal trop volumineux."), 400
        db.session.add(LiveSignal(stream_id=s.id, to_key=vers, from_key=de, kind=kind, payload=texte))
        db.session.commit()
        return jsonify(success=True)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: api_stream_signal : {e}")
        return jsonify(success=False, error="Signal non envoyé."), 500

@main_bp.route('/api/stream/signals')
@login_required
def api_stream_signals():
    try:
        _assurer_tables_live()
        sid = request.args.get('stream_id', 0, type=int)
        after = request.args.get('after_id', 0, type=int)
        s = db.session.get(LiveStream, sid)
        if not s:
            return jsonify(success=False, error="Live introuvable."), 404
        pour = 'host' if s.user_id == current_user.id else _live_cle(request.args.get('viewer_key'))
        if not pour:
            return jsonify(success=False, error="Clé manquante."), 400
        sigs = (LiveSignal.query.filter(LiveSignal.stream_id == sid, LiveSignal.to_key == pour,
                                        LiveSignal.id > after).order_by(LiveSignal.id.asc()).limit(200).all())
        return jsonify(success=True, statut=_live_nettoyer(s).statut, signals=[
            {'id': g.id, 'from': g.from_key, 'kind': g.kind, 'payload': json.loads(g.payload)} for g in sigs])
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: api_stream_signals : {e}")
        return jsonify(success=False, error="Signalisation indisponible."), 500

