@main_bp.route('/ajouter_story', methods=['GET', 'POST'])
def ajouter_story():
    # CORRECTION : cette route acceptait le POST du créateur de story (story.html) mais ne faisait
    # que réafficher la page -> rien n'était enregistré, donc aucune story dans le fil.
    # Le GET reste strictement identique ; seul le POST enregistre maintenant la story.
    if request.method == 'POST':
        if 'user_id' not in session:
            return jsonify(success=False, error="Vous devez être connecté."), 401
        story_type = (request.form.get('type') or 'text').strip()
        if story_type not in ('text', 'media', 'vocal'):
            story_type = 'text'
        texte = (request.form.get('texte') or request.form.get('text') or '').strip()
        bg_color = (request.form.get('bg_color') or '')[:20] or None
        privacy = (request.form.get('privacy') or 'friends')[:20]
        nouvelle_story = Story(user_id=session['user_id'], type=story_type,
            texte=texte if texte else None, bg_color=bg_color, privacy=privacy,
            est_brouillon=False, date_creation=datetime.utcnow())
        try:
            if story_type == 'media':
                fichier = request.files.get('image') or request.files.get('media')
                if not fichier or not fichier.filename:
                    return jsonify(success=False, error="Aucun fichier reçu."), 400
                nom_fichier = f"{uuid.uuid4().hex}_{secure_filename(fichier.filename) or 'story'}"
                fichier.save(os.path.join(UPLOAD_STORY_FOLDER, nom_fichier))
                nouvelle_story.image = 'stories/' + nom_fichier
            elif story_type == 'vocal':
                audio_fichier = request.files.get('audio')
                if not audio_fichier or not audio_fichier.filename:
                    return jsonify(success=False, error="Aucun vocal reçu."), 400
                ext = os.path.splitext(secure_filename(audio_fichier.filename))[1] or '.webm'
                nom_audio = f"{uuid.uuid4().hex}_story_vocal{ext}"
                audio_fichier.save(os.path.join(UPLOAD_STORY_FOLDER, nom_audio))
                nouvelle_story.audio = 'stories/' + nom_audio
            elif not texte:
                return jsonify(success=False, error="Écrivez quelque chose."), 400
            if request.form.get('music_title'):
                nouvelle_story.music_title = request.form.get('music_title')[:200]
                nouvelle_story.music_artist = (request.form.get('music_artist') or '')[:200]
                nouvelle_story.music_preview_url = (request.form.get('music_preview_url') or '')[:300]
                nouvelle_story.music_cover = (request.form.get('music_cover') or '')[:300]
            db.session.add(nouvelle_story)
            db.session.commit()
            return jsonify(success=True, story_id=nouvelle_story.id, redirect=url_for('main.feed'))
        except Exception as e:
            db.session.rollback()
            return jsonify(success=False, error=str(e)), 500
    return render_template('story.html')

@main_bp.route('/story/voir/<int:story_id>')
def voir_story(story_id):
    if 'user_id' not in session:
        return redirect(url_for('main.login'))
    user_actif = db.session.get(User, session['user_id'])
    story = Story.query.get_or_404(story_id)
    if story.est_brouillon:
        return redirect(url_for('main.messagerie'))
    limite_story = datetime.utcnow() - timedelta(hours=DUREE_STORY_HEURES)
    if story.date_creation < limite_story:
        flash("Cette story a expiré (24h écoulées).", "info")
        return redirect(url_for('main.feed'))
    is_own = (story.user_id == user_actif.id)
    if not is_own:
        masque_pour_moi = StoryHiddenUser.query.filter_by(
            owner_id=story.user_id, hidden_user_id=user_actif.id).first()
        if masque_pour_moi: abort(403)
    demandes_acceptees = DemandeAmitie.query.filter(DemandeAmitie.statut == 'acceptee').filter(
        or_(DemandeAmitie.emetteur_id == user_actif.id, DemandeAmitie.recepteur_id == user_actif.id)).all()
    amis_ids = set()
    for d in demandes_acceptees:
        amis_ids.add(d.recepteur_id if d.emetteur_id == user_actif.id else d.emetteur_id)
    if is_own:
        stories_visibles = Story.query.filter(Story.user_id == user_actif.id,
            Story.date_creation >= limite_story, or_(Story.est_brouillon == False, Story.est_brouillon.is_(None))
        ).order_by(Story.date_creation.asc()).all()
    else:
        if story.user_id not in amis_ids and story.user_id != user_actif.id:
            abort(403)
        stories_visibles = Story.query.filter(Story.user_id == story.user_id,
            Story.date_creation >= limite_story, or_(Story.est_brouillon == False, Story.est_brouillon.is_(None))
        ).order_by(Story.date_creation.asc()).all()
    ids_en_sourdine = {m.muted_user_id for m in StoryMute.query.filter_by(user_id=user_actif.id).all()}
    if not is_own:
        stories_visibles = [s for s in stories_visibles if s.user_id not in ids_en_sourdine]
    ids_visibles = [s.id for s in stories_visibles]
    next_url = url_for('main.feed')
    prev_url = url_for('main.feed')
    story_index = 0
    story_total = max(len(ids_visibles), 1)
    if story.id in ids_visibles:
        idx = ids_visibles.index(story.id)
        story_index = idx
        if idx + 1 < len(ids_visibles):
            next_story = stories_visibles[idx + 1]
            next_url = url_for('main.voir_story', story_id=next_story.id)
        if idx > 0:
            prev_story = stories_visibles[idx - 1]
            prev_url = url_for('main.voir_story', story_id=prev_story.id)
    if not is_own:
        deja_vue = StoryView.query.filter_by(story_id=story.id, viewer_id=user_actif.id).first()
        if not deja_vue:
            db.session.add(StoryView(story_id=story.id, viewer_id=user_actif.id))
            db.session.commit()
    vues_count = StoryView.query.filter_by(story_id=story.id).count() if is_own else 0
    return render_template('story.html', story=story, is_own=is_own,
        next_url=next_url, prev_url=prev_url, story_index=story_index,
        story_total=story_total, vues_count=vues_count,
        media_est_video=story_media_est_video(story),
        story_age_texte=formater_age_story(story.date_creation))

