@main_bp.route('/upload_story', methods=['POST'])
def upload_story():
    if 'user_id' not in session:
        return jsonify(success=False, error="Vous devez être connecté."), 401
    story_type = request.form.get('type', 'text')
    texte = request.form.get('text', '').strip()
    bg_color = request.form.get('bg_color')
    privacy = request.form.get('privacy', 'public')
    nouvelle_story = Story(user_id=session['user_id'], type=story_type,
        texte=texte if texte else None, bg_color=bg_color, privacy=privacy,
        est_brouillon=False, date_creation=datetime.utcnow())
    try:
        if story_type == 'media' and 'media' in request.files:
            fichier = request.files['media']
            if fichier and fichier.filename:
                nom_fichier = f"{uuid.uuid4().hex}_{secure_filename(fichier.filename)}"
                fichier.save(os.path.join(UPLOAD_STORY_FOLDER, nom_fichier))
                nouvelle_story.image = 'stories/' + nom_fichier
        if story_type == 'vocal' and 'audio' in request.files:
            audio_fichier = request.files['audio']
            if audio_fichier and audio_fichier.filename:
                nom_audio = f"{uuid.uuid4().hex}_story_vocal.webm"
                audio_fichier.save(os.path.join(UPLOAD_STORY_FOLDER, nom_audio))
                nouvelle_story.audio = 'stories/' + nom_audio
        if request.form.get('music_title'):
            nouvelle_story.music_title = request.form.get('music_title')
            nouvelle_story.music_artist = request.form.get('music_artist')
            nouvelle_story.music_preview_url = request.form.get('music_preview_url')
            nouvelle_story.music_cover = request.form.get('music_cover')
        db.session.add(nouvelle_story); db.session.commit()
        return jsonify(success=True, story_id=nouvelle_story.id)
    except Exception as e:
        db.session.rollback()
        return jsonify(success=False, error=str(e)), 500

@main_bp.route('/story/brouillon/enregistrer', methods=['POST'])
def enregistrer_brouillon_story():
    if 'user_id' not in session:
        return jsonify(success=False, error="Vous devez être connecté."), 401
