# ══════════════════════════════════════════════════════════════
#  REELS EXTERNES (TikTok / Instagram) — EMBEDS OFFICIELS UNIQUEMENT
#  Aucune vidéo n'est téléchargée ni copiée : on stocke seulement le lien
#  et on affiche le lecteur officiel de la plateforme, avec le vrai nom du
#  créateur et un lien vers l'original.
# ══════════════════════════════════════════════════════════════
class ReelEmbed(db.Model):
    __tablename__ = 'reel_embed'
    est_embed = True  # permet au template de distinguer un embed d'une Publication
    id = db.Column(db.Integer, primary_key=True)
    plateforme = db.Column(db.String(20), nullable=False)      # 'tiktok' | 'instagram'
    external_id = db.Column(db.String(120), nullable=False, unique=True)
    source_url = db.Column(db.String(500), nullable=False)
    auteur_nom = db.Column(db.String(120), nullable=False)
    date_creation = db.Column(db.DateTime, default=datetime.utcnow)

    @property
    def embed_src(self):
        if self.plateforme == 'tiktok':
            return f"https://www.tiktok.com/embed/v2/{self.external_id}"
        if self.plateforme == 'youtube':
            return f"https://www.youtube.com/embed/{self.external_id}?playsinline=1&rel=0&modestbranding=1"
        return f"https://www.instagram.com/reel/{self.external_id}/embed"

_RE_TIKTOK = re.compile(r'^https?://(?:www\.|m\.)?tiktok\.com/@([\w.\-]+)/video/(\d+)', re.I)
_RE_YOUTUBE = re.compile(r'^https?://(?:www\.|m\.)?(?:youtube\.com/(?:shorts/|watch\?(?:[^#]*&)?v=|embed/)|youtu\.be/)([\w\-]{11})', re.I)
_RE_INSTAGRAM = re.compile(r'^https?://(?:www\.)?instagram\.com/(?:([\w.]+)/)?(?:reel|reels|p|tv)/([\w\-]+)', re.I)

def parser_lien_embed(url, auteur_fourni=''):
    """Retourne (plateforme, external_id, auteur, url_canonique) ou None."""
    url = (url or '').strip()
    m = _RE_TIKTOK.match(url)
    if m:
        pseudo, vid = m.group(1), m.group(2)
        return ('tiktok', vid, auteur_fourni or '@' + pseudo,
                f"https://www.tiktok.com/@{pseudo}/video/{vid}")
    m = _RE_YOUTUBE.match(url)
    if m:
        vid = m.group(1)
        return ('youtube', vid, auteur_fourni or 'YouTube',
                f"https://www.youtube.com/watch?v={vid}")
    m = _RE_INSTAGRAM.match(url)
    if m:
        pseudo, code = m.group(1), m.group(2)
        auteur = auteur_fourni or (('@' + pseudo) if pseudo else 'Instagram')
        return ('instagram', code, auteur, f"https://www.instagram.com/reel/{code}/")
    return None

def _est_admin_embeds():
    # Accès réservé aux ids listés dans REEL_EMBED_ADMIN_IDS (ex: "1,4").
    # Si la variable n'est pas définie, seul le PREMIER compte créé (id le plus petit) a accès.
    if not getattr(current_user, 'is_authenticated', False):
        return False
    ids = {i.strip() for i in os.getenv('REEL_EMBED_ADMIN_IDS', '').split(',') if i.strip()}
    if not ids:
        premier = db.session.query(db.func.min(User.id)).scalar()
        return premier is not None and current_user.id == premier
    return str(current_user.id) in ids

_table_embeds_verifiee = False
def _assurer_table_embeds():
    # Crée la table reel_embed si elle n'existe pas encore (une seule vérification par démarrage).
    global _table_embeds_verifiee
    if _table_embeds_verifiee:
        return
    try:
        ReelEmbed.__table__.create(bind=db.engine, checkfirst=True)
        _table_embeds_verifiee = True
    except Exception as e:
        print(f"DEBUG: création table reel_embed impossible : {e}")

@main_bp.route('/api/reels/embeds/ajouter', methods=['POST'])
@login_required
def api_reels_embeds_ajouter():
    if not _est_admin_embeds():
        return jsonify(success=False, error="Accès refusé."), 403
    data = request.get_json(silent=True) or {}
    parsed = parser_lien_embed(data.get('url'), (data.get('auteur') or '').strip()[:120])
    if not parsed:
        return jsonify(success=False, error="Lien non reconnu. Utilisez le lien complet d'une vidéo TikTok (…/@pseudo/video/123), d'un reel Instagram (…/reel/CODE/) ou d'un YouTube / Short."), 400
    _assurer_table_embeds()
    plateforme, ext_id, auteur, url_canon = parsed
    if ReelEmbed.query.filter_by(external_id=ext_id).first():
        return jsonify(success=False, error="Cette vidéo est déjà ajoutée."), 409
    e = ReelEmbed(plateforme=plateforme, external_id=ext_id, source_url=url_canon, auteur_nom=auteur)
    db.session.add(e); db.session.commit()
    return jsonify(success=True, id=e.id)

@main_bp.route('/api/reels/embeds/<int:embed_id>/supprimer', methods=['POST'])
@login_required
def api_reels_embeds_supprimer(embed_id):
    if not _est_admin_embeds():
        return jsonify(success=False, error="Accès refusé."), 403
    e = ReelEmbed.query.get_or_404(embed_id)
    db.session.delete(e); db.session.commit()
    return jsonify(success=True)

@main_bp.route('/reels', methods=['GET'])
def reels():
    tous_les_reels = Reel.query.order_by(Reel.created_at.desc()).all()
    publications_via_reel = [r.publication for r in tous_les_reels if r.publication]
    ids_deja_inclus = {p.id for p in publications_via_reel}
    query_videos_feed = Publication.query.filter(_clause_sans_enfants()).filter(Publication.media_url.isnot(None)).filter(db.or_(
        Publication.media_url.ilike('%.mp4'), Publication.media_url.ilike('%.webm')))
    if ids_deja_inclus:
        query_videos_feed = query_videos_feed.filter(~Publication.id.in_(ids_deja_inclus))
    publications_video_direct = query_videos_feed.order_by(Publication.date_creation.desc()).all()
    publications = publications_via_reel + publications_video_direct
    publications.sort(key=lambda p: p.date_creation, reverse=True)
    # AJOUT : confidentialité (Public / Amis / Famille / Moi uniquement), y compris pour les visiteurs non connectés
    _viewer_reels = current_user.id if current_user.is_authenticated else None
    publications = [p for p in publications if _peut_voir_publication(p, _viewer_reels)]
    # Embeds TikTok/Instagram : insérés dans le fil (1 embed après chaque groupe de 3 vidéos).
    # Protégé : si la table n'existe pas encore, le fil fonctionne exactement comme avant.
    _assurer_table_embeds()
    try:
        embeds = ReelEmbed.query.order_by(ReelEmbed.date_creation.desc()).all()
    except Exception as e:
        print(f"DEBUG: lecture des embeds impossible : {e}")
        db.session.rollback()
        embeds = []
    if embeds:
        melange, i_embed = [], 0
        for i, p in enumerate(publications, start=1):
            melange.append(p)
            if i % 3 == 0 and i_embed < len(embeds):
                melange.append(embeds[i_embed]); i_embed += 1
        melange.extend(embeds[i_embed:])
        publications = melange
    return render_template('reel.html', reels=publications, peut_gerer_embeds=_est_admin_embeds())

@main_bp.route('/check-name-protected', methods=['POST'])
def check_name_protected():
    data = request.get_json(silent=True) or {}
