@main_bp.route('/check-account', methods=['POST'])
def check_account():
    data = request.get_json(silent=True)
    if data is not None and 'type' in data:
        type_ = (data.get('type') or '').strip().lower()
        value = (data.get('value') or '').strip()
        if not value or type_ not in ('name', 'phone', 'email'):
            return jsonify({'exists': False})
        user = None
        if type_ == 'email': user = User.query.filter(User.email == value).first()
        elif type_ == 'phone': user = User.query.filter(User.phone == value).first()
        elif type_ == 'name': user = User.query.filter(db.func.lower(User.nom_complet) == value.lower()).first()
        if not user:
            return jsonify({'exists': False})
        return jsonify({'exists': True,
            'masked_name': _masquer_nom(user.nom_complet or user.username),
            'masked_contact': _masquer_contact(value)})
    identity = request.form.get('login_identity')
    if not identity:
        return jsonify({"exists": False})
    user = User.query.filter((User.email == identity) | (User.phone == identity)).first()
    if user:
        session['reset_username'] = user.username
        return jsonify({"exists": True, "username": user.username})
    return jsonify({"exists": False})

@main_bp.route('/check-account-exists', methods=['POST'])
def check_account_exists():
    data = request.get_json(silent=True) or {}
    type_ = (data.get('type') or '').strip().lower()
    value = (data.get('value') or '').strip()
    if not value or type_ not in ('phone', 'email'):
        return jsonify({'exists': False})
    if type_ == 'email':
        user = User.query.filter(User.email == value).first()
        message = "Cette adresse e-mail a déjà été utilisée pour vérifier un autre profil. Veuillez utiliser une autre adresse e-mail."
    else:
        # AJOUT : le numéro n'est refusé qu'une fois la limite de comptes atteinte
        user = User.query.filter(User.phone == value).count() >= MAX_COMPTES_PAR_NUMERO
        message = "Ce numéro de téléphone a déjà été utilisé pour vérifier un autre profil. Veuillez utiliser un autre numéro de téléphone."
    if user:
        return jsonify({'exists': True, 'error': message})
    return jsonify({'exists': False})

@main_bp.route('/check-identity-match', methods=['POST'])
def check_identity_match():
    data = request.get_json(silent=True) or {}
    nom_complet = (data.get('nom_complet') or '').strip()
    birth_date_str = (data.get('birth_date') or '').strip()
    password = data.get('password') or ''
    if not nom_complet or not birth_date_str or not password:
        return jsonify({'exists': False})
    try:
        birth_date = datetime.strptime(birth_date_str, '%Y-%m-%d').date()
    except ValueError:
        return jsonify({'exists': False})
    candidats = User.query.filter(db.func.lower(User.nom_complet) == nom_complet.lower(),
                                  User.birth_date == birth_date).all()
    for user in candidats:
        if user.password and check_password_hash(user.password, password):
            return jsonify({'exists': True, 'name': user.nom_complet or user.username,
                'avatar': user.avatar or 'default_avatar.png'})
    return jsonify({'exists': False})

