@main_bp.route('/update-password', methods=['POST'])
def update_password():
    username = session.get('reset_username')
    new_pass = request.form.get('password')
    user = User.query.filter_by(username=username).first()
    if user:
        user.password = generate_password_hash(new_pass)
        notifier(user.id, 'securite_mot_de_passe')
        db.session.commit()
        session.pop('reset_username', None)
        return jsonify({"success": True})
    return jsonify({"success": False})

def _peut_voir_publication(publication, viewer_id):
    if publication is None:
        return False
    if viewer_id != publication.user_id and _compte_masque(publication.user_id):
        return False   # AJOUT : auteur désactivé ou en cours de suppression
    niveau = getattr(publication, 'confidentialite', 'public') or 'public'
    if niveau == 'public':
        return True
    if viewer_id is None:
        return False
    if viewer_id == publication.user_id:
        return True
    if niveau == 'famille':
        # AJOUT : « Famille uniquement » = membres acceptés du cercle familial de l'auteur
        return _famille_peut_voir(publication.user_id, viewer_id)
    if niveau == 'amis':
        return viewer_id in _amis_ids(publication.user_id)
    return False

# ══════════════════════════════════════════════════════════════
#  MENU ⋮ DES PUBLICATIONS (feed) — actions réelles côté serveur
#  Nouvelles tables (créées automatiquement) : réglages par publication,
#  actions par utilisateur (enregistrer / masquer / notifications coupées)
#  et auteurs favoris. Aucune table existante n'est modifiée.
# ══════════════════════════════════════════════════════════════
class PubReglage(db.Model):
    __tablename__ = 'pub_reglage'
    publication_id = db.Column(db.Integer, primary_key=True)
    epingle = db.Column(db.Boolean, default=False, nullable=False)
    archive = db.Column(db.Boolean, default=False, nullable=False)
    corbeille_le = db.Column(db.DateTime, nullable=True)
    permission_commentaires = db.Column(db.String(20), default='tout_le_monde', nullable=False)

class PubAction(db.Model):
    __tablename__ = 'pub_action'
    __table_args__ = (db.UniqueConstraint('user_id', 'publication_id', 'type', name='uq_pub_action'),)
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, nullable=False, index=True)
    publication_id = db.Column(db.Integer, nullable=False, index=True)
    type = db.Column(db.String(20), nullable=False)   # 'enregistre' | 'masque' | 'muet'
    date_creation = db.Column(db.DateTime, default=datetime.utcnow)

class AuteurFavori(db.Model):
    __tablename__ = 'auteur_favori'
    __table_args__ = (db.UniqueConstraint('user_id', 'auteur_id', name='uq_auteur_favori'),)
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, nullable=False, index=True)
    auteur_id = db.Column(db.Integer, nullable=False, index=True)
    date_creation = db.Column(db.DateTime, default=datetime.utcnow)

_tables_menu_ok = False
def _assurer_tables_menu():
    global _tables_menu_ok
    if _tables_menu_ok:
        return
    try:
        for t in (PubReglage.__table__, PubAction.__table__, AuteurFavori.__table__):
            t.create(bind=db.engine, checkfirst=True)
        _tables_menu_ok = True
    except Exception as e:
        print(f"DEBUG: création tables menu publications impossible : {e}")

def _reglage_pub(pub_id, creer=False):
    _assurer_tables_menu()
    rg = db.session.get(PubReglage, pub_id)
    if rg is None and creer:
        rg = PubReglage(publication_id=pub_id, epingle=False, archive=False, permission_commentaires='tout_le_monde')
        db.session.add(rg)
        db.session.flush()
    return rg

def _ids_actions(user_id, type_action):
    _assurer_tables_menu()
    return {a.publication_id for a in PubAction.query.filter_by(user_id=user_id, type=type_action).all()}

def _a_action(user_id, pub_id, type_action):
    _assurer_tables_menu()
    return PubAction.query.filter_by(user_id=user_id, publication_id=pub_id, type=type_action).first()

def _basculer_action(user_id, pub_id, type_action):
    """Ajoute l'action si absente, la retire sinon. Retourne True si elle est maintenant active."""
    existante = _a_action(user_id, pub_id, type_action)
    if existante:
        db.session.delete(existante); db.session.commit()
        return False
    db.session.add(PubAction(user_id=user_id, publication_id=pub_id, type=type_action))
    db.session.commit()
    return True

def _filtrer_publications_menu(pubs, viewer_id, masquer_masquees=True):
    """Retire archivées / corbeille (pour tous), les publications masquées par le lecteur
    (fil seulement), puis remonte les publications épinglées (profil) et celles des auteurs favoris.
    En cas de problème (table absente...), renvoie la liste inchangée."""
    try:
        _assurer_tables_menu()
        ids = [p.id for p in pubs]
        if not ids:
            return pubs
        reglages = {rg.publication_id: rg for rg in PubReglage.query.filter(PubReglage.publication_id.in_(ids)).all()}
        cache = [p for p in pubs if not (reglages.get(p.id) and (reglages[p.id].archive or reglages[p.id].corbeille_le))]
        if viewer_id and masquer_masquees:
            masquees = _ids_actions(viewer_id, 'masque')
            cache = [p for p in cache if p.id not in masquees]
            cache = _retirer_auteurs_masques(cache, viewer_id)
        if viewer_id and masquer_masquees:
            favoris = {f.auteur_id for f in AuteurFavori.query.filter_by(user_id=viewer_id).all()}
            if favoris:
                cache = [p for p in cache if p.user_id in favoris] + [p for p in cache if p.user_id not in favoris]
        if not masquer_masquees:  # profil : épinglées d'abord
            cache = ([p for p in cache if reglages.get(p.id) and reglages[p.id].epingle] +
                     [p for p in cache if not (reglages.get(p.id) and reglages[p.id].epingle)])
        return cache
    except Exception as e:
        print(f"DEBUG: filtrage publications menu impossible : {e}")
        db.session.rollback()
        return pubs

def _pub_accessible_ou_403(pub_id):
    pub = Publication.query.get_or_404(pub_id)
    if not _peut_voir_publication(pub, current_user.id):
        abort(403)
    return pub

def _pub_du_proprietaire(pub_id):
    pub = Publication.query.get_or_404(pub_id)
    if pub.user_id != current_user.id:
        return None, (jsonify(success=False, error="Action réservée à l'auteur de la publication."), 403)
    return pub, None

@main_bp.route('/api/publication/<int:pub_id>/etat')
@login_required
def api_publication_etat(pub_id):
    pub = _pub_accessible_ou_403(pub_id)
    rg = _reglage_pub(pub_id)
    auteur = db.session.get(User, pub.user_id)
    favori = bool(AuteurFavori.query.filter_by(user_id=current_user.id, auteur_id=pub.user_id).first())
    return jsonify(success=True,
        enregistre=bool(_a_action(current_user.id, pub_id, 'enregistre')),
        muet=bool(_a_action(current_user.id, pub_id, 'muet')),
        favori=favori,
        auteur_nom=(auteur.nom_complet or auteur.username) if auteur else 'cet auteur',
        epingle=bool(rg and rg.epingle),
        permission=(rg.permission_commentaires if rg else 'tout_le_monde'),
        confidentialite=pub.confidentialite or 'public')

