def api_publication_archiver(pub_id):
    pub, err = _pub_du_proprietaire(pub_id)
    if err: return err
    rg = _reglage_pub(pub_id, creer=True)
    rg.archive = True; rg.epingle = False
    db.session.commit()
    return jsonify(success=True)

@main_bp.route('/api/publication/<int:pub_id>/corbeille', methods=['POST'])
@login_required
def api_publication_corbeille(pub_id):
    pub, err = _pub_du_proprietaire(pub_id)
    if err: return err
    rg = _reglage_pub(pub_id, creer=True)
    rg.corbeille_le = datetime.utcnow(); rg.archive = False; rg.epingle = False
    db.session.commit()
    return jsonify(success=True)

# ── AJOUT : suppression DÉFINITIVE d'une publication / d'un reel par son auteur ──
# (jusqu'ici seule la corbeille existait). Supprime la publication, ses commentaires (et leurs
# réactions / signalements), ses likes, partages, vues, boosts…, les notifications liées et les fichiers.
def _supprimer_publication_definitivement(pub):
    from sqlalchemy import inspect as _sa_inspect, select as _sa_select
    pub_id = pub.id
    fichiers = set()
    if pub.media_url:
        fichiers.add(pub.media_url)
    try:
        with db.session.begin_nested():
            for _lg in db.session.execute(_PUB_MEDIAS.select().where(_PUB_MEDIAS.c.publication_id == pub_id)).fetchall():
                if _lg.fichier:
                    fichiers.add(_lg.fichier)
    except Exception:
        pass
    try:
        for rl in Reel.query.filter_by(publication_id=pub_id).all():
            for nom in (rl.fichier_video, rl.thumbnail):
                if nom:
                    fichiers.add(nom)
    except Exception:
        pass
    pub_tbl = Publication.__table__
    existantes = set(_sa_inspect(db.engine).get_table_names())

    def _lot(table, ids, vus):
        for t in list(db.metadata.sorted_tables):
            if t.name not in existantes:
                continue
            for fk in list(t.foreign_keys):
                try:
                    if fk.column is not table.c.id:
                        continue
                except Exception:
                    continue
                col = fk.parent
                if col.nullable:        # lien facultatif : on détache simplement
                    db.session.execute(t.update().where(col.in_(ids)).values({col.name: None}))
                    continue
                if t is table:
                    continue
                cle = (t.name, col.name)
                if cle in vus:
                    continue
                if 'id' in t.c:
                    sous = [x[0] for x in db.session.execute(_sa_select(t.c.id).where(col.in_(ids))).fetchall()]
                    if sous:
                        _dependances(t, sous, vus | {cle})
                db.session.execute(t.delete().where(col.in_(ids)))

    def _dependances(table, ids, vus=frozenset()):
        ids = list(ids)
        for i in range(0, len(ids), 500):
            _lot(table, ids[i:i + 500], vus)

    com_tbl = Commentaire.__table__
    com_ids = [x[0] for x in db.session.execute(
        _sa_select(com_tbl.c.id).where(com_tbl.c.publication_id == pub_id)).fetchall()]
    try:
        _dependances(pub_tbl, [pub_id])
        # tables sans clé étrangère déclarée mais avec une colonne publication_id (réglages, actions…)
        for t in db.metadata.sorted_tables:
            if t is pub_tbl or t.name not in existantes or 'publication_id' not in t.c:
                continue
            if t.c.publication_id.foreign_keys:
                continue
            db.session.execute(t.delete().where(t.c.publication_id == pub_id))
        Notification.query.filter(Notification.target_type == 'post', Notification.target_id == pub_id)\
            .delete(synchronize_session=False)
        for i in range(0, len(com_ids), 500):
            Notification.query.filter(Notification.target_type == 'comment',
                                      Notification.target_id.in_(com_ids[i:i + 500]))\
                .delete(synchronize_session=False)
        db.session.execute(pub_tbl.delete().where(pub_tbl.c.id == pub_id))
        db.session.commit()
    except Exception:
        db.session.rollback()
        raise
    # Fichiers : supprimés seulement s'ils ne servent plus à aucune autre publication / story / reel
    try:
        base = current_app.config.get('UPLOAD_FOLDER') or os.path.join('static', 'uploads')
        racine = os.path.abspath(base)
        for nom in fichiers:
            if Publication.query.filter_by(media_url=nom).count() or Story.query.filter_by(image=nom).count():
                continue
            chemin = os.path.abspath(os.path.join(base, nom))
            if chemin.startswith(racine + os.sep) and os.path.isfile(chemin):
                try:
                    os.remove(chemin)
                except OSError as e:
                    print(f"DEBUG: fichier non supprimé ({nom}) : {e}")
    except Exception as e:
        print(f"DEBUG: nettoyage des fichiers impossible : {e}")

