@main_bp.route('/api/publication/<int:pub_id>/permission-commentaires', methods=['POST'])
@login_required
def api_publication_permission_commentaires(pub_id):
    pub, err = _pub_du_proprietaire(pub_id)
    if err: return err
    val = ((request.get_json(silent=True) or {}).get('permission') or '').strip().lower().replace(' ', '_')
    synonymes = {'tout_le_monde': 'tout_le_monde', 'tous': 'tout_le_monde', 'public': 'tout_le_monde',
                 'amis': 'amis', 'ami': 'amis', 'amis_amis': 'amis_amis', 'amis_de_amis': 'amis_amis',
                 'mentionnes': 'mentionnes', 'personnes_mentionnees': 'mentionnes',
                 'personne': 'personne', 'aucun': 'personne'}
    if val not in synonymes:
        return jsonify(success=False, error='Choix invalide.'), 400
    if synonymes[val] == 'mentionnes' and not _ids_personnes_identifiees(pub):
        return jsonify(success=False, error='Identifiez au moins une personne dans la publication avant de choisir cette option.'), 400
    rg = _reglage_pub(pub_id, creer=True)
    rg.permission_commentaires = synonymes[val]
    db.session.commit()
    return jsonify(success=True, permission=rg.permission_commentaires)

