@main_bp.route('/api/fil/reglages')
@login_required
def api_fil_reglages():
    """Contenu de « Gérer votre fil » : publications masquées, auteurs favoris, archive et corbeille."""
    _assurer_tables_menu()
    def extrait(p):
        t = (p.contenu or '').strip()
        return (t[:60] + '…') if len(t) > 60 else (t or ('Photo' if p.media_url else 'Publication'))
    def nom(u):
        return (u.nom_complet or u.username) if u else 'Utilisateur'
    masquees = []
    for pid in _ids_actions(current_user.id, 'masque'):
        p = db.session.get(Publication, pid)
        if p: masquees.append({'id': p.id, 'auteur': nom(db.session.get(User, p.user_id)), 'extrait': extrait(p)})
    favoris = []
    for f in AuteurFavori.query.filter_by(user_id=current_user.id).all():
        favoris.append({'id': f.auteur_id, 'nom': nom(db.session.get(User, f.auteur_id))})
    mes_ids = [p.id for p in Publication.query.filter_by(user_id=current_user.id).all()]
    archivees, corbeille = [], []
    if mes_ids:
        limite = datetime.utcnow() - timedelta(days=30)
        for rg in PubReglage.query.filter(PubReglage.publication_id.in_(mes_ids)).all():
            p = db.session.get(Publication, rg.publication_id)
            if not p: continue
            if rg.corbeille_le and rg.corbeille_le < limite:
                # Plus de 30 jours dans la corbeille : suppression définitive
                try:
                    db.session.delete(rg); db.session.delete(p); db.session.commit()
                except Exception as e:
                    db.session.rollback(); print(f"DEBUG: purge corbeille impossible : {e}")
                continue
            if rg.corbeille_le: corbeille.append({'id': p.id, 'extrait': extrait(p)})
            elif rg.archive and getattr(p, 'type_publication', None) != 'media_enfant': archivees.append({'id': p.id, 'extrait': extrait(p)})
    return jsonify(success=True, masquees=masquees, favoris=favoris, archivees=archivees, corbeille=corbeille)

