# ══════════════════════════════════════════════════════════════
#  MENU ⋮ — « Masquer les publications de cet auteur » (enregistré en base,
#  suit le compte sur tous les appareils). Table créée automatiquement.
# ══════════════════════════════════════════════════════════════
class AuteurMasque(db.Model):
    __tablename__ = 'auteur_masque'
    __table_args__ = (db.UniqueConstraint('user_id', 'auteur_id', name='uq_auteur_masque'),)
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, nullable=False, index=True)
    auteur_id = db.Column(db.Integer, nullable=False, index=True)
    date_creation = db.Column(db.DateTime, default=datetime.utcnow)

_auteur_masque_ok = False
def _assurer_table_auteur_masque():
    global _auteur_masque_ok
    if _auteur_masque_ok:
        return
    try:
        AuteurMasque.__table__.create(bind=db.engine, checkfirst=True)
        _auteur_masque_ok = True
    except Exception as e:
        print(f"DEBUG: création table auteur_masque impossible : {e}")

def _retirer_auteurs_masques(pubs, viewer_id):
    """Retire du fil les publications des auteurs masqués. En cas de problème : liste inchangée."""
    try:
        _assurer_table_auteur_masque()
        masques = {a.auteur_id for a in AuteurMasque.query.filter_by(user_id=viewer_id).all()}
        if not masques:
            return pubs
        return [p for p in pubs if p.user_id not in masques]
    except Exception as e:
        print(f"DEBUG: filtrage auteurs masqués impossible : {e}")
        return pubs

