@main_bp.route("/api/evenement/<int:event_id>/repondre", methods=["POST"])
def repondre_evenement(event_id):
    """Boutons « Intéressé(e) » / « Participer » de la carte d'événement (cette route n'existait pas : 404)."""
    from models import EvenementReponse
    uid = session.get("user_id") or getattr(current_user, "id", None)
    if not uid:
        return jsonify(success=False, error="non connecté"), 401
    statut = (request.get_json(silent=True) or {}).get("statut")
    if statut not in ("participe", "interesse"):
        return jsonify(success=False, error="statut invalide"), 400
    ev = db.session.get(Evenement, event_id)
    if not ev:
        return jsonify(success=False, error="événement introuvable"), 404
    try:
        rep_existante = EvenementReponse.query.filter_by(evenement_id=event_id, user_id=uid).first()
        mon_statut = statut
        if rep_existante and rep_existante.statut == statut:
            db.session.delete(rep_existante)      # un second clic retire la réponse
            mon_statut = None
        elif rep_existante:
            rep_existante.statut = statut
        else:
            db.session.add(EvenementReponse(evenement_id=event_id, user_id=uid, statut=statut))
        db.session.commit()
        toutes = EvenementReponse.query.filter_by(evenement_id=event_id).all()
    except Exception as e:
        db.session.rollback()
        print(f"[repondre_evenement] erreur : {e}")
        return jsonify(success=False, error="erreur"), 500
    return jsonify(success=True, mon_statut=mon_statut,
                   nb_participe=sum(1 for r in toutes if r.statut == "participe"),
                   nb_interesse=sum(1 for r in toutes if r.statut == "interesse"))


