# ══════════════════════════════════════════════════════════════════════
# AJOUT ADDITIF : reconnaissance automatique de la musique d'une vidéo
# ──────────────────────────────────────────────────────────────────────
# Quand une vidéo est publiée SANS musique choisie, on identifie la musique
# qu'elle contient (service AudD) et on la range dans Publication.musique
# au même format que la musique choisie à la main : « Titre — Artiste ».
# feed.html / reel.html l'affichent alors sous le nom de l'auteur.
#
# Garanties « rien ne casse » :
#   • aucune colonne ajoutée (on réutilise Publication.musique) ;
#   • tout se passe APRÈS l'enregistrement de la publication, dans un
#     thread d'arrière-plan : l'upload n'est jamais ralenti ni bloqué ;
#   • toute erreur (pas de clé, pas de ffmpeg, pas d'internet, quota…)
#     est avalée : la publication reste exactement comme avant ;
#   • sans variable d'environnement AUDD_API_TOKEN, la fonction ne fait rien.
# Prérequis : AUDD_API_TOKEN dans le .env + ffmpeg installé sur le serveur.
# ══════════════════════════════════════════════════════════════════════
def _extraire_extrait_audio(chemin_video):
    """Extrait ~15 s d'audio (mp3 mono léger) de la vidéo avec ffmpeg.
    Retourne le chemin du mp3, ou None (pas de ffmpeg, pas de piste audio…)."""
    ffmpeg = shutil.which('ffmpeg')
    if not ffmpeg:
        print("DEBUG: détection musique ignorée : ffmpeg introuvable sur le serveur.")
        return None
    sortie = chemin_video + '.extrait.mp3'
    try:
        subprocess.run(
            [ffmpeg, '-y', '-loglevel', 'error', '-ss', '1', '-i', chemin_video,
             '-t', '15', '-vn', '-ac', '1', '-ar', '22050', '-b:a', '64k', sortie],
            check=True, timeout=45, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except (subprocess.SubprocessError, OSError):
        return None
    if os.path.exists(sortie) and os.path.getsize(sortie) > 0:
        return sortie
    return None


def _reconnaitre_musique(chemin_audio):
    """Interroge AudD. Retourne « Titre — Artiste » ou None si rien n'est reconnu."""
    import requests as _requests
    token = (os.environ.get('AUDD_API_TOKEN') or '').strip()
    if not token:
        return None
    with open(chemin_audio, 'rb') as f:
        reponse = _requests.post('https://api.audd.io/', data={'api_token': token},
                                 files={'file': f}, timeout=25)
    donnees = reponse.json()
    resultat = donnees.get('result') if donnees.get('status') == 'success' else None
    if not resultat:
        return None
    titre = (resultat.get('title') or '').strip()
    artiste = (resultat.get('artist') or '').strip()
    if not titre:
        return None
    return (f"{titre} — {artiste}" if artiste else titre)[:200]


def _lancer_detection_musique(pub_id, nom_fichier):
    """Lance la détection en arrière-plan (ne bloque jamais la requête)."""
    if not (os.environ.get('AUDD_API_TOKEN') or '').strip():
        return
    import threading
    app = current_app._get_current_object()

    def _travail():
        extrait = None
        try:
            candidats = [os.path.join(app.root_path, 'static', 'uploads', nom_fichier),
                         os.path.join('static', 'uploads', nom_fichier)]
            chemin_video = next((c for c in candidats if os.path.exists(c)), None)
            if not chemin_video:
                return
            extrait = _extraire_extrait_audio(chemin_video)
            if not extrait:
                return
            texte = _reconnaitre_musique(extrait)
            if not texte:
                return
            with app.app_context():
                try:
                    pub = db.session.get(Publication, pub_id)
                    # on n'écrase jamais une musique choisie entre-temps par l'auteur
                    if pub and not pub.musique:
                        pub.musique = texte
                        db.session.commit()
                except Exception:
                    db.session.rollback()
                    raise
                finally:
                    db.session.remove()
        except Exception as e:
            print(f"DEBUG: détection de musique impossible (publication {pub_id}) : {e}")
        finally:
            if extrait:
                try:
                    os.remove(extrait)
                except OSError:
                    pass

    threading.Thread(target=_travail, daemon=True).start()


