# AJOUT ADDITIF : « Publier en souvenir » (depuis la visionneuse de photos du profil)
# Republie une de SES photos dans le fil sous forme de souvenir : nouvelle publication
# (type_publication='souvenir') qui réutilise le même fichier image (rien n'est copié ni
# modifié) avec « Souvenir du <date d'origine> » + un mot facultatif. Aucune colonne ajoutée.
# ══════════════════════════════════════════════════════════════════════
@main_bp.route('/api/publication/<int:pub_id>/souvenir', methods=['POST'])
@login_required
def publier_en_souvenir(pub_id):
    try:
        source = db.session.get(Publication, pub_id)
        if source is None or source.user_id != current_user.id:
            return jsonify(success=False, error="Vous ne pouvez publier en souvenir que vos propres photos."), 403
        extension = (source.media_url or '').rsplit('.', 1)[-1].lower() if source.media_url else ''
        if not source.media_url or extension in ('mp4', 'mov', 'webm', 'avi', 'mkv'):
            return jsonify(success=False, error="Seules les photos peuvent être publiées en souvenir."), 400
        donnees = request.get_json(silent=True) or {}
        legende = (donnees.get('legende') or '').strip()[:300]
        audience = donnees.get('confidentialite') or 'amis'
        if audience not in ('public', 'amis', 'famille', 'prive'):
            audience = 'amis'
        try:
            date_origine = _date_complete_fr(source.date_creation) if source.date_creation else None
        except Exception:
            date_origine = None
        texte = f"🕰️ Souvenir du {date_origine}" if date_origine else "🕰️ Souvenir"
        if legende:
            texte += "\n" + legende
        souvenir = Publication(contenu=texte, media_url=source.media_url, user_id=current_user.id,
                               type_publication='souvenir', confidentialite=audience)
        db.session.add(souvenir)
        db.session.commit()
        return jsonify(success=True, id=souvenir.id)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG publication en souvenir impossible : {e}")
        return jsonify(success=False, error="Impossible de publier ce souvenir pour le moment."), 500


def _creer_story_depuis_publication(publication, media_url, contenu, musique=None,
                                    musique_preview_url=None, musique_cover_url=None):
    """Option « Partager dans votre story » = Oui : crée automatiquement une story
    avec le même média, le même texte et la même musique que la publication."""
    texte = (contenu or '').strip() or None
    if not media_url and not texte and not musique:
        return None
    story = Story(user_id=publication.user_id, privacy='public', est_brouillon=False,
                  date_creation=datetime.utcnow(), texte=texte)
    if media_url:
        source = os.path.join('static', 'uploads', media_url)
        if not os.path.isfile(source):
            return None
        os.makedirs(UPLOAD_STORY_FOLDER, exist_ok=True)
        nom_story = f"{uuid.uuid4().hex}_{media_url}"
        shutil.copyfile(source, os.path.join(UPLOAD_STORY_FOLDER, nom_story))
        story.type = 'media'
        story.image = 'stories/' + nom_story
    else:
        fond = (getattr(publication, 'background_color', None) or '').strip()
        story.type = 'text'
        if fond.startswith('3d:'):
            fond = _FN3D_COULEUR_STORY.get(fond[3:].partition('-')[2], '#1877f2')
        story.bg_color = fond if fond and fond != 'transparent' else '#1877f2'
    if musique:
        story.music_title = musique
        story.music_artist = ''
        story.music_preview_url = musique_preview_url
        story.music_cover = musique_cover_url
    db.session.add(story)
    db.session.commit()
    return story

def _parse_date_programmee(valeur, nom_fuseau=None):
    """Convertit la date du navigateur en UTC naïf (convention de l'application)."""
    brut = (valeur or '').strip()
    if not brut:
        raise ValueError("Choisissez une date et une heure.")
    dt = datetime.fromisoformat(brut.replace('Z', '+00:00'))
    if dt.tzinfo is None:
        # datetime-local est exprimé dans le fuseau de l'utilisateur.
        nom = nom_fuseau or os.environ.get('FACENET_TIMEZONE', 'Africa/Douala')
        try:
            fuseau = pytz.timezone(nom)
        except Exception:
            fuseau = pytz.timezone('Africa/Douala')
        dt = fuseau.localize(dt, is_dst=None)
    return dt.astimezone(pytz.utc).replace(tzinfo=None)


# ── AJOUT : publications à plusieurs photos / vidéos (mosaïque dans le fil, lecture une par une) ──
# Le premier fichier reste dans Publication.media_url (rien ne change pour le reste de l'application) ;
# les fichiers suivants sont rangés, dans l'ordre, dans la table additive « publication_media ».
from sqlalchemy import Table as _SaTable, Column as _SaColumn, Integer as _SaInteger, String as _SaString
_MAX_MEDIAS_PUB = 10
_EXT_IMAGES_PUB = {'jpg', 'jpeg', 'png', 'gif', 'webp'}
_EXT_VIDEOS_PUB = {'mp4', 'mov', 'webm'}
_PUB_MEDIAS = _SaTable(
    'publication_media', db.metadata,
    _SaColumn('id', _SaInteger, primary_key=True),
    _SaColumn('publication_id', _SaInteger, nullable=False, index=True),
    _SaColumn('fichier', _SaString(255), nullable=False),
    _SaColumn('ordre', _SaInteger, nullable=False, default=0),
    extend_existing=True,
)
_table_pub_medias_verifiee = False
def _assurer_table_publication_medias():
    # Crée la table si elle n'existe pas encore (une seule vérification par démarrage).
    global _table_pub_medias_verifiee
    if _table_pub_medias_verifiee:
        return
    try:
        _PUB_MEDIAS.create(bind=db.engine, checkfirst=True)
        _table_pub_medias_verifiee = True
    except Exception as e:
        print(f"DEBUG: création table publication_media impossible : {e}")


def _enregistrer_medias_supp(pub_id, noms):
    """Range les médias supplémentaires d'une publication déjà « flushée ». Ne bloque jamais la publication."""
    noms = [n for n in (noms or []) if isinstance(n, str) and n.strip()][:_MAX_MEDIAS_PUB - 1]
    if not noms:
        return
    try:
        with db.session.begin_nested():
            for i, nom in enumerate(noms, start=1):
                db.session.execute(_PUB_MEDIAS.insert().values(publication_id=pub_id, fichier=nom[:255], ordre=i))
    except Exception as exc:
        print(f"DEBUG: médias supplémentaires non enregistrés pour #{pub_id} : {exc}")


@main_bp.app_template_global('medias_pub')
def medias_pub(pub):
    """Liste ordonnée [{'url', 'video'}] : le média principal puis les médias supplémentaires (templates)."""
    principal = getattr(pub, 'media_url', None)
    if not principal:
        return []
    deja = getattr(pub, '_fn_medias_cache', None)
    if deja is not None:
        return deja

    def _item(nom):
        ext = nom.rsplit('.', 1)[-1].lower() if '.' in nom else ''
        return {'url': url_for('static', filename='uploads/' + nom), 'video': ext in _EXT_VIDEOS_PUB}

    res = [_item(principal)]
    try:
        _assurer_table_publication_medias()
        with db.session.begin_nested():
            lignes = db.session.execute(
                _PUB_MEDIAS.select().where(_PUB_MEDIAS.c.publication_id == pub.id)
                .order_by(_PUB_MEDIAS.c.ordre, _PUB_MEDIAS.c.id)).fetchall()
        for lg in lignes:
            if lg.fichier:
                res.append(_item(lg.fichier))
    except Exception as exc:
        print(f"DEBUG: médias supplémentaires illisibles pour #{getattr(pub, 'id', '?')} : {exc}")
    try:
        pub._fn_medias_cache = res
    except Exception:
        pass
    return res


# ── AJOUT : mention « Contenu IA » automatique quand le fichier porte une marque de génération par IA ──
# On ne devine pas d'après l'image : on repère seulement les marques que les générateurs écrivent dans le fichier
# (métadonnées IPTC/XMP « trainedAlgorithmicMedia », Content Credentials/C2PA, réglages Stable Diffusion, etc.).
_MARQUES_IA_FORTES = (b'trainedalgorithmicmedia', b'compositesynthetic', b'made with google ai', b'midjourney',
                      b'stable diffusion', b'dall-e', b'dall\xc2\xb7e', b'adobe firefly')
_MARQUES_IA_C2PA = (b'openai', b'firefly', b'google ai', b'gemini', b'sora')


def _fichier_porte_marque_ia(chemin):
    try:
        taille = os.path.getsize(chemin)
        with open(chemin, 'rb') as f:
            data = f.read(1024 * 1024)
            if taille > 1024 * 1024:
                f.seek(max(1024 * 1024, taille - 256 * 1024))
                data += f.read(256 * 1024)
    except OSError:
        return False
    bas = data.lower()
    if any(m in bas for m in _MARQUES_IA_FORTES):
        return True
    if b'steps: ' in bas and b'sampler: ' in bas and b'cfg scale' in bas:
        return True
    if (b'c2pa' in bas or b'jumb' in bas) and any(m in bas for m in _MARQUES_IA_C2PA):
        return True
    return False


def _publication_depuis_payload(payload, user_id):
    """Construit une Publication à partir des données immédiates ou programmées."""
    publication = Publication(
        contenu=(payload.get('contenu') or '').strip() or ' ',
        media_url=payload.get('media_url'),
        user_id=user_id,
        background_color=payload.get('background_color') or 'transparent',
        confidentialite=payload.get('confidentialite') or 'public',
        humeur=payload.get('humeur'),
        musique=payload.get('musique'),
        musique_preview_url=payload.get('musique_preview_url'),
        musique_cover_url=payload.get('musique_cover_url'),
        musique_debut=payload.get('musique_debut') or 0,
        mention_ia=bool(payload.get('mention_ia')),
        mention_ia_type=(payload.get('mention_ia_type') or None)
    )
    extras = (
        ('identifies', payload.get('identifies')),
        ('telephone', payload.get('telephone')),
        ('pays', payload.get('pays')),
        ('text_style', payload.get('text_style')),
        ('gif_url', payload.get('gif_url'))
    )
    for champ, valeur in extras:
        if valeur and champ in Publication.__table__.columns:
            setattr(publication, champ, valeur)
    return publication


# ── FN-3D-BG : arrière-plans 3D des publications (clé « 3d:<style>-<palette> ») ──
_FN3D_STYLES = ('dunes', 'orbs', 'waves', 'tunnel', 'grid', 'crystal', 'planet', 'fold')
_FN3D_COULEUR_STORY = {'nuit': '#17255c', 'ocean': '#04607a', 'aurore': '#0b7a5a', 'rubis': '#8e0f2e', 'or': '#a8650a',
                       'foret': '#236b27', 'violet': '#5a22a8', 'rose': '#b3226b', 'glace': '#3b87b8'}

def _fn3d_fond_valide(valeur):
    """Fond choisi dans le compositeur : un fond 3D n'est accepté que s'il existe, sinon « transparent ».
    Les autres valeurs (couleurs, dégradés) restent exactement comme avant."""
    v = valeur or 'transparent'
    if v.startswith('3d:'):
        style, _, palette = v[3:].partition('-')
        return v if style in _FN3D_STYLES and palette in _FN3D_COULEUR_STORY else 'transparent'
    return v

# ── FN-TSAPI-IA : assistant de rédaction du compositeur « Quoi de neuf ? » ──
_CONSIGNE_PUB_IA = (
    "Tu es Tsapi IA, l'assistante de rédaction de FaceNet. Tu rédiges uniquement le texte d'une publication de réseau social, "
    "dans la langue de l'utilisateur (français par défaut), ton naturel, chaleureux et soigné, sans formatage markdown, "
    "sans guillemets autour du texte, sans introduction ni commentaire : seulement le texte final à publier. "
    "Reste sobre et respectueux : refuse poliment toute demande haineuse, trompeuse ou illégale en répondant par une courte phrase neutre. "
    "Tu es toujours poli, même si on t'insulte, et tu ne ripostes jamais. "
    "Tu comprends les messages mal écrits (fautes, mots confondus, abréviations) et tu devines ce que l'utilisateur veut dire.")
_ACTIONS_PUB_IA = {
    'ecrire': "Écris une publication (2 à 5 phrases, quelques emojis bien choisis) à partir de cette idée : ",
    'ameliorer': "Améliore ce texte (style, clarté, émotion) en gardant le sens et la langue : ",
    'corriger': "Corrige uniquement l'orthographe, la grammaire et la ponctuation de ce texte, sans rien changer d'autre : ",
    'hashtags': "Garde ce texte tel quel et ajoute à la fin 3 à 6 hashtags pertinents : ",
    'raccourcir': "Raccourcis ce texte de moitié environ en gardant l'essentiel : ",
}

@main_bp.route('/api/tsapi-ia/publication', methods=['POST'])
@login_required
def tsapi_ia_publication():
    donnees = request.get_json(silent=True) or {}
    action = str(donnees.get('action') or 'ecrire').strip()
    if action not in _ACTIONS_PUB_IA:
        action = 'ecrire'
    demande = str(donnees.get('demande') or '').strip()[:500]
    texte = str(donnees.get('texte') or '').strip()[:2000]
    if action == 'ecrire' and not demande:
        return jsonify(success=False, error="Décris ton idée pour que Tsapi IA écrive la publication."), 400
    if action != 'ecrire' and not texte:
        return jsonify(success=False, error="Écris d'abord ton texte dans la publication."), 400
    if _limite_video_ia_atteinte(('pub_ia', current_user.id), maxi=12, fenetre=60):
        return jsonify(success=False, error="Trop de demandes d'affilée. Patiente une minute."), 429
    matiere = demande if action == 'ecrire' else texte
    consigne = _ACTIONS_PUB_IA[action] + "\n\"\"\"\n" + matiere + "\n\"\"\""
    if action != 'ecrire' and demande:
        consigne += "\nPrécision de l'utilisateur : " + demande
    try:
        rep = client.models.generate_content(
            model='gemini-3.5-flash-lite', contents=consigne,
            config=types.GenerateContentConfig(system_instruction=_CONSIGNE_PUB_IA, temperature=0.8, max_output_tokens=700))
        sortie = (rep.text or '').replace('*', '').replace('`', '').strip().strip('"').strip()
        if not sortie:
            raise ValueError('reponse vide')
        return jsonify(success=True, texte=sortie[:3000])
    except Exception as e:
        _journal_ia(f"tsapi ia publication : {e!r}")
        return jsonify(success=False, error="Tsapi IA n'est pas disponible pour le moment. Réessaie dans un instant."), 503

@main_bp.route('/ajouter_publication', methods=['GET', 'POST'])
@login_required
def creer_publication():
    if request.method == 'GET':
        return redirect(url_for('main.feed'))

    contenu = (request.form.get('contenu') or '').strip()
    humeur = (request.form.get('humeur') or '').strip() or None
    background_color = _fn3d_fond_valide(request.form.get('background_color'))
    confidentialite = request.form.get('confidentialite') or 'public'
    if confidentialite not in ('public', 'amis', 'famille', 'prive'):
        confidentialite = 'public'
    musique = (request.form.get('musique') or '').strip() or None
    musique_preview_url = (request.form.get('musique_preview_url') or '').strip() or None
    musique_cover_url = (request.form.get('musique_cover_url') or '').strip() or None
    try:
        musique_debut = max(0.0, float(request.form.get('musique_debut') or 0))
    except (TypeError, ValueError):
        musique_debut = 0.0

    mode_programmation = (request.form.get('programmation_mode') or 'maintenant').strip()
    date_programmee = None
    if mode_programmation == 'programmer':
        try:
            date_programmee = _parse_date_programmee(
                request.form.get('programmation_datetime'),
                request.form.get('programmation_timezone')
            )
            if date_programmee <= datetime.utcnow():
                raise ValueError("La date choisie doit être dans le futur.")
        except Exception as exc:
            flash(str(exc) or "La date de programmation est invalide.", 'danger')
            return redirect(url_for('main.feed'))
    elif mode_programmation != 'maintenant':
        flash("Mode de programmation invalide.", 'danger')
        return redirect(url_for('main.feed'))

    _fichiers_recus = [f for f in request.files.getlist('media') if f and f.filename]
    fichier = _fichiers_recus[0] if _fichiers_recus else request.files.get('media')
    _gif_url = (request.form.get('gif_url') or '').strip()[:1000]
    _gif_valide = False
    if _gif_url:
        try:
            _gif_parse = urlparse(_gif_url)
            _gif_valide = _gif_parse.scheme in ('http', 'https') and bool(_gif_parse.netloc)
        except Exception:
            _gif_valide = False
    _gif_colonne = 'gif_url' in Publication.__table__.columns

    if not contenu and not (fichier and fichier.filename) and not musique and not (_gif_valide and _gif_colonne):
        flash('Écrivez quelque chose ou ajoutez une photo/vidéo/GIF/musique.', 'danger')
        return redirect(url_for('main.feed'))

    media_url = None
    if fichier and fichier.filename:
        nom = secure_filename(fichier.filename)
        ext = nom.rsplit('.', 1)[1].lower() if '.' in nom else ''
        extensions_images = {'jpg', 'jpeg', 'png', 'gif', 'webp'}
        extensions_videos = {'mp4', 'mov', 'webm'}
        if ext not in extensions_images | extensions_videos:
            flash('Format média non pris en charge.', 'danger')
            return redirect(url_for('main.feed'))
        nom = f"pub_{current_user.id}_{uuid.uuid4().hex[:12]}.{ext}"
        try:
            os.makedirs(os.path.join('static', 'uploads'), exist_ok=True)
            fichier.save(os.path.join('static', 'uploads', nom))
            media_url = nom
        except OSError as exc:
            print(f"DEBUG: échec sauvegarde média publication : {exc}")
            flash("Le fichier n'a pas pu être enregistré, réessayez.", "danger")
            return redirect(url_for('main.feed'))

    # AJOUT : photos / vidéos supplémentaires (le premier fichier est traité ci-dessus, comme avant)
    medias_supp = []
    if media_url and len(_fichiers_recus) > 1:
        _assurer_table_publication_medias()
        for _f in _fichiers_recus[1:_MAX_MEDIAS_PUB]:
            _nom_f = secure_filename(_f.filename)
            _ext_f = _nom_f.rsplit('.', 1)[1].lower() if '.' in _nom_f else ''
            if _ext_f not in (_EXT_IMAGES_PUB | _EXT_VIDEOS_PUB):
                continue
            _nom_f = f"pub_{current_user.id}_{uuid.uuid4().hex[:12]}.{_ext_f}"
            try:
                _f.save(os.path.join('static', 'uploads', _nom_f))
                medias_supp.append(_nom_f)
            except OSError as exc:
                print(f"DEBUG: échec sauvegarde média supplémentaire : {exc}")

    _idf = ','.join(dict.fromkeys(
        p.strip() for p in (request.form.get('identifies') or '').split(',')
        if p.strip().isdigit()
    ))
    _permission_brute = (request.form.get('qui_peut_commenter') or 'public').strip().lower()
    _permissions_creation = {
        'public': 'tout_le_monde', 'tout_le_monde': 'tout_le_monde', 'amis': 'amis',
        'amis_followers': 'amis', 'amis_amis': 'amis_amis', 'mentionnes': 'mentionnes',
        'personne': 'personne'
    }
    _permission_commentaires = _permissions_creation.get(_permission_brute, 'tout_le_monde')
    if _permission_commentaires == 'mentionnes' and not _idf:
        flash("Identifiez au moins une personne pour limiter les commentaires aux personnes mentionnées.", 'danger')
        return redirect(url_for('main.feed'))
    _tel = ''.join(ch for ch in (request.form.get('telephone') or '') if ch.isdigit() or ch in '+ ').strip()[:40]
    _pays = (request.form.get('pays') or '').strip()[:100]
    _text_style = (request.form.get('text_style') or '').strip()[:50]
    _mention_ia = (request.form.get('mention_ia') or '0').strip().lower() in ('1', 'true', 'on', 'yes')
    _mention_ia_type = (request.form.get('mention_ia_type') or 'mixte').strip().lower()
    if _mention_ia_type not in ('texte', 'image', 'video', 'mixte'):
        _mention_ia_type = 'mixte'

    # AJOUT : « Contenu IA » activé automatiquement si un fichier porte une marque de génération par IA
    if not _mention_ia:
        try:
            _types_ia = set()
            for _nom_ia in ([media_url] if media_url else []) + medias_supp:
                if _fichier_porte_marque_ia(os.path.join('static', 'uploads', _nom_ia)):
                    _types_ia.add('video' if _nom_ia.rsplit('.', 1)[-1].lower() in _EXT_VIDEOS_PUB else 'image')
            if _types_ia:
                _mention_ia = True
                _mention_ia_type = next(iter(_types_ia)) if len(_types_ia) == 1 else 'mixte'
        except Exception as exc:
            print(f"DEBUG: détection IA ignorée : {exc}")

    payload = {
        'contenu': contenu,
        'media_url': media_url,
        'medias_supp': medias_supp,
        'background_color': background_color,
        'confidentialite': confidentialite,
        'permission_commentaires': _permission_commentaires,
        'humeur': humeur,
        'musique': musique,
        'musique_preview_url': musique_preview_url,
        'musique_cover_url': musique_cover_url,
        'musique_debut': musique_debut,
        'identifies': _idf,
        'telephone': _tel,
        'pays': _pays,
        'text_style': _text_style,
        'gif_url': _gif_url if _gif_valide and _gif_colonne else None,
        'mention_ia': _mention_ia,
        'mention_ia_type': _mention_ia_type if _mention_ia else None,
        'partager_story': (request.form.get('partager_story') or '0').strip() == '1'
    }

    if date_programmee:
        programme_enregistree = False
        try:
            programme = ScheduledPublication(
                user_id=current_user.id,
                payload=payload,
                scheduled_at=date_programmee,
                status='pending'
            )
            db.session.add(programme)
            db.session.commit()
            programme_enregistree = True
            flash(
                "Publication programmée avec succès. Elle sera publiée automatiquement à l'heure locale choisie.",
                'success'
            )
        except Exception as exc:
            db.session.rollback()
            print(f"[programmation] Enregistrement impossible : {exc}")
            flash("La programmation n'a pas pu être enregistrée. Réessayez.", 'danger')
        if not programme_enregistree and request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify(success=False, error="La programmation n'a pas pu être enregistrée."), 500
        if programme_enregistree and request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify(success=True, message="Publication programmée avec succès.",
                           redirect=url_for('main.feed'))
        return redirect(url_for('main.feed'))

    try:
        publication = _publication_depuis_payload(payload, current_user.id)
        db.session.add(publication)
        db.session.flush()
        _enregistrer_medias_supp(publication.id, payload.get('medias_supp'))
        reglage_commentaires = _reglage_pub(publication.id, creer=True)
        reglage_commentaires.permission_commentaires = payload.get('permission_commentaires') or 'tout_le_monde'
        db.session.commit()
    except Exception as exc:
        db.session.rollback()
        print(f"[publication] Création impossible : {exc}")
        flash("La publication n'a pas pu être créée. Réessayez.", 'danger')
        return redirect(url_for('main.feed'))

    try:
        if media_url and not musique and media_url.rsplit('.', 1)[-1].lower() in ('mp4', 'mov', 'webm'):
            _lancer_detection_musique(publication.id, media_url)
    except Exception as exc:
        print(f"DEBUG: détection de musique non lancée : {exc}")

    message_ok = 'Publication créée avec succès'
    try:
        if payload['partager_story']:
            if _creer_story_depuis_publication(publication, media_url, contenu, musique,
                                               musique_preview_url, musique_cover_url):
                message_ok += ' et partagée dans votre story'
    except Exception as exc:
        db.session.rollback()
        print(f"DEBUG: partage automatique en story ignoré : {exc}")
    flash(message_ok, 'success')
    if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
        return jsonify(success=True, message=message_ok, redirect=url_for('main.feed'), publication_id=publication.id)
    return redirect(url_for('main.feed'))


def traiter_publications_programmees(limite=20):
    """Publie les éléments échus de la file. Appelée périodiquement par app.py."""
    maintenant = datetime.utcnow()
    # Récupère les tâches abandonnées par un arrêt brutal du processus.
    try:
        ScheduledPublication.query.filter(
            ScheduledPublication.status == 'processing',
            ScheduledPublication.updated_at < maintenant - timedelta(minutes=15)
        ).update(
            {'status': 'pending', 'updated_at': maintenant},
            synchronize_session=False
        )
        db.session.commit()
    except Exception as exc:
        db.session.rollback()
        print(f"[programmation] Récupération des tâches interrompues impossible : {exc}")

    ids = [row.id for row in ScheduledPublication.query.filter(
        ScheduledPublication.status == 'pending',
        ScheduledPublication.scheduled_at <= maintenant
    ).order_by(ScheduledPublication.scheduled_at.asc()).limit(max(1, min(int(limite), 100))).all()]

    nb_publiees = 0
    for programme_id in ids:
        try:
            # UPDATE conditionnel = verrouillage atomique entre plusieurs workers.
            pris = ScheduledPublication.query.filter(
                ScheduledPublication.id == programme_id,
                ScheduledPublication.status == 'pending',
                ScheduledPublication.scheduled_at <= datetime.utcnow()
            ).update(
                {'status': 'processing', 'updated_at': datetime.utcnow(),
                 'attempts': ScheduledPublication.attempts + 1},
                synchronize_session=False
            )
            db.session.commit()
            if not pris:
                continue

            programme = db.session.get(ScheduledPublication, programme_id)
            if programme is None:
                continue
            payload = programme.payload or {}
            auteur = db.session.get(User, programme.user_id)
            if auteur is None:
                programme.status = 'failed'
                programme.last_error = "Compte auteur introuvable."
                db.session.commit()
                continue

            publication = _publication_depuis_payload(payload, programme.user_id)
            db.session.add(publication)
            db.session.flush()
            _enregistrer_medias_supp(publication.id, payload.get('medias_supp'))
            reglage_commentaires = _reglage_pub(publication.id, creer=True)
            reglage_commentaires.permission_commentaires = payload.get('permission_commentaires') or 'tout_le_monde'
            programme.status = 'published'
            programme.published_publication_id = publication.id
            programme.last_error = None
            programme.updated_at = datetime.utcnow()
            db.session.commit()
            nb_publiees += 1

            try:
                media = payload.get('media_url')
                musique = payload.get('musique')
                if media and not musique and media.rsplit('.', 1)[-1].lower() in ('mp4', 'mov', 'webm'):
                    _lancer_detection_musique(publication.id, media)
            except Exception as exc:
                print(f"[programmation] Détection audio ignorée pour #{publication.id}: {exc}")

            try:
                if payload.get('partager_story'):
                    _creer_story_depuis_publication(
                        publication, payload.get('media_url'), payload.get('contenu'),
                        payload.get('musique'), payload.get('musique_preview_url'),
                        payload.get('musique_cover_url')
                    )
            except Exception as exc:
                db.session.rollback()
                print(f"[programmation] Partage story ignoré pour #{publication.id}: {exc}")
        except Exception as exc:
            db.session.rollback()
            try:
                programme = db.session.get(ScheduledPublication, programme_id)
                if programme is not None and programme.status != 'published':
                    programme.status = 'failed'
                    programme.last_error = str(exc)[:1000]
                    programme.updated_at = datetime.utcnow()
                    db.session.commit()
            except Exception:
                db.session.rollback()
            print(f"[programmation] Échec publication programmée #{programme_id}: {exc}")
    return nb_publiees


@main_bp.route('/api/publications/programmees', methods=['GET'])
@login_required
def api_liste_publications_programmees():
    lignes = ScheduledPublication.query.filter_by(user_id=current_user.id).order_by(
        ScheduledPublication.scheduled_at.asc()
    ).limit(100).all()
    return jsonify(success=True, publications=[{
        'id': p.id,
        'status': p.status,
        'scheduled_at': p.scheduled_at.isoformat() + 'Z',
        'contenu': (p.payload or {}).get('contenu', '')[:180],
        'media': bool((p.payload or {}).get('media_url')),
        'last_error': p.last_error
    } for p in lignes])


@main_bp.route('/api/publications/programmees/<int:programme_id>/annuler', methods=['POST'])
@login_required
def api_annuler_publication_programmee(programme_id):
    programme = db.session.get(ScheduledPublication, programme_id)
    if programme is None or programme.user_id != current_user.id:
        return jsonify(success=False, error="Programmation introuvable."), 404
    if programme.status != 'pending':
        return jsonify(success=False, error="Cette programmation n'est plus en attente."), 409
    programme.status = 'cancelled'
    programme.updated_at = datetime.utcnow()
    media_annule = (programme.payload or {}).get('media_url')
    db.session.commit()
    try:
        nom_media = os.path.basename(media_annule or '')
        if nom_media and nom_media.startswith(f'pub_{current_user.id}_'):
            chemin_media = os.path.join('static', 'uploads', nom_media)
            if os.path.isfile(chemin_media):
                os.remove(chemin_media)
    except Exception as exc:
        print(f"[programmation] Nettoyage média après annulation ignoré : {exc}")
    return jsonify(success=True, message="Programmation annulée.")


@main_bp.route('/api/publications/programmees/<int:programme_id>/reessayer', methods=['POST'])
@login_required
def api_reessayer_publication_programmee(programme_id):
    programme = db.session.get(ScheduledPublication, programme_id)
    if programme is None or programme.user_id != current_user.id:
        return jsonify(success=False, error="Programmation introuvable."), 404
    if programme.status != 'failed':
        return jsonify(success=False, error="Seules les programmations en échec peuvent être relancées."), 409
    programme.status = 'pending'
    programme.scheduled_at = datetime.utcnow()
    programme.last_error = None
    programme.updated_at = datetime.utcnow()
    db.session.commit()
    return jsonify(success=True, message="Publication remise dans la file.")

@main_bp.route('/api/comment/<int:pub_id>', methods=['POST'])
@login_required
def api_add_comment(pub_id):
    pub = Publication.query.get_or_404(pub_id)
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    autorise, motif = _permission_commentaire_autorise(pub, current_user.id)
    if not autorise:
        return jsonify(success=False, error=motif), 403
    data = request.get_json(silent=True) or {}
    contenu = (data.get('contenu') or '').strip()
    if not contenu:
        return jsonify(success=False, error='Commentaire vide.'), 400
    if len(contenu) > 5000:
        return jsonify(success=False, error='Commentaire trop long.'), 400
    # ── AJOUT : réponse à un commentaire (parent_id facultatif → comportement inchangé sans lui) ──
    racine_id = cible_id = cible_user_id = None
    cible_nom = None
    parent_brut = data.get('parent_id')
    if parent_brut not in (None, '', 0, '0'):
        try:
            cible = Commentaire.query.get(int(parent_brut))
        except (TypeError, ValueError):
            cible = None
        if not cible or cible.publication_id != pub_id:
            return jsonify(success=False, error='Le commentaire auquel vous répondez est introuvable.'), 404
        racine_id = cible.parent_id or cible.id      # les réponses restent à 2 niveaux
        cible_id, cible_user_id = cible.id, cible.user_id
        cible_u = User.query.get(cible.user_id)
        cible_nom = cible_u.nom_complet if cible_u else None
    commentaire = Commentaire(contenu=contenu, user_id=current_user.id, publication_id=pub_id,
                              parent_id=racine_id, reply_to_id=cible_id, reply_to_user_id=cible_user_id)
    db.session.add(commentaire); db.session.commit()
    try:
        _deja_notifies = set()
        if cible_user_id and cible_user_id != current_user.id:
            if notifier(cible_user_id, 'reply', current_user, cible=('comment', cible_id), pub_id=pub_id, comment_id=commentaire.id):
                _deja_notifies.add(cible_user_id)
        if pub.user_id not in _deja_notifies:
            notifier(pub.user_id, 'comment', current_user, cible=('post', pub_id), pub_id=pub_id, comment_id=commentaire.id)
        _deja_notifies.add(pub.user_id)
        notifier_mentions(contenu, current_user, pub_id=pub_id, exclure_ids=_deja_notifies, comment_id=commentaire.id)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG notification commentaire : {e}")
    total = Commentaire.query.filter_by(publication_id=pub_id).count()
    return jsonify(success=True, id=commentaire.id, author=current_user.nom_complet,
                   avatar=current_user.avatar or 'default_avatar.png',
                   contenu=contenu, comments_count=total,
                   author_username=getattr(current_user, 'username', None),
                   date=_iso_utc(commentaire.date_creation),
                   parent_id=racine_id, reply_to_id=cible_id,
                   reply_to_name=cible_nom, parent_author=cible_nom)

@main_bp.route('/api/comment/<int:comment_id>/edit', methods=['POST'])
@login_required
def api_edit_comment(comment_id):
    comment = Commentaire.query.get_or_404(comment_id)
    if comment.user_id != current_user.id:
        return jsonify(success=False, error='Vous ne pouvez modifier que votre commentaire.'), 403
    data = request.get_json(silent=True) or {}
    contenu = (data.get('contenu') or '').strip()
    if not contenu:
        return jsonify(success=False, error='Commentaire vide.'), 400
    comment.contenu = contenu
    comment.date_modification = datetime.utcnow()   # la date de publication d'origine est conservée
    db.session.commit()
    return jsonify(success=True, id=comment.id, contenu=comment.contenu, edited=True)

@main_bp.route('/api/comment/<int:comment_id>/delete', methods=['POST'])
@login_required
def api_delete_comment(comment_id):
    comment = Commentaire.query.get_or_404(comment_id)
    pub = Publication.query.get_or_404(comment.publication_id)
    if current_user.id not in (comment.user_id, pub.user_id):
        return jsonify(success=False, error='Action non autorisée.'), 403
    db.session.delete(comment); db.session.commit()
    total = Commentaire.query.filter_by(publication_id=pub.id).count()
    return jsonify(success=True, id=comment_id, comments_count=total)

@main_bp.route('/api/comment/<int:comment_id>/report', methods=['POST'])
@login_required
def api_report_comment(comment_id):
    comment = Commentaire.query.get_or_404(comment_id)
    data = request.get_json(silent=True) or {}
    raison = (data.get('raison') or 'Autre').strip()[:100]
    description = (data.get('description') or '').strip()[:2000]
    deja = CommentaireSignalement.query.filter_by(commentaire_id=comment_id, user_id=current_user.id).first()
    if deja:
        return jsonify(success=True, message='Commentaire déjà signalé.')
    db.session.add(CommentaireSignalement(commentaire_id=comment_id, user_id=current_user.id,
        raison=raison or 'Autre', description=description or None))
    db.session.commit()
    return jsonify(success=True, message='Commentaire signalé.')

# ══════════════════════════════════════════════════════════════════════════
# COMMENTAIRES — FEUILLE DE COMMENTAIRES (réponses, « Voir plus », réactions)
# Bloc ADDITIF : aucune route existante n'est supprimée. Utilisé par
# templates/_comments_sheet.html (inclus dans feed.html et reel.html).
# ══════════════════════════════════════════════════════════════════════════
_COMMENT_REACTIONS = ('❤️', '😂', '😍', '🔥', '👏', '🙏')
_COMMENT_SCHEMA_OK = False


def _emoji_key(e):
    return (e or '').replace('\ufe0f', '').strip()


_COMMENT_REACTION_MAP = {_emoji_key(e): e for e in _COMMENT_REACTIONS}


@main_bp.before_app_request
def _ensure_commentaire_schema():
    """Ajoute, une seule fois, les colonnes/tables apparues avec les réponses
    aux commentaires. Sans effet si elles existent déjà (rien à migrer à la main)."""
    global _COMMENT_SCHEMA_OK
    if _COMMENT_SCHEMA_OK:
        return
    _COMMENT_SCHEMA_OK = True
    try:
        from sqlalchemy import inspect as _sa_inspect
        insp = _sa_inspect(db.engine)
        if 'commentaire' in insp.get_table_names():
            existantes = {c['name'] for c in insp.get_columns('commentaire')}
            ts = 'TIMESTAMP' if db.engine.dialect.name == 'postgresql' else 'DATETIME'
            ajouts = (('parent_id', 'INTEGER'), ('reply_to_id', 'INTEGER'),
                      ('reply_to_user_id', 'INTEGER'), ('date_modification', ts))
            with db.engine.begin() as conn:
                for nom, typ in ajouts:
                    if nom not in existantes:
                        conn.execute(db.text(f'ALTER TABLE commentaire ADD COLUMN {nom} {typ}'))
        CommentaireReaction.__table__.create(bind=db.engine, checkfirst=True)
    except Exception as e:
        print(f"DEBUG: migration commentaires non effectuée : {e}")


_PUB_SCHEMA_OK = False


@main_bp.before_app_request
def _ensure_publication_schema():
    """Ajoute, une seule fois, les colonnes identifies / telephone / pays à la table
    publication (même principe que _ensure_commentaire_schema). Sans effet si elles existent."""
    global _PUB_SCHEMA_OK
    if _PUB_SCHEMA_OK:
        return
    _PUB_SCHEMA_OK = True
    try:
        from sqlalchemy import inspect as _sa_inspect
        insp = _sa_inspect(db.engine)
        if 'publication' in insp.get_table_names():
            existantes = {c['name'] for c in insp.get_columns('publication')}
            ajouts = (('identifies', 'TEXT'), ('telephone', 'VARCHAR(40)'), ('pays', 'VARCHAR(100)'))
            with db.engine.begin() as conn:
                for nom, typ in ajouts:
                    if nom not in existantes:
                        conn.execute(db.text(f'ALTER TABLE publication ADD COLUMN {nom} {typ}'))
    except Exception as e:
        print(f"DEBUG: migration publication non effectuée : {e}")


def _iso_utc(dt):
    return (dt.strftime('%Y-%m-%dT%H:%M:%S') + 'Z') if dt else None


def _ids_personnes_identifiees(publication):
    """Retourne les identifiants des personnes explicitement identifiées dans le post."""
    brut = getattr(publication, 'identifies', None)
    if not brut:
        return set()
    if isinstance(brut, (list, tuple, set)):
        valeurs = brut
    else:
        # Le formulaire FaceNet enregistre actuellement les identifiants séparés par virgules.
        # Accepte aussi une liste JSON pour rester compatible avec d'éventuelles versions futures.
        texte = str(brut).strip()
        try:
            import json as _json
            decoded = _json.loads(texte)
            valeurs = decoded if isinstance(decoded, list) else texte.split(',')
        except Exception:
            valeurs = texte.split(',')
    ids = set()
    for valeur in valeurs:
        try:
            identifiant = int(valeur.get('id') if isinstance(valeur, dict) else valeur)
            if identifiant > 0:
                ids.add(identifiant)
        except (TypeError, ValueError):
            continue
    return ids


def _permission_commentaire_autorise(pub, viewer_id):
    """Vérifie les règles de commentaire, indépendamment de l'interface."""
    if not pub or not viewer_id:
        return False, "Connectez-vous pour commenter."
    if viewer_id == pub.user_id:
        return True, ''  # L'auteur conserve toujours son bouton et son droit de commenter.
    try:
        rg = _reglage_pub(pub.id)
        perm = (rg.permission_commentaires if rg else 'tout_le_monde') or 'tout_le_monde'
    except Exception:
        db.session.rollback()
        perm = 'tout_le_monde'

    if perm == 'personne':
        return False, "L'auteur a désactivé les commentaires sur cette publication."
    if perm == 'amis_followers':
        perm = 'amis'  # Compatibilité avec les anciennes valeurs du panneau de composition.
    if perm == 'amis':
        if viewer_id not in _amis_ids(pub.user_id):
            return False, "Seuls les amis de l'auteur peuvent commenter cette publication."
    elif perm == 'amis_amis':
        amis_directs = set(_amis_ids(pub.user_id) or [])
        autorises = set(amis_directs)
        for ami_id in amis_directs:
            try:
                autorises.update(_amis_ids(ami_id) or [])
            except Exception:
                continue
        autorises.discard(pub.user_id)
        if viewer_id not in autorises:
            return False, "Seuls les amis et les amis de leurs amis peuvent commenter cette publication."
    elif perm == 'mentionnes':
        if viewer_id not in _ids_personnes_identifiees(pub):
            return False, "Seules les personnes identifiées dans cette publication peuvent commenter."
    elif perm not in ('tout_le_monde', 'tous', 'public'):
        # Valeur historique inconnue : comportement permissif pour ne pas bloquer les posts existants.
        return True, ''
    return True, ''


@main_bp.app_template_global('peut_commenter_publication')
def peut_commenter_publication(pub, viewer_id=None):
    """Expose le contrôle au template pour masquer le bouton aux visiteurs non autorisés."""
    if viewer_id is None:
        viewer_id = current_user.id if getattr(current_user, 'is_authenticated', False) else None
    return _permission_commentaire_autorise(pub, viewer_id)[0]


def _peut_commenter_pub(pub):
    """(autorisé, message) — mêmes règles pour toutes les interfaces de commentaire."""
    return _permission_commentaire_autorise(pub, current_user.id)


def _reactions_pour(ids):
    """{commentaire_id: {counts, total, mine, top}} pour une liste de commentaires."""
    out = {i: {'counts': {}, 'total': 0, 'mine': None, 'top': []} for i in ids}
    if not ids:
        return out
    for r in CommentaireReaction.query.filter(CommentaireReaction.commentaire_id.in_(ids)).all():
        d = out[r.commentaire_id]
        d['counts'][r.emoji] = d['counts'].get(r.emoji, 0) + 1
        d['total'] += 1
        if r.user_id == current_user.id:
            d['mine'] = r.emoji
    for d in out.values():
        d['top'] = [e for e, _ in sorted(d['counts'].items(), key=lambda kv: -kv[1])[:3]]
    return out


def _serialiser_commentaires(commentaires, pub):
    ids = [c.id for c in commentaires]
    user_ids = {c.user_id for c in commentaires} | {c.reply_to_user_id for c in commentaires if c.reply_to_user_id}
    users = {u.id: u for u in User.query.filter(User.id.in_(user_ids)).all()} if user_ids else {}
    reactions = _reactions_pour(ids)
    nb_reponses = {}
    if ids:
        for pid, n in (db.session.query(Commentaire.parent_id, db.func.count(Commentaire.id))
                       .filter(Commentaire.parent_id.in_(ids)).group_by(Commentaire.parent_id).all()):
            nb_reponses[pid] = n
    liste = []
    for c in commentaires:
        u = users.get(c.user_id)
        cible = users.get(c.reply_to_user_id) if c.reply_to_user_id else None
        liste.append({
            'id': c.id,
            'user_id': c.user_id,
            'author': (u.nom_complet if u else 'Utilisateur'),
            'username': (getattr(u, 'username', None) if u else None),
            'avatar': ((u.avatar if u and u.avatar else None) or 'default_avatar.png'),
            'contenu': c.contenu,
            'date': _iso_utc(c.date_creation),
            'edited': bool(c.date_modification),
            'mine': c.user_id == current_user.id,
            'by_post_owner': c.user_id == pub.user_id,
            'can_delete': (c.user_id == current_user.id or pub.user_id == current_user.id),
            'parent_id': c.parent_id,
            'reply_to_id': c.reply_to_id,
            'reply_to_name': (cible.nom_complet if cible else None),
            'replies_count': nb_reponses.get(c.id, 0),
            'reactions': reactions.get(c.id),
        })
    return liste


@main_bp.route('/api/publication/<int:pub_id>/commentaires', methods=['GET'])
@login_required
def api_liste_commentaires(pub_id):
    pub = Publication.query.get_or_404(pub_id)
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    offset = max(request.args.get('offset', 0, type=int), 0)
    limit = min(max(request.args.get('limit', 15, type=int), 1), 30)
    base = Commentaire.query.filter_by(publication_id=pub_id, parent_id=None)
    racines = (base.order_by(Commentaire.date_creation.desc(), Commentaire.id.desc())
               .offset(offset).limit(limit + 1).all())
    has_more = len(racines) > limit
    racines = racines[:limit]
    ok, msg = _peut_commenter_pub(pub)
    return jsonify(
        success=True,
        comments=_serialiser_commentaires(racines, pub),
        has_more=has_more, next_offset=offset + len(racines),
        comments_count=Commentaire.query.filter_by(publication_id=pub_id).count(),
        can_comment=ok, block_message=msg,
        me={'id': current_user.id, 'name': current_user.nom_complet,
            'avatar': current_user.avatar or 'default_avatar.png'},
    )


@main_bp.route('/api/comment/<int:comment_id>/reponses', methods=['GET'])
@login_required
def api_reponses_commentaire(comment_id):
    racine = Commentaire.query.get_or_404(comment_id)
    pub = Publication.query.get_or_404(racine.publication_id)
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    offset = max(request.args.get('offset', 0, type=int), 0)
    limit = min(max(request.args.get('limit', 5, type=int), 1), 30)
    reps = (Commentaire.query.filter_by(parent_id=comment_id)
            .order_by(Commentaire.date_creation.asc(), Commentaire.id.asc())
            .offset(offset).limit(limit + 1).all())
    has_more = len(reps) > limit
    reps = reps[:limit]
    return jsonify(success=True, replies=_serialiser_commentaires(reps, pub),
                   has_more=has_more, next_offset=offset + len(reps),
                   total=Commentaire.query.filter_by(parent_id=comment_id).count())


@main_bp.route('/api/comment/<int:comment_id>/reagir', methods=['POST'])
@login_required
def api_reagir_commentaire(comment_id):
    c = Commentaire.query.get_or_404(comment_id)
    pub = Publication.query.get_or_404(c.publication_id)
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    data = request.get_json(silent=True) or {}
    emoji = _COMMENT_REACTION_MAP.get(_emoji_key(data.get('emoji')))
    if not emoji:
        return jsonify(success=False, error='Réaction non valide.'), 400
    existante = CommentaireReaction.query.filter_by(commentaire_id=comment_id, user_id=current_user.id).first()
    if existante and existante.emoji == emoji:
        db.session.delete(existante)              # même emoji : on retire la réaction
    elif existante:
        existante.emoji = emoji                   # autre emoji : on remplace
    else:
        db.session.add(CommentaireReaction(commentaire_id=comment_id, user_id=current_user.id, emoji=emoji))
    db.session.commit()
    r = _reactions_pour([comment_id])[comment_id]
    return jsonify(success=True, total_reactions=r['total'], mine=r['mine'], top=r['top'], counts=r['counts'])


