# ── AJOUT : suggestions pour les mentions @ (amis + followers de l'utilisateur connecté) ──
@main_bp.route('/api/mentions/suggestions', methods=['GET'])
@login_required
def api_mentions_suggestions():
    q = (request.args.get('q') or '').strip().lstrip('@').lower()[:30]
    try:
        _assurer_table_abonnement()
        ids = set(_amis_ids(current_user.id))
        try:
            ids.update(row[0] for row in db.session.query(Abonnement.follower_id)
                       .filter(Abonnement.suivi_id == current_user.id).limit(2000).all())
        except Exception as e:
            db.session.rollback(); print(f"DEBUG mentions (followers) : {e}")
        ids.discard(current_user.id)
        items = []
        if ids:
            req = User.query.filter(User.id.in_(list(ids)))
            if q:
                motif = f"%{q}%"
                req = req.filter(or_(User.username.ilike(motif), User.nom_complet.ilike(motif)))
            for u in req.order_by(User.nom_complet.asc()).limit(30).all():
                if not re.match(r'^[A-Za-z0-9_.]{2,30}$', u.username or ''):
                    continue   # un pseudo avec espace ou accent ne peut pas être mentionné
                items.append({'type': 'user', 'id': u.id, 'username': u.username,
                              'nom_complet': u.nom_complet or u.username,
                              'avatar': u.avatar or 'default_avatar.png'})
                if len(items) >= 8:
                    break
        groupes = []
        for mot, nom, desc in (('followers', 'Tous vos followers', 'Vos abonnés et vos amis seront notifiés'),
                               ('amis', 'Tous vos amis', 'Tous vos amis seront notifiés')):
            if ids and (not q or mot.startswith(q)):
                groupes.append({'type': 'groupe', 'username': mot, 'nom_complet': nom, 'description': desc})
        return jsonify(success=True, items=groupes + items)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: suggestions de mentions indisponibles : {e}")
        return jsonify(success=False, items=[], error='Suggestions indisponibles.'), 500

# ── AJOUT ADDITIF : amis d'un profil (grille « Amis » façon Facebook de profile.html).
# profile.html appelait déjà /api/amis/<id> : la route n'existait pas (grille vide).
# Mêmes données que la liste des amis déjà affichée publiquement sur le profil.
@main_bp.route('/api/amis/<int:user_id>', methods=['GET'])
def api_amis_de(user_id):
    if db.session.get(User, user_id) is None:
        return jsonify(success=False, error='Utilisateur introuvable.'), 404
    try:
        ids = _amis_ids(user_id)
        amis = User.query.filter(User.id.in_(ids)).all() if ids else []
        viewer_id = current_user.id if current_user.is_authenticated else None
        communs = (ids & _amis_ids(viewer_id)) if (viewer_id and viewer_id != user_id) else set()
        amis.sort(key=lambda u: (u.id not in communs, (u.nom_complet or u.username or '').lower()))
        # AJOUT ADDITIF : nombre d'amis en commun avec le visiteur + pastille de présence (en ligne / « 3 h »),
        # calculés pour les 24 premiers amis seulement (l'aperçu du profil en affiche 4). Clés ajoutées, aucune retirée.
        _nb_communs = {}
        try:
            if viewer_id:
                _amis_visiteur = _amis_ids(viewer_id)
                if _amis_visiteur:
                    _nb_communs = _amis_communs_pour(_amis_visiteur, [u.id for u in amis[:24]]) or {}
        except Exception as _e:
            db.session.rollback()
            print(f"DEBUG: amis en commun (aperçu) indisponibles : {_e}")
            _nb_communs = {}
        def _presence_ami(u):
            try:
                _en_ligne = bool(est_en_ligne(u))
                return _en_ligne, ('' if _en_ligne else badge_presence_court(u.last_seen))
            except Exception:
                return False, ''
        _liste = []
        for _i, u in enumerate(amis):
            _pe, _pb = _presence_ami(u) if _i < 24 else (False, '')
            _liste.append({
                'id': u.id, 'username': u.username,
                'nom_complet': u.nom_complet or u.username,
                'avatar': u.avatar or 'default_avatar.png',
                'en_commun': u.id in communs,
                'nb_communs': int(_nb_communs.get(u.id, 0) or 0) if viewer_id and viewer_id != u.id else 0,
                'pres_en_ligne': _pe, 'pres_badge': _pb})
        return jsonify(success=True, amis=_liste)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: liste d'amis indisponible : {e}")
        return jsonify(success=False, error='Liste indisponible.'), 500

@main_bp.route('/api/partager/<int:pub_id>', methods=['POST'])
@login_required
def api_partager(pub_id):
    pub = Publication.query.get_or_404(pub_id)
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    data = request.get_json(silent=True) or {}
    raw = data.get('destinataires') or []
    if not isinstance(raw, list) or not raw:
        return jsonify(success=False, error='Sélectionnez au moins un ami.'), 400
    ids = set()
    for value in raw:
        try:
            uid = int(value)
            if uid != current_user.id: ids.add(uid)
        except (TypeError, ValueError):
            continue
    amis_ids = _amis_ids(current_user.id)
    ids &= amis_ids
    if not ids:
        return jsonify(success=False, error='Aucun destinataire valide.'), 400
    ajoutes = 0
    for uid in ids:
        deja = PublicationShare.query.filter_by(publication_id=pub_id, sender_id=current_user.id, recipient_id=uid).first()
        if not deja:
            db.session.add(PublicationShare(publication_id=pub_id, sender_id=current_user.id,
                recipient_id=uid, share_type='interne'))
            ajoutes += 1
    if ajoutes:
        pub.share_count = (pub.share_count or 0) + ajoutes
        notifier(pub.user_id, 'share', current_user, cible=('post', pub_id), pub_id=pub_id)
    db.session.commit()
    return jsonify(success=True, shared_count=ajoutes, total_shares=pub.share_count or 0)

@main_bp.route('/api/partager/<int:pub_id>/externe', methods=['POST'])
@login_required
def api_partager_externe(pub_id):
    pub = Publication.query.get_or_404(pub_id)
