@login_required
def approuver_verification(user_id):
    if not current_user.is_pdg:
        abort(403)
    if not _pdg_csrf_ok():
        flash("Session de sécurité expirée, rechargez la page puis réessayez.", "danger")
        return redirect(url_for('main.admin_verifications'))
    utilisateur = User.query.get_or_404(user_id)
    if not utilisateur.piece_identite_fichier:
        flash("Cet utilisateur n'a pas de pièce d'identité en attente.", "info")
        return redirect(url_for('main.admin_verifications'))
    if not utilisateur.forfait_type:
        flash("Le paiement du forfait n'est pas confirmé pour cet utilisateur : validation impossible.", "warning")
        return redirect(url_for('main.admin_verifications'))
    utilisateur.is_verify = True
    utilisateur.has_badge_bleu = True
    utilisateur.badge_expire = datetime.utcnow() + timedelta(days=30)
    SUPPORT_ID = 1
    notifier(utilisateur.id, 'blue_badge_active', message="Félicitations ! Votre pièce d'identité a été vérifiée et votre badge bleu Tsapi Verified est désormais actif sur votre profil.")
    db.session.commit()
    flash(f"Badge bleu attribué à {utilisateur.nom_complet or utilisateur.username}.", "success")
    return redirect(url_for('main.admin_verifications'))

