@groupe_bp.route('/groupe/<int:group_id>')
def groupe_accueil(group_id):
    group = Group.query.get_or_404(group_id)
    members = [gm.user for gm in group.members]
    is_member = current_user.is_authenticated and any(gm.user_id == current_user.id for gm in group.members)
    posts = GroupPost.query.filter_by(group_id=group_id).order_by(GroupPost.date_pub.desc()).all()
