@groupe_bp.route('/groupe/<int:group_id>/rejoindre', methods=['POST'])
@login_required
def groupe_rejoindre(group_id):
    group = Group.query.get_or_404(group_id)
    deja_membre = GroupMember.query.filter_by(group_id=group_id, user_id=current_user.id).first()
    if deja_membre:
        return jsonify(success=False, message="Vous êtes déjà membre.")
    if group.is_private:
        demande = GroupJoinRequest.query.filter_by(group_id=group_id, user_id=current_user.id, statut='en_attente').first()
        if demande:
            return jsonify(success=False, message="Votre demande est déjà en attente.")
        demande = GroupJoinRequest(group_id=group_id, user_id=current_user.id, statut='en_attente', date_demande=datetime.utcnow())
        db.session.add(demande); db.session.commit()
        return jsonify(success=True, message="Demande envoyée, en attente de validation.")
    membre = GroupMember(group_id=group_id, user_id=current_user.id, role='membre', date_adhesion=datetime.utcnow())
    db.session.add(membre); db.session.commit()
    return jsonify(success=True)

