def _reel_visible_pour(reel, viewer_id):
    """AJOUT : un Reel lié à une publication suit la confidentialité de cette publication
    (Public / Amis / Famille / Moi uniquement). Sans publication liée : comportement d'avant."""
    pub = getattr(reel, 'publication', None)
    if pub is None:
        return True
    return _peut_voir_publication(pub, viewer_id)

def get_more_reels(offset, limit):
    lignes = Reel.query.order_by(Reel.created_at.desc()).offset(offset).limit(limit).all()
    return [r for r in lignes if _reel_visible_pour(r, current_user.id)]   # AJOUT : confidentialité

def get_single_reel(reel_id):
    reel = Reel.query.get_or_404(reel_id)
    if not _reel_visible_pour(reel, current_user.id):                      # AJOUT : confidentialité
        abort(404)
    return [reel]

def build_videos_payload(reels):
    payload = []
    for reel in reels:
        payload.append({'id': reel.id,
            'video_url': url_for('static', filename='uploads/reels/' + reel.fichier_video),
            'description': reel.description, 'username': reel.auteur.username})
    return payload

