def _cle_reseau(txt):
    """Forme normalisée d'un nom de réseau : sans accents, majuscules, espaces, @, www ni .com."""
    s = _ud_res.normalize('NFKD', str(txt or '')).encode('ascii', 'ignore').decode('ascii').lower().strip()
    s = _re_res.sub(r'^https?://', '', s)
    s = _re_res.sub(r'^www\.', '', s).lstrip('@')
    s = _re_res.sub(r'\.(com|net|org|fr|io|tv|me|co|app|social|ru|cn)(/.*)?$', '', s)
    return _re_res.sub(r'[^a-z0-9]', '', s)

RESEAUX_PAR_CLE = {}
for _nom_r, _cls_r, _alias_r in _RESEAUX_LISTE:
    for _a_r in [_nom_r] + _alias_r:
        _k_r = _cle_reseau(_a_r)
        if _k_r:
            RESEAUX_PAR_CLE.setdefault(_k_r, (_nom_r, _cls_r))

def detecter_reseau(nom):
    """(nom officiel, classe du logo) si le réseau existe dans la liste, sinon None."""
    k = _cle_reseau(nom)
    return RESEAUX_PAR_CLE.get(k) if k else None

def _detecter_reseau_url(url):
    try:
        h = (_urlparse_res(url if '//' in url else '//' + url).hostname or '').lower()
    except ValueError:
        return None
    for lab in reversed(h.split('.')[:-1]):
        r = detecter_reseau(lab)
        if r:
            return r
    return None

def _msg_reseau_inconnu(nom):
    return (f"« {(nom or '')[:40]} » n'existe pas comme réseau social. "
            "Saisissez le vrai nom d'un réseau social, ou retirez cette ligne.")

def _lire_reseaux_form(form):
    """(dict {réseau: lien}, message d'erreur ou None) à partir des lignes du formulaire.
    Pour « Autre », le nom saisi doit être un réseau social existant : on enregistre son nom officiel."""
    plateformes = form.getlist('social_platform[]')
    liens = form.getlist('social_url[]')
    autres = form.getlist('social_autre[]')
    resultat = {}
    for i, (plat, url) in enumerate(zip(plateformes, liens)):
        plat = (plat or '').strip()
        url = (url or '').strip()
        autre = (autres[i] if i < len(autres) else '').strip()
        if plat == 'Autre':
            if not autre and not url:
                continue
            if autre:
                trouve = detecter_reseau(autre)
                if not trouve:
                    return resultat, _msg_reseau_inconnu(autre)
            else:
                trouve = _detecter_reseau_url(url)
                if not trouve:
                    return resultat, "Indiquez le nom du réseau social : le champ « Autre » ne peut pas rester vide."
            plat = trouve[0]
        if plat and url:
            resultat[plat] = url
    return resultat, None

def _render_edit_profile(**extra):
    visibilite, parcours = _donnees_edition_profil(current_user)
    return render_template('edit_profile.html', visibilite=visibilite, parcours=parcours,
                           partenaire=_partenaire_profil(current_user),
                           infos_sup=_infos_sup_valeurs(current_user.id),
                           communautes=_communautes_profil(current_user, current_user.id, True),   # AJOUT ADDITIF
                           liens_perso=_liens_perso_lire(current_user.id),
                           social_links=_reseaux_sociaux_de(current_user),
                           jours_restants_nom=current_user.jours_restants_changement_nom(),
                           reseaux_connus={k: [v[0], v[1]] for k, v in RESEAUX_PAR_CLE.items()},
                           logos_reseaux={k: r[1] for k, r in ((k, detecter_reseau(k)) for k in _reseaux_sociaux_de(current_user)) if r},
                           **extra)

# ── AJOUT ADDITIF : garde « prénom » et « nom » alignés sur le nom complet choisi
# (sinon « À propos de <prénom> » et les lignes Nom/Prénom du menu du profil restent anciens). ──
def _synchroniser_prenom_nom(user, nom_complet):
    mots = (nom_complet or '').split()
    if not mots:
        return
    user.prenom = mots[0]
    user.nom = ' '.join(mots[1:])

def _reparer_prenom_nom_si_decale(user):
    """Profils dont le nom a déjà été changé avant la synchronisation : on réaligne prénom/nom sur le nom complet affiché.
    N'agit que si le nom a déjà été modifié (last_name_change) ET que prénom + nom ne correspondent plus. Ne lève jamais d'exception."""
    try:
        if not getattr(user, 'last_name_change', None):
            return
        complet = ' '.join((user.nom_complet or '').split())
        actuel = ' '.join(((user.prenom or '') + ' ' + (user.nom or '')).split())
        if complet and complet.lower() != actuel.lower():
            _synchroniser_prenom_nom(user, complet)
            db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: réalignement prénom/nom impossible : {e}")

# ── AJOUT ADDITIF : règle de casse des noms (majuscule au début de chaque partie, le reste en minuscules) ──
def _normaliser_nom_propre(valeur):
    """(nom normalisé, None) si valide ; (None, message) si une partie commence par une minuscule.
    « Jean Pierre » -> accepté ; « jean » ou « Jean pierre » -> refusé ; « JEAN PIERRE » -> « Jean Pierre ».
    Les traits d'union et apostrophes sont gérés : « Jean-pierre » -> « Jean-Pierre »."""
    mots = (valeur or '').split()
    if not mots:
        return valeur, None
    resultat = []
    for mot in mots:
        if not mot[0].isupper():
            return None, "Chaque partie du nom doit commencer par une majuscule (exemple : Jean Pierre)."
        morceaux = re.split(r"([-'\u2019])", mot)
        resultat.append(''.join(m[:1].upper() + m[1:].lower() for m in morceaux))
    return ' '.join(resultat), None

@main_bp.route('/edit_profile', methods=['GET', 'POST'])
@login_required
def edit_profile():
    if request.method == 'POST':
        # ── Règles de noms : personnalités certifiées protégées + délai de 15 jours ──
        # Tout est validé AVANT de modifier current_user : en cas d'erreur, rien n'est enregistré.
        def _change(a, b):
            return a is not None and a.strip() != '' and a.strip() != (b or '').strip()

        session.pop('nom_en_attente', None)   # un ancien choix non terminé est abandonné
        nom_choix_requis = False
        modif_attente_id = None   # AJOUT ADDITIF : demande de revérification (abonné Tsapi Verified)
        _pause_signalee = False   # AJOUT ADDITIF : un seul message de pause, même si nom ET photo changent

        # Réseaux sociaux : « Autre » doit être un réseau existant (vérifié avant toute modification)
        _reseaux_form, _erreur_reseau = _lire_reseaux_form(request.form)
        if _erreur_reseau:
            return _render_edit_profile(social_error=_erreur_reseau, saisie=request.form.to_dict())

        new_username = (request.form.get('username') or '').strip()
        nom_complet = request.form.get('nom_complet')
        nom = request.form.get('nom')
        prénom = request.form.get('prenom')

        username_change = bool(new_username) and new_username.lower() != (current_user.username or '').lower()
        nom_complet_change = _change(nom_complet, current_user.nom_complet)
        nom_change = _change(nom, current_user.nom)
        prenom_change = _change(prénom, current_user.prenom)

        if username_change or nom_complet_change or nom_change or prenom_change:
            # AJOUT ADDITIF : majuscule au début de chaque partie du nom, refus sinon (rien n'est enregistré)
            _erreur_casse = None
            if nom_complet_change:
                nom_complet, _erreur_casse = _normaliser_nom_propre(nom_complet)
            if not _erreur_casse and nom_change:
                nom, _erreur_casse = _normaliser_nom_propre(nom)
            if not _erreur_casse and prenom_change:
                prénom, _erreur_casse = _normaliser_nom_propre(prénom)
            if _erreur_casse:
                return _render_edit_profile(name_error=_erreur_casse, name_suggestions=[],
                                            saisie=request.form.to_dict())
            noms_affiches = []
            if nom_complet_change:
                noms_affiches.append(nom_complet)
            if nom_change or prenom_change:
                noms_affiches.append(
                    f"{(prénom if prenom_change else current_user.prenom) or ''} "
                    f"{(nom if nom_change else current_user.nom) or ''}")

            erreur_nom = None
            suggestions_nom = []
            # 1) Priorité absolue : nom d'une personnalité publique certifiée
            if compte_certifie_possedant_nom(username=new_username if username_change else None,
                                             noms_affiches=noms_affiches,
                                             exclure_user_id=current_user.id):
                erreur_nom = MSG_NOM_CERTIFIE
                if noms_affiches:
                    suggestions_nom = [f"{x['prenom']} {x['nom']}"
                                       for x in suggerer_depuis_nom_complet(noms_affiches[0])]
            else:
                # 2) Délai de 15 jours
                jours = current_user.jours_restants_changement_nom()
                if jours > 0:
                    erreur_nom = f"Vous pourrez modifier votre nom dans {jours} jour{'s' if jours > 1 else ''}."
                # 3) Unicité standard du username
                elif username_change and username_deja_pris(new_username, exclure_user_id=current_user.id):
                    erreur_nom = "Ce nom d'utilisateur est déjà utilisé. Veuillez en choisir un autre."

            if erreur_nom:
                return _render_edit_profile(name_error=erreur_nom, name_suggestions=suggestions_nom,
                                            saisie=request.form.to_dict())

            # AJOUT ADDITIF : abonné Tsapi Verified → le nom n'est PAS appliqué tout de suite, il passe par la revérification
            if _est_abonne_verifie(current_user) and (nom_complet_change or nom_change or prenom_change):
                _pause_rv = _reverif_verrou(current_user.id)
                if _pause_rv:
                    flash(_reverif_message_verrou(_pause_rv), "error")   # nom NON enregistré pendant la pause
                    _pause_signalee = True
                else:
                    _nom_demande = (nom_complet.strip() if nom_complet_change else
                                    f"{(prénom if prenom_change else current_user.prenom) or ''} "
                                    f"{(nom if nom_change else current_user.nom) or ''}".strip())
                    modif_attente_id = _modif_creer(current_user.id, 'nom', nouveau_nom=_nom_demande, commit=False)
                nom_complet_change = nom_change = prenom_change = False

            if username_change: current_user.username = new_username
            if nom_change: current_user.nom = nom.strip()
            if prenom_change: current_user.prenom = prénom.strip()
            if nom_complet_change:
                _mots_nom = nom_complet.strip().split()
                if len(_mots_nom) >= 2 and not (username_change or nom_change or prenom_change):
                    # Le choix de l'ordre (« Paul Bia » ou « Bia Paul ») se fait sur une page dédiée ;
                    # le nom n'est enregistré (et le délai de 15 jours déclenché) qu'après ce choix.
                    session['nom_en_attente'] = ' '.join(_mots_nom)
                    nom_choix_requis = True
                else:
                    current_user.nom_complet = nom_complet.strip()
                    if not (nom_change or prenom_change):
                        _synchroniser_prenom_nom(current_user, nom_complet)
            if username_change or nom_change or prenom_change or (nom_complet_change and not nom_choix_requis):
                current_user.last_name_change = datetime.utcnow()
                current_user.name_change_count = (current_user.name_change_count or 0) + 1
                flash("Nom mis à jour avec succès")
        bio = request.form.get('bio')
        if bio is not None:
            # AJOUT ADDITIF : biographie limitée à 90 caractères (une biographie plus longue déjà enregistrée reste acceptée telle quelle)
            if len(bio.strip()) > 90 and bio.strip() != (current_user.bio or '').strip():
                flash("La biographie ne doit pas dépasser 90 caractères : elle n'a pas été modifiée.")
            else:
                current_user.bio = bio
        birth_date_str = request.form.get('birth_date')
        if birth_date_str:
            try: current_user.birth_date = datetime.strptime(birth_date_str, '%Y-%m-%d').date()
            except ValueError: pass
        sexe = request.form.get('sexe')
        if sexe: current_user.sexe = sexe
        situation = request.form.get('situation_amoureuse')
        if situation: current_user.situation_amoureuse = situation
        langues = request.form.get('langues')
        if langues is not None: current_user.langues = langues
        email = request.form.get('email')
        if email: current_user.email = email
        phone = request.form.get('phone')
        if phone is not None:
            # CORRECTION : un numéro vide est enregistré en NULL (jamais en '') : la colonne user.phone est UNIQUE,
            # et deux profils avec '' provoquaient « UNIQUE constraint failed: user.phone » (erreur 500).
            current_user.phone = phone.strip() or None
        site_web = request.form.get('site_web')
        if site_web is not None: current_user.site_web = site_web
        ville = request.form.get('ville')
        if ville is not None: current_user.ville = ville
        localisation = request.form.get('localisation')
        if localisation is not None: current_user.localisation = localisation
        emploi = request.form.get('emploi_actuel')
        if emploi is not None: current_user.emploi_actuel = emploi
        entreprise = request.form.get('entreprise')
        if entreprise is not None: current_user.entreprise = entreprise
        ecole = request.form.get('ecole')
        if ecole is not None: current_user.ecole = ecole
        universite = request.form.get('universite')
        if universite is not None: current_user.universite = universite
        groupes = request.form.get('groupes_musicaux_preferes')
        if groupes is not None: current_user.groupes_musicaux_preferes = groupes
        jeux = request.form.get('jeux_video_preferes')
        if jeux is not None: current_user.jeux_video_preferes = jeux
        films = request.form.get('films_preferes')
        if films is not None: current_user.films_preferes = films
        emissions = request.form.get('emissions_tv_preferees')
        if emissions is not None: current_user.emissions_tv_preferees = emissions
        plateformes = request.form.getlist('social_platform[]')
        liens = request.form.getlist('social_url[]')
        if plateformes or liens:
            current_user.reseaux_sociaux = json.dumps(_reseaux_form)
        photo_maj = False
        if 'profile_pic' in request.files:
            file = request.files['profile_pic']
            if file and file.filename != '' and _est_abonne_verifie(current_user):
                # AJOUT ADDITIF : abonné Tsapi Verified → la photo est mise en attente de revérification (non appliquée)
                _pause_rv = _reverif_verrou(current_user.id)
                if _pause_rv:
                    if not _pause_signalee:
                        flash(_reverif_message_verrou(_pause_rv), "error")   # photo NON enregistrée pendant la pause
                        _pause_signalee = True
                else:
                    _nf_att, _err_att = _enregistrer_photo_verification(file, prefixe='attente_')
                    if _nf_att:
                        modif_attente_id = _modif_creer(current_user.id, 'photo', nouvelle_photo=_nf_att, commit=False)
                    elif _err_att:
                        flash("Photo refusée : " + _err_att)
            elif file and file.filename != '':
                filename = secure_filename(file.filename)
                import time
                unique_filename = f"{int(time.time())}_{filename}"
                file.save(os.path.join('static', 'uploads', unique_filename))
                current_user.avatar = unique_filename
                photo_maj = True
                # ── AJOUT ADDITIF : publication auto dans le fil (si activé)
                # + entrée dans l'historique des photos de profil.
                nouvelle_pub_avatar = None
                if current_user.notifier_changement_photo:
                    nouvelle_pub_avatar = Publication(
                        contenu="a changé sa photo de profil",
                        media_url=unique_filename,
                        user_id=current_user.id,
                        type_publication='photo_profil',
                        confidentialite='public'
                    )
                    db.session.add(nouvelle_pub_avatar)
                    db.session.flush()  # obtenir l'id avant le commit final
                db.session.add(PhotoHistorique(
                    user_id=current_user.id, type_photo='avatar', url=unique_filename,
                    publication_id=nouvelle_pub_avatar.id if nouvelle_pub_avatar else None
                ))
        if 'cover_pic' in request.files:
            file_cover = request.files['cover_pic']
            if file_cover and file_cover.filename != '':
                filename_c = secure_filename(file_cover.filename)
                import time
                unique_filename_c = f"{int(time.time())}_cover_{filename_c}"
                file_cover.save(os.path.join('static', 'uploads', unique_filename_c))
                current_user.couverture = unique_filename_c
                photo_maj = True
                # ── AJOUT ADDITIF : publication auto dans le fil (si activé)
                # + entrée dans l'historique des photos de couverture.
                nouvelle_pub_couverture = None
                if current_user.notifier_changement_photo:
                    nouvelle_pub_couverture = Publication(
                        contenu="a changé sa photo de couverture",
                        media_url=unique_filename_c,
                        user_id=current_user.id,
                        type_publication='photo_couverture',
                        confidentialite='public'
                    )
                    db.session.add(nouvelle_pub_couverture)
                    db.session.flush()
                db.session.add(PhotoHistorique(
                    user_id=current_user.id, type_photo='couverture', url=unique_filename_c,
                    publication_id=nouvelle_pub_couverture.id if nouvelle_pub_couverture else None
                ))
        # ── AJOUT ADDITIF : dates de parcours + choix afficher/masquer
        try:
            _enregistrer_profil_extra(current_user, request.form)
        except Exception as e:
            print(f"DEBUG: enregistrement profil_extra impossible : {e}")
            db.session.rollback()
            return redirect(url_for('main.edit_profile'))
        # ── AJOUT ADDITIF : partenaire identifié (situation amoureuse)
        try:
            _enregistrer_partenaire(current_user, request.form)
        except Exception as e:
            print(f"DEBUG: enregistrement du partenaire impossible : {e}")
        # ── AJOUT ADDITIF : informations supplémentaires du profil
        try:
            _enregistrer_infos_sup(current_user, request.form)
        except Exception as e:
            print(f"DEBUG: enregistrement des infos supplémentaires impossible : {e}")
        # ── AJOUT ADDITIF : liens personnalisés (nom + lien)
        try:
            _enregistrer_liens_perso(current_user, request.form)
        except Exception as e:
            print(f"DEBUG: enregistrement des liens du profil impossible : {e}")
        try:
            db.session.commit()
        except Exception as _e_commit:
            # CORRECTION : un conflit d'unicité (téléphone / e-mail) donne un message clair, pas une erreur 500
            db.session.rollback()
            _txt_commit = str(_e_commit)
            if 'UNIQUE constraint failed: user.phone' in _txt_commit:
                flash("Ce numéro de téléphone est déjà utilisé par un autre profil. Veuillez en saisir un autre.", 'error')
            elif 'UNIQUE constraint failed: user.email' in _txt_commit:
                flash("Cette adresse e-mail est déjà utilisée par un autre profil. Veuillez en saisir une autre.", 'error')
            else:
                print(f"❌ ERREUR /edit_profile : {_txt_commit}")
                flash("Une erreur est survenue : vos modifications n'ont pas été enregistrées. Réessayez.", 'error')
            return redirect(url_for('main.edit_profile'))
        _toucher_profil(current_user.id)
        if photo_maj: flash('Photo mise à jour', 'photo_success')
        else: flash('Profil mis à jour avec succès !', 'success')
        if modif_attente_id:   # AJOUT ADDITIF : abonné vérifié → étape de vérification de la pièce d'identité
            return redirect(url_for('main.reverif_piece', modif_id=modif_attente_id))
        if nom_choix_requis:
            return redirect(url_for('main.choix_nom_profil'))
        from_verification = request.form.get('from_verification') == 'true' or request.args.get('mode') == 'verification'
        if from_verification:
            return redirect(url_for('main.verification_etape_guide_visage'))
        return redirect(url_for('main.profile', username=current_user.username))
    return _render_edit_profile()

def _options_ordre_nom(nom_saisi):
    """Les façons d'afficher le nom : tel que saisi, et avec le premier mot placé à la fin
    (« Paul Bia » -> « Bia Paul »). Calculé côté serveur : le navigateur ne choisit qu'un numéro."""
    mots = (nom_saisi or '').split()
    if len(mots) < 2:
        return []
    a = ' '.join(mots)
    b = ' '.join(mots[1:] + mots[:1])
    return [a] if a == b else [a, b]

@main_bp.route('/edit_profile/choix-nom', methods=['GET', 'POST'])
@login_required
def choix_nom_profil():
    """Page où l'utilisateur choisit comment son nom s'affiche sur son profil, avant enregistrement."""
    en_attente = session.get('nom_en_attente')
    options = _options_ordre_nom(en_attente)
    if not options:
        session.pop('nom_en_attente', None)
        return redirect(url_for('main.edit_profile'))
    erreur = None
    if request.method == 'POST':
        if not _pdg_csrf_ok():
            flash("Session de sécurité expirée, veuillez réessayer.", "danger")
            return redirect(url_for('main.edit_profile'))
        if request.form.get('action') == 'annuler':
            session.pop('nom_en_attente', None)
            return redirect(url_for('main.edit_profile'))
        try:
            idx = int(request.form.get('choix', ''))
        except (TypeError, ValueError):
            idx = -1
        if not 0 <= idx < len(options):
            erreur = "Choisissez l'une des façons d'afficher votre nom."
        else:
            choisi = options[idx]
            if compte_certifie_possedant_nom(noms_affiches=[choisi], exclure_user_id=current_user.id):
                session.pop('nom_en_attente', None)
                flash(MSG_NOM_CERTIFIE, "danger")
                return redirect(url_for('main.edit_profile'))
            jours = current_user.jours_restants_changement_nom()
            if jours > 0:
                session.pop('nom_en_attente', None)
                flash(f"Vous pourrez modifier votre nom dans {jours} jour{'s' if jours > 1 else ''}.", "warning")
                return redirect(url_for('main.edit_profile'))
            try:
                current_user.nom_complet = choisi
                _synchroniser_prenom_nom(current_user, choisi)
                current_user.last_name_change = datetime.utcnow()
                current_user.name_change_count = (current_user.name_change_count or 0) + 1
                db.session.commit()
                _toucher_profil(current_user.id)
            except Exception as e:
                db.session.rollback()
                print(f"DEBUG choix_nom_profil : {e}")
                flash("Une erreur est survenue pendant l'enregistrement. Veuillez réessayer.", "danger")
                return redirect(url_for('main.choix_nom_profil'))
            session.pop('nom_en_attente', None)
            flash("Nom mis à jour avec succès")
            return redirect(url_for('main.profile', username=current_user.username))
    return render_template('choix_nom.html', options=options, erreur=erreur,
                           nom_actuel=current_user.nom_complet or '',
                           csrf_token=_fn_csrf_token())

@main_bp.route('/forgot-password', methods=['GET', 'POST'])
def forgot_password():
    if request.method == 'POST':
        identifier = request.form.get('identifier')
        user = User.query.filter((User.email == identifier) | (User.phone == identifier)).first()
        if user:
            code = ''.join(random.choices(string.digits, k=6))
            user.reset_code = code
            user.reset_code_expires = datetime.utcnow() + timedelta(minutes=10)
            db.session.commit()
            print(f"Code de réinitialisation pour {user.username} : {code}")
            return redirect(url_for('verify_code', username=user.username))
        flash("Compte introuvable.")
    return render_template('forgot_password.html')

@main_bp.route('/verify-code/<username>', methods=['GET', 'POST'])
def verify_code(username):
    if request.method == 'POST':
        user = User.query.filter_by(username=username).first()
        entered_code = request.form.get('code')
        if user.reset_code == entered_code and datetime.utcnow() < user.reset_code_expires:
            return redirect(url_for('reset_password_final', username=username))
        flash("Code invalide ou expiré.")
    return render_template('verify_code.html', username=username)

@main_bp.route('/api/historique-activite')
@login_required
def api_historique():
    activites = HistoriqueActivite.query.filter_by(user_id=current_user.id)\
        .order_by(HistoriqueActivite.date_consultation.desc()).limit(50).all()
    result = []
    for act in activites:
        result.append({'type': act.type, 'url': act.url, 'titre': act.titre,
            'date': act.date_consultation.strftime('%d %b %Y à %H:%M')})
    return jsonify(result)

@main_bp.route('/api/enregistrer-activite', methods=['POST'])
@login_required
def enregistrer_activite():
    data = request.get_json()
    if not data:
        return jsonify({'status': 'error', 'message': 'Données invalides'}), 400
    type_activite = data.get('type')
    url = data.get('url')
    titre = data.get('titre', '')
    if not type_activite or not url:
        return jsonify({'status': 'error', 'message': 'Champs obligatoires manquants'}), 400
    try:
        nouvelle_activite = HistoriqueActivite(user_id=current_user.id, type=type_activite,
            url=url, titre=titre, date_consultation=datetime.utcnow())
        db.session.add(nouvelle_activite); db.session.commit()
        return jsonify({'status': 'success', 'message': 'Activité enregistrée avec succès'}), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({'status': 'error', 'message': str(e)}), 500

@main_bp.route('/verify-otp', methods=['POST'])
def verify_otp():
    try:
        data = request.get_json()
        if not data:
            return jsonify({"status": "error", "message": "Données manquantes"}), 400
        username = data.get('username')
        user_otp = data.get('otp')
        session_otp = session.get('otp_code')
        print(f"[DEBUG] OTP reçu : {user_otp} | Session : {session_otp}")
        if not session_otp:
            return jsonify({"status": "error", "message": "Code expiré ou inexistant."}), 400
        if str(user_otp).strip() == str(session_otp).strip():
            session.pop('otp_code', None)
            return jsonify({"status": "success", "redirect": "/feed"})
        else:
            return jsonify({"status": "error", "message": "Code de vérification incorrect."}), 400
    except Exception as e:
        print(f"[ERREUR SERVEUR] : {str(e)}")
        return jsonify({"status": "error", "message": f"Erreur technique : {str(e)}"}), 500

@main_bp.route('/check-code', methods=['POST'])
def check_code():
    try:
        data = request.get_json()
        if not data:
            return jsonify({"success": False, "message": "Données manquantes"}), 400
        code_saisi = data.get('verification_code')
        code_session = session.get('otp_code')
        if not code_session and _dernier_otp.get("code") and _dernier_otp.get("expire") and datetime.utcnow() < _dernier_otp["expire"]:
            code_session = _dernier_otp["code"]
        print(f"[DEBUG] Code saisi: {code_saisi} | Code en session: {code_session}")
        if not code_session:
            return jsonify({"success": False, "message": "Aucun code en cours."}), 400
        if str(code_saisi).strip() == str(code_session).strip():
            return jsonify({"success": True})
        else:
            return jsonify({"success": False, "message": "Le code saisi est incorrect."})
    except Exception as e:
        print(f"[ERREUR] Échec de la vérification OTP : {str(e)}")
        return jsonify({"success": False, "message": f"Erreur serveur : {str(e)}"}), 500

