@anniv_bp.route('/anniversaires')
@login_required
def liste_anniversaires():
    tous_les_utilisateurs = User.query.filter(User.date_naissance.isnot(None)).all()
    aujourd_hui = datetime.now().date()
    anniversaires_du_jour = []
    anniversaires_du_mois = []
    prochains_anniversaires = []
    for utilisateur in tous_les_utilisateurs:
        date_nais = utilisateur.date_naissance
        if date_nais.month == aujourd_hui.month and date_nais.day == aujourd_hui.day:
            anniversaires_du_jour.append(utilisateur)
        if date_nais.month == aujourd_hui.month:
            anniversaires_du_mois.append(utilisateur)
        if (date_nais.month, date_nais.day) > (aujourd_hui.month, aujourd_hui.day):
            prochains_anniversaires.append(utilisateur)
    return render_template('anniversaires.html',
        anniversaires_du_jour=anniversaires_du_jour,
        anniversaires_du_mois=anniversaires_du_mois,
        prochains_anniversaires=prochains_anniversaires,
        mois_actuel=aujourd_hui.strftime('%B'))

