# ══════════════════════════════════════════════════════════════
#  AJOUT ADDITIF : « Rechercher dans la vidéo » et « Poser une question »
#  (menu affiché quand un reel est en pause). Ces routes répondent TOUJOURS en JSON.
#  L'assistant reste discret : il ne dit jamais quel moteur ou quelle entreprise le
#  fait fonctionner (consigne ci-dessous).
#
#  VITESSE : la vidéo n'est analysée QU'UNE SEULE FOIS (transcription + description
#  chronologique, gardée en mémoire ET sur disque). Ensuite :
#    - la recherche se fait en local, sans appel IA (quasi instantanée) ;
#    - une question n'envoie que du texte court au moteur (environ 1 s).
#  Dès qu'un reel est mis en pause, la page demande à /preparer de lancer cette
#  analyse en arrière-plan : le plus souvent, elle est déjà prête au premier clic.
# ══════════════════════════════════════════════════════════════
MODELE_VIDEO_IA = 'gemini-3.5-flash-lite'
_CACHE_VIDEOS_IA = {}              # pub_id -> {'uri', 'mime', 'ts'} (gros fichier déjà envoyé au moteur)
_TIMELINES_VIDEO_IA = {}           # pub_id -> {'cle', 'segments': [{'t', 'texte', 'norm'}]}
_EN_COURS_VIDEO_IA = {}            # pub_id -> threading.Event (analyse en cours)
_VERROU_VIDEOS_IA = _threading.Lock()
_LIMITE_VIDEO_IA = {}              # clé -> horodatages récents (anti-abus)
_RAPIDE_IA = {'actif': True}       # réglages de vitesse du moteur ; coupés pour de bon dès qu'ils posent problème
_ECHECS_VIDEO_IA = {}              # pub_id -> instant du dernier échec d'analyse (évite de réessayer aussitôt)
_DOSSIER_CACHE_VIDEO_IA = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'cache_ia_videos')
_CONSIGNE_VIDEO_IA = (
    "Tu es l'assistant de FaceNet chargé d'analyser UNE vidéo (image, voix, texte à l'écran, gestes). "
    "Tu réponds dans la langue de l'utilisateur, de façon courte, claire et exacte. "
    "Tu t'appuies uniquement sur ce qui est réellement visible ou audible dans la vidéo ; "
    "si l'information n'y est pas, tu le dis simplement, sans rien inventer. "
    "Tu ne révèles jamais quel modèle, quelle technologie ou quelle entreprise te fait fonctionner : "
    "si on te le demande, tu réponds seulement que tu es l'assistant de la vidéo sur FaceNet. "
    "Tu n'utilises aucun formatage markdown. "
    "Tu es toujours poli et calme, même si on t'insulte, et tu ne ripostes jamais. "
    "Tu comprends les questions mal écrites (fautes, mots confondus, abréviations) et tu devines ce que l'utilisateur veut dire."
)
_MOTS_VIDES_RECHERCHE = {'le', 'la', 'les', 'un', 'une', 'des', 'de', 'du', 'au', 'aux', 'et', 'ou', 'en',
                         'est', 'sur', 'dans', 'qui', 'que', 'quoi', 'ce', 'cet', 'cette', 'ces', 'il', 'elle'}

def _limite_video_ia_atteinte(cle, maxi=12, fenetre=60):
    maintenant = time.time()
    with _VERROU_VIDEOS_IA:
        recents = [t for t in _LIMITE_VIDEO_IA.get(cle, []) if maintenant - t < fenetre]
        if len(recents) >= maxi:
            _LIMITE_VIDEO_IA[cle] = recents
            return True
        recents.append(maintenant)
        _LIMITE_VIDEO_IA[cle] = recents
    return False

def _secondes_depuis_texte(valeur):
    """'1:05' -> 65, '01:02:03' -> 3723, 42 -> 42, '12s' -> 12 ; None si illisible."""
    if valeur is None or isinstance(valeur, bool):
        return None
    if isinstance(valeur, (int, float)):
        return max(0, int(valeur))
    txt = str(valeur).strip().lower().replace(',', '.')
    if not txt or txt in ('null', 'none', 'aucun'):
        return None
    if re.fullmatch(r'\d+(\.\d+)?\s*s?', txt):
        return max(0, int(float(txt.rstrip('s').strip())))
    m = re.fullmatch(r'(?:(\d+):)?(\d{1,2}):(\d{1,2})(?:\.\d+)?', txt)
    if m:
        h, mi, se = int(m.group(1) or 0), int(m.group(2)), int(m.group(3))
        return h * 3600 + mi * 60 + se
    return None

def _json_depuis_reponse_ia(brut):
    brut = (brut or '').strip()
    brut = re.sub(r'^```(?:json)?|```$', '', brut, flags=re.MULTILINE).strip()
    try:
        return json.loads(brut)
    except Exception:
        m = re.search(r'\{.*\}', brut, flags=re.DOTALL)
        if m:
            try:
                return json.loads(m.group(0))
            except Exception:
                return None
    return None

def _normaliser_recherche(texte):
    t = unicodedata.normalize('NFD', str(texte or '').lower())
    t = ''.join(c for c in t if unicodedata.category(c) != 'Mn')
    return re.sub(r'[^a-z0-9]+', ' ', t).strip()

def _chercher_dans_segments(segments, requete, maxi=6):
    """Recherche locale (sans accents, début de mot accepté). Retourne [{'timestamp', 'texte'}]."""
    mots = [m for m in _normaliser_recherche(requete).split() if len(m) >= 2 and m not in _MOTS_VIDES_RECHERCHE]
    if not mots:
        mots = [m for m in _normaliser_recherche(requete).split() if m]
    if not mots:
        return []
    seuil = max(1, (len(mots) + 1) // 2)
    notes = []
    for seg in segments:
        mots_seg = seg['norm'].split()
        trouves = 0
        for m in mots:
            if any(w.startswith(m) or (len(m) >= 4 and m in w) for w in mots_seg):
                trouves += 1
        if trouves >= seuil:
            notes.append((trouves, seg))
    notes.sort(key=lambda x: (-x[0], x[1]['t']))
    retenus = sorted([n[1] for n in notes[:maxi]], key=lambda x: x['t'])
    return [{'timestamp': x['t'], 'texte': x['texte']} for x in retenus]

def _partie_video_ia(chemin_relatif, pub_id):
    """Prépare la vidéo pour le moteur (envoi direct si légère, sinon envoi de fichier)."""
    racine = os.path.realpath(os.path.join(current_app.root_path, 'static', 'uploads'))
    chemin = os.path.realpath(os.path.join(racine, chemin_relatif))
    if not chemin.startswith(racine + os.sep) or not os.path.isfile(chemin):
        raise FileNotFoundError('video introuvable')
    ext = chemin.rsplit('.', 1)[-1].lower()
    mime = {'mp4': 'video/mp4', 'webm': 'video/webm', 'mov': 'video/quicktime'}.get(ext, 'video/mp4')
    if os.path.getsize(chemin) <= 15 * 1024 * 1024:
        with open(chemin, 'rb') as f:
            return types.Part.from_bytes(data=f.read(), mime_type=mime)
    with _VERROU_VIDEOS_IA:
        c = _CACHE_VIDEOS_IA.get(pub_id)
    if c and time.time() - c['ts'] < 3600:
        return types.Part.from_uri(file_uri=c['uri'], mime_type=c['mime'])
    try:
        fichier = client.files.upload(file=chemin)
    except TypeError:
        fichier = client.files.upload(path=chemin)
    debut = time.time()
    while getattr(getattr(fichier, 'state', None), 'name', '') == 'PROCESSING':
        if time.time() - debut > 120:
            raise TimeoutError('traitement de la video trop long')
        time.sleep(1)
        fichier = client.files.get(name=fichier.name)
    if getattr(getattr(fichier, 'state', None), 'name', '') == 'FAILED':
        raise RuntimeError('video refusee')
    mime_final = getattr(fichier, 'mime_type', None) or mime
    with _VERROU_VIDEOS_IA:
        _CACHE_VIDEOS_IA[pub_id] = {'uri': fichier.uri, 'mime': mime_final, 'ts': time.time()}
    return types.Part.from_uri(file_uri=fichier.uri, mime_type=mime_final)

def _journal_ia(message):
    import traceback
    print(f"DEBUG: {message}\n{traceback.format_exc()}")

def _generer_ia_rapide(contents, max_tokens, temperature=0.2, avec_video=False):
    """Appel au moteur. On essaie d'abord avec les réglages de vitesse (réflexion coupée, résolution vidéo basse) ;
    à la moindre erreur, ils sont abandonnés pour de bon et on refait l'appel de base, qui fonctionnait avant."""
    base = dict(system_instruction=_CONSIGNE_VIDEO_IA, temperature=temperature,
                max_output_tokens=max_tokens, response_mime_type='application/json')
    if _RAPIDE_IA['actif']:
        try:
            extra = {'thinking_config': types.ThinkingConfig(thinking_budget=0)}
            if avec_video:
                extra['media_resolution'] = types.MediaResolution.MEDIA_RESOLUTION_LOW
            return client.models.generate_content(model=MODELE_VIDEO_IA, contents=contents,
                                                  config=types.GenerateContentConfig(**base, **extra))
        except Exception:
            _RAPIDE_IA['actif'] = False
            _journal_ia("reglages de vitesse IA abandonnes (appel de base utilise a la place)")
    return client.models.generate_content(model=MODELE_VIDEO_IA, contents=contents,
                                          config=types.GenerateContentConfig(**base))

def _analyser_video_directe(pub, consigne, max_tokens=2048):
    """Méthode éprouvée (la vidéo part avec la demande) : sert de secours si l'analyse préalable échoue."""
    partie = _partie_video_ia(pub.media_url, pub.id)
    legende = (pub.contenu or '').strip()
    texte = (("Légende publiée avec la vidéo : " + legende[:300] + "\n\n") if legende else "") + consigne
    rep = client.models.generate_content(
        model=MODELE_VIDEO_IA,
        contents=[types.Content(role='user', parts=[partie, types.Part(text=texte)])],
        config=types.GenerateContentConfig(system_instruction=_CONSIGNE_VIDEO_IA, temperature=0.2,
                                           max_output_tokens=max_tokens, response_mime_type='application/json'))
    return _json_depuis_reponse_ia(rep.text)

def _lire_resultats_ia(data):
    resultats = []
    if isinstance(data, dict):
        for r in (data.get('resultats') or [])[:6]:
            if isinstance(r, dict):
                sec = _secondes_depuis_texte(r.get('temps', r.get('timestamp')))
                txt = _retirer_markdown(str(r.get('texte') or '')).strip()[:220]
                if sec is not None and txt:
                    resultats.append({'timestamp': sec, 'texte': txt})
    return resultats

def _cle_cache_video(pub_id, chemin_relatif):
    chemin = os.path.join(current_app.root_path, 'static', 'uploads', chemin_relatif)
    st = os.stat(chemin)
    return f"{pub_id}_{st.st_size}_{int(st.st_mtime)}"

def _segments_depuis_donnees(data):
    segments = []
    for r in (data.get('segments') or []):
        if not isinstance(r, dict):
            continue
        sec = _secondes_depuis_texte(r.get('temps', r.get('timestamp')))
        txt = _retirer_markdown(str(r.get('texte') or '')).strip()[:300]
        if sec is not None and txt:
            segments.append({'t': sec, 'texte': txt, 'norm': _normaliser_recherche(txt)})
    segments.sort(key=lambda x: x['t'])
    return segments

def _analyser_video_une_fois(pub_id, chemin_relatif, legende):
    """Transcription + description chronologique de la vidéo, avec cache mémoire puis disque."""
    cle = _cle_cache_video(pub_id, chemin_relatif)
    c = _TIMELINES_VIDEO_IA.get(pub_id)
    if c and c['cle'] == cle:
        return c['segments']
    os.makedirs(_DOSSIER_CACHE_VIDEO_IA, exist_ok=True)
    fichier_cache = os.path.join(_DOSSIER_CACHE_VIDEO_IA, f"reel_{cle}.json")
    if os.path.isfile(fichier_cache):
        try:
            with open(fichier_cache, 'r', encoding='utf-8') as f:
                segments = _segments_depuis_donnees(json.load(f))
            if segments:
                _TIMELINES_VIDEO_IA[pub_id] = {'cle': cle, 'segments': segments}
                return segments
        except Exception:
            pass
    partie = _partie_video_ia(chemin_relatif, pub_id)
    consigne = (
        ("Légende publiée avec la vidéo : " + legende[:300] + "\n\n") if legende else ""
    ) + (
        "Décris cette vidéo de façon chronologique, pour permettre ensuite de la fouiller. Réponds UNIQUEMENT en JSON : "
        '{"segments":[{"temps":"MM:SS","texte":"..."}]}. Un segment toutes les 4 à 6 secondes (plus rapproché si ça change vite). '
        "Dans « texte » : les paroles prononcées (transcription fidèle, dans la langue d'origine) puis, en quelques mots, "
        "ce qui est visible d'important (personnes, objets, gestes, lieu, texte à l'écran). 1 à 2 phrases courtes par segment.")
    rep = _generer_ia_rapide([types.Content(role='user', parts=[partie, types.Part(text=consigne)])],
                             max_tokens=6000, temperature=0.1, avec_video=True)
    data = _json_depuis_reponse_ia(rep.text)
    if not isinstance(data, dict):
        raise ValueError('analyse inexploitable')
    segments = _segments_depuis_donnees(data)
    if not segments:
        raise ValueError('analyse vide')
    try:
        tmp = fichier_cache + '.tmp'
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump({'segments': [{'temps': x['t'], 'texte': x['texte']} for x in segments]}, f, ensure_ascii=False)
        os.replace(tmp, fichier_cache)
    except Exception as e:
        print(f"DEBUG: cache video IA non ecrit : {e}")
    _TIMELINES_VIDEO_IA[pub_id] = {'cle': cle, 'segments': segments}
    return segments

class _AnalyseVideoIndisponible(Exception):
    pass

def _obtenir_segments_video(pub_id, chemin_relatif, legende, attendre=True):
    """Segments prêts (cache) ou analyse unique ; une seule analyse à la fois par vidéo.
    Si l'analyse a échoué récemment ou n'est pas prête, lève _AnalyseVideoIndisponible (l'appelant utilise le secours)."""
    try:
        cle = _cle_cache_video(pub_id, chemin_relatif)
    except OSError:
        raise FileNotFoundError('video introuvable')
    c = _TIMELINES_VIDEO_IA.get(pub_id)
    if c and c['cle'] == cle:
        return c['segments']
    echec = _ECHECS_VIDEO_IA.get(pub_id)
    if echec and time.time() - echec < 600:
        raise _AnalyseVideoIndisponible('analyse recemment en echec')
    with _VERROU_VIDEOS_IA:
        evt = _EN_COURS_VIDEO_IA.get(pub_id)
        proprietaire = evt is None
        if proprietaire:
            evt = _threading.Event()
            _EN_COURS_VIDEO_IA[pub_id] = evt
    if not proprietaire:
        if not attendre:
            return None
        evt.wait(timeout=25)
        c = _TIMELINES_VIDEO_IA.get(pub_id)
        if c and c['cle'] == cle:
            return c['segments']
        raise _AnalyseVideoIndisponible('analyse pas encore prete')
    try:
        return _analyser_video_une_fois(pub_id, chemin_relatif, legende)
    except Exception:
        _ECHECS_VIDEO_IA[pub_id] = time.time()
        _journal_ia("analyse video IA en echec")
        raise
    finally:
        with _VERROU_VIDEOS_IA:
            _EN_COURS_VIDEO_IA.pop(pub_id, None)
        evt.set()

def _reel_video_accessible(pub_id):
    """Retourne (pub, None) ou (None, (json, code))."""
    pub = db.session.get(Publication, pub_id)
    if pub is None or not pub.media_url:
        return None, (jsonify(success=False, error="Vidéo introuvable."), 404)
    if not str(pub.media_url).lower().endswith(('.mp4', '.webm', '.mov')):
        return None, (jsonify(success=False, error="Cette publication n'est pas une vidéo."), 400)
    if not _peut_voir_publication(pub, current_user.id):
        return None, (jsonify(success=False, error="Cette vidéo n'est pas accessible."), 403)
    return pub, None

@main_bp.route('/api/reel/<int:pub_id>/preparer', methods=['POST'])
@login_required
def api_reel_preparer(pub_id):
    """Lance l'analyse de la vidéo en arrière-plan (sans attendre) pour que recherche et questions soient instantanées."""
    try:
        pub, erreur = _reel_video_accessible(pub_id)
        if erreur:
            return erreur
        c = _TIMELINES_VIDEO_IA.get(pub_id)
        try:
            if c and c['cle'] == _cle_cache_video(pub_id, pub.media_url):
                return jsonify(success=True, pret=True)
        except OSError:
            return jsonify(success=False, error="Vidéo introuvable."), 404
        if _limite_video_ia_atteinte(('preparer', current_user.id), maxi=30):
            return jsonify(success=True, pret=False)
        with _VERROU_VIDEOS_IA:
            deja = pub_id in _EN_COURS_VIDEO_IA
        if not deja:
            app = current_app._get_current_object()
            media, legende = pub.media_url, (pub.contenu or '')
            def _travail():
                try:
                    with app.app_context():
                        _obtenir_segments_video(pub_id, media, legende, attendre=False)
                except Exception as e:
                    print(f"DEBUG: preparation video IA : {e}")
            _threading.Thread(target=_travail, daemon=True).start()
        return jsonify(success=True, pret=False)
    except Exception as e:
        print(f"DEBUG: preparer video IA : {e}")
        return jsonify(success=False, error="Préparation indisponible."), 503

@main_bp.route('/api/reel/<int:pub_id>/rechercher', methods=['GET'])
@login_required
def api_reel_rechercher(pub_id):
    try:
        pub, erreur = _reel_video_accessible(pub_id)
        if erreur:
            return erreur
        q = (request.args.get('q') or '').strip()[:120]
        if not q:
            return jsonify(success=False, error="Tapez un mot-clé pour lancer la recherche."), 400
        if _limite_video_ia_atteinte(current_user.id, maxi=30):
            return jsonify(success=False, error="Trop de recherches d'affilée. Patientez une minute."), 429
        resultats = None
        try:
            segments = _obtenir_segments_video(pub_id, pub.media_url, pub.contenu or '')
            resultats = _chercher_dans_segments(segments, q)
            if not resultats and segments:
                # Aucune correspondance de mots : recherche par le sens, sur le texte seulement (rapide)
                texte_video = "\n".join(f"{x['t']}s | {x['texte']}" for x in segments)[:30000]
                consigne = (
                    "Voici la description chronologique d'une vidéo (secondes | contenu) :\n" + texte_video +
                    "\n\nRetrouve les passages liés à : « " + q + " ». Réponds UNIQUEMENT en JSON "
                    '{"resultats":[{"temps":"MM:SS","texte":"extrait très court"}]}, au maximum 6, '
                    'ou {"resultats":[]} s\'il n\'y en a aucun. N\'invente rien.')
                try:
                    rep = _generer_ia_rapide([types.Content(role='user', parts=[types.Part(text=consigne)])], max_tokens=600)
                    resultats = _lire_resultats_ia(_json_depuis_reponse_ia(rep.text))
                except Exception:
                    _journal_ia("recherche semantique video IA")
        except Exception:
            resultats = None
        if resultats is None:
            # Secours : méthode d'origine (la vidéo est envoyée avec la recherche)
            consigne = (
                "Retrouve dans la vidéo les passages liés à : « " + q + " » (mot dit à voix haute, texte à l'écran, "
                "objet, personne ou action visible). Réponds UNIQUEMENT en JSON de la forme "
                '{"resultats":[{"temps":"MM:SS","texte":"extrait ou description très courte du passage"}]} '
                "avec au maximum 6 passages, dans l'ordre chronologique. N'inclus que des passages réellement "
                "présents ; s'il n'y en a aucun, renvoie {\"resultats\":[]}.")
            data = _analyser_video_directe(pub, consigne)
            if not isinstance(data, dict):
                raise ValueError('reponse inexploitable')
            resultats = _lire_resultats_ia(data)
        return jsonify(success=True, resultats=resultats)
    except Exception as e:
        _journal_ia(f"recherche video IA : {e!r}")
        try: db.session.rollback()
        except Exception: pass
        return jsonify(success=False, error="La recherche n'est pas disponible pour le moment. Réessayez dans un instant."), 503

@main_bp.route('/api/reel/<int:pub_id>/question', methods=['POST'])
@login_required
def api_reel_question(pub_id):
    try:
        pub, erreur = _reel_video_accessible(pub_id)
        if erreur:
            return erreur
        donnees = request.get_json(silent=True) or {}
        question = str(donnees.get('question') or '').strip()[:500]
        if not question:
            return jsonify(success=False, error="Posez votre question sur la vidéo."), 400
        if _limite_video_ia_atteinte(current_user.id):
            return jsonify(success=False, error="Trop de questions d'affilée. Patientez une minute."), 429
        fin_json = (
            "Réponds UNIQUEMENT en JSON de la forme "
            '{"reponse":"réponse courte et précise","temps":"MM:SS ou null"} ; '
            "« temps » est l'instant de la vidéo qui illustre le mieux la réponse, ou null s'il n'y en a pas.")
        data = None
        try:
            segments = _obtenir_segments_video(pub_id, pub.media_url, pub.contenu or '')
            texte_video = "\n".join(f"{x['t']}s | {x['texte']}" for x in segments)[:30000]
            legende = (pub.contenu or '').strip()
            consigne = (
                (("Légende publiée avec la vidéo : " + legende[:300] + "\n") if legende else "") +
                "Description chronologique de la vidéo (secondes | paroles et images) :\n" + texte_video +
                "\n\nQuestion de l'utilisateur : « " + question + " ». " + fin_json)
            rep = _generer_ia_rapide([types.Content(role='user', parts=[types.Part(text=consigne)])], max_tokens=700)
            data = _json_depuis_reponse_ia(rep.text)
        except Exception:
            data = None
        if not isinstance(data, dict) or not str(data.get('reponse') or '').strip():
            # Secours : méthode d'origine (la vidéo est envoyée avec la question)
            data = _analyser_video_directe(pub, "Question de l'utilisateur sur la vidéo : « " + question + " ». " + fin_json)
        if not isinstance(data, dict) or not str(data.get('reponse') or '').strip():
            raise ValueError('reponse inexploitable')
        reponse = _retirer_markdown(str(data['reponse'])).strip()[:1500]
        return jsonify(success=True, reponse=reponse,
                       timestamp=_secondes_depuis_texte(data.get('temps', data.get('timestamp'))))
    except Exception as e:
        _journal_ia(f"question video IA : {e!r}")
        try: db.session.rollback()
        except Exception: pass
        return jsonify(success=False, error="L'assistant n'est pas disponible pour le moment. Réessayez dans un instant."), 503

from models import SignalementVideo, EnregistrementReel

@main_bp.route('/api/reel/<int:pub_id>/signaler', methods=['POST'])
@login_required
def api_reel_signaler(pub_id):
    pub = Publication.query.get_or_404(pub_id)
