@main_bp.route('/api/musique/recherche')
def music_search():
    """Recherche de musiques : Deezer (hits actuels, tous genres) + iTunes (récents d'abord).
    Sans texte tapé : les titres du moment. Même format de réponse qu'avant."""
    query = (request.args.get('q') or '').strip()
    deezer, itunes = [], []
    erreurs = 0
    try:
        if query:
            rd = requests.get("https://api.deezer.com/search", params={"q": query, "limit": 30}, timeout=8)
        else:
            rd = requests.get("https://api.deezer.com/chart/0/tracks", params={"limit": 40}, timeout=8)
        rd.raise_for_status()
        for t in (rd.json().get('data') or []):
            # Le titre reste sélectionnable même si le fournisseur ne propose pas d'extrait.
            alb = t.get('album') or {}
            deezer.append({'title': t.get('title'), 'artist': (t.get('artist') or {}).get('name'),
                           'cover': alb.get('cover_medium') or alb.get('cover'), 'preview_url': t.get('preview') or ''})
    except (requests.RequestException, ValueError):
        erreurs += 1
    try:
        terme = query or "top hits"
        ri = requests.get("https://itunes.apple.com/search",
            params={"term": terme, "media": "music", "entity": "song", "limit": 40}, timeout=8)
        ri.raise_for_status()
        brut = list(ri.json().get('results', []))
        brut.sort(key=lambda t: t.get('releaseDate') or '', reverse=True)   # nouveautés d'abord
        for t in brut:
            itunes.append({'title': t.get('trackName'), 'artist': t.get('artistName'),
                           'cover': (t.get('artworkUrl100') or '').replace('100x100', '300x300'),
                           'preview_url': t.get('previewUrl')})
    except (requests.RequestException, ValueError):
        erreurs += 1
    if erreurs == 2:
        return jsonify({"error": "Service musical indisponible, réessayez."}), 502
    resultats, vus = [], set()
    for i in range(max(len(deezer), len(itunes))):
        for source in (deezer, itunes):
            if i < len(source):
                m = source[i]
                cle = ((m['title'] or '').lower().strip(), (m['artist'] or '').lower().strip())
                if cle not in vus:
                    vus.add(cle)
                    resultats.append(m)
    return jsonify({"results": resultats[:60]})

@main_bp.route('/create-item', methods=['GET', 'POST'])
@login_required
def create_item():
    if request.method == 'POST':
        titre = request.form.get('title', '').strip()
        description = request.form.get('description', '').strip()
        prix = request.form.get('price', type=int)
        localisation = request.form.get('city', '').strip()
        categorie = request.form.get('category', '').strip()
        condition = request.form.get('condition', 'Bon etat')
        quantite = request.form.get('quantity', type=int) or 1
        negociable = request.form.get('negociable') == 'oui'
        contact_telephone = request.form.get('contact_phone', '').strip() or None
        livraison = request.form.get('delivery') == 'oui'
        fait_main = request.form.get('handmade') == 'oui'
        if not titre or not description or prix is None or not localisation or not categorie:
            flash("Merci de remplir tous les champs obligatoires.", "error")
            return render_template('create_item.html')
        fichiers = [f for f in request.files.getlist('images') if f and f.filename]
        if not fichiers:
            flash("Ajoutez au moins une photo.", "error")
            return render_template('create_item.html')
        annonce = Annonce(titre=titre, description=description, prix=prix,
            localisation=localisation, categorie=categorie, condition=condition,
            quantite=quantite, negociable=negociable, contact_telephone=contact_telephone,
            livraison=livraison, fait_main=fait_main, user_id=current_user.id)
        db.session.add(annonce)
        db.session.flush()
        upload_dir = os.path.join(current_app.root_path, 'static', 'uploads')
        os.makedirs(upload_dir, exist_ok=True)
        for fichier in fichiers[:6]:
            nom_fichier = secure_filename(f"annonce_{annonce.id}_{uuid.uuid4().hex}_{fichier.filename}")
            fichier.save(os.path.join(upload_dir, nom_fichier))
            db.session.add(AnnonceImage(filename=nom_fichier, annonce_id=annonce.id))
        db.session.commit()
        flash("Votre annonce a été publiée avec succès !", "success")
        return redirect(url_for('main.marketplace'))
    return render_template('create_item.html')

