# ══════════════════════════════════════════════════════════════════════
# AJOUT ADDITIF : DIFFUSION DES BOOSTS DANS LE FIL DE TOUS LES UTILISATEURS
# ──────────────────────────────────────────────────────────────────────
# • À la création d'un boost (/api/boost/creer) on enregistre une « campagne »
#   (budget, dates, audience, objectif, contact) dans la table boost_campagne.
# • Le fil (/feed et /api/feed/page) y insère les publications sponsorisées :
#   au plus BOOST_MAX_PAR_PAGE par page, jamais à l'auteur lui-même, seulement
#   pendant les dates choisies, selon l'audience (âge, genre, lieu) et jusqu'à
#   ce que le nombre de comptes à toucher (calculé d'après le budget) soit atteint.
# • Les tables sont créées automatiquement au premier usage ; toute erreur laisse
#   le fil normal intact.
# RÉGLAGES :
BOOST_ACTIVATION_AUTO = True        # True = diffusion dès la création (comportement actuel de l'écran
                                    # « Boost lancé »). Passez à False quand un vrai paiement est branché :
                                    # appelez alors boost_activer_campagne(boost_id) quand il est confirmé.
BOOST_IMPRESSIONS_PAR_USD = 1000    # comptes touchés par dollar payé (l'écran annonce 800 à 1 800)
BOOST_MAX_PAR_PAGE = 2              # publications sponsorisées max. par page du fil
BOOST_FREQ_MAX_PAR_JOUR = 3         # affichages max. de la même pub au même utilisateur par jour
BOOST_POSITIONS = (2, 8)            # rangs d'insertion dans une page (après le 2e, puis le 8e post)
# ══════════════════════════════════════════════════════════════════════

class BoostCampagne(db.Model):
    __tablename__ = 'boost_campagne'
    id = db.Column(db.Integer, primary_key=True)
    boost_id = db.Column(db.Integer, index=True)
    publication_id = db.Column(db.Integer, index=True)
    user_id = db.Column(db.Integer, index=True)
    objectif = db.Column(db.String(30))
    devise = db.Column(db.String(8))
    budget_local = db.Column(db.Float)
    budget_usd = db.Column(db.Float)
    jours = db.Column(db.Integer, default=1)
    date_debut = db.Column(db.DateTime, index=True)
    date_fin = db.Column(db.DateTime, index=True)
    audience_mode = db.Column(db.String(10), default='auto')
    age_min = db.Column(db.Integer)
    age_max = db.Column(db.Integer)
    genre = db.Column(db.String(10))
    lieu = db.Column(db.String(120))
    interets = db.Column(db.Text)
    contact_mode = db.Column(db.String(12))
    contact_tel = db.Column(db.String(24))
    advantage_plus = db.Column(db.Boolean, default=True)
    reach_cible = db.Column(db.Integer, default=0)
    statut = db.Column(db.String(12), default='pending', index=True)
    date_creation = db.Column(db.DateTime, default=datetime.utcnow)


class BoostImpression(db.Model):
    __tablename__ = 'boost_impression'
    id = db.Column(db.Integer, primary_key=True)
    campagne_id = db.Column(db.Integer, index=True)
    user_id = db.Column(db.Integer, index=True)
    date = db.Column(db.DateTime, default=datetime.utcnow, index=True)


_boost_tables_ok = False


def _boost_assurer_tables():
    global _boost_tables_ok
    if _boost_tables_ok:
        return True
    try:
        BoostCampagne.__table__.create(bind=db.engine, checkfirst=True)
        BoostImpression.__table__.create(bind=db.engine, checkfirst=True)
        _boost_tables_ok = True
    except Exception as e:
        print(f"DEBUG: tables boost indisponibles : {e}")
    return _boost_tables_ok


def _boost_date_utc(valeur, decalage_min=0):
    """'2026-10-25T14:30' (heure locale de l'annonceur) -> datetime naïf en UTC.
    decalage_min = new Date().getTimezoneOffset() envoyé par le navigateur."""
    if not valeur:
        return None
    try:
        d = datetime.fromisoformat(str(valeur).replace('Z', '+00:00'))
    except ValueError:
        return None
    if d.tzinfo is not None:
        return d.astimezone(__import__('datetime').timezone.utc).replace(tzinfo=None)
    return d + timedelta(minutes=int(decalage_min or 0))


def _boost_creer_campagne(boost_row, pub, data):
    """Enregistre la campagne liée à un boost. Retourne un petit dict de résumé."""
    if not _boost_assurer_tables():
        return None
    try:
        decalage = int(data.get('tz_offset_min') or 0)
    except (TypeError, ValueError):
        decalage = 0
    debut = _boost_date_utc(data.get('start_datetime'), decalage) or datetime.utcnow()
    fin = _boost_date_utc(data.get('end_datetime'), decalage)
    try:
        jours = max(1, int(data.get('duration_days') or 1))
    except (TypeError, ValueError):
        jours = 1
    if not fin or fin <= debut:
        fin = debut + timedelta(days=jours)
    try:
        budget_usd = float(data.get('budget_usd') or 0)
    except (TypeError, ValueError):
        budget_usd = 0.0
    budget_usd = max(0.0, min(budget_usd, 100000.0))
    try:
        budget_local = float(data.get('budget_total') or 0)
    except (TypeError, ValueError):
        budget_local = 0.0
    aud = data.get('audience') or {}
    custom = (aud.get('mode') == 'custom')

    def _entier(v):
        try:
            return int(v)
        except (TypeError, ValueError):
            return None
    genre = (aud.get('gender') or 'all') if custom else 'all'
    cible = int(budget_usd * BOOST_IMPRESSIONS_PAR_USD)
    tel = ''.join(ch for ch in str(data.get('contact_phone') or '') if ch.isdigit())[:20]
    mode_contact = data.get('contact_method') if data.get('contact_method') in ('phone', 'whatsapp') and tel else 'none'
    c = BoostCampagne(
        boost_id=boost_row.id, publication_id=pub.id, user_id=pub.user_id,
        objectif=str(data.get('objective') or 'reach')[:30], devise=str(data.get('currency') or '')[:8],
        budget_local=budget_local, budget_usd=budget_usd, jours=jours, date_debut=debut, date_fin=fin,
        audience_mode='custom' if custom else 'auto',
        age_min=_entier(aud.get('age_min')) if custom else None,
        age_max=_entier(aud.get('age_max')) if custom else None,
        genre=genre if genre in ('all', 'men', 'women') else 'all',
        lieu=(str(aud.get('location') or '').strip()[:120] if custom else ''),
        interets=json.dumps(aud.get('interests') or [], ensure_ascii=False) if custom else '[]',
        contact_mode=mode_contact, contact_tel=tel if mode_contact != 'none' else '',
        advantage_plus=bool(data.get('advantage_plus', True)),
        reach_cible=cible, statut='active' if (BOOST_ACTIVATION_AUTO and cible > 0) else 'pending')
    db.session.add(c)
    db.session.commit()
    return {'id': c.id, 'statut': c.statut, 'reach_cible': c.reach_cible,
            'debut': c.date_debut.isoformat(), 'fin': c.date_fin.isoformat()}


def boost_activer_campagne(boost_id):
    """À appeler quand le paiement réel est confirmé (webhook) si BOOST_ACTIVATION_AUTO = False."""
    _boost_assurer_tables()
    c = BoostCampagne.query.filter_by(boost_id=boost_id).first()
    if c and c.statut == 'pending':
        c.statut = 'active'
        db.session.commit()
        return True
    return False


def _boost_age(user):
    d = getattr(user, 'date_naissance', None) or getattr(user, 'birth_date', None)
    if not d:
        return None
    try:
        today = date.today()
        return today.year - d.year - ((today.month, today.day) < (d.month, d.day))
    except Exception:
        return None


def _boost_cible_ok(c, user):
    """L'utilisateur correspond-il à l'audience choisie par l'annonceur ?"""
    if c.audience_mode != 'custom':
        return True
    if c.age_min or c.age_max:
        age = _boost_age(user)
        if age is None or (c.age_min and age < c.age_min) or (c.age_max and age > c.age_max and c.age_max < 65):
            return False
    if c.genre in ('men', 'women'):
        sexe = (getattr(user, 'sexe', '') or '').strip().lower()
        if c.genre == 'men' and not sexe.startswith(('h', 'm')):
            return False
        if c.genre == 'women' and not sexe.startswith('f'):
            return False
    if c.lieu:
        champs = ' '.join(str(getattr(user, k, '') or '') for k in ('ville', 'localisation', 'pays', 'country')).lower()
        jetons = [t.strip().lower() for t in c.lieu.replace(';', ',').split(',') if t.strip()]
        if not champs.strip() or not any(t in champs for t in jetons):
            return False
    return True


def _boost_boutons(c, pub):
    """Boutons d'action sous la publication sponsorisée (objectif + moyen de contact)."""
    boutons = []
    try:
        if c.contact_mode == 'phone' and c.contact_tel:
            boutons.append({'label': 'Appeler', 'url': 'tel:+' + c.contact_tel, 'icone': 'fa-phone'})
        elif c.contact_mode == 'whatsapp' and c.contact_tel:
            boutons.append({'label': 'WhatsApp', 'url': 'https://wa.me/' + c.contact_tel, 'icone': 'fa-whatsapp'})
        if c.objectif in ('profile_visits', 'new_followers') and getattr(pub.author, 'username', None):
            boutons.append({'label': 'Voir le profil' if c.objectif == 'profile_visits' else "S'abonner",
                            'url': url_for('main.profile', username=pub.author.username), 'icone': 'fa-user'})
    except Exception:
        pass
    return boutons


def _boost_selectionner(user, deja_ids, limite):
    """Choisit jusqu'à `limite` campagnes à montrer à cet utilisateur et enregistre l'affichage."""
    if limite <= 0 or not _boost_assurer_tables():
        return []
    from sqlalchemy import func as _bf
    maintenant = datetime.utcnow()
    debut_jour = maintenant.replace(hour=0, minute=0, second=0, microsecond=0)
    campagnes = (BoostCampagne.query.filter(BoostCampagne.statut == 'active',
                                            BoostCampagne.date_debut <= maintenant,
                                            BoostCampagne.date_fin > maintenant,
                                            BoostCampagne.user_id != user.id)
                 .order_by(BoostCampagne.id.desc()).limit(60).all())
    candidats = []
    for c in campagnes:
        if c.publication_id in deja_ids:
            continue
        atteints = db.session.query(_bf.count(_bf.distinct(BoostImpression.user_id))).filter(
            BoostImpression.campagne_id == c.id).scalar() or 0
        if atteints >= (c.reach_cible or 0):
            c.statut = 'ended'
            continue
        fois_user = BoostImpression.query.filter(BoostImpression.campagne_id == c.id,
                                                 BoostImpression.user_id == user.id,
                                                 BoostImpression.date >= debut_jour).count()
        if fois_user >= BOOST_FREQ_MAX_PAR_JOUR:
            continue
        deja_touche = BoostImpression.query.filter_by(campagne_id=c.id, user_id=user.id).first() is not None
        if not deja_touche:
            # rythme : on étale le budget sur les jours choisis (marge de 50 %)
            aujourdhui = db.session.query(_bf.count(_bf.distinct(BoostImpression.user_id))).filter(
                BoostImpression.campagne_id == c.id, BoostImpression.date >= debut_jour).scalar() or 0
            plafond = int((c.reach_cible or 0) / max(1, c.jours) * 1.5) + 1
            if aujourdhui >= plafond:
                continue
        if not _boost_cible_ok(c, user):
            continue
        pub = db.session.get(Publication, c.publication_id)
        if pub is None or (pub.confidentialite or 'public') != 'public':
            continue
        try:
            if not _peut_voir_publication(pub, user.id):
                continue
        except Exception:
            continue
        reste_h = max(0.5, (c.date_fin - maintenant).total_seconds() / 3600.0)
        urgence = ((c.reach_cible or 0) - atteints) / reste_h
        candidats.append((urgence * (0.7 + 0.6 * random.random()), c, pub))
    candidats.sort(key=lambda t: t[0], reverse=True)
    choisis = []
    for _, c, pub in candidats[:limite]:
        db.session.add(BoostImpression(campagne_id=c.id, user_id=user.id))
        choisis.append((c, pub))
    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
        return []
    return choisis


def _boost_fusionner_dans_fil(publications, user, deja_servis=None):
    """Insère les publications sponsorisées dans une page du fil. Ne lève jamais d'exception."""
    try:
        liste = list(publications)
        deja = {p.id for p in liste} | set(deja_servis or [])
        choix = _boost_selectionner(user, deja, BOOST_MAX_PAR_PAGE)
        servis = []
        for i, (c, pub) in enumerate(choix):
            pub.fn_sponsorise = True
            pub.fn_sponso_cta = _boost_boutons(c, pub)
            rang = BOOST_POSITIONS[min(i, len(BOOST_POSITIONS) - 1)]
            liste.insert(min(rang + i, len(liste)), pub)
            servis.append(pub.id)
        if servis:
            try:
                vus = list(session.get('fn_sponso_servis', []))[-80:] + servis
                session['fn_sponso_servis'] = vus
            except Exception:
                pass
        return liste
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: boosts du fil ignorés : {e}")
        return list(publications)


def _boost_collecter_stats(pub):
    """Statistiques réelles de la publication pour l'écran de boost (jamais d'exception)."""
    def _n(fn):
        try:
            return int(fn() or 0)
        except Exception:
            return 0
    likes = _n(lambda: len(pub.likes))
    commentaires = _n(lambda: len(pub.commentaires))
    partages = _n(lambda: getattr(pub, 'share_count', 0))
    vues = 0
    try:
        from models import PublicationVideoView
        _assurer_table_vues()
        vues = PublicationVideoView.query.filter_by(publication_id=pub.id).count()
    except Exception:
        db.session.rollback()
        vues = 0
    return {'viewers': vues, 'interactions': likes + commentaires + partages,
            'likes': likes, 'comments': commentaires, 'shares': partages, 'link_clicks': 0}


@main_bp.route('/boost', methods=['GET', 'POST'])
@main_bp.route('/boost/<int:post_id>', methods=['GET'])
@main_bp.route('/boost/reel/<int:post_id>', methods=['GET'])
@login_required
def boost(post_id=None):
    """Écran « Booster la publication » (publication ou Reel).
    ID accepté : /boost?post_id=12, /boost?reel_id=12, /boost/12 ou /boost/reel/12."""
    raw = post_id or request.args.get('post_id') or request.args.get('reel_id') or request.args.get('id')
    try:
        raw = int(raw)
    except (TypeError, ValueError):
        raw = None
    publication = db.session.get(Publication, raw) if raw else None
    if not publication:
        flash("Publication introuvable.", "danger")
        return redirect(url_for('main.index'))
    if publication.user_id != current_user.id:
        flash("Vous ne pouvez booster que vos propres publications.", "danger")
        return redirect(url_for('main.index'))
    media = publication.media_url or ''
    est_reel = media.lower().endswith(('.mp4', '.webm', '.mov')) or bool(request.args.get('reel_id')) or '/boost/reel/' in request.path
    auteur = publication.author
    boost_ctx = {
        'id': publication.id,
        'est_reel': est_reel,
        'media_url': url_for('static', filename='uploads/' + media) if media else '',
        'media_type': ('video' if media.lower().endswith(('.mp4', '.webm', '.mov')) else 'image') if media else '',
        'auteur_nom': getattr(auteur, 'nom_complet', None) or getattr(auteur, 'username', '') or '',
        'auteur_avatar': url_for('static', filename='uploads/' + ((getattr(auteur, 'avatar', None)) or 'default_avatar.png')),
        'texte': publication.contenu or '',
        'date': publication.date_creation.strftime('%d/%m/%Y %H:%M') if publication.date_creation else '',
        'stats': _boost_collecter_stats(publication),
        'telephone': (getattr(current_user, 'telephone', None) or getattr(current_user, 'phone', None) or ''),
    }
    # `post` / `publication` conservés pour compatibilité avec l'ancien gabarit
    return render_template('boost.html', post=publication, publication=publication, boost=boost_ctx)

@main_bp.route('/find_account', methods=['GET', 'POST'])
def render_find_account():
    if request.method == 'POST':
        action_step = request.form.get('action_step')
        selected_user_id = request.form.get('selected_user_id')
        recovery_method = request.form.get('recovery_method')
        if action_step == 'choose_method' or recovery_method:
            user_id = session.get('reset_user_id') or selected_user_id
            user = User.query.get(user_id) if user_id else None
            verification_code = str(random.randint(100000, 999999))
            session['reset_code'] = verification_code
            session['reset_method'] = recovery_method or 'email'
            print(f"\n🔑 CODE DE VÉRIFICATION POUR @{user.username if user else 'Utilisateur'} : {verification_code}\n")
            return render_template('find_account.html', step='verify_code',
                method=session.get('reset_method'),
                username=getattr(user, 'nom_complet', None) or getattr(user, 'username', 'votre compte') if user else '')
        if selected_user_id or action_step == 'select_profile':
            user = User.query.get(selected_user_id)
            if user:
                session['reset_user_id'] = user.id
                return render_template('find_account.html', step='choose_method',
                    username=getattr(user, 'nom_complet', None) or user.username,
                    email=getattr(user, 'email', None), phone=getattr(user, 'phone', None),
                    selected_user_id=user.id)
        if action_step == 'verify_code':
            user_code = request.form.get('verification_code', '').strip()
            saved_code = session.get('reset_code')
            user_id = session.get('reset_user_id')
            user = User.query.get(user_id) if user_id else None
            if saved_code and user_code == saved_code and user:
                flash('Code validé avec succès !', 'success')
                return redirect(url_for('main.reset_password_final', username=user.username))
            else:
                flash('Code de vérification incorrect.', 'error')
                return render_template('find_account.html', step='verify_code',
                    method=session.get('reset_method', 'email'),
                    username=getattr(user, 'nom_complet', None) or getattr(user, 'username', 'votre compte') if user else '')
        identifier = request.form.get('recovery_search')
        if not identifier or not identifier.strip():
            flash('Veuillez entrer un nom, un email ou un téléphone.', 'error')
            return render_template('find_account.html', step='search')
        identifier = identifier.strip()
        search_pattern = f"%{identifier}%"
        users_found = User.query.filter(
            (User.email.ilike(search_pattern)) | (User.phone.ilike(search_pattern)) |
            (User.username.ilike(search_pattern)) | (User.nom_complet.ilike(search_pattern))).all()
        if not users_found:
            flash('Aucun compte trouvé avec ces informations.', 'error')
            return render_template('find_account.html', step='search')
        return render_template('find_account.html', step='select_profile', profiles=users_found)
    return render_template('find_account.html', step='search')

