@main_bp.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        identity_raw = (request.form.get('identity') or '').strip()
        password = request.form.get('password')
        identity_clean = re.sub(r'\s+', ' ', identity_raw)
        phone_digits = re.sub(r'\D', '', identity_raw)
        print("--- TENTATIVE DE CONNEXION FACENET ---")
        print(f"Identifiant brut  : '{identity_raw}'")
        print(f"Chiffres téléphone: '{phone_digits}'")
        user = None
        user = User.query.filter(
            (User.email.ilike(identity_clean)) | (User.username.ilike(identity_clean))).first()
        if not user and hasattr(User, 'nom_complet'):
            user = User.query.filter(User.nom_complet.ilike(identity_clean)).first()
        if not user and phone_digits:
            all_users = User.query.filter(User.phone.isnot(None)).all()
            for candidate in all_users:
                candidate_digits = re.sub(r'\D', '', candidate.phone or '')
                if candidate_digits and (phone_digits in candidate_digits or candidate_digits in phone_digits):
                    # AJOUT : plusieurs comptes peuvent partager un numéro -> on retient celui dont le mot de passe correspond
                    if user is None:
                        user = candidate
                    if password and candidate.password and check_password_hash(candidate.password, password):
                        user = candidate
                        break
        if user and user.password and password and check_password_hash(user.password, password):
            if _pl_bloque_connexion(user):   # AJOUT : contrôle parental — profil verrouillé par le tuteur
                return redirect(url_for('main.profil_verrouille'))
            _v_cc = _compte_verdict_connexion(user)   # AJOUT : compte désactivé / en suppression / commémoratif
            if _v_cc is not None:
                if _v_cc[0] == 'gate':
                    return redirect(url_for('main.compte_gate'))
                return render_template('login.html', login_error=_v_cc[1], login_error_kind='identity',
                                       identity_value=identity_raw)
            session['user_id'] = user.id
            login_user(user)
            user.is_online = True
            user.last_seen = datetime.utcnow()
            db.session.commit()
            print(f"Connexion réussie pour @{user.username} !")
            flash("Connexion réussie !", "success")
            # AJOUT : langue choisie sur la page de connexion, sinon langue déjà enregistrée du compte
            _langue_login = (request.form.get('langue') or '').strip()
            if _langue_valide(_langue_login):
                _enregistrer_langue(user.id, _langue_login)
            else:
                _langue_login = _langue_enregistree(user.id) or ''
            if _langue_login:
                session['language'] = _langue_login
            _resp_login = redirect(url_for('main.bon_retour' if _premiere_connexion(user.id) else 'main.feed'))  # AJOUT : bon retour uniquement à la 1re connexion ; page « Heureux de vous revoir » puis fil automatique
            if _langue_login:
                _poser_cookie_langue(_resp_login, _langue_login)
            return _resp_login
        else:
            print(f"ÉCHEC : Utilisateur trouvé ? {user is not None}.")
            if user is None:
                login_error = "Aucun compte ne correspond à cet identifiant. Vérifiez votre e-mail, votre numéro de téléphone ou votre nom d'utilisateur."
                login_error_kind = 'identity'
            else:
                login_error = "Mot de passe incorrect. Vérifiez votre saisie ou utilisez « Mot de passe oublié ? »."
                login_error_kind = 'password'
            return render_template('login.html', login_error=login_error,
                                   login_error_kind=login_error_kind, identity_value=identity_raw)
    deconnecte_id = session.get('user_id')
    if deconnecte_id:
        user_qui_part = db.session.get(User, deconnecte_id)
        if user_qui_part:
            user_qui_part.is_online = False
            db.session.commit()
    logout_user()
    session.clear()
    return render_template('login.html')

# AJOUT : mémorise (table bienvenue_vue, créée automatiquement) qu'un compte a déjà vu la page

# « Heureux de vous revoir ». Retourne True uniquement la toute première fois, False ensuite

# (et False en cas d'erreur : on va alors simplement au fil, sans rien casser).

_bienvenue_table_ok = False



def _premiere_connexion(user_id):

    global _bienvenue_table_ok

    try:

        from sqlalchemy import text as _bv_text

        if not _bienvenue_table_ok:

            db.session.execute(_bv_text("CREATE TABLE IF NOT EXISTS bienvenue_vue (user_id INTEGER PRIMARY KEY)"))

            db.session.commit()

            _bienvenue_table_ok = True

        if db.session.execute(_bv_text("SELECT 1 FROM bienvenue_vue WHERE user_id = :u"), {'u': user_id}).first():

            return False

        db.session.execute(_bv_text("INSERT INTO bienvenue_vue (user_id) VALUES (:u)"), {'u': user_id})

        db.session.commit()

        return True

    except Exception as e:

        try: db.session.rollback()

        except Exception: pass

        print(f"[bienvenue] vérification impossible : {e}")

        return False



# AJOUT : page « Heureux de vous revoir » affichée après une connexion réussie.

