@main_bp.route('/sw.js')
def service_worker_hors_ligne():
    """Service worker : permet d'ouvrir login/feed déjà visités sans connexion Internet."""
    from flask import make_response as _sw_make_response
    js = """const C='facenet-offline-v1';
self.addEventListener('install',e=>{self.skipWaiting();});
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
self.addEventListener('fetch',e=>{
  const r=e.request; if(r.method!=='GET')return;
  if(r.headers.get('X-Rx-Reel-Cache'))return;
  const u=new URL(r.url); if(u.origin!==location.origin)return;
  if(r.mode==='navigate'){
    e.respondWith(fetch(r).then(res=>{ if(res.ok&&!res.redirected){const c=res.clone();caches.open(C).then(x=>x.put(r,c));} return res; })
      .catch(()=>caches.match(r).then(m=>m||caches.match('/feed')).then(m=>m||new Response('<meta charset=utf-8><h1>Hors connexion</h1>',{headers:{'Content-Type':'text/html; charset=utf-8'}}))));
    return;
  }
  if(u.pathname.startsWith('/static/')){
    e.respondWith(caches.match(r).then(m=>m||fetch(r).then(res=>{ if(res.ok){const c=res.clone();caches.open(C).then(x=>x.put(r,c));} return res; })));
  }
});
// --- NOTIFICATIONS PUSH (application fermée) ---
self.addEventListener('push',e=>{
  let d={}; try{ d=e.data?e.data.json():{}; }catch(x){}
  e.waitUntil(self.clients.matchAll({type:'window',includeUncontrolled:true}).then(cl=>{
    if(cl.some(c=>c.visibilityState==='visible')) return;
    return self.registration.showNotification(d.title||'FaceNet',{
      body:d.body||'', icon:d.icon||'/static/uploads/default_avatar.png',
      tag:d.tag||'facenet-notif', renotify:true, vibrate:[200,100,200],
      data:{url:d.url||'/notifications'}
    });
  }));
});
self.addEventListener('notificationclick',e=>{
  e.notification.close();
  const url=(e.notification.data&&e.notification.data.url)||'/notifications';
  e.waitUntil(self.clients.matchAll({type:'window',includeUncontrolled:true}).then(cl=>{
    for(const c of cl){ if('focus' in c){ c.navigate(url); return c.focus(); } }
    return self.clients.openWindow(url);
  }));
});"""
    resp = _sw_make_response(js)
    resp.headers['Content-Type'] = 'application/javascript; charset=utf-8'
    resp.headers['Service-Worker-Allowed'] = '/'
    resp.headers['Cache-Control'] = 'no-cache'
    return resp

