@main_bp.route('/api/push/abonner', methods=['POST'])
def api_push_abonner():
    if 'user_id' not in session:
        return jsonify(success=False, error="Non connecté."), 401
    data = request.get_json(silent=True) or {}
    endpoint = (data.get('endpoint') or '').strip()
    cles = data.get('keys') or {}
    if not endpoint or not cles.get('p256dh') or not cles.get('auth'):
        return jsonify(success=False, error="Abonnement invalide."), 400
    try:
        ab = PushSubscription.query.filter_by(endpoint=endpoint).first()
        if ab is None:
            ab = PushSubscription(endpoint=endpoint)
            db.session.add(ab)
        ab.user_id = session['user_id']
        ab.p256dh = cles['p256dh']
        ab.auth = cles['auth']
        db.session.commit()
        return jsonify(success=True)
    except Exception as e:
        db.session.rollback()
        return jsonify(success=False, error=str(e)), 500

@main_bp.route('/api/push/desabonner', methods=['POST'])
def api_push_desabonner():
    if 'user_id' not in session:
        return jsonify(success=False, error="Non connecté."), 401
    data = request.get_json(silent=True) or {}
    endpoint = (data.get('endpoint') or '').strip()
    try:
        if endpoint:
            PushSubscription.query.filter_by(endpoint=endpoint, user_id=session['user_id']).delete()
            db.session.commit()
        return jsonify(success=True)
    except Exception as e:
        db.session.rollback()
        return jsonify(success=False, error=str(e)), 500

@main_bp.route('/api/appareil/profil')
def appareil_profil():
    """Profil de l'utilisateur connecté + jeton signé pour la connexion en un appui sur cet appareil."""
    import hashlib
    from itsdangerous import URLSafeTimedSerializer
    uid = session.get('user_id')
    user = db.session.get(User, uid) if uid else None
    if not user:
        return jsonify({'success': False}), 401
    ser = URLSafeTimedSerializer(current_app.config['SECRET_KEY'], salt='facenet-appareil')
    token = ser.dumps({'u': user.id, 'f': hashlib.sha256((user.password or '').encode('utf-8')).hexdigest()[:16]})
    return jsonify({'success': True, 'nom': user.nom_complet or user.username, 'username': user.username,
                    'avatar': url_for('static', filename='uploads/' + (user.avatar or 'default_avatar.png')),
                    'token': token})

@main_bp.route('/api/appareil/resume', methods=['POST'])
def appareil_resume():
    """Nombre de notifications non lues par profil enregistré (identifié par son jeton signé)."""
    import hashlib
    from itsdangerous import URLSafeTimedSerializer
    if not _fn_rate_ok('resume:' + (request.remote_addr or ''), 60, 300):
        return jsonify({'counts': {}}), 429
    ser = URLSafeTimedSerializer(current_app.config['SECRET_KEY'], salt='facenet-appareil')
    counts = {}
    for tok in ((request.get_json(silent=True) or {}).get('tokens') or [])[:8]:
        try:
            p = ser.loads(tok, max_age=60 * 60 * 24 * 60)
            user = db.session.get(User, p.get('u'))
            if user and hashlib.sha256((user.password or '').encode('utf-8')).hexdigest()[:16] == p.get('f'):
                counts[str(tok)[-24:]] = Notification.query.filter_by(recipient_id=user.id, is_read=False).count()
        except Exception:
            continue
    return jsonify({'counts': counts})

@main_bp.route('/api/appareil/connexion', methods=['POST'])
def appareil_connexion():
    """Connexion en un appui depuis un profil enregistré (jeton signé, valable 60 jours, invalidé si le mot de passe change)."""
    import hashlib
    from itsdangerous import URLSafeTimedSerializer
    if not _fn_rate_ok('appareil:' + (request.remote_addr or ''), 20, 300):
        return jsonify({'success': False, 'error': 'Trop de tentatives. Réessayez dans quelques minutes.'}), 429
    data = request.get_json(silent=True) or {}
    ser = URLSafeTimedSerializer(current_app.config['SECRET_KEY'], salt='facenet-appareil')
    try:
        p = ser.loads(data.get('token') or '', max_age=60 * 60 * 24 * 60)
    except Exception:
        return jsonify({'success': False, 'error': 'Session expirée. Saisissez de nouveau votre mot de passe.'}), 401
    user = db.session.get(User, p.get('u')) if isinstance(p, dict) else None
    if not user or hashlib.sha256((user.password or '').encode('utf-8')).hexdigest()[:16] != p.get('f'):
        return jsonify({'success': False, 'error': 'Session expirée. Saisissez de nouveau votre mot de passe.'}), 401
    if _pl_bloque_connexion(user):   # AJOUT : contrôle parental — profil verrouillé par le tuteur
        return jsonify({'success': True, 'redirect': url_for('main.profil_verrouille')})
    if _compte_verdict_connexion(user) is not None:   # AJOUT : compte désactivé / suppression non annulable / commémoratif
        _cc_ouvrir_acces(user.id)
        return jsonify({'success': True, 'redirect': url_for('main.compte_gate')})
    session['user_id'] = user.id
    login_user(user)
    user.is_online = True
    user.last_seen = datetime.utcnow()
    db.session.commit()
    return jsonify({'success': True, 'redirect': url_for('main.bon_retour' if _premiere_connexion(user.id) else 'main.feed')})  # AJOUT : bon retour uniquement à la 1re connexion

def _cloturer_notif_invitation(demande):
    """Marque la notification de demande d'ami comme traitée (les boutons disparaissent)."""
    try:
        for n in Notification.query.filter(Notification.recipient_id == demande.recepteur_id,
                Notification.actor_id == demande.emetteur_id,
                Notification.type.in_(['friend_request', 'invitation'])).all():
            extra = dict(n.extra_data or {})
            extra['traitee'] = True
            n.extra_data = extra
            n.is_read = True
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG clôture notification invitation : {e}")

@main_bp.route('/gerer_invitation/<int:demande_id>/<action>', methods=['POST'])
@login_required
def gerer_invitation(demande_id, action):
    demande = DemandeAmitie.query.get_or_404(demande_id)
    if demande.recepteur_id != current_user.id:
        abort(403)
    if demande.statut != 'en_attente':
        flash("Cette invitation a déjà été traitée.", "warning")
        return redirect(request.referrer or url_for('main.afficher_suggesstions'))
    if action == 'accepter':
        demande.statut = 'acceptee'
        db.session.commit()
        notifier(demande.emetteur_id, 'friend_accept', current_user, cible=('user', current_user.id))
        db.session.commit()
        _cloturer_notif_invitation(demande)
    elif action == 'refuser':
        demande.statut = 'refusee'
        db.session.commit()
        _cloturer_notif_invitation(demande)
        flash("Invitation refusée.", "info")
    else:
        abort(400)
    return redirect(request.referrer or url_for('main.afficher_suggesstions'))

# AJOUT ADDITIF : version JSON de /gerer_invitation pour les cartes « Invitations » du fil
# (mêmes règles : seul le destinataire répond, une invitation n'est traitée qu'une fois ; pas de redirection).
@main_bp.route('/api/invitations/<int:demande_id>/<action>', methods=['POST'])
@login_required
def api_invitation_repondre(demande_id, action):
    if action not in ('accepter', 'refuser'):
        return jsonify(success=False, error='Action inconnue.'), 400
    try:
        demande = db.session.get(DemandeAmitie, demande_id)
        if demande is None:
            return jsonify(success=False, error='Invitation introuvable.'), 404
        if demande.recepteur_id != current_user.id:
            return jsonify(success=False, error='Action non autorisée.'), 403
        if demande.statut != 'en_attente':
            return jsonify(success=False, error='Cette invitation a déjà été traitée.'), 409
        if action == 'accepter':
            demande.statut = 'acceptee'
            db.session.commit()
            notifier(demande.emetteur_id, 'friend_accept', current_user, cible=('user', current_user.id))
            db.session.commit()
        else:
            demande.statut = 'refusee'
            db.session.commit()
        _cloturer_notif_invitation(demande)
        return jsonify(success=True, statut=demande.statut)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: réponse à l'invitation impossible : {e}")
        return jsonify(success=False, error='Une erreur est survenue. Réessayez dans un instant.'), 500

@main_bp.route('/supprimer_ami/<int:ami_id>', methods=['POST'])
@login_required
def supprimer_ami(ami_id):
    demande = DemandeAmitie.query.filter(DemandeAmitie.statut == 'acceptee', or_(
        and_(DemandeAmitie.emetteur_id == current_user.id, DemandeAmitie.recepteur_id == ami_id),
        and_(DemandeAmitie.emetteur_id == ami_id, DemandeAmitie.recepteur_id == current_user.id))).first()
    if demande:
        db.session.delete(demande); db.session.commit()
        flash("Ami supprimé.", "info")
    else:
        flash("Cette relation d'amitié est introuvable.", "warning")
    return redirect(request.referrer or url_for('main.afficher_suggesstions'))

@main_bp.route('/amies')
@login_required
def afficher_suggesstions():
    user_actif = current_user
    demandes_envoyees = user_actif.sent_requests
    demandes_recues = [d for d in user_actif.received_requests if d.statut == 'en_attente']
    demandes_envoyees_ids = [f.recepteur_id for f in demandes_envoyees]
    demandes_recues_ids = [f.emetteur_id for f in user_actif.received_requests]
    tous_les_associes_ids = demandes_envoyees_ids + demandes_recues_ids
    tous_les_associes_ids.append(user_actif.id)
    suggestions_amis = User.query.filter(not_(User.id.in_(tous_les_associes_ids))).limit(5).all()
    mes_amis = user_actif.friends
    return render_template('ton_page.html', suggestions=suggestions_amis,
        demandes_recues=demandes_recues, demandes_envoyees=demandes_envoyees, mes_amis=mes_amis)

def _amis_ids(user_id):
    demandes = DemandeAmitie.query.filter(DemandeAmitie.statut == 'acceptee',
        or_(DemandeAmitie.emetteur_id == user_id, DemandeAmitie.recepteur_id == user_id)).all()
    ids = set()
    for d in demandes:
        ids.add(d.recepteur_id if d.emetteur_id == user_id else d.emetteur_id)
    return ids

# ──────────────────────────────────────────────────────────────
#  AJOUT ADDITIF : bouton « Suivre » (compte officiel FaceNet Support uniquement
#  côté profil). Ce compte ne reçoit ni invitation d'ami ni message : on le suit.
# ──────────────────────────────────────────────────────────────
from models import Abonnement

# AJOUT ADDITIF : les trois comptes officiels (FaceNet Support, FaceNet, Tsapi AI) ont le même
# profil « neutre » : bouton Suivre seul, compteur/liste d'abonnés, ni message ni invitation d'ami.
_COMPTES_OFFICIELS_USERNAMES = ('facenet_support', 'facenet_officiel', 'tsapi_ai',
                               'facenet support', 'facenet', 'tsapi ai')   # nouveaux noms (comptes renommés par support_bot.py)

def _est_compte_support(u):
    return bool(u and (getattr(u, 'username', '') or '').strip().lower() in _COMPTES_OFFICIELS_USERNAMES)

_table_abonnement_ok = False
def _assurer_table_abonnement():
    global _table_abonnement_ok
    if _table_abonnement_ok:
        return
    try:
        Abonnement.__table__.create(bind=db.engine, checkfirst=True)
        _table_abonnement_ok = True
    except Exception as e:
        print(f"DEBUG: création table abonnement impossible : {e}")

# ──────────────────────────────────────────────────────────────
#  AJOUT ADDITIF : page de recherche façon Facebook (explore.html)
#  Historique « Récentes » (recherches + profils visités), épinglage (3 max),
#  suppression, « Tout effacer », et infos utiles pour les suggestions en tapant.
# ──────────────────────────────────────────────────────────────
class RechercheRecente(db.Model):
    __tablename__ = 'recherche_recente'
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, nullable=False, index=True)
    kind = db.Column(db.String(10), nullable=False)          # 'terme' | 'profil'
    terme = db.Column(db.String(150))
    cible_id = db.Column(db.Integer, index=True)
    epingle = db.Column(db.Boolean, default=False, nullable=False)
    date = db.Column(db.DateTime, default=datetime.utcnow, index=True)

_table_recherche_ok = False
def _assurer_table_recherche():
    global _table_recherche_ok
    if _table_recherche_ok:
        return
    try:
        RechercheRecente.__table__.create(bind=db.engine, checkfirst=True)
        _table_recherche_ok = True
    except Exception as e:
        print(f"DEBUG: création table recherche_recente impossible : {e}")

_RECHERCHES_MAX = 100
_EPINGLES_MAX = 3

def _fmt_nombre_fr(n):
    try:
        n = int(n or 0)
    except Exception:
        return ''
    def _f(x):
        t = f"{x:.1f}".replace('.', ',')
        return t[:-2] if t.endswith(',0') else t
    if n >= 1000000:
        return _f(n / 1000000) + ' M'
    if n >= 1000:
        return _f(n / 1000) + ' K'
    return str(n)

def _ids_certifies():
    try:
        return {r.user_id: (r.categorie or '') for r in PersonnaliteCertifiee.query.all()}
    except Exception:
        return {}

def _enrichir_utilisateurs(users, moi_id, amis_ids):
    """Ajoute à chaque utilisateur (en mémoire, rien n'est enregistré) les infos affichées par la page :
    amis en commun, compte « à suivre seulement », déjà suivi, invitation déjà envoyée, catégorie, abonnés."""
    if not users:
        return users
    _assurer_table_abonnement()
    ids = [u.id for u in users]
    certifies = _ids_certifies()
    communs = _amis_communs_pour(amis_ids, ids) if amis_ids else {}
    try:
        suivis = {a.suivi_id for a in Abonnement.query.filter(
            Abonnement.follower_id == moi_id, Abonnement.suivi_id.in_(ids)).all()}
    except Exception:
        db.session.rollback()
        suivis = set()
    try:
        invites = {d.recepteur_id for d in DemandeAmitie.query.filter(
            DemandeAmitie.emetteur_id == moi_id, DemandeAmitie.statut == 'en_attente',
            DemandeAmitie.recepteur_id.in_(ids)).all()}
    except Exception:
        db.session.rollback()
        invites = set()
    for u in users:
        def _set(nom, val):
            try:
                setattr(u, nom, val)
            except Exception:
                pass
        suivre_seul = _est_compte_support(u) or (u.id in certifies)
        _set('suivre_seul', suivre_seul)
        _set('est_suivi', u.id in suivis)
        _set('invitation_envoyee', u.id in invites)
        _set('nb_amis_communs', communs.get(u.id, 0))
        if suivre_seul:
            _set('nb_abonnes', getattr(u, 'followers_count', None) or 0)
            if certifies.get(u.id):
                _set('categorie', certifies[u.id])
            elif _est_compte_support(u):
                _set('categorie', 'Compte officiel')
    return users

def _pour_vous_pour(user_id, nb=10):
    """Comptes à suivre (officiels / personnalités certifiées), au hasard, hors soi-même et comptes déjà suivis."""
    try:
        _assurer_table_abonnement()
        ids = set(_ids_certifies().keys())
        for u in User.query.filter(db.func.lower(User.username).in_(_COMPTES_OFFICIELS_USERNAMES)).all():
            ids.add(u.id)
        ids.discard(user_id)
        ids -= _compte_ids_masques()   # AJOUT : comptes masqués
        if not ids:
            return []
        deja = {a.suivi_id for a in Abonnement.query.filter(Abonnement.follower_id == user_id).all()}
        ids = list(ids - deja)
        random.shuffle(ids)
        ids = ids[:nb]
        return User.query.filter(User.id.in_(ids)).all() if ids else []
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG pour_vous ignoré : {e}")
        return []

def _enregistrer_recherche(user_id, terme):
    terme = (terme or '').strip()[:150]
    if not terme:
        return
    _assurer_table_recherche()
    try:
        ligne = RechercheRecente.query.filter(
            RechercheRecente.user_id == user_id, RechercheRecente.kind == 'terme',
            db.func.lower(RechercheRecente.terme) == terme.lower()).first()
        if ligne:
            ligne.date = datetime.utcnow()
            ligne.terme = terme
        else:
            db.session.add(RechercheRecente(user_id=user_id, kind='terme', terme=terme))
        db.session.commit()
        _purger_recherches(user_id)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG enregistrement recherche ignoré : {e}")

def _enregistrer_visite(user_id, cible_id):
    _assurer_table_recherche()
    try:
        ligne = RechercheRecente.query.filter_by(user_id=user_id, kind='profil', cible_id=cible_id).first()
        if ligne:
            ligne.date = datetime.utcnow()
        else:
            db.session.add(RechercheRecente(user_id=user_id, kind='profil', cible_id=cible_id))
        db.session.commit()
        _purger_recherches(user_id)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG enregistrement visite ignoré : {e}")

def _purger_recherches(user_id):
    try:
        lignes = (RechercheRecente.query.filter_by(user_id=user_id, epingle=False)
                  .order_by(RechercheRecente.date.desc()).offset(_RECHERCHES_MAX).all())
        for l in lignes:
            db.session.delete(l)
        if lignes:
            db.session.commit()
    except Exception:
        db.session.rollback()

def _avatar_url_de(u):
    fichier = getattr(u, 'avatar', None) if u else None
    try:
        if fichier:
            return url_for('static', filename='uploads/' + fichier)
        return url_for('static', filename='uploads/default_avatar.png')
    except Exception:
        return ''

def _recentes_pour(user_id, limite=60):
    """Liste prête à afficher : épinglées d'abord, puis les plus récentes."""
    _assurer_table_recherche()
    try:
        lignes = (RechercheRecente.query.filter_by(user_id=user_id)
                  .order_by(RechercheRecente.epingle.desc(), RechercheRecente.date.desc())
                  .limit(limite).all())
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG historique indisponible : {e}")
        return []
    cibles_ids = [l.cible_id for l in lignes if l.kind == 'profil' and l.cible_id]
    par_id = {u.id: u for u in User.query.filter(User.id.in_(cibles_ids)).all()} if cibles_ids else {}
    certifies = _ids_certifies() if cibles_ids else {}
    resultat = []
    for l in lignes:
        if l.kind == 'terme':
            resultat.append({'id': l.id, 'kind': 'terme', 'epingle': bool(l.epingle),
                             'nom': l.terme or '', 'sous_titre': '', 'avatar': '', 'verifie': False,
                             'href': url_for('main.explore', search_query=l.terme or '')})
        else:
            u = par_id.get(l.cible_id)
            if not u or _compte_masque(u.id):
                continue   # profil supprimé ou masqué : on l'ignore
            sous = ''
            if u.id in certifies or _est_compte_support(u):
                p = [certifies.get(u.id) or 'Compte officiel']
                ab = _fmt_nombre_fr(getattr(u, 'followers_count', 0))
                if ab and ab != '0':
                    p.append(ab + ' followers')
                sous = ' · '.join(p)
            resultat.append({'id': l.id, 'kind': 'profil', 'epingle': bool(l.epingle),
                             'nom': u.nom_complet or u.username, 'sous_titre': sous,
                             'avatar': _avatar_url_de(u), 'verifie': bool(getattr(u, 'badge_expire', None)),
                             'href': url_for('main.profil_par_id', user_id=u.id)})
    return resultat

@main_bp.route('/api/explore/historique', methods=['GET'])
@login_required
def api_explore_historique():
    return jsonify(success=True, items=_recentes_pour(current_user.id))

@main_bp.route('/api/explore/historique/profil', methods=['POST'])
@login_required
def api_explore_historique_profil():
    cible_id = request.form.get('cible_id', type=int) or (request.get_json(silent=True) or {}).get('cible_id')
    try:
        cible_id = int(cible_id)
    except Exception:
        return jsonify(success=False, error="Profil invalide."), 400
    if cible_id == current_user.id or db.session.get(User, cible_id) is None:
        return jsonify(success=True)   # rien à enregistrer
    _enregistrer_visite(current_user.id, cible_id)
    return jsonify(success=True)

