@main_bp.route('/api/explore/historique/<int:ligne_id>/epingler', methods=['POST'])
@login_required
def api_explore_historique_epingler(ligne_id):
    _assurer_table_recherche()
    try:
        l = RechercheRecente.query.filter_by(id=ligne_id, user_id=current_user.id).first()
        if not l:
            return jsonify(success=False, error="Élément introuvable."), 404
        if l.epingle:
            l.epingle = False
        else:
            nb = RechercheRecente.query.filter_by(user_id=current_user.id, epingle=True).count()
            if nb >= _EPINGLES_MAX:
                return jsonify(success=False, error="Vous ne pouvez épingler que 3 recherches à la fois."), 400
            l.epingle = True
        db.session.commit()
        return jsonify(success=True, epingle=bool(l.epingle))
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG épinglage impossible : {e}")
        return jsonify(success=False, error="Impossible pour le moment."), 500

