@main_bp.route('/api/suivre/<int:user_id>', methods=['POST'])
@login_required
def api_suivre(user_id):
    """Bascule suivre / ne plus suivre un compte. Répond en JSON."""
    if user_id == current_user.id:
        return jsonify(success=False, error="Vous ne pouvez pas vous suivre vous-même."), 400
    cible = db.session.get(User, user_id)
    if cible is None:
        return jsonify(success=False, error="Compte introuvable."), 404
    _assurer_table_abonnement()
    try:
        existant = Abonnement.query.filter_by(follower_id=current_user.id, suivi_id=user_id).first()
        if existant:
            db.session.delete(existant)
            suivi = False
        else:
            db.session.add(Abonnement(follower_id=current_user.id, suivi_id=user_id))
            suivi = True
        db.session.flush()
        nb = Abonnement.query.filter_by(suivi_id=user_id).count()
        cible.followers_count = nb
        db.session.commit()
        return jsonify(success=True, suivi=suivi, abonnes=nb)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: suivi impossible : {e}")
        return jsonify(success=False, error="Impossible pour le moment. Réessayez."), 500

@main_bp.route('/api/abonnes/<int:user_id>', methods=['GET'])
@login_required
def api_abonnes(user_id):
    """Liste paginée des personnes qui suivent un compte (bouton « Voir plus » du profil)."""
    offset = max(request.args.get('offset', 0, type=int) or 0, 0)
    limit = min(max(request.args.get('limit', 15, type=int) or 15, 1), 50)
    _assurer_table_abonnement()
    try:
        total = Abonnement.query.filter_by(suivi_id=user_id).count()
        lignes = (User.query.join(Abonnement, Abonnement.follower_id == User.id)
                  .filter(Abonnement.suivi_id == user_id)
                  .order_by(Abonnement.id.desc())
                  .offset(offset).limit(limit + 1).all())
        a_plus = len(lignes) > limit
        def _pres(u):
            ol = est_en_ligne(u)
            bd = '' if ol else badge_presence_court(u.last_seen)
            return {'en_ligne': bool(ol), 'badge': bd,
                    'statut': 'En ligne' if ol else (f'Actif il y a {bd}' if bd else 'Hors ligne')}
        return jsonify(success=True, total=total, a_plus=a_plus, abonnes=[
            dict({'id': u.id, 'username': u.username, 'nom_complet': u.nom_complet or u.username, 'avatar': u.avatar},
                 **_pres(u))
            for u in lignes[:limit]])
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: liste des abonnés indisponible : {e}")
        return jsonify(success=False, error="Liste indisponible."), 500

@main_bp.route('/api/suivis/<int:user_id>', methods=['GET'])
@login_required
def api_suivis(user_id):
    """Liste paginée des personnes que ce compte suit (bouton « Suivi(e)s » du profil)."""
    offset = max(request.args.get('offset', 0, type=int) or 0, 0)
    limit = min(max(request.args.get('limit', 20, type=int) or 20, 1), 50)
    _assurer_table_abonnement()
    try:
        total = Abonnement.query.filter_by(follower_id=user_id).count()
        lignes = (User.query.join(Abonnement, Abonnement.suivi_id == User.id)
                  .filter(Abonnement.follower_id == user_id)
                  .order_by(Abonnement.id.desc())
                  .offset(offset).limit(limit + 1).all())
        a_plus = len(lignes) > limit
        return jsonify(success=True, total=total, a_plus=a_plus,
                       est_proprietaire=(current_user.id == user_id),
                       suivis=[{'id': u.id, 'username': u.username,
                                'nom_complet': u.nom_complet or u.username,
                                'avatar': u.avatar}
                               for u in lignes[:limit]])
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: liste des suivis indisponible : {e}")
        return jsonify(success=False, error="Liste indisponible."), 500

@main_bp.route('/envoyer_invitation/<int:user_id>', methods=['POST'])
@login_required
def envoyer_invitation(user_id):
    if user_id == current_user.id:
        return jsonify({'status': 'error', 'message': 'Vous ne pouvez pas vous inviter vous-même.'}), 400
    destinataire = User.query.get_or_404(user_id)
    if _est_compte_support(destinataire):
        return jsonify({'status': 'error', 'message': "Ce compte ne reçoit pas d'invitations : vous pouvez le suivre."}), 400
    demande_existante = DemandeAmitie.query.filter(or_(
        and_(DemandeAmitie.emetteur_id == current_user.id, DemandeAmitie.recepteur_id == user_id),
        and_(DemandeAmitie.emetteur_id == user_id, DemandeAmitie.recepteur_id == current_user.id))).first()
    if demande_existante:
        if demande_existante.statut == 'acceptee':
            return jsonify({'status': 'info', 'message': 'Vous êtes déjà amis.'})
        elif demande_existante.emetteur_id == current_user.id:
            return jsonify({'status': 'warning', 'message': 'Invitation déjà envoyée.'})
        else:
            return jsonify({'status': 'info', 'message': 'Cet utilisateur vous a déjà envoyé une invitation.'})
    else:
        nouvelle_demande = DemandeAmitie(emetteur_id=current_user.id, recepteur_id=user_id)
        db.session.add(nouvelle_demande)
        db.session.flush()
        notifier(user_id, 'friend_request', current_user, cible=('friend_request', nouvelle_demande.id),
                 demande_id=nouvelle_demande.id)
        db.session.commit()
        return jsonify({'status': 'success', 'message': 'Invitation envoyée !', 'demande_id': nouvelle_demande.id})

def _date_demande_iso(demande):
    """Date d'envoi d'une demande d'amitié (UTC, ISO + 'Z'), ou None si le modèle n'a pas de colonne date."""
    for champ in ('date_creation', 'created_at', 'date_envoi', 'date_demande', 'date'):
        valeur = getattr(demande, champ, None)
        if valeur:
            try:
                return valeur.isoformat() + "Z"
            except AttributeError:
                return None
    return None

@main_bp.route('/api/invitations_envoyees', methods=['GET'])
@login_required
def api_invitations_envoyees():
    demandes = DemandeAmitie.query.filter_by(emetteur_id=current_user.id, statut='en_attente').all()
    resultat = []
    for d in demandes:
        destinataire = db.session.get(User, d.recepteur_id)
        if not destinataire:
            continue
        resultat.append({
            'id': d.id,
            'user_id': destinataire.id,
            'nom': destinataire.nom_complet or destinataire.username,
            'username': destinataire.username,
            'avatar': getattr(destinataire, 'avatar', None),
            'date': _date_demande_iso(d)})
    resultat.sort(key=lambda x: x['date'] or '', reverse=True)
    return jsonify({'status': 'success', 'invitations': resultat})

@main_bp.route('/annuler_invitation/<int:demande_id>', methods=['POST'])
@login_required
def annuler_invitation(demande_id):
    demande = db.session.get(DemandeAmitie, demande_id)
    if not demande or demande.emetteur_id != current_user.id:
        return jsonify({'status': 'error', 'message': 'Invitation introuvable.'}), 404
    if demande.statut != 'en_attente':
        return jsonify({'status': 'warning', 'message': 'Cette invitation a déjà été traitée.'}), 400
    # Retire aussi la notification envoyée au destinataire
    Notification.query.filter_by(user_id=demande.recepteur_id, sender_id=current_user.id,
                                 type='invitation').delete()
    db.session.delete(demande)
    db.session.commit()
    return jsonify({'status': 'success', 'message': 'Invitation annulée.'})

# ══════════════════════════════════════════════════════════════════════
# AJOUT ADDITIF : gestion d'un ami depuis « Mes Amis » (ton_page.html)
#   • date d'amitié (« Amis depuis … »)   • retirer des amis
#   • bloquer (retire aussi l'amitié)      • signaler un profil
# Rien d'existant n'est modifié : nouvelles routes JSON + une nouvelle table
# (signalement_profil, créée automatiquement au premier signalement).
# ══════════════════════════════════════════════════════════════════════
MOTIFS_SIGNALEMENT_PROFIL = {
    'faux_compte': "Faux compte",
    'usurpation': "Usurpation d'identité",
    'harcelement': "Harcèlement ou intimidation",
    'spam': "Spam ou arnaque",
    'contenu_inapproprie': "Contenu inapproprié",
    'autre': "Autre",
}

class SignalementProfil(db.Model):
    __tablename__ = 'signalement_profil'
    id = db.Column(db.Integer, primary_key=True)
    auteur_id = db.Column(db.Integer, nullable=False, index=True)
    cible_id = db.Column(db.Integer, nullable=False, index=True)
    motif = db.Column(db.String(40), nullable=False)
    details = db.Column(db.String(500), nullable=True)
    statut = db.Column(db.String(20), default='En attente', nullable=False)
    date_creation = db.Column(db.DateTime, default=datetime.utcnow)

_table_signalement_profil_ok = False
def _assurer_table_signalement_profil():
    global _table_signalement_profil_ok
    if _table_signalement_profil_ok:
        return
    try:
        SignalementProfil.__table__.create(bind=db.engine, checkfirst=True)
        _table_signalement_profil_ok = True
    except Exception as e:
        print(f"DEBUG: création table signalement_profil impossible : {e}")

def _relations_amitie(user_id, ami_id):
    """Les demandes d'amitié acceptées entre deux utilisateurs (dans un sens ou dans l'autre)."""
    return DemandeAmitie.query.filter(DemandeAmitie.statut == 'acceptee', or_(
        and_(DemandeAmitie.emetteur_id == user_id, DemandeAmitie.recepteur_id == ami_id),
        and_(DemandeAmitie.emetteur_id == ami_id, DemandeAmitie.recepteur_id == user_id))).all()

@main_bp.route('/api/amis/depuis', methods=['GET'])
@login_required
def api_amis_depuis():
    """{id_ami: date ISO} : depuis quand chaque ami est ami avec l'utilisateur connecté."""
    demandes = DemandeAmitie.query.filter(DemandeAmitie.statut == 'acceptee', or_(
        DemandeAmitie.emetteur_id == current_user.id,
        DemandeAmitie.recepteur_id == current_user.id)).all()
    depuis = {}
    for d in demandes:
        ami_id = d.recepteur_id if d.emetteur_id == current_user.id else d.emetteur_id
        iso = _date_demande_iso(d)
        if iso:
            depuis[str(ami_id)] = iso
    return jsonify(success=True, depuis=depuis)

@main_bp.route('/api/ami/<int:ami_id>/retirer', methods=['POST'])
@login_required
def api_ami_retirer(ami_id):
    relations = _relations_amitie(current_user.id, ami_id)
    if not relations:
        return jsonify(success=False, error="Cette relation d'amitié est introuvable."), 404
    try:
        for r in relations:
            db.session.delete(r)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: retrait d'un ami impossible : {e}")
        return jsonify(success=False, error="Impossible de retirer cet ami pour le moment."), 500
    return jsonify(success=True)

@main_bp.route('/api/ami/<int:ami_id>/bloquer', methods=['POST'])
@login_required
def api_ami_bloquer(ami_id):
    if ami_id == current_user.id:
        return jsonify(success=False, error="Vous ne pouvez pas vous bloquer vous-même."), 400
    if not db.session.get(User, ami_id):
        return jsonify(success=False, error="Utilisateur introuvable."), 404
    try:
        if not BlockedUser.query.filter_by(owner_id=current_user.id, blocked_id=ami_id).first():
            db.session.add(BlockedUser(owner_id=current_user.id, blocked_id=ami_id))
        for r in _relations_amitie(current_user.id, ami_id):  # bloquer met aussi fin à l'amitié
            db.session.delete(r)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: blocage d'un ami impossible : {e}")
        return jsonify(success=False, error="Impossible de bloquer ce compte pour le moment."), 500
    return jsonify(success=True)

@main_bp.route('/api/ami/<int:ami_id>/signaler', methods=['POST'])
@login_required
def api_ami_signaler(ami_id):
    if ami_id == current_user.id:
        return jsonify(success=False, error="Vous ne pouvez pas vous signaler vous-même."), 400
    if not db.session.get(User, ami_id):
        return jsonify(success=False, error="Utilisateur introuvable."), 404
    data = request.get_json(silent=True) or {}
    motif = (data.get('motif') or '').strip()
    details = (data.get('details') or '').strip()[:500] or None
    if motif not in MOTIFS_SIGNALEMENT_PROFIL:
        return jsonify(success=False, error="Merci de choisir un motif de signalement."), 400
    try:
        _assurer_table_signalement_profil()
        deja = SignalementProfil.query.filter_by(auteur_id=current_user.id, cible_id=ami_id,
                                                 motif=motif, statut='En attente').first()
        if not deja:
            db.session.add(SignalementProfil(auteur_id=current_user.id, cible_id=ami_id,
                                             motif=motif, details=details))
            db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: signalement de profil impossible : {e}")
        return jsonify(success=False, error="Signalement impossible pour le moment."), 500
    return jsonify(success=True)

# ══════════════════════════════════════════════════════════════════════
# AJOUT ADDITIF : actions groupées sur les invitations + « Voir le profil » d'un ami
#   • accepter / refuser plusieurs invitations reçues d'un coup (toutes, 10 premières, 20 premières…)
#   • annuler toutes les invitations envoyées en attente
#   • ouverture du profil d'un ami à partir de son identifiant (insensible aux caractères
#     spéciaux du nom d'utilisateur qui provoquaient une erreur 404)
# Rien d'existant n'est modifié.
# ══════════════════════════════════════════════════════════════════════
MAX_INVITATIONS_GROUPEES = 200

def _supprimer_notifs_invitation(emetteur_id, recepteur_id):
    """Retire la notification de demande d'ami envoyée au destinataire (sans jamais bloquer l'action)."""
    try:
        with db.session.begin_nested():
            Notification.query.filter(
                Notification.recipient_id == recepteur_id,
                Notification.actor_id == emetteur_id,
                Notification.type.in_(['friend_request', 'invitation'])
            ).delete(synchronize_session=False)
    except Exception as e:
        print(f"DEBUG: nettoyage notification invitation ignoré : {e}")

@main_bp.route('/api/invitations_recues/traiter', methods=['POST'])
@login_required
def api_invitations_recues_traiter():
    """Accepte ou refuse en une fois les invitations reçues dont les identifiants sont envoyés."""
    data = request.get_json(silent=True) or {}
    action = data.get('action')
    if action not in ('accepter', 'refuser'):
        return jsonify(success=False, error="Action invalide."), 400
    ids = []
    for v in (data.get('ids') or []):
        try:
            n = int(v)
        except (TypeError, ValueError):
            continue
        if n not in ids:
            ids.append(n)
    ids = ids[:MAX_INVITATIONS_GROUPEES]
    if not ids:
        return jsonify(success=False, error="Aucune invitation à traiter."), 400
    demandes = DemandeAmitie.query.filter(DemandeAmitie.id.in_(ids),
        DemandeAmitie.recepteur_id == current_user.id,
        DemandeAmitie.statut == 'en_attente').all()
    if not demandes:
        return jsonify(success=False, error="Ces invitations ont déjà été traitées."), 409
    nouveau_statut = 'acceptee' if action == 'accepter' else 'refusee'
    try:
        for d in demandes:
            d.statut = nouveau_statut
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: traitement groupé des invitations impossible : {e}")
        return jsonify(success=False, error="Impossible de traiter les invitations pour le moment."), 500
    # Notifications : une erreur ici ne doit jamais annuler les acceptations déjà enregistrées.
    for d in demandes:
        try:
            if action == 'accepter':
                notifier(d.emetteur_id, 'friend_accept', current_user, cible=('user', current_user.id))
                db.session.commit()
            _cloturer_notif_invitation(d)
        except Exception as e:
            db.session.rollback()
            print(f"DEBUG: notification d'invitation groupée ignorée : {e}")
    return jsonify(success=True, traitees=[d.id for d in demandes], nombre=len(demandes))

@main_bp.route('/api/invitations_envoyees/annuler_toutes', methods=['POST'])
@login_required
def api_invitations_envoyees_annuler_toutes():
    """Annule (supprime) toutes les invitations envoyées encore en attente."""
    demandes = DemandeAmitie.query.filter_by(emetteur_id=current_user.id, statut='en_attente').all()
    if not demandes:
        return jsonify(success=True, nombre=0, user_ids=[])
    user_ids = [d.recepteur_id for d in demandes]
    try:
        for d in demandes:
            _supprimer_notifs_invitation(current_user.id, d.recepteur_id)
            db.session.delete(d)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: annulation groupée des invitations impossible : {e}")
        return jsonify(success=False, error="Impossible d'annuler les invitations pour le moment."), 500
    return jsonify(success=True, nombre=len(user_ids), user_ids=user_ids)

