@main_bp.route('/api/generate_paroles', methods=['POST'])
def generate_paroles():
    data = request.get_json()
    titre = data.get('titre')
    artiste = data.get('artiste')
    genre = data.get('genre', 'pop')
    prompt = f"""Écris des paroles de chanson originales pour un titre appelé "{titre}" 
de l'artiste {artiste}, dans un style {genre}. 
Structure avec couplets et refrain, en français."""
    try:
        response = client.chat.completions.create(model="llama-3.3-70b-versatile",
            messages=[{"role": "user", "content": prompt}], temperature=0.8, max_tokens=1000)
        paroles = response.choices[0].message.content
        return jsonify({"success": True, "paroles": paroles})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

from sqlalchemy import func

@main_bp.route('/api/messages/non_lus', methods=['GET'])
def api_messages_non_lus():
    if 'user_id' not in session:
        return jsonify(success=False, error="Non connecté."), 401
    current_id = session['user_id']
    ids_bloques_par_moi = {b.blocked_id for b in BlockedUser.query.filter_by(owner_id=current_id).all()}
    ids_qui_mont_bloque = {b.owner_id for b in BlockedUser.query.filter_by(blocked_id=current_id).all()}
    ids_exclus = ids_bloques_par_moi | ids_qui_mont_bloque
    requete = (Message.query.with_entities(Message.expediteur_id, func.count(Message.id))
        .filter(Message.destinataire_id == current_id, Message.lu == False)
        .group_by(Message.expediteur_id))
    par_conversation = {}
    for exp_id, nb in requete.all():
        if exp_id in ids_exclus: continue
        par_conversation[str(exp_id)] = int(nb)
    return jsonify(success=True, par_conversation=par_conversation, total=sum(par_conversation.values()))

@main_bp.route('/api/messages/derniers', methods=['GET'])
def api_messages_derniers():
    if 'user_id' not in session:
        return jsonify(success=False, error="Non connecté."), 401
    current_id = session['user_id']
    correspondants = set()
    for (exp_id, dest_id) in (Message.query.with_entities(Message.expediteur_id, Message.destinataire_id)
        .filter(or_(Message.expediteur_id == current_id, Message.destinataire_id == current_id)).all()):
        if exp_id == current_id and dest_id != current_id: correspondants.add(dest_id)
        elif dest_id == current_id and exp_id != current_id: correspondants.add(exp_id)
    par_conversation = {}
    efface_map = _conv_effacees_map(current_id)   # AJOUT ADDITIF : discussions supprimées de mon côté
    for contact_id in correspondants:
        dernier = (Message.query.filter(or_(
            and_(Message.expediteur_id == current_id, Message.destinataire_id == contact_id),
            and_(Message.expediteur_id == contact_id, Message.destinataire_id == current_id)))
        .order_by(Message.date_envoi.desc()).first())
        if not dernier: continue
        _lim_ef = efface_map.get(contact_id)
        if _lim_ef and dernier.date_envoi and dernier.date_envoi <= _lim_ef: continue
        if dernier.contenu: texte = dernier.contenu
        elif dernier.media_type == 'image': texte = '📷 Photo'
        elif dernier.media_type == 'video': texte = '🎬 Vidéo'
        elif dernier.media_type == 'audio': texte = '🎤 Message vocal'
        elif dernier.media_type == 'document': texte = '📎 ' + (dernier.media_filename or 'Fichier')
        else: texte = 'Message'
        par_conversation[str(contact_id)] = {'dernier_texte': texte,
            'est_moi': (dernier.expediteur_id == current_id),
            'dernier_ts': (dernier.date_envoi.isoformat() + 'Z') if dernier.date_envoi else ''}
    return jsonify(success=True, par_conversation=par_conversation)

