# ──────────────────────────────────────────────────────────────
#  AJOUT ADDITIF : « Supprimer la discussion » (de mon côté uniquement).
#  On retient la date du dernier message au moment de la suppression : tout ce qui est
#  antérieur disparaît pour moi, la personne en face garde toute la conversation.
#  Un nouveau message (envoyé ou reçu) refait apparaître la discussion, vide d'anciens messages.
# ──────────────────────────────────────────────────────────────
_CONV_EFFACEES_T = None

def _conv_effacees_table():
    global _CONV_EFFACEES_T
    if _CONV_EFFACEES_T is None:
        import sqlalchemy as _sa
        t = _sa.Table('conv_effacees', db.metadata,
                      _sa.Column('id', _sa.Integer, primary_key=True),
                      _sa.Column('user_id', _sa.Integer, nullable=False, index=True),
                      _sa.Column('contact_id', _sa.Integer, nullable=False, index=True),
                      _sa.Column('efface_le', _sa.DateTime, nullable=False),
                      extend_existing=True)
        try:
            t.create(bind=db.engine, checkfirst=True)
        except Exception as e:
            print(f"DEBUG: création de la table conv_effacees impossible : {e}")
        _CONV_EFFACEES_T = t
    return _CONV_EFFACEES_T

def _conv_effacees_map(user_id):
    """{contact_id: date limite} des discussions que j'ai supprimées de mon côté."""
    try:
        t = _conv_effacees_table()
        lignes = db.session.execute(t.select().where(t.c.user_id == user_id)).fetchall()
        return {l.contact_id: l.efface_le for l in lignes}
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: lecture conv_effacees : {e}")
        return {}

def _conv_effacee_limite(user_id, contact_id):
    return _conv_effacees_map(user_id).get(contact_id)

@main_bp.route('/api/messages/conversation/<int:contact_id>/supprimer', methods=['POST'])
def api_conversation_supprimer(contact_id):
    if 'user_id' not in session:
        return jsonify(success=False, error="Non connecté."), 401
    current_id = session['user_id']
    if contact_id == current_id:
        return jsonify(success=False, error="Action impossible."), 400
    try:
        dernier = (Message.query.filter(or_(
            and_(Message.expediteur_id == current_id, Message.destinataire_id == contact_id),
            and_(Message.expediteur_id == contact_id, Message.destinataire_id == current_id)))
            .order_by(Message.date_envoi.desc()).first())
        limite = dernier.date_envoi if (dernier and dernier.date_envoi) else datetime.utcnow()
        t = _conv_effacees_table()
        existe = db.session.execute(t.select().where(
            (t.c.user_id == current_id) & (t.c.contact_id == contact_id))).first()
        if existe:
            db.session.execute(t.update().where(t.c.id == existe.id).values(efface_le=limite))
        else:
            db.session.execute(t.insert().values(user_id=current_id, contact_id=contact_id, efface_le=limite))
        # les messages reçus sont marqués lus : plus de pastille sur une discussion supprimée
        (Message.query.filter(Message.expediteur_id == contact_id, Message.destinataire_id == current_id,
                              Message.lu == False)
            .update({'lu': True, 'date_lu': datetime.utcnow()}, synchronize_session=False))
        db.session.commit()
        return jsonify(success=True)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: suppression de discussion : {e}")
        return jsonify(success=False, error="Impossible pour le moment. Réessayez."), 500

def _verification_etape_courante():
    return int(session.get('verification_etape', 1))

def _verification_set_etape(numero):
    try: session['verification_etape'] = int(numero)
    except (TypeError, ValueError): session['verification_etape'] = 1
    _verification_progres_enregistrer(session.get('verification_etape', 1))  # AJOUT : garde l'étape en base

# ══════════════════════════════════════════════════════════════════
#  AJOUT ADDITIF : REPRISE DU PARCOURS DE VÉRIFICATION + JAMAIS DEUX FOIS LE MÊME PAIEMENT
#  Avant : l'étape atteinte n'était gardée que dans la session. Session expirée = retour à la page des forfaits.
#  Maintenant :
#   • l'étape atteinte est aussi gardée en base (table verification_progres, créée toute seule : rien à migrer) ;
#   • au retour, la session est reconstruite et l'utilisateur est renvoyé à SON étape ;
#   • s'il a déjà payé, /forfait et /obtention-badge le renvoient à son étape, et /process_payment refuse
#     un second paiement ;
#   • un paiement lancé mais pas encore confirmé (page fermée, double clic) est retrouvé et vérifié
#     auprès de la passerelle avant d'en créer un nouveau.
#  Un utilisateur qui n'a rien payé reste sur la page des forfaits. Aucune route existante n'est retirée.
# ══════════════════════════════════════════════════════════════════
class VerificationProgres(db.Model):
    __tablename__ = 'verification_progres'
    user_id = db.Column(db.Integer, primary_key=True)
    etape = db.Column(db.Integer, default=2, nullable=False)           # dernière étape atteinte (2 à 5)
    type_document = db.Column(db.String(30), nullable=True)            # pièce choisie (étape 5)
    paiement_ref = db.Column(db.String(160), nullable=True)            # 'fapshi:<transId>' | 'notchpay:<reference>'
    paiement_forfait = db.Column(db.String(60), nullable=True)
    paiement_montant = db.Column(db.Integer, nullable=True)
    paiement_date = db.Column(db.DateTime, nullable=True)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow)

_VERIF_PROGRES_PRET = False

def _verification_progres_table():
    global _VERIF_PROGRES_PRET
    if _VERIF_PROGRES_PRET:
        return True
    try:
        VerificationProgres.__table__.create(bind=db.engine, checkfirst=True)
        _VERIF_PROGRES_PRET = True
    except Exception as e:
        print(f"DEBUG: table verification_progres : {e}")
    return _VERIF_PROGRES_PRET

def _verification_ligne(creer=False):
    if not current_user.is_authenticated or not _verification_progres_table():
        return None
    ligne = db.session.get(VerificationProgres, current_user.id)
    if ligne is None and creer:
        ligne = VerificationProgres(user_id=current_user.id, etape=2)
        db.session.add(ligne)
    return ligne

def _verification_a_paye(user):
    """Paiement confirmé (forfait enregistré) et encore valable : badge non expiré."""
    if not getattr(user, 'forfait_type', None):
        return False
    expire = getattr(user, 'badge_expire', None)
    return not (expire and expire < datetime.utcnow())

def _verification_en_cours_paye(user):
    """True si l'utilisateur a payé et que sa vérification n'est pas terminée : il ne doit pas repayer."""
    if _verification_statut_utilisateur(user) == 'approuve':
        return False
    return bool(session.get('verification_paiement_valide') or _verification_a_paye(user))

def _verification_url_reprise(user):
    """Adresse de l'étape où l'utilisateur s'était arrêté."""
    statut = _verification_statut_utilisateur(user)
    if statut in ('attente', 'approuve', 'rejete'):
        return url_for('main.verification_en_cours')
    ligne = None
    try:
        ligne = _verification_ligne()
    except Exception:
        ligne = None
    try:
        etape = int(ligne.etape) if ligne and ligne.etape else int(session.get('verification_etape', 2))
    except (TypeError, ValueError):
        etape = 2
    etape = max(2, min(5, etape))
    if etape == 3:
        return url_for('main.verification_etape_guide_visage')
    if etape == 4:
        return url_for('main.verification_etape_choix_piece')
    if etape == 5:
        doc = (ligne.type_document if ligne and ligne.type_document else None) or session.get('verification_type_document') or 'cni'
        return url_for('main.verification_etape_scan', type_document=doc)
    return url_for('main.verification_etape_confirmation')

def _verification_progres_enregistrer(numero):
    """Garde l'étape atteinte en base (sinon elle se perd quand la session expire). Ne bloque jamais la page."""
    try:
        numero = int(numero)
        if numero < 2 or not current_user.is_authenticated:
            return
        if not (session.get('verification_paiement_valide') or _verification_a_paye(current_user)):
            return
        ligne = _verification_ligne(creer=True)
        if ligne is None:
            return
        ligne.etape = numero
        if numero == 5:
            ligne.type_document = session.get('verification_type_document') or ligne.type_document
        ligne.updated_at = datetime.utcnow()
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: enregistrement de l'étape de vérification : {e}")

def _verification_enregistrer_ref(ref, forfait, montant):
    """Mémorise un paiement lancé (avant même qu'il soit confirmé)."""
    try:
        ligne = _verification_ligne(creer=True)
        if ligne is None:
            return
        ligne.paiement_ref = str(ref)[:160]
        ligne.paiement_forfait = forfait
        try:
            ligne.paiement_montant = int(montant)
        except (TypeError, ValueError):
            ligne.paiement_montant = None
        ligne.paiement_date = datetime.utcnow()
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: mémorisation du paiement : {e}")

def _verification_effacer_ref():
    try:
        ligne = _verification_ligne()
        if ligne is not None and ligne.paiement_ref:
            ligne.paiement_ref = None
            ligne.paiement_date = None
            db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: effacement du paiement mémorisé : {e}")

def _verification_restaurer_session():
    """Reconstruit la session depuis la base quand elle a expiré après un paiement confirmé."""
    if session.get('verification_paiement_valide'):
        return
    if _verification_statut_utilisateur(current_user) == 'approuve' or not _verification_a_paye(current_user):
        return
    session['verification_paiement_valide'] = True
    ligne = _verification_ligne()
    try:
        session['verification_etape'] = max(2, min(5, int(ligne.etape))) if ligne and ligne.etape else 2
    except (TypeError, ValueError):
        session['verification_etape'] = 2
    if ligne and ligne.type_document:
        session['verification_type_document'] = ligne.type_document

_FENETRE_PAIEMENT_EN_ATTENTE = timedelta(minutes=10)

def _verification_garde_double_paiement():
    """Retourne une redirection si un paiement est déjà confirmé, ou lancé et pas encore confirmé. Sinon None."""
    try:
        if not current_user.is_authenticated:
            return None
        # 1) déjà payé, vérification pas terminée : on reprend à l'étape atteinte
        if _verification_en_cours_paye(current_user):
            flash("Votre paiement est déjà enregistré. Vous reprenez là où vous vous étiez arrêté.", "info")
            return redirect(_verification_url_reprise(current_user))
        # 2) paiement lancé récemment mais pas encore confirmé (page fermée, double clic) : on le vérifie d'abord
        ligne = _verification_ligne()
        if ligne and ligne.paiement_ref and ligne.paiement_date \
                and (datetime.utcnow() - ligne.paiement_date) < _FENETRE_PAIEMENT_EN_ATTENTE:
            fournisseur, _, ref = ligne.paiement_ref.partition(':')
            if not ref:
                return None
            for cle in ('fapshi_trans_id', 'fapshi_forfait', 'notchpay_reference', 'notchpay_forfait', 'notchpay_montant'):
                session.pop(cle, None)
            if fournisseur == 'fapshi':
                session['fapshi_trans_id'] = ref
                session['fapshi_forfait'] = ligne.paiement_forfait
            elif fournisseur == 'notchpay':
                session['notchpay_reference'] = ref
                session['notchpay_forfait'] = ligne.paiement_forfait
                session['notchpay_montant'] = ligne.paiement_montant
            else:
                return None
            return redirect(url_for('main.verification_paiements_valide'))
    except Exception as e:
        print(f"DEBUG: garde anti double paiement : {e}")
    return None

@main_bp.before_request
def _verification_reprise_avant_requete():
    """Limité aux pages de vérification et de forfait : les autres pages ne sont pas touchées."""
    try:
        chemin = request.path or ''
        if not (chemin.startswith('/verification/') or chemin in ('/forfait', '/obtention-badge')):
            return None
        if chemin == '/verification/reinitialiser' or not current_user.is_authenticated:
            return None
        _verification_restaurer_session()
        if request.method == 'GET' and chemin in ('/forfait', '/obtention-badge') \
                and _verification_en_cours_paye(current_user):
            return redirect(_verification_url_reprise(current_user))
    except Exception as e:
        print(f"DEBUG: reprise de la vérification : {e}")
    return None

