@main_bp.route('/tsapi-info/<slug>')
def tsapi_info(slug):
    try:
        retour_url = url_for('main.profile', username=current_user.username)
    except Exception:
        retour_url = '/'
    if slug in AVANTAGES_PAR_SLUG:
        avantage = AVANTAGES_PAR_SLUG[slug]
        autres = [a for a in AVANTAGES if a['slug'] != slug]
        return render_template('tsapi_info.html', avantage=avantage, autres=autres,
                               plans=PLANS, retour_url=retour_url)
    if slug in PAGES_LEGALES:
        return render_template('tsapi_info.html', avantage=None, page=PAGES_LEGALES[slug],
                               slug=slug, pages=PAGES_LEGALES, ordre=ORDRE_PAGES_LEGALES,
                               date_maj=DATE_MAJ, retour_url=retour_url)
    abort(404)

@main_bp.route('/api/ma-photo')
def ma_photo():
    """Adresse de la photo de profil de l'utilisateur connecté (la page du badge l'interroge toute seule)."""
    rep = jsonify(url=None, v=None)
    if current_user.is_authenticated:
        fichier = (getattr(current_user, 'avatar', None) or '').strip()
        if fichier and fichier != 'default_avatar.png':
            version = None
            if fichier.startswith(('http', '/', 'data:')):
                url = fichier
            else:
                chemin = fichier[7:] if fichier.startswith('static/') else fichier
                if not chemin.startswith('uploads/'):
                    chemin = 'uploads/' + chemin
                url = url_for('static', filename=chemin)
                try:  # la date du fichier change quand la photo est remplacée : le navigateur recharge l'image
                    version = int(os.path.getmtime(os.path.join(current_app.static_folder, chemin)))
                except Exception:
                    pass
            rep = jsonify(url=url, v=version)
    rep.headers['Cache-Control'] = 'no-store'
    return rep

