_EXT_PHOTOS_VERIF = ('jpg', 'jpeg', 'png', 'webp')
_TAILLE_MAX_PHOTO_VERIF = 8 * 1024 * 1024  # 8 Mo

def _enregistrer_photo_verification(fichier, prefixe=''):
    """Enregistre une photo dans static/uploads comme edit_profile.
    Retourne (nom_du_fichier, message_erreur). (None, None) si aucun fichier choisi."""
    if not fichier or not fichier.filename:
        return None, None
    ext = fichier.filename.rsplit('.', 1)[-1].lower() if '.' in fichier.filename else ''
    if ext not in _EXT_PHOTOS_VERIF:
        return None, "format non accepté (JPG, PNG ou WEBP uniquement)."
    fichier.stream.seek(0, os.SEEK_END)
    taille = fichier.stream.tell()
    fichier.stream.seek(0)
    if taille > _TAILLE_MAX_PHOTO_VERIF:
        return None, "la photo dépasse 8 Mo."
    import time
    base = secure_filename(fichier.filename) or ('photo.' + ext)
    nom_fichier = f"{int(time.time())}_{prefixe}{base}"
    os.makedirs(os.path.join('static', 'uploads'), exist_ok=True)
    fichier.save(os.path.join('static', 'uploads', nom_fichier))
    return nom_fichier, None

@main_bp.route('/verification/etape-2-modifier', methods=['GET', 'POST'])
@login_required
def verification_etape_modifier_profil():
    """Etape 2 (correction) : modifier nom, photo de profil, photo de couverture,
    puis 'Suivant' -> etape 3 (guide de la photo)."""
    if not session.get('verification_paiement_valide'):
        flash("Veuillez d'abord choisir un forfait.", "info")
        return redirect(url_for('main.verification_etape_forfait'))
    _verification_set_etape(2)

    # Delai de 15 jours entre deux changements de nom (meme regle que edit_profile)
    jours_restants_nom = None
    if current_user.last_name_change:
        prochain = current_user.last_name_change + timedelta(days=15)
        if datetime.utcnow() < prochain:
            jours_restants_nom = (prochain - datetime.utcnow()).days + 1

    if request.method == 'POST':
        if not _pdg_csrf_ok():
            flash("Session de sécurité expirée, veuillez réessayer.", "danger")
            return redirect(url_for('main.verification_etape_modifier_profil'))
        erreurs = []

        # ----- Nom -----
        nom_complet = (request.form.get('nom_complet') or '').strip()
        nom = (request.form.get('nom') or '').strip()
        prenom = (request.form.get('prenom') or '').strip()
        if len(nom_complet) > 100 or len(nom) > 60 or len(prenom) > 60:
            erreurs.append("Nom trop long : le nom n'a pas été modifié.")
        else:
            nom_change = ((nom_complet and nom_complet != (current_user.nom_complet or '')) or
                          (nom and nom != (current_user.nom or '')) or
                          (prenom and prenom != (current_user.prenom or '')))
            if nom_change:
                _candidat = nom_complet or f"{prenom or current_user.prenom or ''} {nom or current_user.nom or ''}"
                if compte_certifie_possedant_nom(noms_affiches=[_candidat], exclure_user_id=current_user.id):
                    erreurs.append(MSG_NOM_CERTIFIE)
                elif jours_restants_nom:
                    erreurs.append(f"Vous pourrez modifier votre nom dans {jours_restants_nom} jour(s). Les autres modifications ont bien été enregistrées.")
                else:
                    if nom_complet: current_user.nom_complet = nom_complet
                    if nom: current_user.nom = nom
                    if prenom: current_user.prenom = prenom
                    current_user.last_name_change = datetime.utcnow()
                    current_user.name_change_count = (current_user.name_change_count or 0) + 1

        # ----- Photo de profil -----
        try:
            nom_avatar, err = _enregistrer_photo_verification(request.files.get('profile_pic'))
            if err:
                erreurs.append("Photo de profil : " + err)
            elif nom_avatar:
                current_user.avatar = nom_avatar
                pub_avatar = None
                if current_user.notifier_changement_photo:
                    pub_avatar = Publication(contenu="a changé sa photo de profil", media_url=nom_avatar,
                                             user_id=current_user.id, type_publication='photo_profil',
                                             confidentialite='public')
                    db.session.add(pub_avatar)
                    db.session.flush()
                db.session.add(PhotoHistorique(user_id=current_user.id, type_photo='avatar', url=nom_avatar,
                                               publication_id=pub_avatar.id if pub_avatar else None))

            # ----- Photo de couverture -----
            nom_cover, err = _enregistrer_photo_verification(request.files.get('cover_pic'), 'cover_')
            if err:
                erreurs.append("Photo de couverture : " + err)
            elif nom_cover:
                current_user.couverture = nom_cover
                pub_cover = None
                if current_user.notifier_changement_photo:
                    pub_cover = Publication(contenu="a changé sa photo de couverture", media_url=nom_cover,
                                            user_id=current_user.id, type_publication='photo_couverture',
                                            confidentialite='public')
                    db.session.add(pub_cover)
                    db.session.flush()
                db.session.add(PhotoHistorique(user_id=current_user.id, type_photo='couverture', url=nom_cover,
                                               publication_id=pub_cover.id if pub_cover else None))
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            print(f"DEBUG verification_etape_modifier_profil : {e}")
            flash("Une erreur est survenue pendant l'enregistrement. Veuillez réessayer.", "danger")
            return redirect(url_for('main.verification_etape_modifier_profil'))

        if erreurs:
            for e in erreurs:
                flash(e, "warning")
            return redirect(url_for('main.verification_etape_modifier_profil'))
        flash("Informations enregistrées.", "success")
        return redirect(url_for('main.verification_etape_guide_visage'))

    return render_template('modifier_profil_verification.html',
                           csrf_token=_fn_csrf_token(),
                           jours_restants_nom=jours_restants_nom)

