def _verification_statut_utilisateur(user):
    """'approuve' | 'attente' | 'rejete' | None (aucune demande envoyee)."""
    if getattr(user, 'is_verify', False) and getattr(user, 'has_badge_bleu', False):
        return 'approuve'
    if user.piece_identite_fichier:
        return 'attente'
    if user.piece_identite_type == 'rejete':
        return 'rejete'
    return None

