DOSSIER_KARAOKE = os.path.join(os.getcwd(), 'static', 'karaoke_tmp')
os.makedirs(DOSSIER_KARAOKE, exist_ok=True)

@main_bp.route('/api/music/search')
def api_music_search():
    import urllib.request
    import urllib.parse
    import json as _json
    q = request.args.get('q', '').strip()
    if not q:
        return jsonify(success=False, results=[])
    cle_youtube = os.environ.get('YOUTUBE_API_KEY', '').strip()
    if not cle_youtube:
        return jsonify(success=False, message="Clé YouTube non configurée.", results=[])
    try:
        params = urllib.parse.urlencode({'part': 'snippet', 'q': q + ' karaoke',
            'type': 'video', 'maxResults': 15, 'key': cle_youtube})
        url = 'https://www.googleapis.com/youtube/v3/search?' + params
        with urllib.request.urlopen(url, timeout=8) as r:
            data = _json.loads(r.read().decode('utf-8'))
        resultats = []
        for item in data.get('items', []):
            snippet = item.get('snippet', {})
            vid = item.get('id', {}).get('videoId', '')
            if not vid: continue
            resultats.append({'title': snippet.get('title', ''),
                'artist': snippet.get('channelTitle', ''),
                'cover': (snippet.get('thumbnails', {}).get('medium', {}) or {}).get('url', ''),
                'video_id': vid, 'video_url': 'https://www.youtube.com/watch?v=' + vid})
        return jsonify(success=True, results=resultats)
    except Exception as e:
        return jsonify(success=False, message=str(e), results=[])

@main_bp.route('/api/karaoke/separer', methods=['POST'])
def api_karaoke_separer():
    fichier = request.files.get('audio')
    if not fichier or not fichier.filename:
        return jsonify(success=False, message="Aucun fichier reçu."), 400
    nom_securise = secure_filename(fichier.filename)
    identifiant = uuid.uuid4().hex
    dossier_courant = os.path.join(DOSSIER_KARAOKE, identifiant)
    os.makedirs(dossier_courant, exist_ok=True)
    chemin_entree = os.path.join(dossier_courant, nom_securise)
    fichier.save(chemin_entree)
    try:
        commande = ['python', '-m', 'demucs', '--two-stems=vocals', '-o', dossier_courant, chemin_entree]
        resultat = subprocess.run(commande, capture_output=True, text=True, timeout=600)
        if resultat.returncode != 0:
            return jsonify(success=False, message="La séparation a échoué.", details=resultat.stderr[-200:]), 500
        base_nom = os.path.splitext(nom_securise)[0]
        chemin_vocals = None
        chemin_instrumental = None
        for racine, dossiers, fichiers_dans in os.walk(dossier_courant):
            for f in fichiers_dans:
                if f == 'vocals.wav': chemin_vocals = os.path.join(racine, f)
                elif f == 'no_vocals.wav': chemin_instrumental = os.path.join(racine, f)
        if not chemin_instrumental:
            return jsonify(success=False, message="Instrumental introuvable après séparation."), 500
        chemin_instrumental_final = os.path.join(DOSSIER_KARAOKE, identifiant + '_instrumental.wav')
        chemin_vocals_final = os.path.join(DOSSIER_KARAOKE, identifiant + '_voix.wav') if chemin_vocals else None
        shutil.move(chemin_instrumental, chemin_instrumental_final)
        if chemin_vocals: shutil.move(chemin_vocals, chemin_vocals_final)
        shutil.rmtree(dossier_courant, ignore_errors=True)
        return jsonify(success=True,
            instrumental_url=url_for('static', filename='karaoke_tmp/' + os.path.basename(chemin_instrumental_final)),
            voix_url=url_for('static', filename='karaoke_tmp/' + os.path.basename(chemin_vocals_final)) if chemin_vocals_final else '',
            titre=base_nom)
    except subprocess.TimeoutExpired:
        return jsonify(success=False, message="La séparation a pris trop de temps."), 500
    except Exception as e:
        return jsonify(success=False, message=str(e)), 500

