@main_bp.route('/api/boost/creer', methods=['POST'])
def api_boost_creer():
    try:
        data = request.get_json() or {}
        post_id = data.get('post_id')
        objective = data.get('objective')
        audience = data.get('audience', {})
        start_datetime = data.get('start_datetime')
        end_datetime = data.get('end_datetime')
        duration_days = data.get('duration_days', 1)
        billing_country = data.get('billing_country')
        currency = data.get('currency')
        budget_total = data.get('budget_total')
        payment_method = data.get('payment_method')
        if not post_id or not budget_total or float(budget_total) <= 0:
            return jsonify({'success': False, 'message': "Données de boost incomplètes ou budget invalide."}), 400
        try:
            _pub_boost = db.session.get(Publication, int(post_id))
        except (TypeError, ValueError):
            _pub_boost = None
        if _pub_boost is None or _pub_boost.user_id != current_user.id:
            return jsonify({'success': False, 'message': "Vous ne pouvez booster que vos propres publications."}), 403
        if (_pub_boost.confidentialite or 'public') != 'public':
            return jsonify({'success': False, 'message': "Seules les publications publiques peuvent être boostées. Passez-la en « Public » puis réessayez."}), 400
        nouveau_boost = PostBoost(post_id=post_id, user_id=current_user.id, objective=objective,
            quantity=1, currency=currency, country=billing_country, total_amount=str(budget_total),
            payment_method=payment_method, status='pending')
        db.session.add(nouveau_boost); db.session.commit()
        campagne_info = None
        try:
            campagne_info = _boost_creer_campagne(nouveau_boost, _pub_boost, data)
        except Exception as _e_camp:
            db.session.rollback()
            print(f"DEBUG: campagne de boost non créée : {_e_camp}")
        return jsonify({'success': True,
            'message': "Boost enregistré. Redirection vers le paiement...",
            'boost_id': nouveau_boost.id, 'campagne': campagne_info})
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'message': f"Erreur serveur : {str(e)}"}), 500

