ALLOWED_EXTENSIONS = {'pdf', 'png', 'jpg', 'jpeg'}
def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

@main_bp.route('/api/verify-notoriety', methods=['POST'])
@login_required
def verify_notoriety():
    try:
        category = request.form.get('notoriety_category')
        id_doc_type = request.form.get('id_doc_type')
        press_links = request.form.getlist('press_links[]')
        if not press_links or len(press_links) < 5:
            return jsonify({'success': False, 'message': 'Vous devez fournir au moins 5 liens de preuve.'}), 400
        for link in press_links:
            if not link.strip() or not is_valid_url(link):
                return jsonify({'success': False, 'message': f'Le lien "{link}" est invalide.'}), 400
        if not id_doc_type:
            return jsonify({'success': False, 'message': 'Veuillez sélectionner un type de document.'}), 400
        file_recto = request.files.get('notoriety_doc_recto')
        file_verso = request.files.get('notoriety_doc_verso')
        if not file_recto or file_recto.filename == '':
            return jsonify({'success': False, 'message': 'Le fichier Recto est obligatoire.'}), 400
        if not allowed_file(file_recto.filename):
            return jsonify({'success': False, 'message': 'Format Recto non autorisé.'}), 400
        documents_avec_verso = ['passport', 'national_id', 'residence_permit', 'driver_license']
        if id_doc_type in documents_avec_verso:
            if not file_verso or file_verso.filename == '':
                return jsonify({'success': False, 'message': 'Le fichier Verso est obligatoire pour ce type de document.'}), 400
            if not allowed_file(file_verso.filename):
                return jsonify({'success': False, 'message': 'Format Verso non autorisé.'}), 400
        else:
            file_verso = None
        def save_secure_file(file_obj, suffix):
            if not file_obj: return None
            ext = file_obj.filename.rsplit('.', 1)[1].lower()
            unique_filename = f"{uuid.uuid4().hex}_{suffix}.{ext}"
            filepath = os.path.join(current_app.config['UPLOAD_FOLDER'], unique_filename)
            file_obj.save(filepath)
            return unique_filename
        return jsonify({'success': True,
            'message': 'Votre dossier de vérification a été soumis avec succès. Il sera examiné sous 48h.'}), 200
    except Exception as e:
        current_app.logger.error(f"Erreur notoriété : {str(e)}")
        return jsonify({'success': False, 'message': 'Une erreur interne est survenue.'}), 500

@main_bp.route('/api/like/<int:pub_id>', methods=['POST'])
@login_required
def api_toggle_like(pub_id):
    pub = Publication.query.get_or_404(pub_id)
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    like = Like.query.filter_by(user_id=current_user.id, publication_id=pub_id).first()
    if like:
        db.session.delete(like); liked = False
    else:
        db.session.add(Like(user_id=current_user.id, publication_id=pub_id))
        liked = True
        try:
            if not _a_action(pub.user_id, pub_id, 'muet'):
                notifier(pub.user_id, 'like', current_user, cible=('post', pub_id), pub_id=pub_id)
        except Exception as e:
            print(f"DEBUG notification like : {e}")
    db.session.commit()
    # Réactions : un appui simple = réaction « J'aime » ; retirer le like retire aussi son type.
    try:
        if _fn_assurer_table_reactions():
            FnReactionPublication.query.filter_by(user_id=current_user.id, publication_id=pub_id).delete()
            if liked:
                db.session.add(FnReactionPublication(user_id=current_user.id, publication_id=pub_id, type='like'))
            db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG synchro réaction : {e}")
    total = Like.query.filter_by(publication_id=pub_id).count()
    return jsonify(success=True, liked=liked, total_likes=total)

@main_bp.route('/api/like/<int:pub_id>/amis', methods=['GET'])
@login_required
def api_likes_amis(pub_id):
    """Amis de l'utilisateur connecté qui ont aussi aimé cette publication (lecture seule)."""
    pub = db.session.get(Publication, pub_id)
    if pub is None:
        return jsonify(success=False, error="Publication introuvable."), 404
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    ids_amis = _amis_ids(current_user.id)
    if not ids_amis:
        return jsonify(success=True, total=0, amis=[])
    try:
        bloques = {b.blocked_id for b in BlockedUser.query.filter_by(owner_id=current_user.id).all()}
    except Exception:
        db.session.rollback()
        bloques = set()
    ids_amis = set(ids_amis) - bloques
    if not ids_amis:
        return jsonify(success=True, total=0, amis=[])
    likes = Like.query.filter(Like.publication_id == pub_id, Like.user_id.in_(ids_amis)).all()
    ids_likers = []
    for l in likes:
        if l.user_id not in ids_likers:
            ids_likers.append(l.user_id)
    if not ids_likers:
        return jsonify(success=True, total=0, amis=[])
    # AJOUT : type de réaction de chaque ami (like / love / haha…) pour l'afficher dans les Reels
    types_amis = {}
    try:
        if _fn_assurer_table_reactions():
            for r in FnReactionPublication.query.filter(FnReactionPublication.publication_id == pub_id,
                                                        FnReactionPublication.user_id.in_(ids_likers)).all():
                types_amis[r.user_id] = r.type if r.type in REACTION_TYPES else 'like'
    except Exception:
        db.session.rollback()
        types_amis = {}
    utilisateurs = {u.id: u for u in User.query.filter(User.id.in_(ids_likers)).all()}
    amis = []
    for uid in ids_likers:
        u = utilisateurs.get(uid)
        if not u:
            continue
        amis.append({
            'id': u.id,
            'nom': u.nom_complet or u.username or 'Membre FaceNet',
            'username': u.username,
            'type': types_amis.get(u.id, 'like'),
            'avatar': url_for('static', filename='uploads/' + (u.avatar if getattr(u, 'avatar', None) else 'default_avatar.png'))})
    return jsonify(success=True, total=len(amis), amis=amis[:3])

