# ---------------------------------------------------------
# ROUTE 1 : Initialisation du paiement Notch Pay
# ---------------------------------------------------------
@main_bp.route("/api/paiement/notchpay", methods=["POST"])
def route_paiement_notchpay():
    data = request.get_json() or {}

    email = data.get("email")
    forfait = data.get("forfait")  # 'standard', 'premium', 'max', 'max_plus'
    channel = data.get("channel", "card")  # 'card', 'cm.mtn', 'cm.orange', etc.
    phone = data.get("phone", "")

    if not email or not forfait:
        return (
            jsonify({"error": "L'adresse email et le forfait sont requis."}),
            400,
        )

    resultat = notchpay.initier_paiement_notchpay(
        email, forfait, channel, phone
    )

    if resultat["success"]:
        return jsonify(
            {
                "status": "success",
                "payment_url": resultat["payment_url"],
                "montant": resultat["montant"],
                "forfait": resultat["forfait"],
            }
        )
    else:
        return jsonify({"error": resultat["error"]}), 400


# ---------------------------------------------------------
# ROUTE 2 : Webhook Notch Pay (Validation automatique)
# ---------------------------------------------------------
@main_bp.route("/api/notchpay/webhook", methods=["POST"])
def route_webhook_notchpay():
    signature = request.headers.get("x-notch-signature")

    # Vérification sécurisée HMAC
    if not notchpay.verifier_signature_webhook(request.data, signature):
        return jsonify({"error": "Signature invalide"}), 400

    data_event = request.get_json() or {}

    if data_event.get("event") == "payment.complete":
        details = data_event.get("data", {})
        email_client = details.get("customer", {}).get("email")
        montant = details.get("amount")

        # LOGIQUE FACENET : Activer l'abonnement en BDD
        print(f"[NOTCH PAY] Paiement validé pour {email_client} ({montant} XAF)")

    return jsonify({"status": "ok"}), 200

 
# ---------------------------------------------------------
# ROUTE 1 : Création d'un événement (/api/evenement/creer)
# ---------------------------------------------------------
@main_bp.route("/api/evenement/creer", methods=["POST"])
@login_required
def creer_evenement():
    # ── Enregistre vraiment l'événement (avant : simple "TODO" qui ne sauvait rien
    # et répondait {"status": ...} alors que feed.html attend {"success": true}). ──
    from models import EvenementExtra
    data = request.get_json(silent=True) or {}

    titre = (data.get("titre") or "").strip()
    if not titre:
        return jsonify(success=False, error="Le titre de l'événement est obligatoire."), 400
    if len(titre) > 150:
        return jsonify(success=False, error="Le titre est trop long (150 caractères maximum)."), 400

    description = (data.get("description") or "").strip()
    lieu = (data.get("lieu") or "").strip()[:150] or None

    # feed.html envoie "date_debut" (ex. "2026-10-20T12:00") ; on accepte aussi "date".
    date_ev = None
    brut = (data.get("date_debut") or data.get("date") or "").strip()
    if brut:
        try:
            date_ev = datetime.fromisoformat(brut.replace("Z", "")).replace(tzinfo=None)
        except ValueError:
            for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d", "%d/%m/%Y"):
                try:
                    date_ev = datetime.strptime(brut, fmt)
                    break
                except ValueError:
                    continue
    if date_ev is None:
        date_ev = datetime.utcnow()   # la colonne date_evenement est NOT NULL

    # Image facultative envoyée en data-URL base64 par l'assistant d'événement.
    image_nom = None
    image_brute = data.get("image")
    if isinstance(image_brute, str) and image_brute.startswith("data:image/") and "," in image_brute:
        try:
            import base64
            mime = image_brute.split(";", 1)[0].split(":", 1)[1].lower()
            extension = {"image/jpeg": "jpg", "image/png": "png", "image/webp": "webp", "image/gif": "gif"}.get(mime)
            octets = base64.b64decode(image_brute.split(",", 1)[1], validate=True)
            if extension and 0 < len(octets) <= 8 * 1024 * 1024:
                image_nom = f"evt_{current_user.id}_{uuid.uuid4().hex[:12]}.{extension}"
                os.makedirs(os.path.join("static", "uploads"), exist_ok=True)
                with open(os.path.join("static", "uploads", image_nom), "wb") as f:
                    f.write(octets)
        except Exception as e:
            print(f"DEBUG: image d'événement ignorée : {e}")
            image_nom = None

    try:
        ev = Evenement(titre=titre, description=description or None,
                       date_evenement=date_ev, lieu=lieu)
        db.session.add(ev)
        db.session.flush()   # récupère ev.id sans valider

        reponses = data.get("reponses")
        # Apparence choisie avant la publication :
        #   simple      -> carte classique
        #   background  -> photo de l'utilisateur derrière le texte (exige une image valide)
        #   logo        -> logo (icône) de l'événement sur fond de la couleur de sa catégorie
        _mode_demande = data.get("mode_affichage")
        if _mode_demande == "background" and image_nom:
            _mode_final = "background"
        elif _mode_demande == "logo":
            _mode_final = "logo"
        else:
            _mode_final = "simple"
        _hex6 = re.compile(r"^#[0-9a-fA-F]{6}$")
        _tc = str(data.get("texte_couleur") or "#ffffff")
        _cc = str(data.get("couleur") or "")
        try:
            _v_brut = data.get("voile")
            _voile = min(max(float(_v_brut if _v_brut not in (None, "") else 0.55), 0.0), 0.9)
        except (TypeError, ValueError):
            _voile = 0.55
        design_config = {
            "mode_affichage": _mode_final,
            "texte_couleur": _tc if _hex6.match(_tc) else "#ffffff",
            "voile": str(round(_voile, 2)),
            "couleur": _cc if _hex6.match(_cc) else "#1877f2",
            "reponses": reponses,
        }
        _icone_brute = str(data.get("icone") or "")
        _icone_ok = _icone_brute if re.match(r"^fa-[a-z0-9-]{1,30}$", _icone_brute) else None
        db.session.add(EvenementExtra(
            evenement_id=ev.id,
            user_id=current_user.id,
            categorie=(str(data.get("categorie") or "")[:60] or None),
            type_evenement=(str(data.get("type_evenement") or "")[:120] or None),
            icone=_icone_ok,
            image=image_nom,
            reponses=json.dumps(design_config, ensure_ascii=False),
        ))

        # Publication visible dans le fil (sans toucher à la table Publication).
        lignes = [f"📅 {titre}", f"🗓 {date_ev.strftime('%d/%m/%Y à %H:%M')}"]
        if lieu:
            lignes.append(f"📍 {lieu}")
        if description:
            lignes += ["", description]
        db.session.add(Publication(
            contenu="\n".join(lignes)[:5000], media_url=None,
            user_id=current_user.id, confidentialite="public"))

        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"[creer_evenement] erreur : {e}")
        return jsonify(success=False, error="Impossible d'enregistrer l'événement, réessaie."), 500

    return jsonify(success=True, evenement_id=ev.id, message="Événement créé avec succès !"), 201


# ---------------------------------------------------------
# Création d'un sondage (/api/sondage/creer) — la route n'existait pas :
# feed.html appelait une URL inconnue (404) donc rien ne se publiait.
# ---------------------------------------------------------
@main_bp.route("/api/sondage/creer", methods=["POST"])
@login_required
def creer_sondage():
    from models import Poll, PollOption
    data = request.get_json(silent=True) or {}

    question = (data.get("question") or "").strip()
    brutes = data.get("options") or []
    options = []
    for o in brutes if isinstance(brutes, list) else []:
        t = str(o).strip()
        if t and t not in options:
            options.append(t)

    if not question or len(options) < 2:
        return jsonify(success=False, error="Ajoute une question et au moins 2 options."), 400
    if len(question) > 300:
        return jsonify(success=False, error="La question est trop longue (300 caractères maximum)."), 400
    if len(options) > 10 or any(len(t) > 120 for t in options):
        return jsonify(success=False, error="10 options maximum, 120 caractères chacune."), 400

    try:
        pub = Publication(contenu=question, user_id=current_user.id, confidentialite="public")
        db.session.add(pub)
        db.session.flush()
        poll = Poll(publication_id=pub.id, question=question)
        db.session.add(poll)
        db.session.flush()
        for i, t in enumerate(options):
            db.session.add(PollOption(poll_id=poll.id, texte=t, ordre=i))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"[creer_sondage] erreur : {e}")
        return jsonify(success=False, error="Impossible de publier le sondage, réessaie."), 500

    return jsonify(success=True, publication_id=pub.id, poll_id=poll.id), 201


# ---------------------------------------------------------
# RÉACTIONS : J'aime, J'adore, Solidaire, Haha, Wouah, Triste, Grrr
# Une réaction = la ligne Like existante (compteurs, notifications, amis,
# statistiques : rien ne change) + son type, enregistré dans la table
# fn_reaction_publication (créée automatiquement au premier usage).
# ---------------------------------------------------------
REACTION_TYPES = ('like', 'love', 'care', 'haha', 'wow', 'sad', 'angry')


class FnReactionPublication(db.Model):
    __tablename__ = 'fn_reaction_publication'
    __table_args__ = (db.UniqueConstraint('user_id', 'publication_id', name='uq_fn_reaction_user_pub'),
                      {'extend_existing': True})
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, nullable=False, index=True)
    publication_id = db.Column(db.Integer, nullable=False, index=True)
    type = db.Column(db.String(16), nullable=False, default='like')
    created_at = db.Column(db.DateTime, default=datetime.utcnow)


_FN_REACTION_TABLE_OK = False


def _fn_assurer_table_reactions():
    """Crée la table des réactions si elle n'existe pas encore. Ne lève jamais d'exception."""
    global _FN_REACTION_TABLE_OK
    if _FN_REACTION_TABLE_OK:
        return True
    try:
        FnReactionPublication.__table__.create(bind=db.engine, checkfirst=True)
        _FN_REACTION_TABLE_OK = True
    except Exception as e:
        print(f"DEBUG: table fn_reaction_publication indisponible : {e}")
    return _FN_REACTION_TABLE_OK


def _fn_etat_reactions(pub_id, user_id):
    """Compteurs par type + réaction de l'utilisateur (None s'il n'a pas aimé)."""
    ids_likers = [l.user_id for l in Like.query.filter_by(publication_id=pub_id).all()]
    types = {}
    if _fn_assurer_table_reactions():
        try:
            for r in FnReactionPublication.query.filter_by(publication_id=pub_id).all():
                types[r.user_id] = r.type if r.type in REACTION_TYPES else 'like'
        except Exception:
            db.session.rollback()
            types = {}
    compteurs = {t: 0 for t in REACTION_TYPES}
    for uid in set(ids_likers):
        compteurs[types.get(uid, 'like')] += 1
    actif = types.get(user_id, 'like') if (user_id is not None and user_id in set(ids_likers)) else None
    return {'active_type': actif, 'compteurs': compteurs, 'total': len(ids_likers)}


@main_bp.route('/api/reaction/<int:pub_id>', methods=['POST'])
@login_required
def api_reaction_publication(pub_id):
    pub = db.session.get(Publication, pub_id)
    if pub is None:
        return jsonify(success=False, error="Publication introuvable."), 404
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    donnees = request.get_json(silent=True) or {}
    type_r = str(donnees.get('type') or 'like').strip().lower()
    if type_r not in REACTION_TYPES:
        return jsonify(success=False, error="Réaction inconnue."), 400
    try:
        table_ok = _fn_assurer_table_reactions()
        like = Like.query.filter_by(user_id=current_user.id, publication_id=pub_id).first()
        ligne = None
        if table_ok:
            ligne = FnReactionPublication.query.filter_by(user_id=current_user.id, publication_id=pub_id).first()
        ancien = (ligne.type if ligne else 'like') if like else None
        if like and ancien == type_r:
            # Même réaction qu'avant : on la retire (comme un second appui sur J'aime).
            db.session.delete(like)
            if ligne:
                db.session.delete(ligne)
        else:
            if not like:
                db.session.add(Like(user_id=current_user.id, publication_id=pub_id))
                try:
                    if not _a_action(pub.user_id, pub_id, 'muet'):
                        notifier(pub.user_id, 'like', current_user, cible=('post', pub_id), pub_id=pub_id)
                except Exception as e:
                    print(f"DEBUG notification réaction : {e}")
            if table_ok:
                if ligne:
                    ligne.type = type_r
                else:
                    db.session.add(FnReactionPublication(user_id=current_user.id, publication_id=pub_id, type=type_r))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG api_reaction_publication : {e}")
        return jsonify(success=False, error="Impossible d'enregistrer la réaction."), 500
    etat = _fn_etat_reactions(pub_id, current_user.id)
    return jsonify(success=True, liked=etat['active_type'] is not None, total_likes=etat['total'],
                   connecte=True, **etat)


@main_bp.route("/api/reaction/<int:reaction_id>/etat", methods=["GET"])
def etat_reaction(reaction_id):
    """État des réactions d'une publication (reaction_id = id de la publication)."""
    uid = None
    try:
        if current_user.is_authenticated:
            uid = current_user.id
    except Exception:
        uid = None
    if uid is None:
        uid = session.get('user_id')
    etat = {'active_type': None, 'compteurs': {t: 0 for t in REACTION_TYPES}, 'total': 0}
    try:
        pub = db.session.get(Publication, reaction_id)
        if pub is not None and (uid is None or _peut_voir_publication(pub, uid)):
            etat = _fn_etat_reactions(reaction_id, uid)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG etat_reaction : {e}")
    return jsonify({
        "status": "success",
        "success": True,
        "reaction_id": reaction_id,
        "etat": "active",
        "connecte": uid is not None,
        **etat
    }), 200

# ── AJOUT ADDITIF : liste de ceux qui ont réagi à une publication (page « Réactions ») ──
@main_bp.route('/api/reaction/<int:pub_id>/liste', methods=['GET'])
@login_required
def api_reaction_liste(pub_id):
    """Qui a réagi à cette publication (lecture seule) : réaction de chacun, amis en commun, état d'amitié."""
    pub = db.session.get(Publication, pub_id)
    if pub is None:
        return jsonify(success=False, error="Publication introuvable."), 404
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    LIMITE = 1000
    try:
        likes = Like.query.filter_by(publication_id=pub_id).order_by(Like.id.desc()).all()
        types = {}
        if _fn_assurer_table_reactions():
            for lg in FnReactionPublication.query.filter_by(publication_id=pub_id).all():
                types[lg.user_id] = lg.type if lg.type in REACTION_TYPES else 'like'
        ids = []
        for l in likes:
            if l.user_id not in ids:
                ids.append(l.user_id)
        utilisateurs = {u.id: u for u in User.query.filter(User.id.in_(ids)).all()} if ids else {}
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG api_reaction_liste : {e}")
        return jsonify(success=False, error="Impossible de charger les réactions."), 500

    ids_affiches = [uid for uid in ids if uid in utilisateurs][:LIMITE]
    ensemble = set(ids_affiches)

    # Amis en commun + état d'amitié (requêtes groupées ; en cas d'erreur on n'affiche simplement pas ces infos)
    communs = {}
    statuts = {}
    try:
        mes_amis = _amis_ids(current_user.id)
        if ensemble:
            amis_de = {}
            for d in DemandeAmitie.query.filter(DemandeAmitie.statut == 'acceptee',
                    or_(DemandeAmitie.emetteur_id.in_(ensemble), DemandeAmitie.recepteur_id.in_(ensemble))).all():
                if d.emetteur_id in ensemble:
                    amis_de.setdefault(d.emetteur_id, set()).add(d.recepteur_id)
                if d.recepteur_id in ensemble:
                    amis_de.setdefault(d.recepteur_id, set()).add(d.emetteur_id)
            for uid in ensemble:
                communs[uid] = len(amis_de.get(uid, set()) & mes_amis)
            for d in DemandeAmitie.query.filter(or_(
                    and_(DemandeAmitie.emetteur_id == current_user.id, DemandeAmitie.recepteur_id.in_(ensemble)),
                    and_(DemandeAmitie.recepteur_id == current_user.id, DemandeAmitie.emetteur_id.in_(ensemble)))).all():
                autre = d.recepteur_id if d.emetteur_id == current_user.id else d.emetteur_id
                if d.statut == 'acceptee':
                    statuts[autre] = 'ami'
                elif d.emetteur_id == current_user.id:
                    statuts[autre] = 'envoye'
                else:
                    statuts[autre] = 'recu'
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG api_reaction_liste (amis) : {e}")

    reactions = []
    compteurs = {t: 0 for t in REACTION_TYPES}
    for uid in ids_affiches:
        u = utilisateurs[uid]
        t = types.get(uid, 'like')
        compteurs[t] += 1
        nom_user = (u.username or '').strip()
        try:
            if nom_user and '/' not in nom_user:
                profil = url_for('main.profile', username=nom_user)
            else:
                profil = url_for('main.profile', username=str(u.id))
        except Exception:
            profil = ''
        reactions.append({
            'id': u.id,
            'nom': u.nom_complet or u.username or 'Membre FaceNet',
            'username': u.username,
            'profil': profil,
            'type': t,
            'moi': u.id == current_user.id,
            'amis_communs': communs.get(uid, 0),
            'statut': 'moi' if u.id == current_user.id else statuts.get(uid, 'aucun'),
            'avatar': url_for('static', filename='uploads/' + (u.avatar if getattr(u, 'avatar', None) else 'default_avatar.png'))})
    ordre = sorted([t for t in REACTION_TYPES if compteurs[t] > 0], key=lambda t: -compteurs[t])
    return jsonify(success=True, total=len(reactions), ordre=ordre, compteurs=compteurs, reactions=reactions)


@telemetry_bp.route('/api/telemetry/collecter', methods=['POST'])
def collecter_telemetrie():
    """
    Route de réception de la télémétrie FaceNet (Batterie, GPS, Écran, User-Agent).
    Reçoit les données envoyées par le script JS de base.html.
    """
    try:
        # 1. Vérification du format des données envoyées
        data = request.get_json(silent=True)
        if not data:
            return jsonify({
                "success": False, 
                "message": "Aucune donnée JSON valide reçue."
            }), 400

        # 2. Extraction sécurisée des champs de télémétrie
        screen_resolution = data.get('screen_resolution')  # ex: "1920x1080"
        user_agent = data.get('user_agent')                # navigateurs / appareil
        language = data.get('language')                    # ex: "fr-FR"
        battery_level = data.get('battery_level')          # ex: 85 (en %)
        charging = data.get('charging')                    # True / False / None
        latitude = data.get('latitude')                    # float ou None
        longitude = data.get('longitude')                  # float ou None

        # 3. Récupération des métadonnées de requête
        ip_adresse = request.headers.get('X-Forwarded-For', request.remote_addr)
        horodatage = datetime.utcnow()
        user_id = current_user.id if hasattr(current_user, 'is_authenticated') and current_user.is_authenticated else None

        # 4. EXEMPLE DE TRAITEMENT / SAUVEGARDE EN BASE DE DONNÉES (SQLAlchemy)
        # -------------------------------------------------------------------
        # Si tu as un modèle TelemetryLog dans ton models.py, tu peux faire :
        """
        log = TelemetryLog(
            user_id=user_id,
            ip_address=ip_adresse,
            screen_resolution=screen_resolution,
            user_agent=user_agent,
            language=language,
            battery_level=battery_level,
            charging=charging,
            latitude=latitude,
            longitude=longitude,
            created_at=horodatage
        )
        db.session.add(log)
        db.session.commit()
        """

        # Pour le débogage local en mode développement :
        print(f"[Télémétrie FaceNet] User: {user_id} | IP: {ip_adresse} | Écran: {screen_resolution} | Batterie: {battery_level}% | GPS: ({latitude}, {longitude})")

        # 5. Réponse de confirmation au client
        return jsonify({
            "success": True,
            "message": "Télémétrie reçue avec succès."
        }), 200

    except Exception as e:
        # En cas d'erreur inattendue, on renvoie une réponse propre sans faire planter le serveur
        print(f"[Erreur Télémétrie] : {str(e)}")
        return jsonify({
            "success": False,
            "error": "Une erreur interne est survenue lors de l'enregistrement."
        }), 500

@main_bp.route('/admin/telemetrie')
@login_required
def dashboard_telemetrie():
    # Vérification des privilèges PDG/Admin
    is_admin = getattr(current_user, 'is_admin', False) or getattr(current_user, 'role', '') == 'admin'
    if not is_admin:
        abort(403)  # Accès refusé pour les utilisateurs ordinaires

    # Récupération des 100 dernières métriques collectées
    logs = TelemetryLog.query.order_by(TelemetryLog.created_at.desc()).limit(100).all()
    return render_template('admin_telemetry.html', logs=logs)


