_FN_MODELS = (FnUserPrefs, FnSecurity, FnSessionRecord, FnAuditLog, FnAppPassword, FnPasskey)
_fn_tables_ok = False


def _fn_assurer_tables():
    global _fn_tables_ok
    if _fn_tables_ok:
        return
    try:
        for m in _FN_MODELS:
            m.__table__.create(bind=db.engine, checkfirst=True)
        _fn_tables_ok = True
    except Exception as e:
        print(f"DEBUG: création des tables paramètres avancés impossible : {e}")


# ──────────────────────────────────────────────────────────────
#  OUTILS GÉNÉRAUX
# ──────────────────────────────────────────────────────────────
_fn_log = _fn_logging.getLogger('facenet.settings')


def _fn_uid():
    uid = session.get('user_id')
    if uid is None and session.get('_user_id') is not None:
        uid = session.get('_user_id')
    try:
        return int(uid) if uid is not None else None
    except (TypeError, ValueError):
        return None


def _fn_user():
    uid = _fn_uid()
    return db.session.get(User, uid) if uid else None


def _fn_is_admin(user):
    return bool(user) and (bool(getattr(user, 'is_admin', False)) or getattr(user, 'role', '') == 'admin')


def _fn_ip():
    return (request.remote_addr or '')[:64]


def _fn_ua():
    return (request.headers.get('User-Agent') or '')[:300]


def _fn_ok(**kw):
    out = {'success': True}
    out.update(kw)
    return jsonify(out)


def _fn_err(message, code=400, **kw):
    out = {'success': False, 'error': message}
    out.update(kw)
    return jsonify(out), code


class _FnCsrfStr(str):
    """Jeton CSRF utilisable a la fois comme texte ({{ csrf_token }}) et comme
    fonction ({{ csrf_token() }}) : evite 'str' object is not callable dans base.html
    quand on passe csrf_token=... a render_template."""
    def __call__(self):
        return str(self)


def _fn_csrf_token():
    tok = session.get('fn_csrf')
    if not tok:
        tok = _fn_secrets.token_urlsafe(32)
        session['fn_csrf'] = tok
    return _FnCsrfStr(tok)


def _fn_csrf_ok():
    tok = session.get('fn_csrf')
    hdr = request.headers.get(_FN_CSRF_HEADER, '')
    return bool(tok) and bool(hdr) and _fn_hmac.compare_digest(tok, hdr)


def _fn_api(admin=False, csrf=True):
    """Décorateur : session requise, CSRF sur les écritures, erreurs propres en JSON."""
    def deco(fn):
        import functools

        @functools.wraps(fn)
        def wrapper(*a, **kw):
            _fn_assurer_tables()
            if not _fn_uid():
                return _fn_err('Connexion requise.', 401)
            if csrf and request.method in ('POST', 'PUT', 'PATCH', 'DELETE') and not _fn_csrf_ok():
                return _fn_err('Jeton de sécurité invalide. Rechargez la page.', 403)
            if admin and not _fn_is_admin(_fn_user()):
                return _fn_err('Accès réservé aux administrateurs.', 403)
            try:
                return fn(*a, **kw)
            except Exception as e:
                db.session.rollback()
                _fn_log.exception('Erreur API paramètres avancés')
                print(f"[Paramètres avancés] {fn.__name__} : {e}")
                return _fn_err('Une erreur interne est survenue.', 500)
        return wrapper
    return deco


_fn_rate_store = {}
_fn_rate_lock = _fn_threading.Lock()


def _fn_rate_ok(key, limit=5, window=300):
    """Limiteur en mémoire : `limit` tentatives par `window` secondes."""
    now = _fn_time.time()
    with _fn_rate_lock:
        dq = _fn_rate_store.setdefault(key, _fn_deque())
        while dq and now - dq[0] > window:
            dq.popleft()
        if len(dq) >= limit:
            return False
        dq.append(now)
        return True


def _fn_rate_reset(key):
    with _fn_rate_lock:
        _fn_rate_store.pop(key, None)


def _fn_audit(uid, action, detail=''):
    try:
        db.session.add(FnAuditLog(user_id=uid, action=action, detail=(detail or '')[:300],
                                  ip=_fn_ip(), user_agent=_fn_ua()))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"[Audit] écriture impossible : {e}")


def _fn_get_security(uid, create=True):
    sec = db.session.get(FnSecurity, uid)
    if not sec and create:
        sec = FnSecurity(user_id=uid)
        db.session.add(sec)
        db.session.flush()
    return sec


def _fn_ua_label(ua):
    ua = ua or ''
    nav = 'Navigateur'
    for needle, name in (('Edg/', 'Edge'), ('OPR/', 'Opera'), ('Firefox/', 'Firefox'),
                         ('Chrome/', 'Chrome'), ('Safari/', 'Safari')):
        if needle in ua:
            nav = name
            break
    osn = 'Appareil inconnu'
    for needle, name in (('Windows', 'Windows'), ('Android', 'Android'), ('iPhone', 'iPhone'),
                         ('iPad', 'iPad'), ('Mac OS X', 'macOS'), ('Linux', 'Linux')):
        if needle in ua:
            osn = name
            break
    return f"{nav} sur {osn}"


def _fn_iso(dt):
    return (dt.isoformat() + 'Z') if dt else None


