@main_bp.route('/api/fn/prefs', methods=['GET', 'POST'])
@_fn_api()
def fn_api_prefs():
    uid = _fn_uid()
    if request.method == 'POST':
        patch = request.get_json(silent=True) or {}
        merged, clean = _fn_store_prefs(uid, patch)
        for k, label in (('hide_presence', 'statut en ligne masqué'), ('hide_search', 'masquage recherche'),
                         ('no_telemetry', 'télémétrie désactivée'), ('message_expiry', "expiration des messages")):
            if k in clean:
                _fn_audit(uid, 'confidentialite', f"{label} : {clean[k]}")
        return _fn_ok(prefs=merged, server=_fn_server_flags(uid))
    return _fn_ok(prefs=_fn_load_prefs(uid), server=_fn_server_flags(uid))


# ──────────────────────────────────────────────────────────────
#  1. DOUBLE AUTHENTIFICATION (TOTP, RFC 6238) + codes de secours
# ──────────────────────────────────────────────────────────────
def _fn_fernet():
    try:
        from cryptography.fernet import Fernet
        base = ('fn-totp|' + str(current_app.config.get('SECRET_KEY') or '')).encode()
        return Fernet(_fn_b64.urlsafe_b64encode(_fn_hashlib.sha256(base).digest()))
    except Exception:
        return None


def _fn_seal(secret):
    f = _fn_fernet()
    return ('f1:' + f.encrypt(secret.encode()).decode()) if f else ('p0:' + secret)


def _fn_unseal(blob):
    if not blob:
        return None
    if blob.startswith('f1:'):
        f = _fn_fernet()
        return f.decrypt(blob[3:].encode()).decode() if f else None
    return blob[3:] if blob.startswith('p0:') else blob


def _fn_totp_code(secret_b32, counter, digits=6):
    key = _fn_b64.b32decode(secret_b32.upper() + '=' * (-len(secret_b32) % 8))
    h = _fn_hmac.new(key, _fn_struct.pack('>Q', counter), _fn_hashlib.sha1).digest()
    o = h[-1] & 0x0F
    val = (_fn_struct.unpack('>I', h[o:o + 4])[0] & 0x7FFFFFFF) % (10 ** digits)
    return str(val).zfill(digits)


def _fn_totp_check(secret_b32, code, last_step=0, now=None):
    """Retourne le pas TOTP valide (±1 pas, anti-rejeu) ou None."""
    code = re.sub(r'\D', '', code or '')
    if len(code) != 6:
        return None
    step_now = int((now if now is not None else _fn_time.time()) // 30)
    for step in (step_now, step_now - 1, step_now + 1):
        if step > last_step and _fn_hmac.compare_digest(_fn_totp_code(secret_b32, step), code):
            return step
    return None


def _fn_qr_svg(text):
    try:
        import qrcode
        import qrcode.image.svg
        img = qrcode.make(text, image_factory=qrcode.image.svg.SvgPathImage, box_size=8, border=2)
        buf = _fn_io.BytesIO()
        img.save(buf)
        return buf.getvalue().decode('utf-8')
    except Exception:
        return None


def _fn_new_recovery_codes(n=8):
    codes = [(_fn_secrets.token_hex(5)[:5] + '-' + _fn_secrets.token_hex(5)[:5]) for _ in range(n)]
    return codes, [_fn_hashlib.sha256(c.encode()).hexdigest() for c in codes]


def _fn_use_recovery(sec, code):
    code = (code or '').strip().lower()
    if not re.match(r'^[0-9a-f]{5}-[0-9a-f]{5}$', code):
        return False
    h = _fn_hashlib.sha256(code.encode()).hexdigest()
    try:
        lst = json.loads(sec.recovery_hashes or '[]')
    except Exception:
        lst = []
    if h in lst:
        lst.remove(h)
        sec.recovery_hashes = json.dumps(lst)
        return True
    return False


def _fn_check_second_factor(sec, code):
    """Valide un code TOTP ou un code de secours (consomme le code). Ne commit pas."""
    secret = _fn_unseal(sec.totp_secret)
    if not secret:
        return False
    step = _fn_totp_check(secret, code, sec.totp_last_step or 0)
    if step:
        sec.totp_last_step = step
        return True
    return _fn_use_recovery(sec, code)


@main_bp.route('/api/fn/2fa/setup', methods=['POST'])
@_fn_api()
def fn_api_2fa_setup():
    uid = _fn_uid()
    sec = _fn_get_security(uid)
    if sec.totp_enabled:
        return _fn_err('La double authentification est déjà active.', 409)
    secret = _fn_b64.b32encode(_fn_secrets.token_bytes(20)).decode().rstrip('=')
    sec.totp_secret = _fn_seal(secret)
    sec.totp_last_step = 0
    db.session.commit()
    user = db.session.get(User, uid)
    from urllib.parse import quote
    label = quote(f"FaceNet:{user.username or user.email or uid}")
    uri = f"otpauth://totp/{label}?secret={secret}&issuer=FaceNet&algorithm=SHA1&digits=6&period=30"
    return _fn_ok(secret=secret, otpauth_uri=uri, qr_svg=_fn_qr_svg(uri))


@main_bp.route('/api/fn/2fa/enable', methods=['POST'])
@_fn_api()
def fn_api_2fa_enable():
    uid = _fn_uid()
    if not _fn_rate_ok(f'2fa-enable:{uid}'):
        return _fn_err('Trop de tentatives. Réessayez dans quelques minutes.', 429)
    sec = _fn_get_security(uid, create=False)
    if not sec or not sec.totp_secret:
        return _fn_err("Lancez d'abord la configuration.", 400)
    if sec.totp_enabled:
        return _fn_err('Déjà active.', 409)
    secret = _fn_unseal(sec.totp_secret)
    step = _fn_totp_check(secret, (request.get_json(silent=True) or {}).get('code'), 0) if secret else None
    if not step:
        return _fn_err('Code invalide. Vérifiez l\'heure de votre téléphone.', 400)
    codes, hashes = _fn_new_recovery_codes()
    sec.totp_enabled = True
    sec.totp_last_step = step
    sec.recovery_hashes = json.dumps(hashes)
    db.session.commit()
    session['fn_2fa_uid'] = uid
    _fn_rate_reset(f'2fa-enable:{uid}')
    _fn_audit(uid, '2fa_activee', 'Double authentification activée')
    return _fn_ok(recovery_codes=codes)


@main_bp.route('/api/fn/2fa/recovery', methods=['POST'])
@_fn_api()
def fn_api_2fa_recovery():
    uid = _fn_uid()
    if not _fn_rate_ok(f'2fa-recovery:{uid}'):
        return _fn_err('Trop de tentatives.', 429)
    sec = _fn_get_security(uid, create=False)
    if not sec or not sec.totp_enabled:
        return _fn_err("La double authentification n'est pas active.", 400)
    if not _fn_check_second_factor(sec, (request.get_json(silent=True) or {}).get('code')):
        db.session.rollback()
        return _fn_err('Code invalide.', 400)
    codes, hashes = _fn_new_recovery_codes()
    sec.recovery_hashes = json.dumps(hashes)
    db.session.commit()
    _fn_audit(uid, '2fa_codes_secours', 'Nouveaux codes de secours générés')
    return _fn_ok(recovery_codes=codes)


@main_bp.route('/api/fn/2fa/disable', methods=['POST'])
@_fn_api()
def fn_api_2fa_disable():
    uid = _fn_uid()
    if not _fn_rate_ok(f'2fa-disable:{uid}'):
        return _fn_err('Trop de tentatives.', 429)
    data = request.get_json(silent=True) or {}
    user = db.session.get(User, uid)
    sec = _fn_get_security(uid, create=False)
    if not sec or not sec.totp_enabled:
        return _fn_err("La double authentification n'est pas active.", 400)
    if not (user.password and data.get('password') and check_password_hash(user.password, data['password'])):
        return _fn_err('Mot de passe incorrect.', 400)
    if not _fn_check_second_factor(sec, data.get('code')):
        db.session.rollback()
        return _fn_err('Code invalide.', 400)
    sec.totp_enabled = False
    sec.totp_secret = None
    sec.recovery_hashes = None
    db.session.commit()
    _fn_rate_reset(f'2fa-disable:{uid}')
    _fn_audit(uid, '2fa_desactivee', 'Double authentification désactivée')
    return _fn_ok()


