def _fn_safe_next(nxt):
    nxt = (nxt or '').strip()
    if nxt.startswith('/') and not nxt.startswith('//') and '\\' not in nxt:
        return nxt
    return '/settings'


@main_bp.route('/fn/2fa/verify', methods=['GET', 'POST'])
def fn_2fa_verify():
    _fn_assurer_tables()
    uid = _fn_uid()
    if not uid:
        return redirect(url_for('main.login'))
    sec = db.session.get(FnSecurity, uid)
    nxt = _fn_safe_next(request.values.get('next'))
    if not sec or not sec.totp_enabled or session.get('fn_2fa_uid') == uid:
        return redirect(nxt)
    erreur = ''
    if request.method == 'POST':
        tok = session.get('fn_csrf', '')
        if not tok or not _fn_hmac.compare_digest(tok, request.form.get('csrf', '')):
            erreur = 'Session expirée, réessayez.'
        elif not _fn_rate_ok(f'2fa-login:{uid}', 5, 300):
            erreur = 'Trop de tentatives. Patientez quelques minutes.'
        elif _fn_check_second_factor(sec, request.form.get('code', '')):
            db.session.commit()
            session['fn_2fa_uid'] = uid
            _fn_rate_reset(f'2fa-login:{uid}')
            _fn_audit(uid, '2fa_connexion', 'Seconde étape validée')
            return redirect(nxt)
        else:
            db.session.rollback()
            erreur = 'Code incorrect.'
            _fn_audit(uid, '2fa_echec', 'Code de seconde étape incorrect')
    return _fn_render_string(_FN_VERIFY_PAGE, erreur=erreur, csrf=_fn_csrf_token(), nxt=nxt)


