@main_bp.route('/api/fn/audit')
@_fn_api()
def fn_api_audit():
    uid = _fn_uid()
    try:
        limit = max(1, min(int(request.args.get('limit', 30)), 100))
        offset = max(0, int(request.args.get('offset', 0)))
    except ValueError:
        return _fn_err('Paramètres invalides.', 400)
    q = FnAuditLog.query.filter_by(user_id=uid)
    kind = request.args.get('kind', 'all')
    if kind == 'login':
        q = q.filter(FnAuditLog.action.in_(('connexion', 'connexion_echouee', '2fa_connexion', '2fa_echec')))
    elif kind == 'security':
        q = q.filter(~FnAuditLog.action.in_(('connexion', 'connexion_echouee')))
    rows = q.order_by(FnAuditLog.created_at.desc(), FnAuditLog.id.desc()).offset(offset).limit(limit + 1).all()
    return _fn_ok(has_more=len(rows) > limit, events=[{
        'id': r.id, 'action': r.action, 'detail': r.detail, 'ip': r.ip,
        'device': _fn_ua_label(r.user_agent), 'at': _fn_iso(r.created_at)} for r in rows[:limit]])


# ──────────────────────────────────────────────────────────────
#  3. PASSKEYS (WebAuthn) — nécessite : pip install webauthn
# ──────────────────────────────────────────────────────────────
def _fn_webauthn_lib():
    try:
        import webauthn
        from webauthn.helpers import base64url_to_bytes, bytes_to_base64url
        from webauthn.helpers.structs import (AuthenticatorSelectionCriteria, PublicKeyCredentialDescriptor,
                                              ResidentKeyRequirement, UserVerificationRequirement)
        return webauthn, base64url_to_bytes, bytes_to_base64url, (
            AuthenticatorSelectionCriteria, PublicKeyCredentialDescriptor,
            ResidentKeyRequirement, UserVerificationRequirement)
    except Exception:
        return None


def _fn_rp():
    host = request.host.split(':')[0]
    return host, request.host_url.rstrip('/')


@main_bp.route('/api/fn/passkeys')
@_fn_api()
def fn_api_passkeys():
    uid = _fn_uid()
    rows = FnPasskey.query.filter_by(user_id=uid).order_by(FnPasskey.created_at.desc()).all()
    return _fn_ok(available=_fn_webauthn_lib() is not None, passkeys=[{
        'id': r.id, 'label': r.label or 'Clé de sécurité', 'created_at': _fn_iso(r.created_at)} for r in rows])


@main_bp.route('/api/fn/passkeys/register/options', methods=['POST'])
@_fn_api()
def fn_api_passkey_options():
    lib = _fn_webauthn_lib()
    if not lib:
        return _fn_err('Module « webauthn » absent sur le serveur (pip install webauthn).', 501)
    webauthn, b64u_to_bytes, bytes_to_b64u, (AuthSel, Desc, ResKey, UV) = lib
    uid = _fn_uid()
    user = db.session.get(User, uid)
    rp_id, _origin = _fn_rp()
    existing = [Desc(id=b64u_to_bytes(p.credential_id)) for p in FnPasskey.query.filter_by(user_id=uid).all()]
    opts = webauthn.generate_registration_options(
        rp_id=rp_id, rp_name='FaceNet', user_id=str(uid).encode(),
        user_name=(user.username or user.email or str(uid)),
        user_display_name=(getattr(user, 'nom_complet', None) or user.username or 'Utilisateur'),
        exclude_credentials=existing,
        authenticator_selection=AuthSel(resident_key=ResKey.PREFERRED, user_verification=UV.PREFERRED))
    session['fn_wa_challenge'] = bytes_to_b64u(opts.challenge)
    return _fn_ok(options=json.loads(webauthn.options_to_json(opts)))


@main_bp.route('/api/fn/passkeys/register/verify', methods=['POST'])
@_fn_api()
def fn_api_passkey_verify():
    lib = _fn_webauthn_lib()
    if not lib:
        return _fn_err('Module « webauthn » absent sur le serveur.', 501)
    webauthn, b64u_to_bytes, bytes_to_b64u, _ = lib
    uid = _fn_uid()
    data = request.get_json(silent=True) or {}
    chal = session.pop('fn_wa_challenge', None)
    if not chal or not isinstance(data.get('credential'), dict):
        return _fn_err('Requête invalide.', 400)
    rp_id, origin = _fn_rp()
    try:
        ver = webauthn.verify_registration_response(
            credential=data['credential'], expected_challenge=b64u_to_bytes(chal),
            expected_rp_id=rp_id, expected_origin=origin)
    except Exception as e:
        print(f"[Passkey] vérification échouée : {e}")
        return _fn_err("L'enregistrement de la clé a été refusé.", 400)
    cid = bytes_to_b64u(ver.credential_id)
    if FnPasskey.query.filter_by(credential_id=cid).first():
        return _fn_err('Cette clé est déjà enregistrée.', 409)
    label = re.sub(r'\s+', ' ', str(data.get('label') or 'Clé de sécurité')).strip()[:80] or 'Clé de sécurité'
    db.session.add(FnPasskey(user_id=uid, credential_id=cid, label=label,
                             public_key=bytes_to_b64u(ver.credential_public_key), sign_count=ver.sign_count))
    db.session.commit()
    _fn_audit(uid, 'passkey_ajoutee', f"Passkey ajoutée : {label}")
    return _fn_ok()


@main_bp.route('/api/fn/passkeys/<int:pid>', methods=['DELETE'])
@_fn_api()
def fn_api_passkey_delete(pid):
    uid = _fn_uid()
    p = FnPasskey.query.filter_by(id=pid, user_id=uid).first()
    if not p:
        return _fn_err('Clé introuvable.', 404)
    label = p.label
    db.session.delete(p)
    db.session.commit()
    _fn_audit(uid, 'passkey_supprimee', f"Passkey supprimée : {label}")
    return _fn_ok()


# ──────────────────────────────────────────────────────────────
#  6. MOTS DE PASSE D'APPLICATION (jetons API)
# ──────────────────────────────────────────────────────────────
def _fn_hash_token(tok):
    return _fn_hashlib.sha256(tok.encode()).hexdigest()


@main_bp.route('/api/fn/app-passwords', methods=['GET', 'POST'])
@_fn_api()
def fn_api_app_passwords():
    uid = _fn_uid()
    if request.method == 'POST':
        data = request.get_json(silent=True) or {}
        label = re.sub(r'\s+', ' ', str(data.get('label') or '')).strip()[:80]
        if len(label) < 2:
            return _fn_err("Donnez un nom à l'outil (2 caractères minimum).", 400)
        if FnAppPassword.query.filter_by(user_id=uid, revoked=False).count() >= 20:
            return _fn_err('Limite de 20 jetons actifs atteinte.', 400)
        tok = 'fnap_' + _fn_secrets.token_urlsafe(32)
        db.session.add(FnAppPassword(user_id=uid, label=label, token_hash=_fn_hash_token(tok),
                                     prefix=tok[:10], single_use=bool(data.get('single_use'))))
        db.session.commit()
        _fn_audit(uid, 'jeton_cree', f"Mot de passe d'application créé : {label}")
        return _fn_ok(token=tok)          # affiché UNE seule fois
    rows = FnAppPassword.query.filter_by(user_id=uid, revoked=False).order_by(FnAppPassword.created_at.desc()).all()
    return _fn_ok(tokens=[{
        'id': r.id, 'label': r.label, 'prefix': r.prefix, 'single_use': r.single_use,
        'created_at': _fn_iso(r.created_at), 'last_used_at': _fn_iso(r.last_used_at)} for r in rows])


@main_bp.route('/api/fn/app-passwords/<int:tid>', methods=['DELETE'])
@_fn_api()
def fn_api_app_password_delete(tid):
    uid = _fn_uid()
    r = FnAppPassword.query.filter_by(id=tid, user_id=uid, revoked=False).first()
    if not r:
        return _fn_err('Jeton introuvable.', 404)
    r.revoked = True
    db.session.commit()
    _fn_audit(uid, 'jeton_revoque', f"Mot de passe d'application révoqué : {r.label}")
    return _fn_ok()


def fn_user_depuis_app_password(token):
    """Utilitaire pour vos futures routes API : retourne le User du jeton Bearer, ou None.
    Les jetons « usage unique » sont révoqués dès leur premier emploi réussi."""
    if not token or not token.startswith('fnap_') or len(token) > 80:
        return None
    r = FnAppPassword.query.filter_by(token_hash=_fn_hash_token(token), revoked=False).first()
    if not r:
        return None
    r.last_used_at = datetime.utcnow()
    if r.single_use:
        r.revoked = True
    db.session.commit()
    return db.session.get(User, r.user_id)


@main_bp.route('/api/fn/app/whoami')
def fn_api_app_whoami():
    """Exemple d'usage par un outil tiers : Authorization: Bearer fnap_..."""
    _fn_assurer_tables()
    if not _fn_rate_ok(f'app-token:{_fn_ip()}', 30, 60):
        return _fn_err('Trop de requêtes.', 429)
    auth = request.headers.get('Authorization', '')
    user = fn_user_depuis_app_password(auth[7:].strip() if auth.lower().startswith('bearer ') else '')
    if not user:
        return _fn_err('Jeton invalide.', 401)
    return _fn_ok(user_id=user.id, username=user.username)


# ──────────────────────────────────────────────────────────────
#  8. E2EE — seule la clé PUBLIQUE est envoyée au serveur
# ──────────────────────────────────────────────────────────────
_FN_B64U_RE = re.compile(r'^[A-Za-z0-9_-]{40,100}$')


@main_bp.route('/api/fn/e2ee/public-key', methods=['GET', 'POST', 'DELETE'])
@_fn_api()
def fn_api_e2ee_own():
    uid = _fn_uid()
    sec = _fn_get_security(uid)
    if request.method == 'POST':
        jwk = (request.get_json(silent=True) or {}).get('public_jwk')
        if not (isinstance(jwk, dict) and jwk.get('kty') == 'EC' and jwk.get('crv') == 'P-256'
                and _FN_B64U_RE.match(str(jwk.get('x', ''))) and _FN_B64U_RE.match(str(jwk.get('y', '')))
                and 'd' not in jwk):
            return _fn_err('Clé publique invalide (P-256 attendue, sans partie privée).', 400)
        canon = json.dumps({'crv': 'P-256', 'kty': 'EC', 'x': jwk['x'], 'y': jwk['y']}, sort_keys=True,
                           separators=(',', ':'))
        sec.e2ee_public_key = canon
        sec.e2ee_fingerprint = _fn_hashlib.sha256(canon.encode()).hexdigest()
        db.session.commit()
        _fn_audit(uid, 'e2ee_cle_publiee', f"Clé publique E2EE publiée ({sec.e2ee_fingerprint[:12]})")
    elif request.method == 'DELETE':
        sec.e2ee_public_key = None
        sec.e2ee_fingerprint = None
        db.session.commit()
        _fn_audit(uid, 'e2ee_cle_retiree', 'Clé publique E2EE retirée')
    return _fn_ok(public_jwk=json.loads(sec.e2ee_public_key) if sec.e2ee_public_key else None,
                  fingerprint=sec.e2ee_fingerprint)


@main_bp.route('/api/fn/e2ee/public-key/<int:other_id>')
@_fn_api()
def fn_api_e2ee_other(other_id):
    sec = db.session.get(FnSecurity, other_id)
    if not sec or not sec.e2ee_public_key:
        return _fn_err("Cet utilisateur n'a pas publié de clé.", 404)
    return _fn_ok(public_jwk=json.loads(sec.e2ee_public_key), fingerprint=sec.e2ee_fingerprint)


# ──────────────────────────────────────────────────────────────
#  14. SAUVEGARDE : le serveur fournit les données, le CHIFFREMENT se fait
#      dans le navigateur (PBKDF2 + AES-GCM) avant l'enregistrement du fichier.
# ──────────────────────────────────────────────────────────────
@main_bp.route('/api/fn/backup/export')
@_fn_api()
def fn_api_backup_export():
    uid = _fn_uid()
    user = db.session.get(User, uid)
    pubs = Publication.query.filter_by(user_id=uid).filter(_clause_sans_enfants()).order_by(Publication.date_creation.desc()).limit(2000).all()
    msgs = (Message.query.filter(_fn_or(Message.expediteur_id == uid, Message.destinataire_id == uid))
            .order_by(Message.date_envoi.desc()).limit(5000).all())
    audits = FnAuditLog.query.filter_by(user_id=uid).order_by(FnAuditLog.created_at.desc()).limit(500).all()
    data = {
        'format': 'facenet-backup', 'version': 1, 'exported_at': datetime.utcnow().isoformat() + 'Z',
        'profil': {k: getattr(user, k, None) for k in ('id', 'username', 'nom_complet', 'email', 'phone')},
        'preferences': _fn_load_prefs(uid),
        'publications': [{'contenu': p.contenu, 'confidentialite': p.confidentialite,
                          'date_creation': p.date_creation.isoformat() if p.date_creation else None} for p in pubs],
        'messages': [{'de': m.expediteur_id, 'a': m.destinataire_id, 'contenu': m.contenu,
                      'date': m.date_envoi.isoformat() if m.date_envoi else None} for m in msgs],
        'audit': [{'action': a.action, 'detail': a.detail, 'date': _fn_iso(a.created_at)} for a in audits],
    }
    _fn_audit(uid, 'sauvegarde_exportee', 'Export de sauvegarde généré')
    resp = jsonify(success=True, data=data)
    resp.headers['Cache-Control'] = 'no-store'
    return resp


@main_bp.route('/api/fn/backup/import', methods=['POST'])
@_fn_api()
def fn_api_backup_import():
    uid = _fn_uid()
    if (request.content_length or 0) > 8 * 1024 * 1024:
        return _fn_err('Fichier trop volumineux (8 Mo max).', 413)
    data = (request.get_json(silent=True) or {}).get('data')
    if not isinstance(data, dict) or data.get('format') != 'facenet-backup':
        return _fn_err('Fichier de sauvegarde invalide.', 400)
    report = {'preferences': 0, 'publications': 0, 'ignorees': 0, 'messages_non_importes': 0}
    if isinstance(data.get('preferences'), dict):
        _merged, clean = _fn_store_prefs(uid, data['preferences'])
        report['preferences'] = len(clean)
    existing = {(p.contenu or '', p.date_creation.isoformat() if p.date_creation else '')
                for p in Publication.query.filter_by(user_id=uid).limit(5000).all()}
    for p in (data.get('publications') or [])[:500]:
        if not isinstance(p, dict) or not isinstance(p.get('contenu'), str) or not p['contenu'].strip():
            report['ignorees'] += 1
            continue
        key = (p['contenu'], p.get('date_creation') or '')
        if key in existing:
            report['ignorees'] += 1
            continue
        niveau = p.get('confidentialite') if p.get('confidentialite') in NIVEAUX_CONFIDENTIALITE else 'prive'
        try:
            db.session.add(Publication(user_id=uid, contenu=p['contenu'][:5000], confidentialite=niveau))
            existing.add(key)
            report['publications'] += 1
        except Exception:
            report['ignorees'] += 1
    # Les messages ne sont volontairement jamais réimportés : on ne peut pas
    # authentifier ceux écrits par d'autres personnes.
    report['messages_non_importes'] = len(data.get('messages') or [])
    db.session.commit()
    _fn_audit(uid, 'sauvegarde_importee', f"{report['publications']} publication(s) et {report['preferences']} réglage(s) restaurés")
    return _fn_ok(report=report)


# ──────────────────────────────────────────────────────────────
#  19. CONTRÔLE PARENTAL — second mot de passe (vérifié côté serveur)
# ──────────────────────────────────────────────────────────────
def _fn_parental_check(uid, password):
    sec = db.session.get(FnSecurity, uid)
    return bool(sec and sec.parental_enabled and sec.parental_hash and password
                and check_password_hash(sec.parental_hash, password))


@main_bp.route('/api/fn/parental', methods=['GET', 'POST'])
@_fn_api()
def fn_api_parental():
    uid = _fn_uid()
    if request.method == 'GET':
        sec = db.session.get(FnSecurity, uid)
        return _fn_ok(enabled=bool(sec and sec.parental_enabled), level=(sec.parental_level if sec else 'standard'))
    data = request.get_json(silent=True) or {}
    action = data.get('action')
    user = db.session.get(User, uid)
    sec = _fn_get_security(uid)
    if action == 'enable':
        pwd = str(data.get('password') or '')
        if sec.parental_enabled:
            return _fn_err('Le contrôle parental est déjà actif.', 409)
        if len(pwd) < 6:
            return _fn_err('Le mot de passe parental doit contenir au moins 6 caractères.', 400)
        if user.password and check_password_hash(user.password, pwd):
            return _fn_err('Choisissez un mot de passe différent de celui du compte.', 400)
        sec.parental_hash = generate_password_hash(pwd)
        sec.parental_enabled = True
        sec.parental_level = data.get('level') if data.get('level') in ('standard', 'strict') else 'standard'
        db.session.commit()
        _fn_audit(uid, 'parental_active', 'Contrôle parental activé')
        return _fn_ok(enabled=True, level=sec.parental_level)
    if action in ('verify', 'update', 'disable'):
        if not _fn_rate_ok(f'parental:{uid}', 5, 300):
            return _fn_err('Trop de tentatives. Patientez quelques minutes.', 429)
        if not _fn_parental_check(uid, str(data.get('password') or '')):
            _fn_audit(uid, 'parental_echec', 'Mot de passe parental incorrect')
            return _fn_err('Mot de passe parental incorrect.', 400)
        _fn_rate_reset(f'parental:{uid}')
        if action == 'update':
            if data.get('level') in ('standard', 'strict'):
                sec.parental_level = data['level']
            db.session.commit()
            _fn_audit(uid, 'parental_modifie', f"Niveau : {sec.parental_level}")
        elif action == 'disable':
            sec.parental_enabled = False
            sec.parental_hash = None
            try:   # AJOUT : désactiver le contrôle parental lève aussi le verrouillage programmé
                _pl_l = _pl_ligne(uid)
                if _pl_l is not None:
                    db.session.delete(_pl_l)
            except Exception:
                pass
            db.session.commit()
            _fn_audit(uid, 'parental_desactive', 'Contrôle parental désactivé')
        return _fn_ok(enabled=bool(sec.parental_enabled), level=sec.parental_level)
    return _fn_err('Action inconnue.', 400)


# ──────────────────────────────────────────────────────────────
#  18. MODE DÉVELOPPEUR — console serveur (ADMIN uniquement, vérifié ici)
# ──────────────────────────────────────────────────────────────
_FN_LOG_BUFFER = _fn_deque(maxlen=500)
_FN_REQ_BUFFER = _fn_deque(maxlen=300)


class _FnBufferHandler(_fn_logging.Handler):
    def emit(self, record):
        try:
            _FN_LOG_BUFFER.append({'t': datetime.utcfromtimestamp(record.created).isoformat() + 'Z',
                                   'level': record.levelname, 'logger': record.name,
                                   'msg': self.format(record)[:600]})
        except Exception:
            pass


if not any(isinstance(h, _FnBufferHandler) for h in _fn_logging.getLogger().handlers):
    _fn_h = _FnBufferHandler()
    _fn_h.setFormatter(_fn_logging.Formatter('%(message)s'))
    _fn_logging.getLogger().addHandler(_fn_h)
    if _fn_logging.getLogger().level in (0, _fn_logging.WARNING):
        _fn_logging.getLogger().setLevel(_fn_logging.INFO)


