# ======================================================================
# MOT DE PASSE OUBLIÉ - parcours par étapes (AJOUT, rien d'existant modifié)
# Étape 1 : /mot-de-passe-oublie        -> saisie de l'e-mail, envoi du code
# Étape 2 : /mot-de-passe-oublie/code   -> code + nouveau mot de passe
# ======================================================================
_MDP_MAX_ESSAIS = 5

def _mdp_envoyer_code(user):
    """Génère un code à 6 chiffres valable 10 min et l'envoie par e-mail."""
    import secrets as _mdp_secrets
    code = ''.join(_mdp_secrets.choice(string.digits) for _ in range(6))
    user.reset_code = code
    user.reset_code_expires = datetime.utcnow() + timedelta(minutes=10)
    db.session.commit()
    print("\n" + "=" * 40)
    print(f" 🔑 CODE MOT DE PASSE OUBLIÉ POUR @{user.username} : {code}")
    print("=" * 40 + "\n")
    try:
        from email_otp import envoyer_code_email, mail_est_configure
        if mail_est_configure() and user.email:
            envoyer_code_email(user.email, code,
                               "Votre code de réinitialisation FaceNet",
                               "Voici votre code pour choisir un nouveau mot de passe.")
    except Exception as e:
        print(f"[Mot de passe oublié] envoi e-mail impossible : {e}")

@main_bp.route('/mot-de-passe-oublie', methods=['GET', 'POST'])
def mdp_oublie_demande():
    if request.method == 'POST':
        email = (request.form.get('email') or '').strip()
        if not email:
            flash("Veuillez entrer votre adresse e-mail.", "error")
            return render_template('reset_password_request.html')
        user = User.query.filter(db.func.lower(User.email) == email.lower()).first()
        if user:
            _mdp_envoyer_code(user)
        # Même réponse que le compte existe ou non (on ne révèle rien)
        session['mdp_email'] = email
        session['mdp_essais'] = 0
        flash("Si un compte existe pour cette adresse, un code vient d'être envoyé.", "info")
        return redirect(url_for('main.mdp_oublie_confirmer'))
    return render_template('reset_password_request.html')

@main_bp.route('/mot-de-passe-oublie/code', methods=['GET', 'POST'])
def mdp_oublie_confirmer():
    email = session.get('mdp_email')
    if not email:
        return redirect(url_for('main.mdp_oublie_demande'))
    if request.method == 'POST':
        code = (request.form.get('code') or '').strip()
        mot_de_passe = request.form.get('password') or ''
        confirmation = request.form.get('confirm_password') or ''
        if session.get('mdp_essais', 0) >= _MDP_MAX_ESSAIS:
            flash("Trop de tentatives. Demandez un nouveau code.", "error")
            return render_template('reset_password_confirm.html', email=email)
        if len(mot_de_passe) < 8:
            flash("Le mot de passe doit contenir au moins 8 caractères.", "error")
            return render_template('reset_password_confirm.html', email=email)
        if mot_de_passe != confirmation:
            flash("Les deux mots de passe ne correspondent pas.", "error")
            return render_template('reset_password_confirm.html', email=email)
        user = User.query.filter(db.func.lower(User.email) == email.lower()).first()
        valide = bool(user and user.reset_code and code == str(user.reset_code)
                      and user.reset_code_expires and datetime.utcnow() < user.reset_code_expires)
        if not valide:
            session['mdp_essais'] = session.get('mdp_essais', 0) + 1
            flash("Code invalide ou expiré.", "error")
            return render_template('reset_password_confirm.html', email=email)
        user.password = generate_password_hash(mot_de_passe)
        user.reset_code = None
        user.reset_code_expires = None
        notifier(user.id, 'securite_mot_de_passe')
        db.session.commit()
        session.pop('mdp_email', None)
        session.pop('mdp_essais', None)
        flash("Mot de passe mis à jour. Vous pouvez vous connecter.", "success")
        return redirect(url_for('main.login'))
    return render_template('reset_password_confirm.html', email=email)

@main_bp.route('/mot-de-passe-oublie/renvoyer', methods=['POST'])
def mdp_oublie_renvoyer():
    email = session.get('mdp_email')
    if not email:
        return redirect(url_for('main.mdp_oublie_demande'))
    user = User.query.filter(db.func.lower(User.email) == email.lower()).first()
    if user:
        _mdp_envoyer_code(user)
    session['mdp_essais'] = 0
    flash("Un nouveau code a été envoyé.", "info")
    return redirect(url_for('main.mdp_oublie_confirmer'))

