# COMMENTAIRES VOCAUX — bloc ADDITIF pour routes.py
#
# OÙ LE COLLER : dans routes.py, juste APRÈS la route `api_reagir_commentaire`
# (et donc après la définition de `_serialiser_commentaires`), AVANT
# `@main_bp.route('/api/amis' ...)`.
#
# Aucune route, aucune fonction et aucune table existante n'est modifiée :
#  - nouvelle table `commentaire_vocal` (créée toute seule, comme CommentaireReaction)
#  - nouvelle route POST /api/comment/<pub_id>/vocal
#  - `_serialiser_commentaires` est « enveloppée » pour ajouter audio_url / audio_duree
#    (les anciens champs ne changent pas)
# Utilisé par templates/_comments_sheet.html (feed.html + reel.html).
# ══════════════════════════════════════════════════════════════════════════
 
UPLOAD_COMMENT_VOCAL_FOLDER = os.path.join('static', 'uploads', 'comment_vocals')
os.makedirs(UPLOAD_COMMENT_VOCAL_FOLDER, exist_ok=True)

_CV_MAX_OCTETS = 6 * 1024 * 1024      # taille maximale du fichier reçu
_CV_MAX_SECONDES = 180                # identique à V_MAX dans _comments_sheet.html
_CV_MIN_SECONDES = 1                  # identique à V_MIN
_CV_MAX_PAR_MINUTE = 6                # anti-spam : vocaux / minute / utilisateur
_CV_TEXTE = '🎤 Message vocal'        # texte stocké dans Commentaire.contenu (aperçus, notifications…)
_CV_TABLE_OK = False


class CommentaireVocal(db.Model):
    __tablename__ = 'commentaire_vocal'
    id = db.Column(db.Integer, primary_key=True)
    commentaire_id = db.Column(db.Integer, db.ForeignKey('commentaire.id', ondelete='CASCADE'),
                               nullable=False, unique=True, index=True)
    user_id = db.Column(db.Integer, nullable=False, index=True)
    fichier = db.Column(db.String(255), nullable=False)
    duree = db.Column(db.Float, nullable=False, default=0)
    date_creation = db.Column(db.DateTime, default=datetime.utcnow, index=True)


@main_bp.before_app_request
def _ensure_vocal_schema():
    """Crée une seule fois la table commentaire_vocal (sans effet si elle existe)."""
    global _CV_TABLE_OK
    if _CV_TABLE_OK:
        return
    try:
        CommentaireVocal.__table__.create(bind=db.engine, checkfirst=True)
        _CV_TABLE_OK = True
    except Exception as e:
        print(f"DEBUG: table commentaire_vocal non créée : {e}")


@_cv_event.listens_for(Commentaire, 'after_delete')
def _cv_nettoyer_vocal(mapper, connection, cible):
    """Quand un commentaire est supprimé (par n'importe quelle route), on supprime aussi
    sa ligne vocale et son fichier audio."""
    if not _CV_TABLE_OK:
        return
    try:
        ligne = connection.execute(
            db.text('SELECT fichier FROM commentaire_vocal WHERE commentaire_id = :i'), {'i': cible.id}).first()
        if ligne:
            connection.execute(db.text('DELETE FROM commentaire_vocal WHERE commentaire_id = :i'), {'i': cible.id})
            chemin = os.path.join(UPLOAD_COMMENT_VOCAL_FOLDER, os.path.basename(ligne[0]))
            if os.path.isfile(chemin):
                os.remove(chemin)
    except Exception as e:
        print(f"DEBUG: nettoyage vocal commentaire : {e}")


def _cv_url(nom):
    return url_for('static', filename='uploads/comment_vocals/' + nom)


def _cv_joindre(liste):
    """Ajoute audio_url / audio_duree aux commentaires sérialisés qui sont des vocaux."""
    if not liste or not _CV_TABLE_OK:
        return liste
    ids = [c['id'] for c in liste]
    vocaux = {v.commentaire_id: v for v in CommentaireVocal.query.filter(CommentaireVocal.commentaire_id.in_(ids)).all()}
    for c in liste:
        v = vocaux.get(c['id'])
        c['audio_url'] = _cv_url(v.fichier) if v else None
        c['audio_duree'] = round(v.duree or 0, 1) if v else None
    return liste


# On enveloppe la fonction existante : les routes de liste / réponses l'appellent par son nom,
# elles renvoient donc désormais aussi les vocaux, sans qu'on touche à leur code.
_serialiser_commentaires_sans_vocal = _serialiser_commentaires


def _serialiser_commentaires(commentaires, pub):
    liste = _serialiser_commentaires_sans_vocal(commentaires, pub)
    try:
        _cv_joindre(liste)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: vocaux non joints : {e}")
    return liste


def _cv_format_reel(tete):
    """Détecte le vrai format d'après les premiers octets (le nom / le type MIME envoyés
    par le navigateur ne sont pas fiables). Retourne 'webm', 'ogg', 'm4a', 'wav', 'mp3' ou None."""
    if tete[:4] == b'\x1a\x45\xdf\xa3':
        return 'webm'
    if tete[:4] == b'OggS':
        return 'ogg'
    if tete[4:8] == b'ftyp':
        return 'm4a'
    if tete[:4] == b'RIFF' and tete[8:12] == b'WAVE':
        return 'wav'
    if tete[:3] == b'ID3' or (len(tete) > 1 and tete[0] == 0xFF and (tete[1] & 0xE0) == 0xE0):
        return 'mp3'
    return None


def _cv_duree_ffprobe(chemin):
    ffprobe = shutil.which('ffprobe')
    if not ffprobe:
        return None
    try:
        out = subprocess.run([ffprobe, '-v', 'error', '-show_entries', 'format=duration',
                              '-of', 'default=nw=1:nk=1', chemin],
                             capture_output=True, timeout=15, check=True).stdout.decode().strip()
        return float(out)
    except Exception:
        return None


def _cv_nettoyer_audio(data, fmt):
    """Passe le vocal dans ffmpeg : mono, AAC 64 kbit/s (lisible partout, iPhone compris),
    métadonnées supprimées, durée plafonnée, voix nettoyée (filtre des basses parasites,
    réduction de bruit, volume normalisé). Retourne (octets, durée) ou (None, None)
    si ffmpeg est absent ou si le fichier n'a pas de piste audio valide."""
    ffmpeg = shutil.which('ffmpeg')
    if not ffmpeg:
        return None, None
    entree = sortie = None
    try:
        with _cv_tempfile.NamedTemporaryFile(suffix='.' + fmt, delete=False) as f:
            f.write(data)
            entree = f.name
        sortie = entree + '.m4a'
        base = [ffmpeg, '-y', '-loglevel', 'error', '-i', entree, '-vn', '-map_metadata', '-1',
                '-t', str(_CV_MAX_SECONDES), '-ac', '1', '-ar', '44100']
        fin = ['-c:a', 'aac', '-b:a', '64k', '-movflags', '+faststart', sortie]
        # 1) voix nettoyée ; 2) filtres plus simples si le build ffmpeg n'a pas tout ; 3) conversion nue
        for filtre in ('highpass=f=80,afftdn=nf=-30,loudnorm=I=-16:TP=-1.5:LRA=11',
                       'highpass=f=80,dynaudnorm', None):
            try:
                if os.path.exists(sortie):
                    os.remove(sortie)
                subprocess.run(base + (['-af', filtre] if filtre else []) + fin,
                               check=True, timeout=45, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception:
                continue
            if os.path.exists(sortie) and os.path.getsize(sortie) > 1024:
                with open(sortie, 'rb') as f:
                    return f.read(), _cv_duree_ffprobe(sortie)
        return None, None
    except Exception as e:
        print(f"DEBUG: nettoyage vocal commentaire impossible : {e}")
        return None, None
    finally:
        for c in (entree, sortie):
            try:
                if c and os.path.exists(c):
                    os.remove(c)
            except OSError:
                pass


@main_bp.route('/api/comment/<int:pub_id>/vocal', methods=['POST'])
@login_required
def api_add_comment_vocal(pub_id):
    pub = Publication.query.get_or_404(pub_id)
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    ok, msg = _peut_commenter_pub(pub)               # mêmes règles que le commentaire texte
    if not ok:
        return jsonify(success=False, error=msg), 403

    # — anti-spam : quelques vocaux par minute et par utilisateur —
    try:
        recents = CommentaireVocal.query.filter(
            CommentaireVocal.user_id == current_user.id,
            CommentaireVocal.date_creation >= datetime.utcnow() - timedelta(seconds=60)).count()
        if recents >= _CV_MAX_PAR_MINUTE:
            return jsonify(success=False, error='Vous envoyez trop de vocaux. Patientez un instant.'), 429
    except Exception:
        db.session.rollback()

    # — réception et filtrage du fichier —
    if request.content_length and request.content_length > _CV_MAX_OCTETS + 200 * 1024:
        return jsonify(success=False, error='Vocal trop volumineux.'), 413
    fichier = request.files.get('audio')
    if not fichier:
        return jsonify(success=False, error='Aucun enregistrement reçu.'), 400
    data = fichier.read(_CV_MAX_OCTETS + 1)
    if len(data) > _CV_MAX_OCTETS:
        return jsonify(success=False, error='Vocal trop volumineux.'), 413
    if len(data) < 800:
        return jsonify(success=False, error='Enregistrement vide ou trop court.'), 400
    fmt = _cv_format_reel(data[:16])
    if not fmt:
        return jsonify(success=False, error="Format audio non reconnu."), 400
    if fmt == 'm4a' and not (fichier.mimetype or '').startswith(('audio/', 'video/mp4', 'application/octet-stream')):
        return jsonify(success=False, error="Format audio non reconnu."), 400

    try:
        duree_client = float(request.form.get('duree', 0))
    except (TypeError, ValueError):
        duree_client = 0.0

    propre, duree_reelle = _cv_nettoyer_audio(data, fmt)
    if propre is not None:
        data, fmt = propre, 'm4a'
        duree = duree_reelle if duree_reelle else duree_client
    else:
        # ffmpeg absent / échec : on garde l'original, mais seulement s'il est bien de l'audio déclaré
        if shutil.which('ffmpeg') and fmt == 'm4a':
            return jsonify(success=False, error="Ce fichier ne contient pas d'audio valide."), 400
        if not (fichier.mimetype or '').startswith('audio/') and fmt != 'm4a':
            return jsonify(success=False, error="Ce fichier n'est pas un enregistrement audio."), 400
        duree = duree_client
    duree = max(0.0, min(float(duree or 0), float(_CV_MAX_SECONDES)))
    if duree < _CV_MIN_SECONDES:
        return jsonify(success=False, error='Vocal trop court.'), 400

    # — réponse à un commentaire (facultatif), comme pour le texte —
    racine_id = cible_id = cible_user_id = None
    cible_nom = None
    parent_brut = request.form.get('parent_id')
    if parent_brut not in (None, '', '0'):
        try:
            cible = Commentaire.query.get(int(parent_brut))
        except (TypeError, ValueError):
            cible = None
        if not cible or cible.publication_id != pub_id:
            return jsonify(success=False, error='Le commentaire auquel vous répondez est introuvable.'), 404
        racine_id = cible.parent_id or cible.id
        cible_id, cible_user_id = cible.id, cible.user_id
        cible_u = User.query.get(cible.user_id)
        cible_nom = cible_u.nom_complet if cible_u else None

    # — enregistrement —
    nom = f"{uuid.uuid4().hex}.{fmt}"
    chemin = os.path.join(UPLOAD_COMMENT_VOCAL_FOLDER, nom)
    try:
        with open(chemin, 'wb') as f:
            f.write(data)
        commentaire = Commentaire(contenu=_CV_TEXTE, user_id=current_user.id, publication_id=pub_id,
                                  parent_id=racine_id, reply_to_id=cible_id, reply_to_user_id=cible_user_id)
        db.session.add(commentaire)
        db.session.flush()
        db.session.add(CommentaireVocal(commentaire_id=commentaire.id, user_id=current_user.id,
                                        fichier=nom, duree=duree))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        try:
            if os.path.exists(chemin):
                os.remove(chemin)
        except OSError:
            pass
        print(f"DEBUG: commentaire vocal non enregistré : {e}")
        return jsonify(success=False, error="Impossible d'enregistrer le vocal."), 500

    try:
        _deja_notifies = set()
        if cible_user_id and cible_user_id != current_user.id:
            if notifier(cible_user_id, 'reply', current_user, cible=('comment', cible_id), pub_id=pub_id, comment_id=commentaire.id):
                _deja_notifies.add(cible_user_id)
        if pub.user_id not in _deja_notifies:
            notifier(pub.user_id, 'comment', current_user, cible=('post', pub_id), pub_id=pub_id, comment_id=commentaire.id)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG notification commentaire vocal : {e}")

    total = Commentaire.query.filter_by(publication_id=pub_id).count()
    return jsonify(success=True, id=commentaire.id, author=current_user.nom_complet,
                   avatar=current_user.avatar or 'default_avatar.png',
                   contenu=_CV_TEXTE, comments_count=total,
                   author_username=getattr(current_user, 'username', None),
                   date=_iso_utc(commentaire.date_creation),
                   parent_id=racine_id, reply_to_id=cible_id,
                   reply_to_name=cible_nom, parent_author=cible_nom,
                   audio_url=_cv_url(nom), audio_duree=round(duree, 1))



 
@main_bp.route('/api/notifications/<int:notif_id>/supprimer', methods=['POST'])
@login_required
def api_notification_supprimer(notif_id):
    notif = Notification.query.get(notif_id)                    # (*) ton modèle
    # Sécurité : on ne peut supprimer que SES propres notifications
    if notif is None or notif.user_id != current_user.id:       # (*) champ du destinataire (user_id / recipient_id…)
        return jsonify(success=False, error="Notification introuvable."), 404
    try:
        db.session.delete(notif)                                # (*) ton objet db
        db.session.commit()
    except Exception:
        db.session.rollback()
        return jsonify(success=False, error="Suppression impossible pour le moment."), 500
    return jsonify(success=True)

