#  AJOUT ADDITIF — REPUBLIER UN REEL
#  reel.html appelle 3 routes qui n'existaient pas (→ 404, donc « Republication
#  impossible ») :
#    • GET  /api/reels/republications/etat?ids=1,2,3
#    • POST /api/reel/<id>/republier          { commentaire }
#    • POST /api/reel/<id>/republier/annuler
#  La table est créée automatiquement au premier appel : aucune migration,
#  aucune table existante modifiée (models.py n'est pas touché).
# ══════════════════════════════════════════════════════════════════
class ReelRepublication(db.Model):
    __tablename__ = 'reel_republication'
    id = db.Column(db.Integer, primary_key=True)
    publication_id = db.Column(db.Integer, nullable=False, index=True)
    user_id = db.Column(db.Integer, nullable=False, index=True)
    commentaire = db.Column(db.Text, nullable=True)   # AJOUT : mot facultatif, sans limite pratique (était 300 caractères)
    date_creation = db.Column(db.DateTime, default=datetime.utcnow)
    __table_args__ = (db.UniqueConstraint('publication_id', 'user_id', name='uq_reel_republication'),)

_NOTE_REPUBLICATION_MAX = 20000   # simple garde-fou technique contre un envoi abusif


_table_republication_ok = False
def _assurer_table_republication():
    global _table_republication_ok
    if _table_republication_ok:
        return
    try:
        ReelRepublication.__table__.create(bind=db.engine, checkfirst=True)
        # AJOUT : une table créée avant cette version a une colonne limitée à 300 caractères → on l'agrandit (SQLite ne limite pas)
        try:
            dialecte = db.engine.dialect.name
            with db.engine.begin() as conn:
                if dialecte == 'postgresql':
                    conn.execute(db.text('ALTER TABLE reel_republication ALTER COLUMN commentaire TYPE TEXT'))
                elif dialecte in ('mysql', 'mariadb'):
                    conn.execute(db.text('ALTER TABLE reel_republication MODIFY commentaire TEXT NULL'))
        except Exception as e:
            print(f"DEBUG: agrandissement du champ du mot de republication impossible (sans gravité) : {e}")
        _table_republication_ok = True
    except Exception as e:
        print(f"DEBUG: création de la table des republications impossible : {e}")


