# ──────────────────────────────────────────────────────────────────────
# Voix ElevenLabs pour « Prononciation du nom » (mp3 mis en cache sur disque).
# Réutilise `client_eleven` déjà défini plus haut dans routes.py.
# ──────────────────────────────────────────────────────────────────────
import hashlib as _pn_hashlib
from flask import send_file as _pn_send_file

_VOIX_NOMS_ID = "21m00Tcm4TlvDq8ikWAM"   # Rachel — remplace par une autre voix ElevenLabs si tu préfères

def _dossier_voix_noms():
    d = os.path.join('static', 'audio', 'noms')
    os.makedirs(d, exist_ok=True)
    return d


def _generer_voix_nom(texte, chemin):
    """Génère un mp3 ElevenLabs lent et clair pour un nom. True si réussi."""
    try:
        try:
            audio = client_eleven.text_to_speech.convert(
                voice_id=_VOIX_NOMS_ID,
                text=texte,
                model_id="eleven_multilingual_v2",
                output_format="mp3_44100_128",
                voice_settings={"stability": 0.75, "similarity_boost": 0.8, "style": 0.0, "speed": 0.85},
            )
        except TypeError:
            # SDK sans l'option voice_settings : appel simple
            audio = client_eleven.text_to_speech.convert(
                voice_id=_VOIX_NOMS_ID, text=texte,
                model_id="eleven_multilingual_v2", output_format="mp3_44100_128")
        with open(chemin, 'wb') as f:
            if isinstance(audio, (bytes, bytearray)):
                f.write(audio)
            else:
                for chunk in audio:
                    if chunk:
                        f.write(chunk)
        if os.path.getsize(chemin) == 0:
            os.remove(chemin)
            return False
        return True
    except Exception as e:
        print(f"DEBUG: voix ElevenLabs (prononciation) impossible : {e}")
        try:
            if os.path.exists(chemin):
                os.remove(chemin)
        except OSError:
            pass
        return False


@main_bp.route('/api/prononciation-audio')
@login_required
def api_prononciation_audio():
    """?user_id=<id> : lit la prononciation enregistrée (sinon le nom complet).
       ?texte=<...>  : aperçu d'un texte saisi (150 caractères max)."""
    texte = re.sub(r'\s+', ' ', (request.args.get('texte') or '')).strip()
    if not texte:
        uid = request.args.get('user_id', type=int)
        cible = db.session.get(User, uid) if uid else None
        if cible is None:
            return jsonify(success=False, error="Profil introuvable."), 404
        _assurer_tables_transparence()
        try:
            t = db.session.get(ProfilTransparence, cible.id)
        except Exception:
            db.session.rollback()
            t = None
        texte = ((t.prononciation if t else '') or cible.nom_complet or cible.username or '').strip()
    if not texte:
        return jsonify(success=False, error="Aucun nom à prononcer."), 400
    if len(texte) > 150:
        return jsonify(success=False, error="150 caractères au maximum."), 400
    cle = _pn_hashlib.sha1(texte.lower().encode('utf-8')).hexdigest()[:24]
    chemin = os.path.join(_dossier_voix_noms(), f"{cle}.mp3")
    if not os.path.exists(chemin):
        if not _generer_voix_nom(texte, chemin):
            return jsonify(success=False, error="La voix n'est pas disponible pour le moment."), 503
    rep = _pn_send_file(os.path.abspath(chemin), mimetype='audio/mpeg')
    rep.headers['Cache-Control'] = 'private, max-age=86400'
    return rep

# ══════════════════════════════════════════════════════════════════════
# AJOUT ADDITIF : Tsapi AI x ElevenLabs
# (voix, effets sonores, doublage, liste des voix)
# Aucune ligne existante n'est modifiée.
# ══════════════════════════════════════════════════════════════════════
import base64 as _el_b64
from flask import Response as _ElResponse

_EL_BASE = "https://api.elevenlabs.io/v1"
_EL_VOIX_DEFAUT = os.environ.get("ELEVENLABS_DEFAULT_VOICE_ID", "21m00Tcm4TlvDq8ikWAM")
_EL_MODELE_TTS = "eleven_multilingual_v2"
_EL_MODELE_STS = "eleven_multilingual_sts_v2"
_EL_FORMAT_SORTIE = "mp3_44100_128"
_EL_MAX_UPLOAD = 50 * 1024 * 1024
_EL_DOSSIER_AUDIO = os.path.join('static', 'audio', 'tsapi_ai')
_EL_ID_VOIX_RE = re.compile(r'^[A-Za-z0-9]{10,40}$')


class _ElErreur(Exception):
    def __init__(self, message, statut=502):
        super().__init__(message)
        self.statut = statut


def _el_entetes():
    """Clé : variable ELEVENLABS_API_KEY, sinon la clé déjà utilisée par client_eleven."""
    cle = (os.environ.get("ELEVENLABS_API_KEY") or "").strip()
    if not cle:
        try:
            cle = (client_eleven._client_wrapper.get_headers().get("xi-api-key") or "").strip()
        except Exception:
            cle = ""
    if not cle:
        raise _ElErreur("Clé ElevenLabs non configurée sur le serveur (ELEVENLABS_API_KEY).", 500)
    return {"xi-api-key": cle}


def _el_parametres():
    data = request.get_json(silent=True)
    if isinstance(data, dict):
        return data
    data = {}
    data.update(request.args.to_dict())
    data.update(request.form.to_dict())
    return data


def _el_reglages_voix(valeur):
    if not valeur:
        return None
    if isinstance(valeur, dict):
        return valeur
    try:
        d = json.loads(valeur)
        if isinstance(d, dict):
            return d
    except (ValueError, TypeError):
        pass
    raise _ElErreur("'voice_settings' doit être un objet JSON valide.", 400)


def _el_id_voix(valeur):
    voix = str(valeur or _EL_VOIX_DEFAUT).strip()
    if not _EL_ID_VOIX_RE.match(voix):
        raise _ElErreur("Identifiant de voix invalide.", 400)
    return voix


def _el_erreur_amont(resp):
    message = f"Erreur ElevenLabs (HTTP {resp.status_code})."
    try:
        detail = resp.json().get("detail")
        if isinstance(detail, dict):
            message = detail.get("message") or json.dumps(detail, ensure_ascii=False)
        elif isinstance(detail, list):
            message = "; ".join(str(d.get("msg", d)) if isinstance(d, dict) else str(d) for d in detail)
        elif detail:
            message = str(detail)
    except Exception:
        pass
    statut = resp.status_code if 400 <= resp.status_code < 500 else 502
    return _ElErreur(message, statut)


def _el_purger(dossier, jours=3):
    try:
        limite = time.time() - jours * 86400
        for nom in os.listdir(dossier):
            chemin = os.path.join(dossier, nom)
            if nom.endswith(".mp3") and os.path.getmtime(chemin) < limite:
                os.remove(chemin)
    except Exception as e:
        print(f"DEBUG: purge audios ElevenLabs ignorée : {e}")


def _el_reponse_audio(octets, prefixe, format_reponse):
    """url (défaut) : JSON avec audio_url | base64 : JSON + audio_base64 | stream : audio direct."""
    if format_reponse == "stream":
        return _ElResponse(octets, mimetype="audio/mpeg",
                           headers={"Content-Disposition": f'inline; filename="{prefixe}.mp3"'})
    os.makedirs(_EL_DOSSIER_AUDIO, exist_ok=True)
    _el_purger(_EL_DOSSIER_AUDIO)
    nom = f"{prefixe}_{uuid.uuid4().hex[:12]}.mp3"
    with open(os.path.join(_EL_DOSSIER_AUDIO, nom), "wb") as f:
        f.write(octets)
    charge = {"success": True, "audio_url": f"static/audio/tsapi_ai/{nom}",
              "mimetype": "audio/mpeg", "size_bytes": len(octets)}
    if format_reponse == "base64":
        charge["audio_base64"] = _el_b64.b64encode(octets).decode("ascii")
    return jsonify(charge), 200


def _el_controle():
    uid = session.get('user_id')
    if not uid:
        return None, (jsonify({"success": False, "error": "Connexion requise."}), 401)
    if not _fn_rate_ok(f"el:{uid}", 20, 60):
        return None, (jsonify({"success": False, "error": "Trop de requêtes. Patientez une minute."}), 429)
    return uid, None


def _el_reponse_erreur(exc):
    if isinstance(exc, _ElErreur):
        return jsonify({"success": False, "error": str(exc)}), exc.statut
    if isinstance(exc, requests.exceptions.Timeout):
        return jsonify({"success": False, "error": "ElevenLabs met trop de temps à répondre. Réessayez."}), 504
    if isinstance(exc, requests.exceptions.RequestException):
        return jsonify({"success": False, "error": "Impossible de joindre le service ElevenLabs."}), 502
    print(f"DEBUG: erreur Tsapi AI / ElevenLabs : {exc}")
    return jsonify({"success": False, "error": "Erreur interne du serveur."}), 500


# ── Text-to-Speech : texte -> voix parlée ────────────────────────────
@main_bp.route("/api/tsapi-ai/tts", methods=["POST"])
def tsapi_ai_tts():
    uid, refus = _el_controle()
    if refus:
        return refus
    try:
        p = _el_parametres()
        texte = str(p.get("text") or "").strip()
        if str(p.get("nettoyer", "1")).lower() not in ("0", "false", "non"):
            texte = _nettoyer_texte_pour_voix(texte)   # retire markdown/code/liens (1500 caractères max)
        if not texte:
            return jsonify({"success": False, "error": "Le champ 'text' est requis."}), 400
        if len(texte) > 5000:
            return jsonify({"success": False, "error": "Texte trop long (5000 caractères maximum)."}), 400
        corps = {"text": texte, "model_id": p.get("model_id") or _EL_MODELE_TTS}
        reglages = _el_reglages_voix(p.get("voice_settings"))
        if reglages:
            corps["voice_settings"] = reglages
        entetes = _el_entetes()
        entetes.update({"Content-Type": "application/json", "Accept": "audio/mpeg"})
        resp = requests.post(f"{_EL_BASE}/text-to-speech/{_el_id_voix(p.get('voice_id'))}",
                             headers=entetes, params={"output_format": _EL_FORMAT_SORTIE},
                             json=corps, timeout=120)
        if resp.status_code != 200:
            raise _el_erreur_amont(resp)
        return _el_reponse_audio(resp.content, "tts", p.get("response_format", "url"))
    except Exception as exc:
        return _el_reponse_erreur(exc)


# ── Sound Effects : prompt texte -> bruitage ─────────────────────────
@main_bp.route("/api/tsapi-ai/sound-effects", methods=["POST"])
def tsapi_ai_sound_effects():
    uid, refus = _el_controle()
    if refus:
        return refus
    try:
        p = _el_parametres()
        prompt = str(p.get("prompt") or p.get("text") or "").strip()
        if not prompt:
            return jsonify({"success": False, "error": "Le champ 'prompt' est requis."}), 400
        corps = {"text": prompt[:450]}
        for cle, mini, maxi in (("duration_seconds", 0.5, 30), ("prompt_influence", 0, 1)):
            if p.get(cle) not in (None, ""):
                try:
                    valeur = float(p[cle])
                except (TypeError, ValueError):
                    return jsonify({"success": False, "error": f"'{cle}' doit être un nombre."}), 400
                if not mini <= valeur <= maxi:
                    return jsonify({"success": False, "error": f"'{cle}' doit être entre {mini} et {maxi}."}), 400
                corps[cle] = valeur
        entetes = _el_entetes()
        entetes.update({"Content-Type": "application/json", "Accept": "audio/mpeg"})
        resp = requests.post(f"{_EL_BASE}/sound-generation", headers=entetes,
                             params={"output_format": _EL_FORMAT_SORTIE}, json=corps, timeout=120)
        if resp.status_code != 200:
            raise _el_erreur_amont(resp)
        return _el_reponse_audio(resp.content, "sfx", p.get("response_format", "url"))
    except Exception as exc:
        return _el_reponse_erreur(exc)


# ── Speech-to-Speech / doublage : fichier vocal -> autre voix ────────
# Envoi en multipart/form-data : champ fichier "audio" + voice_id
@main_bp.route("/api/tsapi-ai/speech-to-speech", methods=["POST"])
def tsapi_ai_speech_to_speech():
    uid, refus = _el_controle()
    if refus:
        return refus
    try:
        p = _el_parametres()
        fichier = request.files.get("audio") or request.files.get("file")
        if not fichier or not fichier.filename:
            return jsonify({"success": False, "error": "Aucun fichier audio reçu (champ 'audio' attendu)."}), 400
        octets = fichier.read(_EL_MAX_UPLOAD + 1)
        if not octets:
            return jsonify({"success": False, "error": "Le fichier audio est vide."}), 400
        if len(octets) > _EL_MAX_UPLOAD:
            return jsonify({"success": False, "error": "Fichier trop volumineux (50 Mo maximum)."}), 413
        donnees = {"model_id": p.get("model_id") or _EL_MODELE_STS}
        reglages = _el_reglages_voix(p.get("voice_settings"))
        if reglages:
            donnees["voice_settings"] = json.dumps(reglages)
        if str(p.get("remove_background_noise", "")).lower() in ("1", "true", "yes", "on"):
            donnees["remove_background_noise"] = "true"
        resp = requests.post(f"{_EL_BASE}/speech-to-speech/{_el_id_voix(p.get('voice_id'))}",
                             headers=_el_entetes(), params={"output_format": _EL_FORMAT_SORTIE},
                             data=donnees,
                             files={"audio": (secure_filename(fichier.filename) or "audio.webm", octets,
                                              fichier.mimetype or "application/octet-stream")},
                             timeout=180)
        if resp.status_code != 200:
            raise _el_erreur_amont(resp)
        return _el_reponse_audio(resp.content, "sts", p.get("response_format", "url"))
    except Exception as exc:
        return _el_reponse_erreur(exc)


# ── Liste des voix du compte ElevenLabs ──────────────────────────────
@main_bp.route("/api/tsapi-ai/voices", methods=["GET"])
def tsapi_ai_voices():
    uid, refus = _el_controle()
    if refus:
        return refus
    try:
        resp = requests.get(f"{_EL_BASE}/voices", headers=_el_entetes(), timeout=30)
        if resp.status_code != 200:
            raise _el_erreur_amont(resp)
        voix = [{"voice_id": v.get("voice_id"), "name": v.get("name"), "category": v.get("category"),
                 "description": v.get("description"), "labels": v.get("labels") or {},
                 "preview_url": v.get("preview_url")} for v in resp.json().get("voices", [])]
        return jsonify({"success": True, "count": len(voix), "voices": voix}), 200
    except Exception as exc:
        return _el_reponse_erreur(exc)

