# ─────────────────────────  AMIS (choix des participants)  ─────────────────────────
@main_bp.route('/api/msgr/amis')
@_msgr_auth
def msgr_amis():
    uid = session['user_id']
    ids = _msgr_ids_amis(uid)
    res = []
    if ids:
        for u in User.query.filter(User.id.in_(ids)).all():
            res.append(_msgr_user_json(u))
    res.sort(key=lambda x: (not x['en_ligne'], x['nom'].lower()))
    return jsonify(success=True, amis=res)


# ─────────────────────────  GROUPES  ─────────────────────────
@main_bp.route('/api/msgr/groupes', methods=['GET', 'POST'])
@_msgr_auth
def msgr_groupes():
    uid = session['user_id']
    if request.method == 'GET':
        res = []
        for m in ChatGroupeMembre.query.filter_by(user_id=uid).all():
            g = db.session.get(ChatGroupe, m.groupe_id)
            if g:
                res.append(_msgr_groupe_json(g, uid))
        res.sort(key=lambda x: x['dernier_iso'], reverse=True)
        return jsonify(success=True, groupes=res)

    data = request.get_json(silent=True) or {}
    try:
        ids = {int(x) for x in (data.get('membres') or [])}
    except (TypeError, ValueError):
        return jsonify(success=False, error="Participants invalides."), 400
    ids.discard(uid)
    if not ids:
        return jsonify(success=False, error="Choisissez au moins un participant."), 400
    if len(ids) > 99:
        return jsonify(success=False, error="Un groupe ne peut pas dépasser 100 membres."), 400
    if not ids.issubset(_msgr_ids_amis(uid)):
        return jsonify(success=False, error="Vous ne pouvez ajouter que vos amis."), 403
    moi = db.session.get(User, uid)
    nom = re.sub(r'\s+', ' ', str(data.get('nom') or '')).strip()[:60]
    if not nom:
        prenoms = [(_msgr_nom(u).split(' ')[0]) for u in User.query.filter(User.id.in_(list(ids)[:3])).all()]
        nom = ', '.join([_msgr_nom(moi).split(' ')[0]] + prenoms)[:60]
    g = ChatGroupe(nom=nom, createur_id=uid)
    db.session.add(g)
    db.session.flush()
    db.session.add(ChatGroupeMembre(groupe_id=g.id, user_id=uid, role='admin', vu=True, ajoute_par=uid))
    for i in ids:
        db.session.add(ChatGroupeMembre(groupe_id=g.id, user_id=i, role='membre', vu=False, ajoute_par=uid))
    db.session.add(ChatGroupeMessage(groupe_id=g.id, systeme=True,
                                     contenu=f"{_msgr_nom(moi)} a créé le groupe « {nom} »."))
    db.session.commit()
    return jsonify(success=True, groupe=_msgr_groupe_json(g, uid))


@main_bp.route('/api/msgr/groupes/nouveaux')
@_msgr_auth
def msgr_groupes_nouveaux():
    uid = session['user_id']
    res = []
    for m in ChatGroupeMembre.query.filter_by(user_id=uid, vu=False).order_by(ChatGroupeMembre.id.desc()).all():
        g = db.session.get(ChatGroupe, m.groupe_id)
        if not g:
            continue
        j = _msgr_groupe_json(g, uid)
        par = db.session.get(User, m.ajoute_par) if m.ajoute_par else None
        j['ajoute_par'] = _msgr_nom(par) if par else ''
        res.append(j)
    return jsonify(success=True, groupes=res)


@main_bp.route('/api/msgr/groupes/<int:gid>')
@_msgr_auth
def msgr_groupe_detail(gid):
    uid = session['user_id']
    if not _msgr_membre(gid, uid):
        return jsonify(success=False, error="Groupe introuvable."), 404
    g = db.session.get(ChatGroupe, gid)
    membres = []
    for m in ChatGroupeMembre.query.filter_by(groupe_id=gid).order_by(ChatGroupeMembre.id.asc()).all():
        u = db.session.get(User, m.user_id)
        if u:
            j = _msgr_user_json(u)
