@main_bp.route('/api/msgr/groupes/<int:gid>/messages', methods=['GET', 'POST'])
@_msgr_auth
def msgr_groupe_messages(gid):
    uid = session['user_id']
    m = _msgr_membre(gid, uid)
    g = db.session.get(ChatGroupe, gid)
    if not m or not g:
        return jsonify(success=False, error="Groupe introuvable."), 404
    cache = {}
    if request.method == 'POST':
        texte = str((request.get_json(silent=True) or {}).get('contenu') or '').strip()
        if not texte:
            return jsonify(success=False, error="Message vide."), 400
        msg = ChatGroupeMessage(groupe_id=gid, expediteur_id=uid, contenu=texte[:4000])
        db.session.add(msg)
        g.dernier_msg_at = datetime.utcnow()
        db.session.flush()
        _msgr_gx_lier_reponse(msg, gid, (request.get_json(silent=True) or {}).get('reponse_a'))
        m.dernier_lu_id = msg.id
        m.vu = True
        db.session.commit()
        return jsonify(success=True, message=_msgr_msg_json(msg, uid, cache))
    try:
        apres = int(request.args.get('apres') or 0)
    except ValueError:
        apres = 0
    q = ChatGroupeMessage.query.filter(ChatGroupeMessage.groupe_id == gid)
    q = _msgr_gx_sans_masques(q, gid, uid)       # ajout : messages « supprimés pour moi »
    if apres:
        q = q.filter(ChatGroupeMessage.id > apres)
        msgs = q.order_by(ChatGroupeMessage.id.asc()).limit(200).all()
    else:
        msgs = list(reversed(q.order_by(ChatGroupeMessage.id.desc()).limit(100).all()))
    if msgs and msgs[-1].id > (m.dernier_lu_id or 0):
        m.dernier_lu_id = msgs[-1].id
    if not m.vu:
        m.vu = True
    db.session.commit()
    en_ligne = 0
    for mb in ChatGroupeMembre.query.filter_by(groupe_id=gid).all():
        u = db.session.get(User, mb.user_id)
        if u and est_en_ligne(u):
            en_ligne += 1
    nb = ChatGroupeMembre.query.filter_by(groupe_id=gid).count()
    _maj, _modifs = _msgr_gx_modifs(gid, uid, cache)   # ajout : messages modifiés / supprimés depuis le dernier passage
    return jsonify(success=True, messages=[_msgr_msg_json(x, uid, cache) for x in msgs],
                   nb_membres=nb, nb_en_ligne=en_ligne, nom=g.nom, maj=_maj, modifs=_modifs)


@main_bp.route('/api/msgr/groupes/<int:gid>/vu', methods=['POST'])
@_msgr_auth
def msgr_groupe_vu(gid):
    m = _msgr_membre(gid, session['user_id'])
    if not m:
        return jsonify(success=False, error="Groupe introuvable."), 404
    m.vu = True
    db.session.commit()
    return jsonify(success=True)


@main_bp.route('/api/msgr/groupes/<int:gid>/quitter', methods=['POST'])
@_msgr_auth
def msgr_groupe_quitter(gid):
    uid = session['user_id']
    m = _msgr_membre(gid, uid)
    g = db.session.get(ChatGroupe, gid)
    if not m or not g:
        return jsonify(success=False, error="Groupe introuvable."), 404
    moi = db.session.get(User, uid)
    db.session.delete(m)
    ChatArchive.query.filter_by(user_id=uid, kind='groupe', cible_id=gid).delete()
    db.session.flush()
    restants = ChatGroupeMembre.query.filter_by(groupe_id=gid).order_by(ChatGroupeMembre.id.asc()).all()
    if not restants:
        ChatGroupeMessage.query.filter_by(groupe_id=gid).delete()
        ChatArchive.query.filter_by(kind='groupe', cible_id=gid).delete()
        db.session.delete(g)
    else:
        if m.role == 'admin' and not any(x.role == 'admin' for x in restants):
            restants[0].role = 'admin'
        db.session.add(ChatGroupeMessage(groupe_id=gid, systeme=True,
                                         contenu=f"{_msgr_nom(moi)} a quitté le groupe."))
        g.dernier_msg_at = datetime.utcnow()
    db.session.commit()
    return jsonify(success=True)


# ─────────────────────────  ARCHIVE  ─────────────────────────
@main_bp.route('/api/msgr/archive', methods=['GET', 'POST'])
@_msgr_auth
def msgr_archive():
    uid = session['user_id']
    if request.method == 'POST':
        data = request.get_json(silent=True) or {}
        kind = data.get('kind')
        try:
            cible = int(data.get('id'))
        except (TypeError, ValueError):
            return jsonify(success=False, error="Cible invalide."), 400
        if kind not in ('user', 'groupe'):
            return jsonify(success=False, error="Type invalide."), 400
        if kind == 'groupe' and not _msgr_membre(cible, uid):
            return jsonify(success=False, error="Groupe introuvable."), 404
        ligne = ChatArchive.query.filter_by(user_id=uid, kind=kind, cible_id=cible).first()
        if data.get('archive', True):
            if not ligne:
                db.session.add(ChatArchive(user_id=uid, kind=kind, cible_id=cible))
        elif ligne:
            db.session.delete(ligne)
        db.session.commit()
    users, groupes = [], []
    for a in ChatArchive.query.filter_by(user_id=uid).order_by(ChatArchive.id.desc()).all():
        if a.kind == 'user':
            u = db.session.get(User, a.cible_id)
            if u:
                users.append(_msgr_user_json(u))
        else:
            g = db.session.get(ChatGroupe, a.cible_id)
            if g and _msgr_membre(g.id, uid):
                groupes.append(_msgr_groupe_json(g, uid))
    return jsonify(success=True, users=users, groupes=groupes,
                   ids_users=[u['id'] for u in users])


# ══════════════════════════════════════════════════════════════════════════════
# AJOUT ADDITIF — Revérification des abonnés Tsapi Verified (changement de nom / photo de profil)
#  - la modification est mise « en attente » : l'ancien nom/la photo actuelle restent affichés ;
#  - l'abonné filme sa pièce d'identité ; le PDG approuve ou refuse sur /admin/modifications-profil ;
#  - ne touche NI au badge, NI à la date d'expiration de l'abonnement, NI au parcours de vérification existant.
# ══════════════════════════════════════════════════════════════════════════════
_MODIFS_PROFIL_T = None
_REVERIF_PIECES = {'cni': "Carte d'identité", 'passport': 'Passeport', 'permis': 'Permis de conduire',
                   'sejour': 'Carte de séjour', 'driver_license': 'Permis de conduire',
                   'residence_permit': 'Carte de séjour'}
_REVERIF_EXT_PIECE = ('jpg', 'jpeg', 'png', 'webp', 'pdf')
_REVERIF_TAILLE_MAX = 15 * 1024 * 1024  # 15 Mo

def _modifs_table():
    global _MODIFS_PROFIL_T
    if _MODIFS_PROFIL_T is None:
        import sqlalchemy as _sa
        t = _sa.Table('modifs_profil_attente', db.metadata,
                      _sa.Column('id', _sa.Integer, primary_key=True),
                      _sa.Column('user_id', _sa.Integer, nullable=False, index=True),
                      _sa.Column('type', _sa.String(10), nullable=False),
                      _sa.Column('nouveau_nom', _sa.String(120)),
                      _sa.Column('nouvelle_photo', _sa.String(255)),
                      _sa.Column('piece_type', _sa.String(30)),
                      _sa.Column('piece_fichier', _sa.String(255)),
                      _sa.Column('statut', _sa.String(12), nullable=False),
                      _sa.Column('cree_le', _sa.DateTime),
                      _sa.Column('decide_le', _sa.DateTime),
                      _sa.Column('motif', _sa.String(255)),
                      extend_existing=True)
        try:
            t.create(bind=db.engine, checkfirst=True)
        except Exception as e:
            print(f"DEBUG: création de la table modifs_profil_attente impossible : {e}")
        _MODIFS_PROFIL_T = t
    return _MODIFS_PROFIL_T

def _est_abonne_verifie(user):
    """Abonné Tsapi Verified = même critère que l'affichage du badge sur le profil."""
    try:
        return bool(user and user.is_authenticated and getattr(user, 'badge_expire', None))
    except Exception:
        return False

def _modif_creer(user_id, type_, nouveau_nom=None, nouvelle_photo=None, commit=True):
    t = _modifs_table()
    # une nouvelle demande du même type remplace l'ancienne demande non terminée
    db.session.execute(t.update().where(_sa_and(t.c.user_id == user_id, t.c.type == type_,
                                                t.c.statut.in_(('brouillon', 'attente')))).values(statut='annule'))
    res = db.session.execute(t.insert().values(user_id=user_id, type=type_, nouveau_nom=nouveau_nom,
                                               nouvelle_photo=nouvelle_photo, statut='brouillon',
                                               cree_le=datetime.utcnow()))
    modif_id = res.inserted_primary_key[0]
    if commit:
        db.session.commit()
    return modif_id

def _modif_lire(modif_id):
    t = _modifs_table()
    return db.session.execute(t.select().where(t.c.id == modif_id)).mappings().first()

def _modifs_de(user_id, statuts=None, limite=8):
    t = _modifs_table()
    q = t.select().where(t.c.user_id == user_id)
    if statuts:
        q = q.where(t.c.statut.in_(statuts))
    return [dict(r) for r in db.session.execute(q.order_by(t.c.id.desc()).limit(limite)).mappings().all()]

def _sa_and(*c):
    import sqlalchemy as _sa
    return _sa.and_(*c)

# ── AJOUT ADDITIF : 5 refus de revérification d'affilée -> pause de 2 jours ──
_REVERIF_MAX_REFUS = 5
_REVERIF_PAUSE = timedelta(days=2)

def _reverif_etat(user_id):
    """Retourne (fin_de_pause ou None, refus_dans_la_série_en_cours).
    - un envoi de pièce (nom + photo ensemble) compte pour UN seul essai ;
    - le 5e refus ouvre une pause de 2 jours à partir de ce refus, puis le compteur repart de zéro ;
    - une approbation remet tout à zéro."""
    t = _modifs_table()
    lignes = [dict(x) for x in db.session.execute(
        t.select().where(_sa_and(t.c.user_id == user_id, t.c.statut.in_(('rejete', 'approuve'))))
         .order_by(t.c.decide_le.asc(), t.c.id.asc())).mappings().all()]
    serie, fin_pause, vus = 0, None, set()
    for x in lignes:
        if x['statut'] == 'approuve':
            serie, fin_pause, vus = 0, None, set()
            continue
        quand = x['decide_le'] or x['cree_le'] or datetime.utcnow()
        if fin_pause and quand < fin_pause:
            continue   # refus décidé pendant une pause déjà ouverte : même pause
        cle = x['piece_fichier'] or ('id%s' % x['id'])
        if cle in vus:
            continue
        vus.add(cle)
        serie += 1
        if serie >= _REVERIF_MAX_REFUS:
            fin_pause, serie = quand + _REVERIF_PAUSE, 0
    if fin_pause and datetime.utcnow() >= fin_pause:
        fin_pause = None
    return fin_pause, serie

def _reverif_verrou(user_id):
    """Fin de la pause en cours (datetime) ou None. Ne lève jamais d'exception."""
    try:
        return _reverif_etat(user_id)[0]
    except Exception as e:
        print(f"DEBUG: calcul de la pause de revérification impossible : {e}")
        return None

def _reverif_delai_txt(delta):
    secondes = max(int(delta.total_seconds()), 60)
    j, reste = divmod(secondes, 86400)
    h, reste = divmod(reste, 3600)
    m = reste // 60
    if j:
        return f"{j} jour{'s' if j > 1 else ''}" + (f" et {h} heure{'s' if h > 1 else ''}" if h else '')
    if h:
        return f"{h} heure{'s' if h > 1 else ''}" + (f" et {m} minute{'s' if m > 1 else ''}" if m else '')
    return f"{max(m, 1)} minute{'s' if m > 1 else ''}"

def _reverif_message_verrou(fin_pause):
    return (f"Vous avez atteint {_REVERIF_MAX_REFUS} refus de revérification. "
            f"Vous pourrez réessayer dans {_reverif_delai_txt(fin_pause - datetime.utcnow())}.")

def _reverif_refus_si_non_abonne():
    if not _est_abonne_verifie(current_user):
        flash("Cette page est réservée aux abonnés Tsapi Verified.", "info")
        return redirect(url_for('main.edit_profile'))
    return None

