def reverif_nom():
    r = _reverif_refus_si_non_abonne()
    if r: return r
    _pause_rv = _reverif_verrou(current_user.id)
    if _pause_rv:
        session['reverif_erreur'] = _reverif_message_verrou(_pause_rv)
        return redirect(url_for('main.reverif_choix'))
    erreur, saisie = None, ''
    if request.method == 'POST':
        saisie = (request.form.get('nom_complet') or '').strip()
        nom, erreur = _normaliser_nom_propre(saisie)
        if not _pdg_csrf_ok():
            erreur = "Session de sécurité expirée, rechargez la page puis réessayez."
        elif not erreur and (not nom or len(nom) > 100):
            erreur = "Le nom est vide ou trop long (100 caractères maximum)."
        elif not erreur and nom.strip().lower() == (current_user.nom_complet or '').strip().lower():
            erreur = "Ce nom est déjà celui de votre profil."
        elif not erreur and compte_certifie_possedant_nom(username=None, noms_affiches=[nom], exclure_user_id=current_user.id):
            erreur = MSG_NOM_CERTIFIE
        elif not erreur:
            jours = current_user.jours_restants_changement_nom()
            if jours > 0:
                erreur = f"Vous pourrez modifier votre nom dans {jours} jour{'s' if jours > 1 else ''}."
        if not erreur:
            return redirect(url_for('main.reverif_piece', modif_id=_modif_creer(current_user.id, 'nom', nouveau_nom=nom)))
    return render_template('reverif_nom.html', csrf_token=_fn_csrf_token(), erreur=erreur, saisie=saisie)

