# Réception de l'image envoyée par TON scanner (mêmes champs que /verification/piece-identite)
@main_bp.route('/profil/reverification/<int:modif_id>/piece-envoi', methods=['POST'])
@login_required
def reverif_piece_envoi(modif_id):
    if not _est_abonne_verifie(current_user):
        return jsonify(success=False, error="Réservé aux abonnés Tsapi Verified."), 403
    m = _modif_lire(modif_id)
    if not m or m['user_id'] != current_user.id:
        return jsonify(success=False, error="Demande introuvable."), 404
    if m['statut'] != 'brouillon':
        return jsonify(success=False, error="Cette demande a déjà été envoyée."), 400
    _pause_rv = _reverif_verrou(current_user.id)
    if _pause_rv:
        return jsonify(success=False, error=_reverif_message_verrou(_pause_rv)), 429
    if not _pdg_csrf_ok():
        return jsonify(success=False, error="Session de sécurité expirée, rechargez la page."), 400
    type_piece = re.sub(r'[^a-z_]', '', (request.form.get('type_piece') or '').strip().lower())[:30]
    fichier = request.files.get('document')
    if not type_piece or not fichier or not fichier.filename:
        return jsonify(success=False, error="Merci de choisir un type de pièce et d'envoyer le document."), 400
    ext = fichier.filename.rsplit('.', 1)[-1].lower() if '.' in fichier.filename else ''
    fichier.stream.seek(0, os.SEEK_END); taille = fichier.stream.tell(); fichier.stream.seek(0)
    if ext not in _REVERIF_EXT_PIECE:
        return jsonify(success=False, error="Format non accepté. Envoyez une photo (JPG, PNG) ou un PDF."), 400
    if taille > _REVERIF_TAILLE_MAX:
        return jsonify(success=False, error="Le fichier dépasse 15 Mo."), 400
    try:
        os.makedirs(UPLOAD_ID_FOLDER, exist_ok=True)
        nom_f = f"reverif_{uuid.uuid4().hex}_{secure_filename(fichier.filename)}"
        fichier.save(os.path.join(UPLOAD_ID_FOLDER, nom_f))
        t = _modifs_table()
        db.session.execute(t.update().where(_sa_and(t.c.user_id == current_user.id, t.c.statut == 'brouillon'))
                           .values(statut='attente', piece_type=type_piece, piece_fichier=nom_f))
        db.session.commit()
        session['reverif_envoye'] = True
        return jsonify(success=True)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: envoi de la pièce de revérification impossible : {e}")
        return jsonify(success=False, error="Envoi impossible pour le moment. Réessayez."), 500

