def _reverif_decider(modif_id, approuver):
    if not current_user.is_pdg:
        abort(403)
    if not _pdg_csrf_ok():
        flash("Session de sécurité expirée, rechargez la page puis réessayez.")
        return redirect(url_for('main.admin_reverif'))
    m = _modif_lire(modif_id)
    if not m or m['statut'] != 'attente':
        flash("Cette demande n'est plus en attente.")
        return redirect(url_for('main.admin_reverif'))
    u = db.session.get(User, m['user_id'])
    t = _modifs_table()
    motif = (request.form.get('motif') or '').strip()[:200] or None
    if not u:
        abort(404)
    if approuver:
        if m['type'] == 'nom':
            if compte_certifie_possedant_nom(username=None, noms_affiches=[m['nouveau_nom']], exclure_user_id=u.id):
                flash("Refusé automatiquement : ce nom est protégé (personnalité certifiée).")
                approuver, motif = False, "Ce nom est protégé."
            else:
                u.nom_complet = m['nouveau_nom']
                _synchroniser_prenom_nom(u, m['nouveau_nom'])
                u.last_name_change = datetime.utcnow()
                u.name_change_count = (u.name_change_count or 0) + 1
        elif m['type'] == 'photo':
            u.avatar = m['nouvelle_photo']
            pub = None
            if u.notifier_changement_photo:
                pub = Publication(contenu="a changé sa photo de profil", media_url=m['nouvelle_photo'], user_id=u.id,
                                  type_publication='photo_profil', confidentialite='public')
                db.session.add(pub); db.session.flush()
            db.session.add(PhotoHistorique(user_id=u.id, type_photo='avatar', url=m['nouvelle_photo'],
                                           publication_id=pub.id if pub else None))
    db.session.execute(t.update().where(t.c.id == modif_id).values(
        statut='approuve' if approuver else 'rejete', decide_le=datetime.utcnow(), motif=None if approuver else motif))
    try:
        if approuver:
            notifier(u.id, 'reverif_approuvee')
        else:
            _pause_rv, _serie_rv = _reverif_etat(u.id)
            _debut_msg = "Votre modification de profil n'a pas pu être validée" + (f" : {motif}." if motif else ".")
            if _pause_rv:
                _msg = (f"{_debut_msg} Vous avez atteint {_REVERIF_MAX_REFUS} refus : vous pourrez réessayer dans "
                        f"{_reverif_delai_txt(_pause_rv - datetime.utcnow())}.")
                _restants = 0
            else:
                _restants = _REVERIF_MAX_REFUS - _serie_rv
                _msg = (f"{_debut_msg} Touchez pour réessayer avec un document plus lisible "
                        f"({_restants} essai{'s' if _restants > 1 else ''} restant{'s' if _restants > 1 else ''} "
                        f"avant une pause de 2 jours).")
            notifier(u.id, 'reverif_refusee', message=_msg, essais_restants=_restants)
    except Exception as e:
        print(f"DEBUG: notification de revérification impossible : {e}")
    db.session.commit()
    if approuver:
        _toucher_profil(u.id)
    flash("Demande approuvée et appliquée." if approuver else "Demande refusée.")
    return redirect(url_for('main.admin_reverif'))

