# COMMENTAIRES — PAGE commentaire.html « façon Facebook »
# (tri, photos, GIF, autocollants, avatar, étoiles, épinglage, signalement)
#
# BLOC ADDITIF : à coller TOUT À LA FIN de routes.py (après le dernier bloc).
# Aucune route, aucune fonction et aucune table existante n'est modifiée :
#   - nouvelles tables (créées toutes seules) : commentaire_media, commentaire_epingle
#   - nouvelles routes :
#       GET  /api/publication/<id>/commentaires-tri   (Plus pertinents / Plus récents / Tous)
#       GET  /api/comment/<id>/contexte               (ancre #comment-<id> venant d'une notification)
#       POST /api/comment/<pub_id>/media              (photo, GIF, autocollant, avatar, étoile)
#       POST /api/comment/<id>/epingler               (l'auteur de la publication épingle un commentaire)
#       GET  /api/gifs                                (recherche de GIF, clé GIPHY_API_KEY dans .env)
#   - `_serialiser_commentaires` est « enveloppée » une 2e fois (comme pour les vocaux) pour ajouter
#     media / pinned / verified aux commentaires. Les anciens champs ne changent pas, donc la feuille
#     _comments_sheet.html continue de fonctionner (elle verra simplement le texte de repli).
#   - les réactions 👍 et 👎 sont ajoutées à la liste acceptée par /api/comment/<id>/reagir.
# ══════════════════════════════════════════════════════════════════════════
from sqlalchemy import event as _cp_event

UPLOAD_COMMENT_MEDIA_FOLDER = os.path.join('static', 'uploads', 'comment_media')
os.makedirs(UPLOAD_COMMENT_MEDIA_FOLDER, exist_ok=True)

_CP_MAX_IMAGE_OCTETS = 8 * 1024 * 1024
_CP_MAX_MEDIAS_PAR_MINUTE = 10
_CP_TABLES_OK = False
_CP_KINDS = ('image', 'gif', 'sticker', 'avatar', 'etoile')
_CP_TEXTE_REPLI = {'image': '📷 Photo', 'gif': 'GIF', 'sticker': '', 'avatar': '🙂 Avatar', 'etoile': '⭐ Étoile'}
_CP_ETOILES = ('🌸', '⭐', '🌟', '💎', '🔥', '🎁')          # visuels d'étoiles proposés
_CP_HOTES_GIF = ('giphy.com', 'tenor.com')

# 👍 et 👎 deviennent des réactions valides (le dict est lu à chaque appel par /reagir)
for _e in ('👍', '👎'):
    _COMMENT_REACTION_MAP[_emoji_key(_e)] = _e


class CommentaireMedia(db.Model):
    __tablename__ = 'commentaire_media'
    id = db.Column(db.Integer, primary_key=True)
    commentaire_id = db.Column(db.Integer, db.ForeignKey('commentaire.id', ondelete='CASCADE'),
                               nullable=False, unique=True, index=True)
    kind = db.Column(db.String(12), nullable=False)          # image | gif | sticker | avatar | etoile
    fichier = db.Column(db.String(255))                      # image / avatar (nom dans static/uploads/…)
    url = db.Column(db.String(600))                          # gif (https://media.giphy.com/…)
    emoji = db.Column(db.String(16))                         # sticker / étoile
    quantite = db.Column(db.Integer, default=1)              # étoiles
    date_creation = db.Column(db.DateTime, default=datetime.utcnow, index=True)


class CommentaireEpingle(db.Model):
    __tablename__ = 'commentaire_epingle'
    id = db.Column(db.Integer, primary_key=True)
    publication_id = db.Column(db.Integer, nullable=False, unique=True, index=True)
    commentaire_id = db.Column(db.Integer, nullable=False, index=True)
    date_creation = db.Column(db.DateTime, default=datetime.utcnow)


@main_bp.before_app_request
def _ensure_cp_schema():
    """Crée une seule fois les 2 tables ci-dessus (sans effet si elles existent)."""
    global _CP_TABLES_OK
    if _CP_TABLES_OK:
        return
    try:
        CommentaireMedia.__table__.create(bind=db.engine, checkfirst=True)
        CommentaireEpingle.__table__.create(bind=db.engine, checkfirst=True)
        _CP_TABLES_OK = True
    except Exception as e:
        print(f"DEBUG: tables commentaire_media / commentaire_epingle non créées : {e}")


@_cp_event.listens_for(Commentaire, 'after_delete')
def _cp_nettoyer(mapper, connection, cible):
    """Suppression d'un commentaire (par n'importe quelle route) : on retire aussi son média,
    son éventuel épinglage et le fichier image."""
    if not _CP_TABLES_OK:
        return
    try:
        ligne = connection.execute(db.text('SELECT kind, fichier FROM commentaire_media WHERE commentaire_id = :i'),
                                   {'i': cible.id}).first()
        if ligne:
            connection.execute(db.text('DELETE FROM commentaire_media WHERE commentaire_id = :i'), {'i': cible.id})
            if ligne[0] == 'image' and ligne[1]:
                chemin = os.path.join(UPLOAD_COMMENT_MEDIA_FOLDER, os.path.basename(ligne[1]))
                if os.path.isfile(chemin):
                    os.remove(chemin)
        connection.execute(db.text('DELETE FROM commentaire_epingle WHERE commentaire_id = :i'), {'i': cible.id})
    except Exception as e:
        print(f"DEBUG: nettoyage média commentaire : {e}")


# ── Série d'étoiles : nombre de semaines consécutives où `uid` a envoyé une étoile à l'auteur ──
def _cp_serie_etoiles(uid, auteur_id):
    try:
        lignes = (db.session.query(Commentaire.date_creation)
                  .join(CommentaireMedia, CommentaireMedia.commentaire_id == Commentaire.id)
                  .join(Publication, Publication.id == Commentaire.publication_id)
                  .filter(CommentaireMedia.kind == 'etoile', Commentaire.user_id == uid,
                          Publication.user_id == auteur_id).all())
    except Exception:
        db.session.rollback()
        return 0
    semaines = {(d.isocalendar()[0], d.isocalendar()[1]) for (d,) in lignes if d}
    if not semaines:
        return 0
    cur = datetime.utcnow().date()
    if (cur.isocalendar()[0], cur.isocalendar()[1]) not in semaines:
        cur -= timedelta(days=7)                    # on tolère la semaine en cours encore vide
    n = 0
    while (cur.isocalendar()[0], cur.isocalendar()[1]) in semaines:
        n += 1
        cur -= timedelta(days=7)
    return n


_serialiser_commentaires_sans_media = _serialiser_commentaires


def _serialiser_commentaires(commentaires, pub):
    liste = _serialiser_commentaires_sans_media(commentaires, pub)
    try:
        ids = [c['id'] for c in liste]
        medias = {m.commentaire_id: m for m in CommentaireMedia.query.filter(
            CommentaireMedia.commentaire_id.in_(ids)).all()} if (ids and _CP_TABLES_OK) else {}
        epingle = CommentaireEpingle.query.filter_by(publication_id=pub.id).first() if _CP_TABLES_OK else None
        users = {u.id: u for u in User.query.filter(User.id.in_({c['user_id'] for c in liste})).all()} if liste else {}
        series = {}
        for c in liste:
            m = medias.get(c['id'])
            media = None
            if m:
                if m.kind == 'image' and m.fichier:
                    src = url_for('static', filename='uploads/comment_media/' + m.fichier)
                elif m.kind == 'avatar':
                    a = users.get(c['user_id'])
                    src = url_for('static', filename='uploads/' + ((a.avatar if a and a.avatar else None) or 'default_avatar.png'))
                else:
                    src = m.url
                media = {'kind': m.kind, 'src': src, 'emoji': m.emoji, 'quantite': m.quantite or 1}
                if m.kind == 'etoile':
                    cle = (c['user_id'], pub.user_id)
                    if cle not in series:
                        series[cle] = _cp_serie_etoiles(*cle)
                    media['serie'] = series[cle]
            c['media'] = media
            c['pinned'] = bool(epingle and epingle.commentaire_id == c['id'])
            u = users.get(c['user_id'])
            c['verified'] = bool(u and (getattr(u, 'is_verify', False) or getattr(u, 'has_badge_bleu', False)))
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: médias de commentaires non joints : {e}")
    return liste


# ── Tri « façon Facebook » ──────────────────────────────────────────────────
_CP_RE_LIEN = re.compile(r'(https?://|www\.)', re.I)


def _cp_ids_spam(racines, amis, owner_id):
    """Commentaires « spam potentiel » : ≥3 signalements, lien posté par un inconnu,
    ou même texte posté ≥3 fois par la même personne sur la publication."""
    spam = set()
    if not racines:
        return spam
    ids = [c.id for c in racines]
    try:
        signales = dict(db.session.query(CommentaireSignalement.commentaire_id, db.func.count(CommentaireSignalement.id))
                        .filter(CommentaireSignalement.commentaire_id.in_(ids))
                        .group_by(CommentaireSignalement.commentaire_id).all())
    except Exception:
        db.session.rollback()
        signales = {}
    doublons = {}
    for c in racines:
        cle = (c.user_id, (c.contenu or '').strip().lower())
        doublons[cle] = doublons.get(cle, 0) + 1
    for c in racines:
        if c.user_id in amis or c.user_id == owner_id or c.user_id == current_user.id:
            continue
        if signales.get(c.id, 0) >= 3 or _CP_RE_LIEN.search(c.contenu or '') \
                or doublons[(c.user_id, (c.contenu or '').strip().lower())] >= 3:
            spam.add(c.id)
    return spam


@main_bp.route('/api/publication/<int:pub_id>/commentaires-tri', methods=['GET'])
@login_required
def api_commentaires_tri(pub_id):
    pub = Publication.query.get_or_404(pub_id)
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    tri = request.args.get('tri', 'pertinents')
    if tri not in ('pertinents', 'recents', 'tous'):
        tri = 'pertinents'
    offset = max(request.args.get('offset', 0, type=int), 0)
    limit = min(max(request.args.get('limit', 15, type=int), 1), 30)

    epingle = CommentaireEpingle.query.filter_by(publication_id=pub_id).first()
    pinned_id = epingle.commentaire_id if epingle else None
    base = Commentaire.query.filter_by(publication_id=pub_id, parent_id=None)
    if pinned_id:
        base = base.filter(Commentaire.id != pinned_id)
    candidats = (base.order_by(Commentaire.date_creation.desc(), Commentaire.id.desc()).limit(600).all())
    amis = _amis_ids(current_user.id)

    if tri != 'tous':
        spam = _cp_ids_spam(candidats, amis, pub.user_id)
        candidats = [c for c in candidats if c.id not in spam]
    if tri == 'pertinents' and candidats:
        ids = [c.id for c in candidats]
        reac = {}
        for cid, n in (db.session.query(CommentaireReaction.commentaire_id, db.func.count(CommentaireReaction.id))
                       .filter(CommentaireReaction.commentaire_id.in_(ids),
                               CommentaireReaction.emoji != '👎')
                       .group_by(CommentaireReaction.commentaire_id).all()):
            reac[cid] = n
        reps = dict(db.session.query(Commentaire.parent_id, db.func.count(Commentaire.id))
                    .filter(Commentaire.parent_id.in_(ids)).group_by(Commentaire.parent_id).all())
        maintenant = datetime.utcnow()

        def score(c):
            age_h = max((maintenant - c.date_creation).total_seconds() / 3600.0, 0) if c.date_creation else 9999
            s = 0.0
            if c.user_id == current_user.id or c.user_id in amis:
                s += 60                                  # commentaires d'ami(e)s d'abord
            if c.user_id == pub.user_id:
                s += 40                                  # l'auteur de la publication
            s += 12 * reac.get(c.id, 0) + 6 * reps.get(c.id, 0)
            s += 25 / (1.0 + age_h / 24.0)               # petit bonus de fraîcheur
            return s
        candidats.sort(key=score, reverse=True)

    page = candidats[offset:offset + limit + 1]
    has_more = len(page) > limit
    page = page[:limit]
    liste = _serialiser_commentaires(page, pub)
    if offset == 0 and pinned_id:
        c_pin = db.session.get(Commentaire, pinned_id)
        if c_pin:
            liste = _serialiser_commentaires([c_pin], pub) + liste

    ok, msg = _peut_commenter_pub(pub)
    try:                                              # nom de l'auteur (panneau « Étoiles »)
        _auteur = db.session.get(User, pub.user_id)
        nom_auteur = (getattr(_auteur, 'prenom', None) or (_auteur.nom_complet or '').split(' ')[0]) if _auteur else ''
    except Exception:
        db.session.rollback()
        nom_auteur = ''
    try:
        aime = Like.query.filter_by(user_id=current_user.id, publication_id=pub.id).first() is not None
    except Exception:
        db.session.rollback()
        aime = False
    return jsonify(
        success=True, tri=tri, comments=liste, has_more=has_more, next_offset=offset + len(page),
        comments_count=Commentaire.query.filter_by(publication_id=pub_id).count(),
        can_comment=ok, block_message=msg,
        header={'likes': len(pub.likes), 'liked': aime, 'shares': pub.share_count or 0,
                'owner_id': pub.user_id, 'is_owner': pub.user_id == current_user.id, 'owner_name': nom_auteur},
        me={'id': current_user.id, 'name': current_user.nom_complet,
            'prenom': getattr(current_user, 'prenom', None) or (current_user.nom_complet or '').split(' ')[0],
            'avatar': current_user.avatar or 'default_avatar.png'},
    )


