# ── Envoi d'un commentaire « média » ────────────────────────────────────────
def _cp_format_image(tete):
    if tete[:8] == b'\x89PNG\r\n\x1a\n':
        return 'png'
    if tete[:3] == b'\xff\xd8\xff':
        return 'jpg'
    if tete[:6] in (b'GIF87a', b'GIF89a'):
        return 'gif'
    if tete[:4] == b'RIFF' and tete[8:12] == b'WEBP':
        return 'webp'
    return None


def _cp_reencoder(data, fmt):
    """Si Pillow est installé : retire les métadonnées (position GPS…) et plafonne à 1600 px.
    Sinon, le fichier validé est conservé tel quel."""
    try:
        from PIL import Image, ImageOps
        import io
        im = Image.open(io.BytesIO(data))
        if fmt == 'gif' and getattr(im, 'is_animated', False):
            return data, fmt
        im = ImageOps.exif_transpose(im)
        im.thumbnail((1600, 1600))
        out = io.BytesIO()
        if fmt in ('png', 'webp'):
            im.save(out, format='PNG' if fmt == 'png' else 'WEBP')
        else:
            im.convert('RGB').save(out, format='JPEG', quality=88, optimize=True)
            fmt = 'jpg'
        return out.getvalue(), fmt
    except Exception:
        return data, fmt


def _cp_emoji_valide(s, maxlen=12):
    s = (s or '').strip()
    return bool(s) and len(s) <= maxlen and not any(ch.isascii() and ch.isalnum() for ch in s)


@main_bp.route('/api/comment/<int:pub_id>/media', methods=['POST'])
@login_required
def api_add_comment_media(pub_id):
    pub = Publication.query.get_or_404(pub_id)
    if not _peut_voir_publication(pub, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    ok, msg = _peut_commenter_pub(pub)
    if not ok:
        return jsonify(success=False, error=msg), 403
    kind = (request.form.get('kind') or '').strip()
    if kind not in _CP_KINDS:
        return jsonify(success=False, error='Type de média non valide.'), 400

    try:
        recents = (db.session.query(db.func.count(CommentaireMedia.id))
                   .filter(CommentaireMedia.date_creation >= datetime.utcnow() - timedelta(seconds=60))
                   .join(Commentaire, Commentaire.id == CommentaireMedia.commentaire_id)
                   .filter(Commentaire.user_id == current_user.id).scalar() or 0)
        if recents >= _CP_MAX_MEDIAS_PAR_MINUTE:
            return jsonify(success=False, error='Vous envoyez trop de médias. Patientez un instant.'), 429
    except Exception:
        db.session.rollback()

    legende = (request.form.get('texte') or '').strip()[:1000]
    fichier = url = emoji = None
    quantite = 1
    nom_ecrit = None

    if kind == 'image':
        f = request.files.get('image')
        if not f:
            return jsonify(success=False, error='Aucune image reçue.'), 400
        data = f.read(_CP_MAX_IMAGE_OCTETS + 1)
        if len(data) > _CP_MAX_IMAGE_OCTETS:
            return jsonify(success=False, error='Image trop volumineuse (8 Mo maximum).'), 413
        fmt = _cp_format_image(data[:16])
        if not fmt:
            return jsonify(success=False, error="Ce fichier n'est pas une image valide."), 400
        data, fmt = _cp_reencoder(data, fmt)
        nom_ecrit = f"{uuid.uuid4().hex}.{fmt}"
        fichier = nom_ecrit
    elif kind == 'gif':
        url = (request.form.get('url') or '').strip()
        p = urlparse(url)
        hote = (p.hostname or '').lower()
        if p.scheme != 'https' or not any(hote == h or hote.endswith('.' + h) for h in _CP_HOTES_GIF) or len(url) > 600:
            return jsonify(success=False, error='GIF non valide.'), 400
    elif kind == 'sticker':
        emoji = (request.form.get('emoji') or '').strip()
        if not _cp_emoji_valide(emoji):
            return jsonify(success=False, error='Autocollant non valide.'), 400
    elif kind == 'etoile':
        emoji = (request.form.get('emoji') or '🌸').strip()
        if emoji not in _CP_ETOILES:
            return jsonify(success=False, error="Étoile non valide."), 400
        if current_user.id == pub.user_id:
            return jsonify(success=False, error="Vous ne pouvez pas vous envoyer une étoile."), 400
        quantite = min(max(request.form.get('quantite', 1, type=int), 1), 5)
    elif kind == 'avatar':
        # le serveur utilise l'avatar du compte ; seul le cadre (forme) est choisi par l'utilisateur
        emoji = (request.form.get('emoji') or 'circle').strip()
        if emoji not in ('circle', 'rounded', 'heart', 'star', 'hex'):
            emoji = 'circle'

    racine_id = cible_id = cible_user_id = None
    cible_nom = None
    parent_brut = request.form.get('parent_id')
    if parent_brut not in (None, '', '0'):
        try:
            cible = Commentaire.query.get(int(parent_brut))
        except (TypeError, ValueError):
            cible = None
        if not cible or cible.publication_id != pub_id:
            return jsonify(success=False, error='Le commentaire auquel vous répondez est introuvable.'), 404
        racine_id = cible.parent_id or cible.id
        cible_id, cible_user_id = cible.id, cible.user_id
        cible_u = User.query.get(cible.user_id)
        cible_nom = cible_u.nom_complet if cible_u else None

    if kind == 'etoile':
        texte = legende or f"A envoyé {quantite} Étoile{'s' if quantite > 1 else ''}"
    elif kind == 'sticker':
        texte = legende or emoji
    else:
        texte = legende or _CP_TEXTE_REPLI[kind]

    chemin = None
    try:
        if nom_ecrit:
            chemin = os.path.join(UPLOAD_COMMENT_MEDIA_FOLDER, nom_ecrit)
            with open(chemin, 'wb') as fh:
                fh.write(data)
        commentaire = Commentaire(contenu=texte, user_id=current_user.id, publication_id=pub_id,
                                  parent_id=racine_id, reply_to_id=cible_id, reply_to_user_id=cible_user_id)
        db.session.add(commentaire)
        db.session.flush()
        db.session.add(CommentaireMedia(commentaire_id=commentaire.id, kind=kind, fichier=fichier,
                                        url=url, emoji=emoji, quantite=quantite))
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        try:
            if chemin and os.path.exists(chemin):
                os.remove(chemin)
        except OSError:
            pass
        print(f"DEBUG: commentaire média non enregistré : {e}")
        return jsonify(success=False, error="Impossible d'enregistrer le commentaire."), 500

    try:
        deja = set()
        if cible_user_id and cible_user_id != current_user.id:
            if notifier(cible_user_id, 'reply', current_user, cible=('comment', cible_id), pub_id=pub_id, comment_id=commentaire.id):
                deja.add(cible_user_id)
        if pub.user_id not in deja:
            notifier(pub.user_id, 'comment', current_user, cible=('post', pub_id), pub_id=pub_id, comment_id=commentaire.id)
        deja.add(pub.user_id)
        if legende:
            notifier_mentions(legende, current_user, pub_id=pub_id, exclure_ids=deja, comment_id=commentaire.id)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG notification commentaire média : {e}")

    item = _serialiser_commentaires([commentaire], pub)[0]
    return jsonify(success=True, comment=item, comments_count=Commentaire.query.filter_by(publication_id=pub_id).count())


@main_bp.route('/api/comment/<int:comment_id>/epingler', methods=['POST'])
@login_required
def api_epingler_commentaire(comment_id):
    c = Commentaire.query.get_or_404(comment_id)
    pub = Publication.query.get_or_404(c.publication_id)
    if pub.user_id != current_user.id:
        return jsonify(success=False, error="Seul l'auteur de la publication peut épingler un commentaire."), 403
    if c.parent_id:
        return jsonify(success=False, error='Seul un commentaire principal peut être épinglé.'), 400
    ligne = CommentaireEpingle.query.filter_by(publication_id=pub.id).first()
    if ligne and ligne.commentaire_id == c.id:
        db.session.delete(ligne)                          # déjà épinglé : on désépingle
        db.session.commit()
        return jsonify(success=True, pinned=False)
    if ligne:
        ligne.commentaire_id = c.id
    else:
        db.session.add(CommentaireEpingle(publication_id=pub.id, commentaire_id=c.id))
    db.session.commit()
    return jsonify(success=True, pinned=True)


# ── Recherche de GIF (Giphy) — la clé reste côté serveur ────────────────────
_CP_GIF_CACHE = {}


@main_bp.route('/api/gifs', methods=['GET'])
@login_required
def api_gifs():
    cle = os.getenv('GIPHY_API_KEY', '').strip()
    if not cle:
        return jsonify(success=False, code='non_configure',
                       error="Les GIF ne sont pas encore activés (clé GIPHY_API_KEY manquante)."), 503
    q = (request.args.get('q') or '').strip()[:60]
    pos = max(request.args.get('pos', 0, type=int), 0)
    ident = (q.lower(), pos)
    en_cache = _CP_GIF_CACHE.get(ident)
    if en_cache and time.time() - en_cache[0] < 300:
        return jsonify(en_cache[1])
    try:
        if q:
            r = requests.get('https://api.giphy.com/v1/gifs/search', timeout=6,
                             params={'api_key': cle, 'q': q, 'limit': 24, 'offset': pos, 'rating': 'pg-13', 'lang': 'fr'})
        else:
            r = requests.get('https://api.giphy.com/v1/gifs/trending', timeout=6,
                             params={'api_key': cle, 'limit': 24, 'offset': pos, 'rating': 'pg-13'})
        r.raise_for_status()
        brut = r.json()
    except Exception:
        return jsonify(success=False, error='Service de GIF indisponible.'), 502
    items = []
    for g in brut.get('data', []):
        im = g.get('images', {})
        gros = im.get('fixed_height') or im.get('downsized') or {}
        petit = im.get('fixed_width_small') or im.get('fixed_width') or gros
        if gros.get('url') and petit.get('url'):
            items.append({'id': g.get('id'), 'titre': g.get('title') or 'GIF', 'url': gros['url'],
                          'apercu': petit['url'], 'w': int(petit.get('width') or 0), 'h': int(petit.get('height') or 0)})
    rep = {'success': True, 'gifs': items, 'next': pos + len(items)}
    if len(_CP_GIF_CACHE) > 200:
        _CP_GIF_CACHE.clear()
    _CP_GIF_CACHE[ident] = (time.time(), rep)
    return jsonify(rep)


