class ChatGroupeMeta(db.Model):
    __tablename__ = 'chat_groupe_meta'
    groupe_id = db.Column(db.Integer, primary_key=True)
    reaction_idx = db.Column(db.Integer, default=0, nullable=False)        # index dans _MSGR_REACTIONS


class ChatGroupePerso(db.Model):
    __tablename__ = 'chat_groupe_perso'
    id = db.Column(db.Integer, primary_key=True)
    groupe_id = db.Column(db.Integer, nullable=False, index=True)
    user_id = db.Column(db.Integer, nullable=False, index=True)
    pseudo = db.Column(db.String(40), nullable=True)                       # pseudo de ce membre dans le groupe
    sourdine = db.Column(db.Boolean, default=False, nullable=False)       # notifications coupées par ce membre


class ChatGroupeSignalement(db.Model):
    __tablename__ = 'chat_groupe_signalement'
    id = db.Column(db.Integer, primary_key=True)
    groupe_id = db.Column(db.Integer, nullable=False, index=True)
    user_id = db.Column(db.Integer, nullable=False)
    motif = db.Column(db.String(120), nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)


