_msgr_gx_ok = False


def _msgr_gx_assurer():
    global _msgr_gx_ok
    if _msgr_gx_ok:
        return
    try:
        for t in (ChatGroupeMeta.__table__, ChatGroupePerso.__table__, ChatGroupeSignalement.__table__,
                  ChatGroupeMsgExtra.__table__, ChatGroupeMsgMasque.__table__,
                  ChatGroupePhoto.__table__, ChatGroupeMsgMedia.__table__, ChatGroupeMsgReponse.__table__,
                  ChatAppel.__table__, ChatAppelPart.__table__, ChatAppelSignal.__table__):
            t.create(bind=db.engine, checkfirst=True)
        _msgr_gx_ok = True
    except Exception as e:
        print(f"DEBUG: création tables groupes (paramètres) impossible : {e}")


def _msgr_gx_perso(gid, uid, creer=False):
    p = ChatGroupePerso.query.filter_by(groupe_id=gid, user_id=uid).first()
    if not p and creer:
        p = ChatGroupePerso(groupe_id=gid, user_id=uid, sourdine=False)
        db.session.add(p)
    return p


def _msgr_gx_reaction(gid):
    meta = db.session.get(ChatGroupeMeta, gid)
    i = meta.reaction_idx if meta else 0
    return _MSGR_REACTIONS[i] if 0 <= i < len(_MSGR_REACTIONS) else _MSGR_REACTIONS[0]


def _msgr_gx_groupe_json(g, uid):
    """Même contenu que _msgr_groupe_json + les champs attendus par la page des paramètres."""
    j = _msgr_groupe_json(g, uid)
    createur = db.session.get(User, g.createur_id)
    j['createur'] = {'id': g.createur_id, 'nom': _msgr_nom(createur)}
    j['reaction'] = _msgr_gx_reaction(g.id)
    p = _msgr_gx_perso(g.id, uid)
    j['sourdine'] = bool(p and p.sourdine)
    return j


def _msgr_gx_sys(gid, texte):
    db.session.add(ChatGroupeMessage(groupe_id=gid, systeme=True, contenu=texte[:4000]))
    g = db.session.get(ChatGroupe, gid)
    if g:
        g.dernier_msg_at = datetime.utcnow()


@main_bp.route('/api/msgr/groupes/<int:gid>/membres')
@_msgr_auth
def msgr_gx_membres(gid):
    _msgr_gx_assurer()
    uid = session['user_id']
    moi = _msgr_membre(gid, uid)
    g = db.session.get(ChatGroupe, gid)
    if not moi or not g:
        return jsonify(success=False, error="Groupe introuvable."), 404
    pseudos = {p.user_id: p.pseudo for p in ChatGroupePerso.query.filter_by(groupe_id=gid).all() if p.pseudo}
    membres = []
    for m in ChatGroupeMembre.query.filter_by(groupe_id=gid).order_by(ChatGroupeMembre.id.asc()).all():
        u = db.session.get(User, m.user_id)
        if not u:
            continue
        j = _msgr_user_json(u)
        j['role'] = m.role
        j['moi'] = (u.id == uid)
        j['createur'] = (u.id == g.createur_id)
        j['pseudo'] = pseudos.get(u.id, '')
        membres.append(j)
    return jsonify(success=True, groupe=_msgr_gx_groupe_json(g, uid), membres=membres, mon_role=moi.role)


@main_bp.route('/api/msgr/groupes/<int:gid>/membres/ajouter', methods=['POST'])
@_msgr_auth
def msgr_gx_ajouter(gid):
    _msgr_gx_assurer()
    uid = session['user_id']
    moi = _msgr_membre(gid, uid)
    g = db.session.get(ChatGroupe, gid)
    if not moi or not g:
        return jsonify(success=False, error="Groupe introuvable."), 404
    data = request.get_json(silent=True) or {}
    try:
        ids = {int(x) for x in (data.get('membres') or [])}
    except (TypeError, ValueError):
        return jsonify(success=False, error="Participants invalides."), 400
    ids.discard(uid)
    if not ids:
        return jsonify(success=False, error="Choisissez au moins un participant."), 400
    if not ids.issubset(_msgr_ids_amis(uid)):
        return jsonify(success=False, error="Vous ne pouvez ajouter que vos amis."), 403
    existants = {m.user_id for m in ChatGroupeMembre.query.filter_by(groupe_id=gid).all()}
    nouveaux = ids - existants
    if not nouveaux:
        return jsonify(success=False, error="Ces personnes sont déjà dans le groupe."), 400
    if len(existants) + len(nouveaux) > 100:
        return jsonify(success=False, error="Un groupe ne peut pas dépasser 100 membres."), 400
    noms = []
    for i in nouveaux:
        u = db.session.get(User, i)
        if not u:
            continue
        db.session.add(ChatGroupeMembre(groupe_id=gid, user_id=i, role='membre', vu=False, ajoute_par=uid))
        noms.append(_msgr_nom(u))
    if not noms:
        return jsonify(success=False, error="Utilisateurs introuvables."), 400
    _msgr_gx_sys(gid, f"{_msgr_nom(db.session.get(User, uid))} a ajouté {', '.join(noms)} au groupe.")
    db.session.commit()
    return jsonify(success=True, ajoutes=len(noms))


@main_bp.route('/api/msgr/groupes/<int:gid>/membres/<int:cible>/retirer', methods=['POST'])
@_msgr_auth
def msgr_gx_retirer(gid, cible):
    _msgr_gx_assurer()
    uid = session['user_id']
    moi = _msgr_membre(gid, uid)
    g = db.session.get(ChatGroupe, gid)
    if not moi or not g:
        return jsonify(success=False, error="Groupe introuvable."), 404
    if moi.role != 'admin':
        return jsonify(success=False, error="Seuls les administrateurs peuvent retirer des membres."), 403
    if cible == uid:
        return jsonify(success=False, error="Utilisez « Quitter le groupe »."), 400
    if cible == g.createur_id:
        return jsonify(success=False, error="Le créateur du groupe ne peut pas être retiré."), 403
    m = _msgr_membre(gid, cible)
    if not m:
        return jsonify(success=False, error="Ce membre n'est plus dans le groupe."), 404
    u = db.session.get(User, cible)
    db.session.delete(m)
    ChatArchive.query.filter_by(user_id=cible, kind='groupe', cible_id=gid).delete()
    ChatGroupePerso.query.filter_by(groupe_id=gid, user_id=cible).delete()
    _msgr_gx_sys(gid, f"{_msgr_nom(db.session.get(User, uid))} a retiré {_msgr_nom(u)} du groupe.")
    db.session.commit()
    return jsonify(success=True)


@main_bp.route('/api/msgr/groupes/<int:gid>/membres/<int:cible>/admin', methods=['POST'])
@_msgr_auth
def msgr_gx_admin(gid, cible):
    _msgr_gx_assurer()
    uid = session['user_id']
    moi = _msgr_membre(gid, uid)
    g = db.session.get(ChatGroupe, gid)
    if not moi or not g:
        return jsonify(success=False, error="Groupe introuvable."), 404
    if moi.role != 'admin':
        return jsonify(success=False, error="Réservé aux administrateurs."), 403
    if cible == g.createur_id:
        return jsonify(success=False, error="Le rôle du créateur ne peut pas être modifié."), 403
    m = _msgr_membre(gid, cible)
    if not m:
        return jsonify(success=False, error="Ce membre n'est plus dans le groupe."), 404
    devient = bool((request.get_json(silent=True) or {}).get('admin'))
    m.role = 'admin' if devient else 'membre'
    nom = _msgr_nom(db.session.get(User, cible))
    _msgr_gx_sys(gid, f"{nom} est maintenant administrateur." if devient else f"{nom} n'est plus administrateur.")
    db.session.commit()
    return jsonify(success=True, role=m.role)


