@main_bp.route('/api/msgr/groupes/<int:gid>/photo', methods=['POST'])
@_msgr_auth
def msgr_gx_photo(gid):
    """Change la photo du groupe (tout membre peut le faire, comme pour le nom)."""
    _msgr_gx_assurer()
    uid = session['user_id']
    g = db.session.get(ChatGroupe, gid)
    if not g or not _msgr_membre(gid, uid):
        return jsonify(success=False, error="Groupe introuvable."), 404
    nom, ext, err = _msgr_gx_enregistrer(request.files.get('fichier'), _MSGR_EXT_IMG, 8 * 1024 * 1024)
    if err:
        return jsonify(success=False, error=err + " Choisissez une image JPG, PNG ou WEBP."), 400
    p = db.session.get(ChatGroupePhoto, gid)
    ancien = p.fichier if p else None
    if p:
        p.fichier = nom
        p.updated_at = datetime.utcnow()
    else:
        db.session.add(ChatGroupePhoto(groupe_id=gid, fichier=nom))
    _msgr_gx_sys(gid, f"{_msgr_nom(db.session.get(User, uid))} a changé la photo du groupe.")
    db.session.commit()
    if ancien:
        try:
            base = current_app.config.get('UPLOAD_FOLDER') or os.path.join('static', 'uploads')
            os.remove(os.path.join(base, 'msgr_groupes', ancien))
        except OSError:
            pass
    return jsonify(success=True, photo=_msgr_gx_url(nom))


@main_bp.route('/api/msgr/groupes/<int:gid>/media', methods=['POST'])
@_msgr_auth
def msgr_gx_media(gid):
    """Envoie une photo ou un message vocal dans le groupe."""
    _msgr_gx_assurer()
    uid = session['user_id']
    m = _msgr_membre(gid, uid)
    g = db.session.get(ChatGroupe, gid)
    if not m or not g:
        return jsonify(success=False, error="Groupe introuvable."), 404
    nom, ext, err = _msgr_gx_enregistrer(request.files.get('fichier'), _MSGR_EXT_IMG | _MSGR_EXT_AUDIO, 25 * 1024 * 1024)
    if err:
        return jsonify(success=False, error=err), 400
    type_ = 'image' if ext in _MSGR_EXT_IMG else 'audio'
    msg = ChatGroupeMessage(groupe_id=gid, expediteur_id=uid,
                            contenu='📷 Photo' if type_ == 'image' else '🎤 Message vocal')
    db.session.add(msg)
    g.dernier_msg_at = datetime.utcnow()
    db.session.flush()
    db.session.add(ChatGroupeMsgMedia(message_id=msg.id, groupe_id=gid, type=type_, fichier=nom))
    _msgr_gx_lier_reponse(msg, gid, request.form.get('reponse_a'))
    m.dernier_lu_id = msg.id
    m.vu = True
    db.session.commit()
    return jsonify(success=True, message=_msgr_msg_json(msg, uid, {}))


