@main_bp.route('/parametres/compte/supprimer')
def compte_supprimer_page():
    user = _cc_exige_connecte()
    if user is None:
        return redirect(url_for('main.login'))
    return render_template('compte_supprimer.html', motifs=CC_MOTIFS_SUPPRESSION,
                           jours=DELAI_SUPPRESSION_JOURS, est_pdg=bool(getattr(user, 'is_pdg', False)),
                           csrf_token=str(_fn_csrf_token()))


def _cc_motifs_valides(brut, autorises, minimum):
    if not isinstance(brut, list):
        return None
    codes = {c for c, _ in autorises}
    propres = []
    for m in brut:
        if isinstance(m, str) and m in codes and m not in propres:
            propres.append(m)
    return propres if len(propres) >= minimum else None


@main_bp.route('/api/compte/desactiver', methods=['POST'])
def api_compte_desactiver():
    _r = _cc_csrf_refuse()
    if _r is not None:
        return _r
    user = _cc_exige_connecte()
    if user is None:
        return jsonify(success=False, error="Session expirée. Reconnectez-vous."), 401
    if not _fn_rate_ok(f'cc_desact:{user.id}', 6, 600):
        return jsonify(success=False, error="Trop de tentatives. Réessayez dans quelques minutes."), 429
    data = _cc_json_requis()
    motifs = _cc_motifs_valides(data.get('motifs'), CC_MOTIFS_DESACTIVATION, 1)
    if motifs is None:
        return jsonify(success=False, error="Choisissez au moins une raison."), 400
    if not _cc_mdp_ok(user, data.get('password')):
        return jsonify(success=False, error="Mot de passe incorrect."), 403
    if getattr(user, 'is_pdg', False):
        return jsonify(success=False, error="Ce compte administrateur ne peut pas être désactivé ici."), 403
    if not _cc_assurer_tables():
        return jsonify(success=False, error="Service momentanément indisponible."), 503
    try:
        db.session.add(CompteRetour(user_id=user.id, type='desactivation', motifs=json.dumps(motifs),
                                    commentaire=(str(data.get('commentaire') or '')[:1000] or None)))
        etat = db.session.get(CompteEtat, user.id)
        if etat is None:
            etat = CompteEtat(user_id=user.id)
            db.session.add(etat)
        etat.etat, etat.origine, etat.demande_le, etat.echeance = 'desactive', 'utilisateur', datetime.utcnow(), None
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: désactivation impossible : {e}")
        return jsonify(success=False, error="Impossible de désactiver le compte pour le moment."), 500
    _cc_invalider()
    _cc_audit(user.id, 'compte_desactive', 'Compte désactivé par son propriétaire')
    _cc_quitter(user)
    return jsonify(success=True, redirect=url_for('main.login', compte='desactive'))


@main_bp.route('/api/compte/supprimer', methods=['POST'])
def api_compte_supprimer():
    _r = _cc_csrf_refuse()
    if _r is not None:
        return _r
    user = _cc_exige_connecte()
    if user is None:
        return jsonify(success=False, error="Session expirée. Reconnectez-vous."), 401
    if not _fn_rate_ok(f'cc_suppr:{user.id}', 6, 600):
        return jsonify(success=False, error="Trop de tentatives. Réessayez dans quelques minutes."), 429
    data = _cc_json_requis()
    motifs = _cc_motifs_valides(data.get('motifs'), CC_MOTIFS_SUPPRESSION, 3)
    if motifs is None:
        return jsonify(success=False, step=1, error="Choisissez au moins 3 raisons."), 400
    principal = data.get('principal')
    if principal not in motifs:
        return jsonify(success=False, step=2, error="Indiquez votre raison principale parmi celles choisies."), 400
    rep = data.get('reponses') if isinstance(data.get('reponses'), dict) else {}
    for cle, permis in CC_QUESTIONS_SUPPRESSION.items():
        if rep.get(cle) not in permis:
            return jsonify(success=False, step=2, error="Répondez à toutes les questions de l'étape 2."), 400
    accuses = data.get('accuses') if isinstance(data.get('accuses'), list) else []
    if any(a not in accuses for a in CC_ACCUSES_SUPPRESSION):
        return jsonify(success=False, step=2, error="Cochez toutes les confirmations."), 400
    if (data.get('confirmation') or '').strip() != 'SUPPRIMER':
        return jsonify(success=False, step=3, error="Tapez exactement SUPPRIMER pour confirmer."), 400
    if not _cc_mdp_ok(user, data.get('password')):
        return jsonify(success=False, step=3, error="Mot de passe incorrect."), 403
    if getattr(user, 'is_pdg', False):
        return jsonify(success=False, error="Le compte administrateur ne peut pas être supprimé ici."), 403
    if not _cc_assurer_tables():
        return jsonify(success=False, error="Service momentanément indisponible."), 503
    echeance = datetime.utcnow() + timedelta(days=DELAI_SUPPRESSION_JOURS)
    try:
        reponses = {k: rep[k] for k in CC_QUESTIONS_SUPPRESSION}
        reponses['principal'] = principal
        db.session.add(CompteRetour(user_id=user.id, type='suppression', motifs=json.dumps(motifs),
                                    reponses=json.dumps(reponses),
                                    commentaire=(str(data.get('commentaire') or '')[:1000] or None)))
        etat = db.session.get(CompteEtat, user.id)
        if etat is None:
            etat = CompteEtat(user_id=user.id)
            db.session.add(etat)
        etat.etat, etat.origine, etat.demande_le, etat.echeance = 'suppression', 'utilisateur', datetime.utcnow(), echeance
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: suppression programmée impossible : {e}")
        return jsonify(success=False, error="Impossible de programmer la suppression pour le moment."), 500
    _cc_invalider()
    _cc_audit(user.id, 'compte_suppression_programmee', f"Suppression définitive prévue le {echeance:%d/%m/%Y %H:%M} UTC")
    _cc_quitter(user)
    return jsonify(success=True, redirect=url_for('main.login', compte='suppression'))


# ── Page de contrôle à la reconnexion (horloge / mise en veille) ─────────────────
def _cc_contexte_gate():
    uid = session.get('compte_gate_uid')
    ts = session.get('compte_gate_ts') or 0
    if not uid or _cc_time.time() - ts > 1200:
        return None
    user = db.session.get(User, uid)
    etat = _cc_etat(uid)
    if user is None or etat is None:
        return None
    return user, etat


@main_bp.route('/login/compte', methods=['GET'])
@no_cache
def compte_gate():
    ctx = _cc_contexte_gate()
    if ctx is None:
        session.pop('compte_gate_uid', None)
        return redirect(url_for('main.login'))
    user, etat = ctx
    maintenant = datetime.utcnow()
    peut_reactiver = (etat.etat == 'desactive' or (etat.etat == 'suppression' and etat.origine == 'utilisateur'
                                                  and etat.echeance and etat.echeance > maintenant))
    avatar = user.avatar or 'default_avatar.png'
    return render_template(
        'compte_gate.html', etat=etat.etat, origine=etat.origine, csrf_token=str(_fn_csrf_token()),
        nom=user.nom_complet or user.username, avatar_url=url_for('static', filename='uploads/' + avatar),
        echeance_ms=_cc_ms(etat.echeance) if etat.echeance else None, serveur_ms=_cc_ms(maintenant),
        demande_ms=_cc_ms(etat.demande_le), total_ms=DELAI_SUPPRESSION_JOURS * 86400 * 1000,
        demande_txt=etat.demande_le.strftime('%d/%m/%Y'),
        peut_reactiver=peut_reactiver, exige_naissance=bool(user.birth_date),
        exige_contact=bool((user.email or '').strip() or (user.phone or '').strip()),
        contact_type=('e-mail' if (user.email or '').strip() else 'numéro de téléphone'))


def _cc_chiffres(s):
    return re.sub(r'\D', '', s or '')


@main_bp.route('/login/compte/action', methods=['POST'])
@no_cache
def compte_gate_action():
    _r = _cc_csrf_refuse()
    if _r is not None:
        return _r
    ctx = _cc_contexte_gate()
    if ctx is None:
        return jsonify(success=False, error="Session expirée.", redirect=url_for('main.login')), 401
    user, etat = ctx
    data = _cc_json_requis()
    action = data.get('action')
    if action == 'quitter':
        session.clear()
        return jsonify(success=True, redirect=url_for('main.login'))
    if action != 'reactiver':
        return jsonify(success=False, error="Action inconnue."), 400
    if not (_fn_rate_ok(f'cc_gate:{user.id}', 5, 900) and _fn_rate_ok(f'cc_gate_ip:{_cc_ip()}', 20, 900)):
        return jsonify(success=False, error="Trop de tentatives. Patientez 15 minutes avant de réessayer."), 429
    maintenant = datetime.utcnow()
    if etat.etat == 'commemoratif' or etat.origine == 'deces':
        return jsonify(success=False, error="Ce compte ne peut pas être réactivé."), 403
    if etat.etat == 'suppression' and (not etat.echeance or etat.echeance <= maintenant):
        return jsonify(success=False, error="Le délai est écoulé : la suppression est en cours."), 403
    # Vérification renforcée : TOUS les éléments doivent correspondre (message volontairement identique en cas d'échec)
    ok = _cc_mdp_ok(user, data.get('password'))
    ok = ok and (str(data.get('username') or '').strip().lower() == (user.username or '').strip().lower())
    if user.birth_date:
        ok = ok and (str(data.get('birth_date') or '').strip() == user.birth_date.strftime('%Y-%m-%d'))
    saisi = str(data.get('contact') or '').strip()
    if (user.email or '').strip():
        ok = ok and saisi.lower() == user.email.strip().lower()
    elif (user.phone or '').strip():
        a, b = _cc_chiffres(saisi), _cc_chiffres(user.phone)
        ok = ok and len(a) >= 6 and (a == b or a.endswith(b[-8:]) or b.endswith(a[-8:]))
    if not ok:
        _cc_audit(user.id, 'compte_reactivation_echec', f"IP {_cc_ip()}")
        return jsonify(success=False, error="Les informations ne correspondent pas. Vérifiez chaque champ."), 403
    try:
        db.session.delete(db.session.get(CompteEtat, user.id))
        user.is_online = True
        user.last_seen = datetime.utcnow()
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: réactivation impossible : {e}")
        return jsonify(success=False, error="Réactivation impossible pour le moment."), 500
    _cc_invalider()
    session.clear()
    session['user_id'] = user.id
    login_user(user)
    _cc_audit(user.id, 'compte_reactive', 'Compte réactivé après vérification')
    return jsonify(success=True, redirect=url_for('main.feed'))


# ── Décès : formulaire d'un proche + validation par l'équipe (PDG) ───────────────
_CC_LIENS = ('Conjoint(e)', 'Parent', 'Enfant', 'Frère / sœur', 'Autre membre de la famille', 'Ami(e)', 'Autre')
_CC_EXT_PREUVE = {
    'jpg': 'image', 'jpeg': 'image', 'png': 'image', 'webp': 'image', 'heic': 'image',
    'mp4': 'video', 'mov': 'video', 'webm': 'video', 'm4v': 'video', '3gp': 'video',
    'pdf': 'document'}
_CC_TAILLE_PREUVE = 40 * 1024 * 1024


@main_bp.route('/parametres/compte/deces')
def compte_deces_page():
    user = _cc_exige_connecte()
    if user is None:
        return redirect(url_for('main.login'))
    mes = []
    if _cc_assurer_tables():
        for d in CompteDeces.query.filter_by(declarant_id=user.id).order_by(CompteDeces.id.desc()).limit(10).all():
            cible = db.session.get(User, d.cible_id)
            mes.append({'ref': f"DC-{d.id:05d}", 'nom': (cible.nom_complet or cible.username) if cible else 'Profil supprimé',
                        'statut': d.statut, 'date': d.cree_le.strftime('%d/%m/%Y'), 'motif': d.motif_refus})
    return render_template('compte_deces.html', liens=_CC_LIENS, mes_demandes=mes, csrf_token=str(_fn_csrf_token()))


@main_bp.route('/api/compte/deces', methods=['POST'])
def api_compte_deces():
    _r = _cc_csrf_refuse()
    if _r is not None:
        return _r
    user = _cc_exige_connecte()
    if user is None:
        return jsonify(success=False, error="Session expirée. Reconnectez-vous."), 401
    if not _fn_rate_ok(f'cc_deces:{user.id}', 3, 3600):
        return jsonify(success=False, error="Trop de demandes. Réessayez plus tard."), 429
    f = request.form
    cible_txt = (f.get('cible') or '').strip().lstrip('@')
    cible_txt = cible_txt.rstrip('/').split('/')[-1] if '/' in cible_txt else cible_txt
    declarant_nom = (f.get('declarant_nom') or '').strip()[:150]
    lien = (f.get('lien') or '').strip()
    contact = (f.get('contact') or '').strip()[:150]
    souhait = (f.get('souhait') or '').strip()
    if not cible_txt or not declarant_nom or not contact or lien not in _CC_LIENS or souhait not in ('commemoratif', 'suppression'):
        return jsonify(success=False, error="Remplissez tous les champs obligatoires."), 400
    if f.get('certifie') != '1':
        return jsonify(success=False, error="Vous devez certifier que ces informations sont exactes."), 400
    cible = User.query.filter(db.func.lower(User.username) == cible_txt.lower()).first()
    if cible is None:
        return jsonify(success=False, error="Aucun profil ne correspond à ce nom d'utilisateur."), 404
    if cible.id == user.id:
        return jsonify(success=False, error="Vous ne pouvez pas signaler votre propre profil."), 400
    if getattr(cible, 'is_pdg', False):
        return jsonify(success=False, error="Ce profil ne peut pas être traité par ce formulaire. Contactez l'assistance."), 403
    fichier = request.files.get('preuve')
    if not fichier or not fichier.filename:
        return jsonify(success=False, error="Ajoutez une preuve du décès (photo, vidéo ou document)."), 400
    ext = fichier.filename.rsplit('.', 1)[-1].lower() if '.' in fichier.filename else ''
    if ext not in _CC_EXT_PREUVE:
        return jsonify(success=False, error="Format non accepté. Utilisez une photo, une vidéo (MP4, MOV, WEBM) ou un PDF."), 400
    if request.content_length and request.content_length > _CC_TAILLE_PREUVE + 1024 * 1024:
        return jsonify(success=False, error="Fichier trop lourd (40 Mo maximum)."), 413
    date_deces = None
    if (f.get('date_deces') or '').strip():
        try:
            date_deces = datetime.strptime(f.get('date_deces').strip(), '%Y-%m-%d').date()
            if date_deces > datetime.utcnow().date():
                return jsonify(success=False, error="La date du décès ne peut pas être dans le futur."), 400
        except ValueError:
            return jsonify(success=False, error="Date invalide."), 400
    if not _cc_assurer_tables():
        return jsonify(success=False, error="Service momentanément indisponible."), 503
    if CompteDeces.query.filter_by(cible_id=cible.id, declarant_id=user.id, statut='en_attente').first():
        return jsonify(success=False, error="Vous avez déjà une demande en cours pour ce profil."), 409
    base = current_app.config.get('UPLOAD_FOLDER')
    if not base:
        return jsonify(success=False, error="Stockage indisponible."), 503
    dossier = os.path.join(base, 'deces_preuves')
    os.makedirs(dossier, exist_ok=True)
    nom_fichier = f"{uuid.uuid4().hex}.{ext}"
    chemin = os.path.join(dossier, nom_fichier)
    fichier.save(chemin)
    if os.path.getsize(chemin) > _CC_TAILLE_PREUVE:
        os.remove(chemin)
        return jsonify(success=False, error="Fichier trop lourd (40 Mo maximum)."), 413
    try:
        d = CompteDeces(cible_id=cible.id, declarant_id=user.id, declarant_nom=declarant_nom, lien=lien, contact=contact,
                        date_deces=date_deces, preuve_fichier=nom_fichier, preuve_type=_CC_EXT_PREUVE[ext], souhait=souhait,
                        personne_confiance=(f.get('personne_confiance') or '').strip()[:300] or None,
                        instructions=(f.get('instructions') or '').strip()[:2000] or None)
        db.session.add(d)
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        try:
            os.remove(chemin)
        except Exception:
            pass
        print(f"DEBUG: signalement de décès impossible : {e}")
        return jsonify(success=False, error="Impossible d'enregistrer la demande pour le moment."), 500
    _cc_audit(user.id, 'deces_signale', f"Signalement DC-{d.id:05d}")
    return jsonify(success=True, ref=f"DC-{d.id:05d}")


def _cc_exige_pdg():
    user = _cc_exige_connecte()
    if user is None or not getattr(user, 'is_pdg', False):
        abort(404)
    return user


@main_bp.route('/pdg/deces')
def pdg_deces():
    _cc_exige_pdg()
    _cc_assurer_tables()
    lignes = []
    for d in CompteDeces.query.order_by(CompteDeces.statut.asc(), CompteDeces.id.desc()).limit(100).all():
        cible = db.session.get(User, d.cible_id)
        lignes.append({'d': d, 'ref': f"DC-{d.id:05d}",
                       'cible': (cible.nom_complet or cible.username) if cible else 'Profil supprimé',
                       'cible_user': cible.username if cible else '',
                       'cible_naissance': cible.birth_date.strftime('%d/%m/%Y') if cible and cible.birth_date else '—'})
    comptes = []
    for e in CompteEtat.query.filter(CompteEtat.etat.in_(('suppression', 'commemoratif'))).order_by(CompteEtat.demande_le.desc()).limit(100).all():
        u = db.session.get(User, e.user_id)
        comptes.append({'etat': e, 'nom': (u.nom_complet or u.username) if u else 'Profil supprimé'})
    return render_template('compte_deces_admin.html', lignes=lignes, comptes=comptes, jours=DELAI_SUPPRESSION_JOURS,
                           csrf_token=str(_fn_csrf_token()))


