@main_bp.route('/api/pdg/deces/<int:did>/decision', methods=['POST'])
def api_pdg_deces_decision(did):
    _r = _cc_csrf_refuse()
    if _r is not None:
        return _r
    admin = _cc_exige_pdg()
    d = CompteDeces.query.get_or_404(did)
    data = _cc_json_requis()
    decision = data.get('decision')
    if d.statut != 'en_attente':
        return jsonify(success=False, error="Cette demande a déjà été traitée."), 409
    if decision not in ('valide', 'refuse'):
        return jsonify(success=False, error="Décision invalide."), 400
    try:
        if decision == 'refuse':
            d.statut, d.motif_refus = 'refuse', (str(data.get('motif') or '').strip()[:300] or "Preuve insuffisante.")
        else:
            d.statut = 'valide'
            etat = db.session.get(CompteEtat, d.cible_id)
            if etat is None:
                etat = CompteEtat(user_id=d.cible_id)
                db.session.add(etat)
            etat.origine, etat.demande_le = 'deces', datetime.utcnow()
            if d.souhait == 'suppression':
                etat.etat, etat.echeance = 'suppression', datetime.utcnow() + timedelta(days=DELAI_SUPPRESSION_JOURS)
            else:
                etat.etat, etat.echeance = 'commemoratif', None
        d.traite_le, d.traite_par = datetime.utcnow(), admin.id
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: décision décès impossible : {e}")
        return jsonify(success=False, error="Enregistrement impossible."), 500
    _cc_invalider()
    _cc_audit(admin.id, 'deces_decision', f"DC-{d.id:05d} : {decision}")
    return jsonify(success=True)


@main_bp.route('/api/pdg/compte/<int:uid>/annuler', methods=['POST'])
def api_pdg_compte_annuler(uid):
    """Annule une suppression / un état commémoratif décidé par erreur (réservé au PDG)."""
    _r = _cc_csrf_refuse()
