# ── Liste « profils enregistrés sur cet appareil » (login.html) : état + compte à rebours ──────────
@main_bp.route('/api/appareil/comptes-etat', methods=['POST'])
def api_appareil_comptes_etat():
    """Pour chaque profil enregistré (jeton signé, comme /api/appareil/resume) : état du compte
    (veille, suppression, commémoratif) et échéance, afin d'afficher le compte à rebours."""
    import hashlib
    from itsdangerous import URLSafeTimedSerializer
    if not _fn_rate_ok('cc_etat:' + (request.remote_addr or ''), 60, 300):
        return jsonify({'etats': {}}), 429
    ser = URLSafeTimedSerializer(current_app.config['SECRET_KEY'], salt='facenet-appareil')
    jetons = (request.get_json(silent=True) or {}).get('tokens')
    etats = {}
    for tok in (jetons if isinstance(jetons, list) else [])[:8]:
        try:
            p = ser.loads(tok, max_age=60 * 60 * 24 * 60)
            user = db.session.get(User, p.get('u'))
            if not user or hashlib.sha256((user.password or '').encode('utf-8')).hexdigest()[:16] != p.get('f'):
                continue
            e = _cc_etat(user.id)
            if e is None:
                continue
            etats[str(tok)[-24:]] = {'etat': e.etat, 'origine': e.origine,
                                     'echeance_ms': _cc_ms(e.echeance) if e.echeance else None}
        except Exception:
            continue
    return jsonify({'etats': etats, 'serveur_ms': _cc_ms(datetime.utcnow())})


