# ══════════════════════════════════════════════════════════════════════
# AJOUT ADDITIF : protection anti-CSRF globale (contrôle de l'origine des écritures)
# Rien de ce qui précède n'est modifié. Toute requête POST/PUT/PATCH/DELETE envoyée par
# un AUTRE site (le navigateur l'indique dans Sec-Fetch-Site / Origin / Referer) est
# refusée ; les requêtes de ton propre site, les appels serveur-à-serveur (webhooks de
# paiement) et les clients sans en-tête d'origine continuent de passer comme avant.
#   • Désactiver en urgence : variable d'environnement FN_CSRF_ORIGINE=0
#   • Domaine supplémentaire autorisé (ex. proxy) : FN_ORIGINES_AUTORISEES=exemple.com,autre.com
# ══════════════════════════════════════════════════════════════════════
_CSRF_ORIG_METHODES = ('POST', 'PUT', 'PATCH', 'DELETE')
_CSRF_ORIG_EXEMPTES = ('/fapshi-webhook', '/api/notchpay/webhook')


def _csrf_orig_hotes_autorises():
    hotes = set()
    try:
        if request.host:
            hotes.add(request.host.strip().lower())
    except Exception:
        pass
    for h in (request.headers.get('X-Forwarded-Host', '') or '').split(','):
        h = h.strip().lower()
        if h:
            hotes.add(h)
    for h in (os.environ.get('FN_ORIGINES_AUTORISEES', '') or '').split(','):
        h = h.strip().lower()
        if h:
            hotes.add(h)
    return hotes


def _csrf_orig_est_refusee():
    """True si l'écriture vient manifestement d'un autre site."""
    site = (request.headers.get('Sec-Fetch-Site', '') or '').strip().lower()
    if site in ('same-origin', 'none'):
        return False
    source = (request.headers.get('Origin', '') or '').strip()
    if not source:
        source = (request.headers.get('Referer', '') or '').strip()
    if not source:
        # Aucun indice d'origine : on ne bloque que si le navigateur dit « autre site ».
        return site == 'cross-site'
    try:
        hote_source = (urlparse(source).netloc or '').strip().lower()
    except Exception:
        return True
    if not hote_source:          # « Origin: null » (iframe isolée, redirection inter-sites…)
        return True
    return hote_source not in _csrf_orig_hotes_autorises()


@main_bp.before_app_request
def _csrf_controle_origine():
    try:
        if request.method not in _CSRF_ORIG_METHODES:
            return None
        if os.environ.get('FN_CSRF_ORIGINE', '1') == '0':
            return None
        if request.path in _CSRF_ORIG_EXEMPTES:
            return None
        if not _csrf_orig_est_refusee():
            return None
        print(f"DEBUG CSRF : écriture refusée {request.method} {request.path} "
              f"(Origin={request.headers.get('Origin')!r}, Sec-Fetch-Site={request.headers.get('Sec-Fetch-Site')!r})")
        message = "Requête refusée : elle ne provient pas de ce site. Rechargez la page et réessayez."
        if request.path.startswith('/api/') or request.is_json or 'application/json' in (request.headers.get('Accept', '') or ''):
            return jsonify(success=False, status='error', error=message, message=message), 403
        return message, 403
    except Exception as e_csrf:
        print(f"DEBUG CSRF : contrôle d'origine ignoré ({e_csrf})")
        return None


# Cookie de session : « Lax » par défaut (sans écraser une valeur déjà choisie dans app.py).
@main_bp.record_once
def _csrf_cookies_lax(etat):
    try:
        for cle in ('SESSION_COOKIE_SAMESITE', 'REMEMBER_COOKIE_SAMESITE'):
            if not etat.app.config.get(cle):      # ne touche pas à une valeur déjà choisie
                etat.app.config[cle] = 'Lax'
    except Exception as e_lax:
        print(f"DEBUG CSRF : SameSite non appliqué ({e_lax})")

# ─────────────────────────────────────────────────────────────────────────────
# Route à COLLER dans ton fichier de routes (même blueprint que /api/musique/recherche).
# Elle reçoit l'enregistrement (chant / fredonnement) envoyé par l'écran « Chanson » de feed.html
# et interroge AudD (https://audd.io) : empreinte (musique jouée), reconnaissance de mélodie
# (chantée / fredonnée) puis recherche par paroles. Il faut un jeton AudD (gratuit pour tester) :
#     Windows (PowerShell) :  $env:AUDD_API_TOKEN = "ton_jeton"
# et :  pip install requests
# Remplace `main` par le nom de ton blueprint si besoin, et décommente @login_required
# si tu utilises flask_login (pour que personne d'autre ne consomme ton quota).
# ─────────────────────────────────────────────────────────────────────────────
 

AUDD_URL = 'https://api.audd.io/'


@main_bp.route('/api/musique/reconnaitre', methods=['POST'])
@login_required
def api_musique_reconnaitre():
    jeton = os.environ.get('AUDD_API_TOKEN', '').strip()
    if not jeton:
        return jsonify(success=False, results=[], error='Service de reconnaissance non configuré'), 503

    audio = request.files.get('audio')
    texte = (request.form.get('texte') or '').strip()
    trouves, vus = [], set()

    def journal(etape, r):
        # Rend visibles les refus d'AudD (jeton invalide, quota épuisé, format refusé…) au lieu d'un échec silencieux.
        try:
            if isinstance(r, dict) and r.get('status') != 'success':
                print(f"DEBUG AudD ({etape}) : {r.get('error')}")
            elif isinstance(r, dict) and not r.get('result'):
                print(f"DEBUG AudD ({etape}) : aucun résultat")
        except Exception:
            pass

    def ajouter(titre, artiste):
        titre, artiste = (titre or '').strip(), (artiste or '').strip()
        cle = (titre + '|' + artiste).lower()
        if titre and cle not in vus:
            vus.add(cle)
            trouves.append({'title': titre, 'artist': artiste})

    try:
        if audio:
            donnees = audio.read()
            if len(donnees) > 12 * 1024 * 1024:
                return jsonify(success=False, results=[], error='Fichier trop lourd'), 413

            # 1) Musique jouée près du téléphone (empreinte audio)
            r = requests.post(AUDD_URL, data={'api_token': jeton},
                              files={'file': ('extrait.wav', donnees, 'audio/wav')}, timeout=20).json()
            journal('empreinte', r)
            res = r.get('result') if isinstance(r, dict) else None
            if isinstance(res, dict):
                ajouter(res.get('title'), res.get('artist'))

            # 2) Chantée / fredonnée (reconnaissance de mélodie — précision non garantie par AudD)
            if not trouves:
                r = requests.post(AUDD_URL + 'recognizeWithOffset/', data={'api_token': jeton},
                                  files={'file': ('extrait.wav', donnees, 'audio/wav')}, timeout=20).json()
                journal('melodie', r)
                res = r.get('result') if isinstance(r, dict) else None
                if isinstance(res, dict):
                    for it in (res.get('list') or [])[:5]:
                        ajouter(it.get('title'), it.get('artist'))

        # 3) Paroles transcrites sur le téléphone
        if not trouves and len(texte.split()) >= 3:
            r = requests.post(AUDD_URL + 'findLyrics/', data={'api_token': jeton, 'q': texte[:200]}, timeout=20).json()
            journal('paroles', r)
            res = r.get('result') if isinstance(r, dict) else None
            if isinstance(res, list):
                for it in res[:5]:
                    ajouter(it.get('title'), it.get('artist'))
    except Exception as e_reco:
        print(f"DEBUG AudD : appel impossible ({e_reco})")
        return jsonify(success=False, results=[], error='Service de reconnaissance indisponible'), 502

    return jsonify(success=True, results=trouves[:5])

# =============================================================================
# À COLLER DANS route.py (blueprint "main") — recherche de chansons karaoké
# Imports à ajouter en haut de route.py s'ils n'y sont pas déjà :
#   import json, os, re, subprocess, unicodedata
#   from flask import current_app, jsonify, request
# Catalogue : instance/karaoke_catalogue.json (voir karaoke_catalogue.exemple.json)
# =============================================================================

TOLERANCE_DUREE = 0.97      # la piste doit durer au moins 97 % de la durée annoncée
LIMITE_MAX = 50

_cache_catalogue = {'mtime': None, 'data': []}
_cache_duree = {}           # (chemin, mtime) -> durée réelle en secondes
_cache_lrc = {}             # (chemin, mtime) -> lignes de paroles


# ----------------------------------------------------------------------------
# Utilitaires
# ----------------------------------------------------------------------------
def _normaliser(texte):
    texte = unicodedata.normalize('NFD', str(texte or ''))
    texte = ''.join(c for c in texte if unicodedata.category(c) != 'Mn')
    return re.sub(r'\s+', ' ', texte.lower()).strip()


def _chemin_catalogue():
    return current_app.config.get(
        'KARAOKE_CATALOGUE_PATH',
        os.path.join(current_app.instance_path, 'karaoke_catalogue.json'))


def _charger_catalogue():
    chemin = _chemin_catalogue()
    try:
        mtime = os.path.getmtime(chemin)
    except OSError:
        return []
    if _cache_catalogue['mtime'] != mtime:
        try:
            with open(chemin, 'r', encoding='utf-8') as f:
                data = json.load(f)
            _cache_catalogue['data'] = data if isinstance(data, list) else []
        except (OSError, ValueError):
            current_app.logger.exception('Catalogue karaoké illisible')
            _cache_catalogue['data'] = []
        _cache_catalogue['mtime'] = mtime
    return _cache_catalogue['data']


def _chemin_local(url):
    """Transforme /static/... en chemin disque. Retourne None pour une URL distante."""
    if not url or not url.startswith('/static/'):
        return None
    base = os.path.realpath(current_app.static_folder)
    chemin = os.path.realpath(os.path.join(base, url[len('/static/'):]))
    if not chemin.startswith(base + os.sep):    # protection contre ../
        return None
    return chemin if os.path.isfile(chemin) else None


def _duree_reelle(chemin):
    """Durée réelle du fichier via ffprobe (None si indisponible)."""
    try:
        cle = (chemin, os.path.getmtime(chemin))
    except OSError:
        return None
    if cle in _cache_duree:
        return _cache_duree[cle]
    duree = None
    try:
        sortie = subprocess.run(
            ['ffprobe', '-v', 'error', '-show_entries', 'format=duration',
             '-of', 'default=noprint_wrappers=1:nokey=1', chemin],
            capture_output=True, text=True, timeout=15, check=True).stdout.strip()
        duree = float(sortie)
    except (OSError, ValueError, subprocess.SubprocessError):
        duree = None
    _cache_duree[cle] = duree
    return duree


def _lire_lrc(url):
    """Paroles synchronisées (fichier .lrc que tu fournis toi-même)."""
    chemin = _chemin_local(url)
    if not chemin:
        return []
    cle = (chemin, os.path.getmtime(chemin))
    if cle in _cache_lrc:
        return _cache_lrc[cle]
    lignes = []
    motif = re.compile(r'\[(\d+):(\d+(?:\.\d+)?)\](.*)')
    try:
        with open(chemin, 'r', encoding='utf-8') as f:
            for brut in f:
                m = motif.match(brut.strip())
                if m and m.group(3).strip():
                    lignes.append({'t': int(m.group(1)) * 60 + float(m.group(2)),
                                   'text': m.group(3).strip()})
    except OSError:
        lignes = []
    lignes.sort(key=lambda l: l['t'])
    _cache_lrc[cle] = lignes
    return lignes


def _verifier_complete(entree):
    """
    Une chanson est « complète » si :
      - elle est marquée sans voix (vocals_removed != False),
      - sa durée annoncée est connue,
      - et, quand le fichier est local, sa vraie durée atteint 97 % de la durée annoncée.
    """
    if entree.get('vocals_removed') is False or entree.get('published') is False:
        return False, 0
    annoncee = float(entree.get('duration') or 0)
    if annoncee <= 0:
        return False, 0
    chemin = _chemin_local(entree.get('instrumental_url', ''))
    if chemin:
        reelle = _duree_reelle(chemin)
        if reelle is None:                       # ffprobe absent : on s'en tient au catalogue
            return True, annoncee
        if reelle < annoncee * TOLERANCE_DUREE:
            return False, reelle
        return True, reelle
    return True, annoncee                        # URL distante : non vérifiable ici


# ----------------------------------------------------------------------------
# Route
# ----------------------------------------------------------------------------
@main_bp.route('/karaoke/api/search', methods=['GET'])
def api_search():
    q = _normaliser(request.args.get('q', ''))
    try:
        limit = max(1, min(LIMITE_MAX, int(request.args.get('limit', 30))))
        page = max(1, int(request.args.get('page', 1)))
    except ValueError:
        return jsonify(ok=False, error='Paramètres invalides'), 400

    mots = q.split()
    trouves = []
    for e in _charger_catalogue():
        if not isinstance(e, dict) or not e.get('instrumental_url') or not e.get('title'):
            continue
        meule = _normaliser(e.get('title', '') + ' ' + e.get('artist', ''))
        if all(m in meule for m in mots):
            trouves.append(e)

    trouves.sort(key=lambda e: _normaliser(e.get('title', '')))
    total = len(trouves)
    debut = (page - 1) * limit

    resultats = []
    for e in trouves[debut:debut + limit]:
        complete, duree = _verifier_complete(e)
        if not complete:
            continue                              # on n'expose jamais une piste incomplète
        resultats.append({
            'id': e.get('id') or _normaliser(e['title']).replace(' ', '-'),
            'title': e['title'],
            'artist': e.get('artist', ''),
            'duration': round(duree, 2),
            'cover': e.get('cover', ''),
            'instrumental_url': e['instrumental_url'],
            'complete': True,
            'vocals_removed': True,
            'lyrics': _lire_lrc(e['lyrics_url']) if e.get('lyrics_url') else [],
        })

    return jsonify(ok=True, results=resultats, total=total, page=page, limit=limit)

# ══════════════════════════════════════════════════════════════════════
