def _mh_url(endpoint, fallback, **kw):
    try:
        return url_for(endpoint, **kw)
    except Exception:
        return fallback


def _mh_famille_url():
    """URL du « Centre familial » (module famille.py) : détectée parmi les routes enregistrées, '' si aucune."""
    try:
        cands = [x.rule for x in current_app.url_map.iter_rules()
                 if 'GET' in x.methods and not x.arguments and 'famil' in x.rule.lower()
                 and not x.rule.startswith(('/api', '/static', '/admin'))]
        return min(cands, key=len) if cands else ''
    except Exception:
        return ''


