@main_bp.route('/messenger-login', methods=['GET', 'POST'], endpoint='messenger_login')
def messenger_login_page():
    _identite = (request.args.get('identite') or '')[:120]
    # « Ajouter un profil » (depuis le hub) : on ferme la session courante puis on affiche la connexion.
    if request.method == 'GET' and request.args.get('ajouter'):
        try:
            _u_cur = db.session.get(User, session['user_id']) if 'user_id' in session else None
            if _u_cur is not None:
                _u_cur.is_online = False
                db.session.commit()
        except Exception:
            db.session.rollback()
        logout_user()
        session.clear()
        return render_template('messenger_login.html', identity_value=_identite)
    # Déjà connecté : on va directement au hub, sans ressaisir identifiants ni mot de passe.
    if 'user_id' in session and db.session.get(User, session['user_id']) is not None:
        return redirect(url_for('main.messenger_hub'))
    if request.method == 'GET':
        return render_template('messenger_login.html', identity_value=_identite)
    identity_raw = (request.form.get('identity') or '').strip()
    password = request.form.get('password')
    identity_clean = re.sub(r'\s+', ' ', identity_raw)
    phone_digits = re.sub(r'\D', '', identity_raw)
    user = User.query.filter(
        (User.email.ilike(identity_clean)) | (User.username.ilike(identity_clean))).first()
    if not user and hasattr(User, 'nom_complet'):
        user = User.query.filter(User.nom_complet.ilike(identity_clean)).first()
    if not user and phone_digits:
        for candidate in User.query.filter(User.phone.isnot(None)).all():
            cd = re.sub(r'\D', '', candidate.phone or '')
            if cd and (phone_digits in cd or cd in phone_digits):
                if user is None:
                    user = candidate
                if password and candidate.password and check_password_hash(candidate.password, password):
                    user = candidate
                    break
    if user and user.password and password and check_password_hash(user.password, password):
        if _pl_bloque_connexion(user):
            return redirect(url_for('main.profil_verrouille'))
        _v_cc = _compte_verdict_connexion(user)
        if _v_cc is not None:
            if _v_cc[0] == 'gate':
                return redirect(url_for('main.compte_gate'))
            return render_template('messenger_login.html', login_error=_v_cc[1], identity_value=identity_raw)
        session['user_id'] = user.id
        login_user(user)
        user.is_online = True
        user.last_seen = datetime.utcnow()
        db.session.commit()
        return redirect(url_for('main.messenger_hub'))
    if user is None:
        err = "Aucun compte ne correspond à cet identifiant. Vérifiez votre e-mail, votre numéro de téléphone ou votre nom d'utilisateur."
    else:
        err = "Mot de passe incorrect. Vérifiez votre saisie ou utilisez « Mot de passe oublié ? »."
    return render_template('messenger_login.html', login_error=err, identity_value=identity_raw)

# ======================================================================
# DÉBUT : À LA UNE — routes (profile-2.html)
# À COLLER À LA TOUTE FIN DE routes.py (là où mainbp, db, Publication
# sont déjà définis / importés). Rien d'existant n'est modifié.
#
# Endpoints créés (utilisés par profile-2.html via url_for('main.…')) :
#   main.api_une_photos      GET   /api/a-la-une/photos
#   main.api_une_creer       POST  /api/a-la-une/creer
#   main.api_une_supprimer   POST  /api/a-la-une/<collection_id>/supprimer
# + fonction de template  a_la_une_de(user_id)  (utilisée par le profil)
# ======================================================================

from models import UneCollection

_UNE_MAX_PHOTOS = 30                 # identique au JS (MAX = 30)
_UNE_MAX_TAILLE = 8 * 1024 * 1024    # identique au JS (8 Mo)
_UNE_MAX_TITRE = 18                  # identique au JS (maxlength = 18)
_UNE_MAX_COLLECTIONS = 20            # limite par utilisateur
_UNE_PREFIXE = 'une_'                # préfixe des fichiers créés par cette fonction
_UNE_VIDEOS = ('mp4', 'mov', 'webm')
_UNE_PAR_DEFAUT = ('default.png', 'default_cover.png', 'default_avatar.png')

_une_etat = {'table_ok': False}


def _une_assurer_table():
    if _une_etat['table_ok']:
        return
    try:
        UneCollection.__table__.create(db.engine, checkfirst=True)
        _une_etat['table_ok'] = True
    except Exception:
        current_app.logger.exception('À la une : création de la table impossible')


def _une_dossier():
    return os.path.join(current_app.static_folder, 'uploads')


def _une_url(ref):
    return url_for('static', filename='uploads/' + ref)


def _une_est_image(nom):
    return bool(nom) and nom.rsplit('.', 1)[-1].lower() not in _UNE_VIDEOS


def _une_refs_autorisees(user):
    """Photos déjà importées par l'utilisateur : images de ses publications,
    sa couverture et son avatar. Seules ces photos peuvent être réutilisées."""
    refs = []
    try:
        pubs = (Publication.query.filter_by(user_id=user.id).filter(_clause_sans_enfants())
                .order_by(Publication.date_creation.desc()).limit(500).all())
    except Exception:
        db.session.rollback()
        pubs = []
    for p in pubs:
        m = getattr(p, 'media_url', None)
        if m and _une_est_image(m) and getattr(p, 'type_publication', None) != 'souvenir':
            refs.append(m)
    for attr in ('couverture', 'avatar'):
        v = getattr(user, attr, None)
        if v and v not in _UNE_PAR_DEFAUT and _une_est_image(v):
            refs.append(v)
    vus, resultat = set(), []
    for r in refs:
        if r not in vus:
            vus.add(r)
            resultat.append(r)
    return resultat


def _une_extension(octets):
    """Détecte le vrai format à partir du contenu (JPG, PNG ou WEBP)."""
    if octets[:3] == b'\xff\xd8\xff':
        return 'jpg'
    if octets[:8] == b'\x89PNG\r\n\x1a\n':
        return 'png'
    if octets[:4] == b'RIFF' and octets[8:12] == b'WEBP':
        return 'webp'
    return None


def _une_supprimer_fichiers(noms):
    """Supprime uniquement les fichiers créés par « À la une » (préfixe une_)
    qui ne sont plus utilisés par aucune collection."""
    for nom in set(noms):
        try:
            if not nom or os.sep in nom or '/' in nom or not nom.startswith(_UNE_PREFIXE):
                continue
            encore = UneCollection.query.filter(UneCollection.items.like('%"' + nom + '"%')).first()
            if encore:
                continue
            chemin = os.path.join(_une_dossier(), nom)
            if os.path.isfile(chemin):
                os.remove(chemin)
        except Exception:
            current_app.logger.exception('À la une : suppression de fichier impossible')


def a_la_une_de(user_id):
    """Utilisée par profile-2.html : renvoie les collections d'un utilisateur
    sous la forme [{id, titre, cover, items:[urls]}]. Ne lève jamais d'erreur :
    en cas de souci, le profil s'affiche normalement avec une liste vide."""
    try:
        _une_assurer_table()
        lignes = (UneCollection.query.filter_by(user_id=user_id)
                  .order_by(UneCollection.date_creation.desc(), UneCollection.id.desc()).all())
        sortie = []
        for c in lignes:
            try:
                refs = json.loads(c.items or '[]')
            except Exception:
                refs = []
            refs = [r for r in refs if isinstance(r, str) and r]
            if not refs:
                continue
            urls = [_une_url(r) for r in refs]
            i = c.cover_index if 0 <= (c.cover_index or 0) < len(urls) else 0
            sortie.append({'id': c.id, 'titre': c.titre or '', 'cover': urls[i], 'items': urls})
        return sortie
    except Exception:
        db.session.rollback()
        current_app.logger.exception('À la une : lecture impossible')
        return []


@main_bp.app_context_processor
def _une_injecter_dans_les_templates():
    return {'a_la_une_de': a_la_une_de}


@main_bp.route('/api/a-la-une/photos', methods=['GET'])
def api_une_photos():
    """Onglet « Importées » : photos déjà présentes sur le profil."""
    if not current_user.is_authenticated:
        return jsonify(success=False, error='Connexion requise.', photos=[]), 401
    try:
        photos = [{'ref': r, 'src': _une_url(r)} for r in _une_refs_autorisees(current_user)]
        return jsonify(success=True, photos=photos)
    except Exception:
        current_app.logger.exception('À la une : liste des photos impossible')
        return jsonify(success=False, error='Impossible de charger vos photos.', photos=[]), 500


@main_bp.route('/api/a-la-une/creer', methods=['POST'])
def api_une_creer():
    """Crée une collection : photos envoyées (files) et/ou déjà importées (ref),
    dans l'ordre choisi (ordre), avec la couverture (couverture) et le titre."""
    if not current_user.is_authenticated:
        return jsonify(success=False, error='Connexion requise.'), 401
    _une_assurer_table()

    try:
        ordre = json.loads(request.form.get('ordre') or '[]')
    except Exception:
        return jsonify(success=False, error='Données invalides.'), 400
    if not isinstance(ordre, list) or not ordre:
        return jsonify(success=False, error='Choisissez au moins une photo.'), 400
    if len(ordre) > _UNE_MAX_PHOTOS:
        return jsonify(success=False, error='Vous pouvez choisir %d photos au maximum.' % _UNE_MAX_PHOTOS), 400

    try:
        if UneCollection.query.filter_by(user_id=current_user.id).count() >= _UNE_MAX_COLLECTIONS:
            return jsonify(success=False, error='Limite de %d collections atteinte. Supprimez-en une pour continuer.' % _UNE_MAX_COLLECTIONS), 400
    except Exception:
        db.session.rollback()
        return jsonify(success=False, error='Création impossible, veuillez réessayer.'), 500

    fichiers = request.files.getlist('files')
    autorisees = set(_une_refs_autorisees(current_user))
    ecrits, refs_finales = [], []

    try:
        os.makedirs(_une_dossier(), exist_ok=True)
        for e in ordre:
            if not isinstance(e, dict):
                raise ValueError('Données invalides.')
            t, v = e.get('t'), e.get('v')
            if t == 'ref':
                if v not in autorisees:
                    raise ValueError('Une des photos choisies est introuvable.')
                refs_finales.append(v)
            elif t == 'file':
                if not isinstance(v, int) or v < 0 or v >= len(fichiers):
                    raise ValueError('Une des photos envoyées est manquante.')
                f = fichiers[v]
                octets = f.read(_UNE_MAX_TAILLE + 1)
                if len(octets) > _UNE_MAX_TAILLE:
                    raise ValueError('%s : dépasse 8 Mo.' % (f.filename or 'Photo'))
                ext = _une_extension(octets)
                if not ext:
                    raise ValueError('%s : format non accepté (JPG, PNG ou WEBP).' % (f.filename or 'Photo'))
                nom = '%s%d_%s.%s' % (_UNE_PREFIXE, current_user.id, uuid.uuid4().hex, ext)
                with open(os.path.join(_une_dossier(), nom), 'wb') as sortie:
                    sortie.write(octets)
                ecrits.append(nom)
                refs_finales.append(nom)
            else:
                raise ValueError('Données invalides.')

        try:
            couv = int(request.form.get('couverture', 0))
        except (TypeError, ValueError):
            couv = 0
        if couv < 0 or couv >= len(refs_finales):
            couv = 0

        titre = (request.form.get('titre') or '').strip()[:_UNE_MAX_TITRE] or 'À la une'

        c = UneCollection(user_id=current_user.id, titre=titre,
                          items=json.dumps(refs_finales), cover_index=couv)
        db.session.add(c)
        db.session.commit()
        return jsonify(success=True, id=c.id)
    except ValueError as err:
        db.session.rollback()
        _une_supprimer_fichiers(ecrits)
        return jsonify(success=False, error=str(err)), 400
    except Exception:
        db.session.rollback()
        _une_supprimer_fichiers(ecrits)
        current_app.logger.exception('À la une : création impossible')
        return jsonify(success=False, error='Création impossible, veuillez réessayer.'), 500


@main_bp.route('/api/a-la-une/<int:collection_id>/supprimer', methods=['POST'])
def api_une_supprimer(collection_id):
    """Supprime une collection (propriétaire uniquement)."""
    if not current_user.is_authenticated:
        return jsonify(success=False, error='Connexion requise.'), 401
    _une_assurer_table()
    try:
        c = UneCollection.query.get(collection_id)
        if not c or c.user_id != current_user.id:
            return jsonify(success=False, error='Collection introuvable.'), 404
        try:
            refs = json.loads(c.items or '[]')
        except Exception:
            refs = []
        db.session.delete(c)
        db.session.commit()
        _une_supprimer_fichiers([r for r in refs if isinstance(r, str)])
        return jsonify(success=True)
    except Exception:
        db.session.rollback()
        current_app.logger.exception('À la une : suppression impossible')
        return jsonify(success=False, error='Suppression impossible, veuillez réessayer.'), 500

