# ======================================================================
# AJOUT ADDITIF : J'AIME / COMMENTAIRES / PARTAGES / REPUBLICATIONS PAR PHOTO
# ----------------------------------------------------------------------
# Dans une publication à plusieurs photos/vidéos, chaque média possède SES PROPRES interactions,
# indépendantes de celles de la publication (affichée dans le fil). Principe : à la première
# ouverture, chaque média reçoit une publication « enfant » invisible (type 'media_enfant',
# archivée : absente du fil, du profil et des Reels). Toutes les routes existantes (J'aime,
# réactions, commentaires, partage, republier) fonctionnent dessus sans aucune modification.
# L'enfant hérite de la confidentialité et de la permission de commentaires de la publication.
# ======================================================================
from sqlalchemy import UniqueConstraint as _SaUniqueC
_TYPE_MEDIA_ENFANT = 'media_enfant'
_PUB_MEDIA_ENFANTS = _SaTable(
    'publication_media_enfant', db.metadata,
    _SaColumn('id', _SaInteger, primary_key=True),
    _SaColumn('parent_id', _SaInteger, nullable=False, index=True),
    _SaColumn('indice', _SaInteger, nullable=False),
    _SaColumn('enfant_id', _SaInteger, nullable=False, index=True),
    _SaUniqueC('parent_id', 'indice', name='uq_pub_media_enfant'),
    extend_existing=True,
)
_table_media_enfants_ok = False
def _assurer_table_media_enfants():
    global _table_media_enfants_ok
    if _table_media_enfants_ok:
        return
    try:
        _PUB_MEDIA_ENFANTS.create(bind=db.engine, checkfirst=True)
        _table_media_enfants_ok = True
    except Exception as e:
        print(f"DEBUG: création table publication_media_enfant impossible : {e}")


def _clause_sans_enfants():
    """Filtre SQL : exclut les publications « enfants » (une par photo) des listes publiques."""
    return db.or_(Publication.type_publication.is_(None), Publication.type_publication != _TYPE_MEDIA_ENFANT)


def _fichiers_medias_pub(pub):
    """Noms de fichiers des médias d'une publication, dans l'ordre (le premier = media_url)."""
    res = [pub.media_url] if pub.media_url else []
    try:
        _assurer_table_publication_medias()
        lignes = db.session.execute(_PUB_MEDIAS.select().where(_PUB_MEDIAS.c.publication_id == pub.id)
                                    .order_by(_PUB_MEDIAS.c.ordre, _PUB_MEDIAS.c.id)).fetchall()
        res += [lg.fichier for lg in lignes if lg.fichier]
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: médias supplémentaires illisibles pour #{pub.id} : {e}")
    return res


@main_bp.route('/api/publication/<int:pub_id>/medias-enfants', methods=['POST'])
@login_required
def api_medias_enfants(pub_id):
    """Renvoie (en les créant au besoin) l'état J'aime / commentaires / partages de CHAQUE média."""
    parent = Publication.query.get_or_404(pub_id)
    if getattr(parent, 'type_publication', None) == _TYPE_MEDIA_ENFANT:
        return jsonify(success=False, error="Publication invalide."), 400
    if not _peut_voir_publication(parent, current_user.id):
        return jsonify(success=False, error="Cette publication n'est pas accessible."), 403
    fichiers = _fichiers_medias_pub(parent)
    if len(fichiers) < 2:
        return jsonify(success=True, medias=[])
    try:
        _assurer_table_media_enfants()
        _assurer_tables_menu()
        liens = {row.indice: row.enfant_id for row in db.session.execute(
            _PUB_MEDIA_ENFANTS.select().where(_PUB_MEDIA_ENFANTS.c.parent_id == pub_id)).fetchall()}
        rg_parent = _reglage_pub(pub_id)
        permission = (rg_parent.permission_commentaires if rg_parent else 'tout_le_monde') or 'tout_le_monde'
        enfants = []
        for i, nom in enumerate(fichiers):
            enfant = db.session.get(Publication, liens[i]) if i in liens else None
            if enfant is None:
                enfant = Publication(contenu='', media_url=nom, user_id=parent.user_id,
                                     type_publication=_TYPE_MEDIA_ENFANT,
                                     confidentialite=parent.confidentialite or 'public')
                if parent.date_creation:
                    enfant.date_creation = parent.date_creation
                db.session.add(enfant)
                db.session.flush()
                try:
                    with db.session.begin_nested():
                        db.session.execute(_PUB_MEDIA_ENFANTS.insert().values(parent_id=pub_id, indice=i, enfant_id=enfant.id))
                except Exception:
                    # Un autre appel simultané l'a déjà créé : on supprime le doublon et on relit.
                    db.session.delete(enfant)
                    db.session.flush()
                    ligne = db.session.execute(_PUB_MEDIA_ENFANTS.select().where(
                        (_PUB_MEDIA_ENFANTS.c.parent_id == pub_id) & (_PUB_MEDIA_ENFANTS.c.indice == i))).first()
                    enfant = db.session.get(Publication, ligne.enfant_id) if ligne else None
                    if enfant is None:
                        continue
            # Héritage : confidentialité + permission de commentaires + archivée (invisible dans les listes)
            if enfant.confidentialite != (parent.confidentialite or 'public'):
                enfant.confidentialite = parent.confidentialite or 'public'
            rg = _reglage_pub(enfant.id, creer=True)
            rg.archive = True
            rg.epingle = False
            rg.permission_commentaires = permission
            enfants.append((i, enfant))
        db.session.commit()

        ids = [e.id for _, e in enfants]
        likes = dict(db.session.query(Like.publication_id, func.count(Like.id))
                     .filter(Like.publication_id.in_(ids)).group_by(Like.publication_id).all()) if ids else {}
        coms = dict(db.session.query(Commentaire.publication_id, func.count(Commentaire.id))
                    .filter(Commentaire.publication_id.in_(ids)).group_by(Commentaire.publication_id).all()) if ids else {}
        mes_likes = {l.publication_id for l in Like.query.filter(
            Like.user_id == current_user.id, Like.publication_id.in_(ids)).all()} if ids else set()
        sortie = []
        for i, e in enfants:
            try:
                can_comment = bool(peut_commenter_publication(e, current_user.id))
            except Exception:
                can_comment = True
            sortie.append({'indice': i, 'pub_id': e.id, 'liked': e.id in mes_likes,
                           'likes': int(likes.get(e.id, 0)), 'comments': int(coms.get(e.id, 0)),
                           'shares': int(e.share_count or 0), 'can_comment': can_comment,
                           'enregistre': bool(_a_action(current_user.id, e.id, 'enregistre')),
                           'proprietaire': parent.user_id == current_user.id})
        return jsonify(success=True, medias=sortie)
    except Exception as exc:
        db.session.rollback()
        print(f"DEBUG: interactions par photo indisponibles pour #{pub_id} : {exc}")
        return jsonify(success=False, error="Interactions indisponibles pour le moment."), 500


@main_bp.route('/api/publication/<int:pub_id>/media/<int:indice>/supprimer', methods=['POST'])
@login_required
def api_media_supprimer(pub_id, indice):
    """Retire UNE photo/vidéo d'une publication à plusieurs médias (réservé à l'auteur).
    Le fichier reste sur le disque ; l'enfant correspondant est simplement détaché (invisible)."""
    parent, err = _pub_du_proprietaire(pub_id)
    if err:
        return err
    try:
        fichiers = _fichiers_medias_pub(parent)
        if len(fichiers) < 2:
            return jsonify(success=False, error="C'est le seul média : supprimez plutôt la publication."), 400
        if indice < 0 or indice >= len(fichiers):
            return jsonify(success=False, error="Média introuvable."), 404
        lignes = db.session.execute(_PUB_MEDIAS.select().where(_PUB_MEDIAS.c.publication_id == pub_id)
                                    .order_by(_PUB_MEDIAS.c.ordre, _PUB_MEDIAS.c.id)).fetchall()
        if indice == 0:
            # Le premier extra devient le média principal
            parent.media_url = lignes[0].fichier
            db.session.execute(_PUB_MEDIAS.delete().where(_PUB_MEDIAS.c.id == lignes[0].id))
        else:
            db.session.execute(_PUB_MEDIAS.delete().where(_PUB_MEDIAS.c.id == lignes[indice - 1].id))
        # Décaler les liens vers les publications « enfants » (le média retiré est détaché)
        _assurer_table_media_enfants()
        liens = sorted(db.session.execute(_PUB_MEDIA_ENFANTS.select().where(
            _PUB_MEDIA_ENFANTS.c.parent_id == pub_id)).fetchall(), key=lambda r: r.indice)
        for r in liens:
            if r.indice == indice:
                db.session.execute(_PUB_MEDIA_ENFANTS.delete().where(_PUB_MEDIA_ENFANTS.c.id == r.id))
        for r in liens:
            if r.indice > indice:
                db.session.execute(_PUB_MEDIA_ENFANTS.update().where(_PUB_MEDIA_ENFANTS.c.id == r.id)
                                   .values(indice=r.indice - 1))
        db.session.commit()
        return jsonify(success=True, restants=len(fichiers) - 1)
    except Exception as exc:
        db.session.rollback()
        print(f"DEBUG: suppression du média #{indice} de la publication #{pub_id} impossible : {exc}")
        return jsonify(success=False, error="Suppression impossible pour le moment."), 500


