# ── ASSISTANT « COMPTE PARENTAL » (AJOUT) ───────────────────────────────────────
#  Route appelée par l'assistant en 7 étapes de Paramètres > Contrôle parental
#  (settings.html : PC_ENDPOINT = '/api/fn/parental/compte').
#  Le responsable (connecté) protège le profil de l'enfant : le second mot de passe
#  (parental) est enregistré sur le profil de l'enfant, avec le niveau de filtrage,
#  les mots interdits et la configuration complète (temps d'écran, interactions…).
PC_EXIGER_DATE_NAISSANCE = True   # True : seul un profil dont la date de naissance indique un mineur peut être protégé


_PC_CATS = ('adult', 'violence', 'language', 'gambling', 'selfharm')


_PC_RELS = ('parent', 'tuteur', 'autre')


_PC_AGES = ('lt8', '8-12', '13-15', '16-17')


_PC_EMAIL_RE = re.compile(r'^[^@\s]{1,64}@[^@\s]{1,255}\.[^@\s]{2,}$')


_PC_USER_RE = re.compile(r'^[A-Za-z0-9._]{3,30}$')


class ParentalCompte(db.Model):
    """Configuration du compte parental d'un profil enfant (créée automatiquement)."""
    __tablename__ = 'parental_compte'
    child_id = db.Column(db.Integer, primary_key=True)
    guardian_id = db.Column(db.Integer, nullable=False, index=True)
    data = db.Column(db.Text, nullable=False, default='{}')
    cree_le = db.Column(db.DateTime, default=datetime.utcnow)
    maj_le = db.Column(db.DateTime, default=datetime.utcnow)


_pc_tables_ok = False


def _pc_tables():
    global _pc_tables_ok
    if _pc_tables_ok:
        return
    try:
        ParentalCompte.__table__.create(bind=db.engine, checkfirst=True)
        _pc_tables_ok = True
    except Exception as e:
        print(f"DEBUG: création de la table du compte parental impossible : {e}")


def _pc_valider(data):
    """Valide strictement la configuration envoyée. Renvoie (config_propre, message_erreur)."""
    if not isinstance(data, dict):
        return None, 'Requête invalide.'
    g = data.get('guardian') if isinstance(data.get('guardian'), dict) else {}
    g_nom = re.sub(r'\s+', ' ', str(g.get('name') or '')).strip()[:80]
    g_rel = g.get('relation') if g.get('relation') in _PC_RELS else 'parent'
    g_mail = str(g.get('email') or '').strip()[:320]
    if len(g_nom) < 2:
        return None, 'Indiquez votre nom (2 caractères minimum).'
    if not _PC_EMAIL_RE.match(g_mail):
        return None, 'Saisissez une adresse e-mail valide.'

    level = data.get('level') if data.get('level') in ('standard', 'strict') else None
    if level is None:
        return None, 'Niveau de protection invalide.'

    cats_in = data.get('categories') if isinstance(data.get('categories'), dict) else {}
    cats = {c: bool(cats_in.get(c, True)) for c in _PC_CATS}

    t = data.get('time') if isinstance(data.get('time'), dict) else {}
    limite = t.get('limit_minutes')
    if limite is not None:
        if isinstance(limite, bool) or not isinstance(limite, int) or not (5 <= limite <= 1440):
            return None, 'Durée quotidienne invalide.'
    couvre = t.get('curfew')
    if couvre is not None:
        if not isinstance(couvre, dict):
            return None, 'Horaires invalides.'
        d, f = str(couvre.get('from') or ''), str(couvre.get('to') or '')
        if not (_FN_TIME_RE.match(d) and _FN_TIME_RE.match(f)) or d == f:
            return None, "L'heure de début et de fin doivent être valides et différentes."
        couvre = {'from': d, 'to': f}
    jours = t.get('days')
    if not isinstance(jours, list):
        jours = [0, 1, 2, 3, 4, 5, 6]
    jours = sorted({x for x in jours if isinstance(x, int) and not isinstance(x, bool) and 0 <= x <= 6})
    if not jours:
        return None, 'Choisissez au moins un jour.'

    s = data.get('social') if isinstance(data.get('social'), dict) else {}
    social = {
        'strangersMsg': bool(s.get('strangersMsg', False)),
        'approveFriends': bool(s.get('approveFriends', True)),
        'hideSearch': bool(s.get('hideSearch', True)),
        'noLocation': bool(s.get('noLocation', True)),
        'visibility': s.get('visibility') if s.get('visibility') in ('friends', 'private') else 'friends',
    }
    mots = _fn_clean_prefs({'keywords': data.get('keywords') if isinstance(data.get('keywords'), list) else []}).get('keywords', [])[:50]

    cfg = {
        'guardian': {'name': g_nom, 'relation': g_rel, 'email': g_mail},
        'level': level, 'categories': cats,
        'time': {'limit_minutes': limite, 'curfew': couvre, 'days': jours},
        'social': social, 'keywords': mots,
    }
    return cfg, None


@main_bp.route('/api/fn/parental/compte', methods=['POST'])
@_fn_api()
def fn_api_parental_compte():
    uid = _fn_uid()                       # le responsable (connecté)
    data = request.get_json(silent=True) or {}
    if not _fn_rate_ok(f'pc_compte:{uid}', 6, 3600):
        return _fn_err('Trop de tentatives. Réessayez dans quelques minutes.', 429)
    _pc_tables()

    cfg, erreur = _pc_valider(data)
    if erreur:
        return _fn_err(erreur, 400)

    pwd = str(data.get('password') or '')
    if len(pwd) < 8:
        return _fn_err('Le mot de passe parental doit contenir au moins 8 caractères.', 400)

    guardian = db.session.get(User, uid)
    if guardian is None:
        return _fn_err('Connexion requise.', 401)
    if guardian.password and check_password_hash(guardian.password, pwd):
        return _fn_err('Choisissez un mot de passe différent de celui de votre compte.', 400)

    # ── profil de l'enfant ──
    c = data.get('child') if isinstance(data.get('child'), dict) else {}
    mode = c.get('mode')
    age = c.get('age_range') if c.get('age_range') in _PC_AGES else None
    if age is None:
        return _fn_err("Choisissez la tranche d'âge de l'enfant.", 400)
    if mode == 'new':
        return _fn_err("Création automatique d'un profil enfant indisponible : créez d'abord le profil de l'enfant "
                       "(inscription), puis relancez l'assistant et choisissez « Profil existant ».", 409)
    if mode != 'existing':
        return _fn_err("Choisissez le profil de l'enfant.", 400)
    nom_enfant = str(c.get('username') or '').strip()
    if not _PC_USER_RE.match(nom_enfant):
        return _fn_err("Choisissez le profil de l'enfant.", 400)
    enfant = User.query.filter(db.func.lower(User.username) == nom_enfant.lower()).first()
    if enfant is None:
        return _fn_err('Profil introuvable.', 404)
    if enfant.id == uid:
        return _fn_err('Vous ne pouvez pas vous placer vous-même sous contrôle parental avec cet assistant.', 400)
    if _fn_is_admin(enfant):
        return _fn_err('Ce profil ne peut pas être placé sous contrôle parental.', 403)
    naissance = getattr(enfant, 'birth_date', None)
    if naissance is not None:
        auj = date.today()
        age_reel = auj.year - naissance.year - ((auj.month, auj.day) < (naissance.month, naissance.day))
        if age_reel >= 18:
            return _fn_err("Ce profil appartient à une personne majeure : le contrôle parental n'est pas applicable.", 403)
    elif PC_EXIGER_DATE_NAISSANCE:
        return _fn_err("La date de naissance de ce profil n'est pas renseignée : impossible de confirmer qu'il s'agit d'un mineur.", 403)

    sec = _fn_get_security(enfant.id)
    if sec.parental_enabled:
        return _fn_err('Ce profil est déjà sous contrôle parental.', 409)
    if enfant.password and check_password_hash(enfant.password, pwd):
        return _fn_err("Choisissez un mot de passe différent de celui du compte de l'enfant.", 400)

    # ── enregistrement ──
    sec.parental_hash = generate_password_hash(pwd)
    sec.parental_enabled = True
    sec.parental_level = cfg['level']
    sec.updated_at = datetime.utcnow()

    cfg['child'] = {'username': enfant.username, 'age_range': age}
    ligne = db.session.get(ParentalCompte, enfant.id)
    if ligne is None:
        ligne = ParentalCompte(child_id=enfant.id, guardian_id=uid)
        db.session.add(ligne)
    ligne.guardian_id = uid
    ligne.data = json.dumps(cfg, ensure_ascii=False)
    ligne.maj_le = datetime.utcnow()
    db.session.commit()

    # ── effets immédiats sur les préférences de l'enfant (mots interdits, recherche) ──
    try:
        patch = {}
        if cfg['keywords']:
            actuels = _fn_load_prefs(enfant.id).get('keywords') or []
            patch['keywords'] = list(actuels) + [w for w in cfg['keywords'] if w.lower() not in {a.lower() for a in actuels}]
        if cfg['social']['hideSearch']:
            patch['hide_search'] = True
        if patch:
            _fn_store_prefs(enfant.id, patch)
    except Exception as e:
        db.session.rollback()
        print(f"DEBUG: préférences parentales non appliquées : {e}")

    _fn_audit(enfant.id, 'parental_active', f"Contrôle parental activé par {cfg['guardian']['name']}")
    return _fn_ok(enabled=True, level=cfg['level'],
                  child={'username': enfant.username, 'nom': getattr(enfant, 'nom_complet', None) or enfant.username})


# ======================================================================
# SON : publier un son sans vidéo — envoi de la photo (pochette) choisie
# par l'utilisateur. La publication elle-même passe par /ajouter_publication
# (mêmes règles de confidentialité que le fil).
# ======================================================================
@main_bp.route('/api/son/pochette', methods=['POST'])
@login_required
def api_son_pochette():
    fichier = request.files.get('pochette')
    if not fichier or not fichier.filename:
        return jsonify(success=False, error="Aucune image reçue."), 400
    try:
        fichier.seek(0, os.SEEK_END)
        taille = fichier.tell()
        fichier.seek(0)
        if taille <= 0:
            return jsonify(success=False, error="Cette image est vide."), 400
        if taille > 10 * 1024 * 1024:
            return jsonify(success=False, error="Cette image dépasse 10 Mo."), 413
        tete = fichier.read(16)
        fichier.seek(0)
        # On se fie au contenu réel du fichier, pas à son nom ni à son type annoncé.
        if tete[:3] == b'\xff\xd8\xff':
            ext = 'jpg'
        elif tete[:8] == b'\x89PNG\r\n\x1a\n':
            ext = 'png'
        elif tete[:6] in (b'GIF87a', b'GIF89a'):
            ext = 'gif'
        elif tete[:4] == b'RIFF' and tete[8:12] == b'WEBP':
            ext = 'webp'
        else:
            return jsonify(success=False, error="Format d'image non pris en charge (JPG, PNG, WebP ou GIF)."), 400
        nom_final = f"pochette_{current_user.id}_{uuid.uuid4().hex[:12]}.{ext}"
        os.makedirs(os.path.join('static', 'uploads'), exist_ok=True)
        fichier.save(os.path.join('static', 'uploads', nom_final))
    except OSError as exc:
        print(f"DEBUG: échec sauvegarde pochette de son : {exc}")
        return jsonify(success=False, error="La photo n'a pas pu être enregistrée."), 500
    return jsonify(success=True, url=url_for('static', filename='uploads/' + nom_final))